    fn postCacheChanged(context: *anyopaque) !bool {
        const self: *App = @ptrCast(@alignCast(context));
        return platform.postEvent(self.loop, .cache_changed);
    }
    fn postThemeTick(context: *anyopaque) !void {
        const self: *App = @ptrCast(@alignCast(context));
        const now = Io.Timestamp.now(self.io, .awake).toMilliseconds();
        const update_tick = now >= self.update_tick_at;
        if (!self.theme_following.load(.acquire) and !self.grace_pending.load(.acquire) and !self.meeting_wake.load(.acquire) and !update_tick) return;
        if (now < self.theme_tick_at) return;
        self.theme_tick_at = now +| if (self.grace_pending.load(.acquire)) @as(i64, 500) else 2000;
        if (update_tick) self.update_tick_at = now +| 60000;
        if (self.theme_tick_pending.swap(true, .acq_rel)) return;
        const accepted = platform.postEvent(self.loop, .theme_tick) catch |err| {
            self.theme_tick_pending.store(false, .release);
            return err;
        };
        if (!accepted) self.theme_tick_pending.store(false, .release);
    }
    fn startCacheWatch(self: *App) !void {
        self.cache_watch.io = self.io;
        self.cache_watch.allocator = self.allocator;
        self.cache_watch.client = self.client;
        self.cache_watch.context = self;
        self.cache_watch.postFn = postCacheChanged;
        self.cache_watch.idleFn = postThemeTick;
        for (self.accounts, 0..) |account_value, index| {
            if (get(account_value, "enabled") != .null and !truth(get(account_value, "enabled"))) continue;
            self.cache_watch.accounts[index] = text(get(account_value, "address"));
        }
        // The cached first frame is already visible. Establish notification
        // baselines before starting this TUI's provider refresh.
        try self.cache_watch.prime();
        self.cache_activity = self.cache_watch.latest;
        for (self.cache_activity, 0..) |value_in, index| if (value_in) |activity| self.new_mail.observe(index, activity.inboxArrivalCount);
        try self.cache_watch.start();
    }
    fn onCacheChanged(self: *App) !void {
        const changes = try self.cache_watch.take();
        for (changes.values, 0..) |value_in, index| {
            if (changes.mask & (@as(u8, 1) << @intCast(index)) == 0) continue;
            const activity = value_in orelse continue;
            if (activity.lastSyncAt <= self.last_interaction_at) self.new_mail.seen[index] = activity.inboxArrivalCount else self.new_mail.observe(index, activity.inboxArrivalCount);
            const previous = self.cache_activity[index];
            if (previous == null or previous.?.generation != activity.generation or previous.?.lastSyncAt != activity.lastSyncAt) self.cache_reload[index] = true;
            // A body commit may not change generation. Retry an outstanding
            // local body read after that atomic replacement too.
            if (index == self.account_index and (self.pending_cached_list or self.pending_cached_read or self.readerNeedsCacheRefresh())) self.cache_reload[index] = true;
            self.cache_activity[index] = activity;
            if (activity.lastSyncAt > self.sync[index].last_sync_at) {
                self.sync[index].last_sync_at = activity.lastSyncAt;
                self.sync[index].cache_ready = true;
                self.sync[index].error_len = 0;
                if (self.job.future == null or self.job.account_index != index or self.job.kind != .refresh) self.sync[index].state = .current;
            }
        }
    }
    fn adoptBackgroundCache(self: *App) !void {
        if (self.calendar.open) return;
        if (!self.cache_reload[self.account_index] or self.mode != .browse or self.drafts_list or self.follow_ups_list or self.label_picker or self.reader_overlay != .none or self.query.value().len > 0 or self.job.future != null or self.page_loading) return;
        // Provider-visible older mail can lie outside the retained cache.
        // Probe the anchor before changing the page or its navigation history.
        const screen_row = self.selected -| self.top;
        const at_head = self.top == 0 and !(self.has_more_cached_before orelse (self.previous_cursor.value().len > 0));
        self.background_merge = true;
        defer self.background_merge = false;
        const merged = self.loadCachedListImpl(self.messageId(), true) catch |err| switch (err) {
            error.AnchorNotCached => {
                self.cache_reload[self.account_index] = false;
                return;
            },
            error.CacheBusy => return,
            else => return err,
        };
        if (merged) {
            self.clearHistory();
            // At the newest head, show newly prepended rows while retaining
            // selection. A scrolled/later window stays visually anchored.
            self.top = if (at_head) 0 else self.selected -| screen_row;
            self.cache_reload[self.account_index] = false;
            if (self.pending_cached_read) try self.preview(self.pending_cached_thread);
        }
    }
    fn mainScreenNotice(self: *const App) bool {
        return self.ordinaryMailbox() and self.new_mail.visible();
    }
    fn ordinaryMailbox(self: *const App) bool {
        return !self.calendar.open and self.mode == .browse and !self.readerCopyVisible() and !self.update_open and self.ux_overlay == .none and !self.compose_active and !self.grace_active and !self.compose_choice and !self.expanded and !self.drafts_list and !self.label_picker and self.reader_overlay == .none and self.query.value().len == 0 and self.mail_selection.count == 0;
    }
    fn updateVisible(self: *const App) bool {
        return self.update_loaded and self.ordinaryMailbox() and updates.visible(&self.update_snapshot, @import("build_options").version);
    }
    fn updateJob(kind: JobKind) bool {
        return kind == .updates_load or kind == .updates_check;
    }
    fn openUpdates(self: *App) void {
        if (!self.capabilities.updates) {
            self.say(false, "Release checks are unavailable on this platform", .{});
            return;
        }
        self.closeUx();
        self.update_open = true;
        self.update_card_focus = null;
        self.update_focus = 0;
        self.update_scroll = 0;
        self.update_message = .{};
    }
    fn closeUpdates(self: *App) void {
        self.update_open = false;
        self.update_card_focus = null;
    }
    fn scheduleUpdateCheck(self: *App) bool {
        if (!self.capabilities.updates) return false;
        if (!self.update_loaded or self.options.fixtures or !updates.due(&self.update_snapshot.state, updates.now(self.io))) return false;
        const was_pending = self.update_pending;
        self.update_pending = true;
        return !was_pending;
    }
    fn dismissUpdate(self: *App) !void {
        if (browser_target) return;
        if (self.job.future != null and updateJob(self.job.kind)) self.cancelJob();
        updates.dismiss(self.io, self.allocator, self.environ, &self.update_snapshot) catch |err| {
            self.openUpdates();
            try self.update_message.set(try std.fmt.allocPrint(self.frame.allocator(), "Dismissal could not be saved: {s}", .{@errorName(err)}));
            return;
        };
        self.update_card_focus = null;
    }
    fn drawUpdateNotice(self: *App, win: vaxis.Window) !void {
        if (!self.updateVisible()) {
            self.update_card_focus = null;
            return;
        }
        const width: u16 = @min(win.width -| 2, 46);
        const y: u16 = if (self.notice_rect) |mail_rect| mail_rect.y +| mail_rect.height +| 1 else 2;
        if (win.width < 70 or win.height < y + 10) {
            self.update_compact = true;
            const label = "[Updates]";
            const x = win.width -| @as(u16, label.len + 1);
            const area = win.child(.{ .x_off = x, .y_off = 1, .width = @intCast(label.len), .height = 1 });
            area.fill(.{ .style = self.style(.text) });
            _ = try self.actionButton(area, 0, 0, label, self.update_card_focus != null, true, .dialog_action, 301);
            self.update_rect = .{ .x = x, .y = 1, .width = @intCast(label.len), .height = 1 };
            return;
        }
        self.update_compact = false;
        const rect: layout.Rect = .{ .x = win.width - width - 1, .y = y, .width = width, .height = 6 };
        const area = win.child(.{ .x_off = rect.x, .y_off = rect.y, .width = width, .height = rect.height });
        area.fill(.{ .style = self.style(.text) });
        const inner = self.panel(area, 0, width, " Upgrade available ", true);
        try self.line(inner, 0, try std.fmt.allocPrint(self.frame.allocator(), "Omagma {s} → {s}", .{ @import("build_options").version, self.update_snapshot.state.latest.slice() }), .subject);
        try self.line(inner, 1, "New features, ready when you are", .muted);
        const x = try self.actionButton(inner, 3, 0, "[Dismiss]", self.update_card_focus == 0, true, .dialog_action, 300);
        _ = try self.actionButton(inner, 3, x, "[How to update]", self.update_card_focus == 1, true, .dialog_action, 301);
        self.update_rect = rect;
    }
    fn activateUpdateCard(self: *App, index: usize) !void {
        if (index == 0) try self.dismissUpdate() else self.openUpdates();
    }
    fn copyUpdateText(self: *App, value: []const u8) !void {
        if (!self.options.fixtures and !@import("builtin").is_test) try self.vx.copyToSystemClipboard(self.tty.writer(), value, self.allocator);
        try self.update_message.set("Copied to terminal clipboard · clipboard support depends on your terminal");
    }
    fn activateUpdate(self: *App, index: usize) !void {
        if (browser_target) return error.UpdatesUnavailable;
        _ = self.cancelMeetingRead();
        switch (index) {
            0 => try self.copyUpdateText(try updates.commands(self.frame.allocator(), &self.update_snapshot)),
            1, 2 => {
                const url = if (index == 1) (if (self.update_snapshot.state.releaseUrl.slice().len > 0) self.update_snapshot.state.releaseUrl.slice() else updates.release_page) else updates.installationUrl(&self.update_snapshot);
                // Explicit browser opens use the existing configured profile route.
                // This operation needs configuration, not a Gmail bearer token.
                if (self.job.future != null and updateJob(self.job.kind)) self.cancelJob();
                if (self.job.future != null) {
                    try self.update_message.set("Mail work is still running · try opening the page again shortly");
                    return;
                }
                try self.start(.open, .{ .cmd = "browser.open", .account = self.account(), .url = url });
            },
            3 => {
                self.update_pending = true;
                self.update_manual_check = true;
                try self.update_message.set("Check requested · mail work takes priority");
                try self.dispatchPending();
            },
            4 => {
                if (self.job.future != null and updateJob(self.job.kind)) self.cancelJob();
                self.update_snapshot.state.manualOnly = !self.update_snapshot.state.manualOnly;
                updates.save(self.io, self.allocator, self.environ, &self.update_snapshot) catch |err| {
                    self.update_snapshot.state.manualOnly = !self.update_snapshot.state.manualOnly;
                    try self.update_message.set(try std.fmt.allocPrint(self.frame.allocator(), "Check preference could not be saved: {s}", .{@errorName(err)}));
                    return;
                };
                if (self.update_snapshot.state.manualOnly) self.update_pending = false else _ = self.scheduleUpdateCheck();
                try self.update_message.set(if (self.update_snapshot.state.manualOnly) "Automatic checks are off · Check again is always available" else "Automatic checks are on · at most once daily");
            },
            5 => try self.copyUpdateText(try updates.agentRequest(self.frame.allocator(), &self.update_snapshot)),
            6 => self.closeUpdates(),
            else => {},
        }
    }
    fn onUpdatesKey(self: *App, key: Key) !void {
        if (key.matches(Key.escape, .{}) or key.matches('q', .{}) or key.matches('c', .{ .ctrl = true })) {
            self.closeUpdates();
        } else if (tabDirection(key)) |backwards| {
            self.update_focus = (self.update_focus + if (backwards) @as(usize, 6) else 1) % 7;
        } else if (key.matches(Key.enter, .{})) {
            try self.activateUpdate(self.update_focus);
        } else if (key.matches('j', .{}) or key.matches(Key.down, .{})) {
            self.update_scroll = @min(self.update_scroll +| 1, self.update_lines -| self.update_height);
        } else if (key.matches('k', .{}) or key.matches(Key.up, .{})) {
            self.update_scroll -|= 1;
        } else if (key.matches('d', .{ .ctrl = true })) {
            self.update_scroll = @min(self.update_scroll +| @max(self.update_height / 2, 1), self.update_lines -| self.update_height);
        } else if (key.matches('u', .{ .ctrl = true })) {
            self.update_scroll -|= @max(self.update_height / 2, 1);
        } else if (key.matches('g', .{ .ctrl = true })) self.update_scroll = 0;
    }
    fn drawUpdates(self: *App, win: vaxis.Window) !void {
        if (!self.update_open) return;
        self.mouse_hits.clear();
        const width = @min(win.width -| 2, 92);
        const height = @min(win.height -| 2, 34);
        const area = win.child(.{ .x_off = @intCast((win.width - width) / 2), .y_off = @intCast((win.height - height) / 2), .width = width, .height = height });
        area.fill(.{ .style = self.style(.text) });
        const inner = self.panel(area, 0, width, " Updates · this installation ", true);
        const labels = [_][]const u8{ "[Copy commands]", "[Release notes]", "[Install guide]", "[Check again]", if (self.update_snapshot.state.manualOnly) "[Checks: manual]" else "[Checks: daily]", "[Copy agent request]", "[Back]" };
        var button_rows: usize = 1;
        var measure_x: usize = 0;
        for (labels) |label| {
            if (measure_x > 0 and measure_x + label.len > inner.width) {
                button_rows += 1;
                measure_x = 0;
            }
            measure_x += label.len + 2;
        }
        if (inner.height <= button_rows + 5) {
            try self.line(inner, 0, try std.fmt.allocPrint(self.frame.allocator(), "Omagma {s}", .{@import("build_options").version}), .subject);
            try self.line(inner, 1, "Resize for the full update guide", .muted);
            _ = try self.actionButton(inner, inner.height -| 2, 0, labels[self.update_focus], true, true, .dialog_action, 400 + self.update_focus);
            try self.line(inner, inner.height -| 1, "Tab Controls · Enter · q Back", .muted);
            return;
        }
        const busy = self.job.future != null and updateJob(self.job.kind);
        const title = if (!self.update_loaded) "Reading release status…" else if (busy) "Checking available releases…" else if (self.update_snapshot.state.latest.slice().len == 0) "No successful release check yet" else if (updates.available(&self.update_snapshot, @import("build_options").version)) "A newer version is available" else if (self.update_snapshot.install.method == .homebrew and updates.isNewer(self.update_snapshot.state.latest.slice(), @import("build_options").version)) "Upstream release · Homebrew package pending or pinned" else if (updates.isNewer(@import("build_options").version, self.update_snapshot.state.latest.slice())) "Running newer than the latest stable release" else "You're up to date";
        try self.line(inner, 0, title, .subject);
        try self.line(inner, 1, try std.fmt.allocPrint(self.frame.allocator(), "Running {s}{s}{s}", .{ @import("build_options").version, if (self.update_snapshot.state.latest.slice().len > 0) @as([]const u8, " · Latest stable ") else "", self.update_snapshot.state.latest.slice() }), .accent);
        const message = if (self.update_message.slice().len > 0) self.update_message.slice() else self.update_snapshot.state.errorMessage.slice();
        try self.line(inner, 2, try self.fitLine(inner, message, inner.width), .muted);
        const footer = inner.height -| @as(u16, @intCast(button_rows + 1));
        const content = inner.child(.{ .y_off = 4, .height = footer -| 5 });
        self.update_height = content.height;
        const guide = if (self.update_loaded) try updates.guide(self.frame.allocator(), &self.update_snapshot) else "Release information loads in the background after cached mail.\nNo additional Gmail permissions are needed.";
        const notes = self.update_snapshot.state.notes.slice();
        const all = if (notes.len > 0) try std.fmt.allocPrint(self.frame.allocator(), "{s}\n\nRelease highlights\n{s}", .{ guide, notes }) else guide;
        self.update_lines = try self.flowTone(content, all, self.update_scroll, 0, .text);
        self.update_scroll = @min(self.update_scroll, self.update_lines -| self.update_height);
        var x: u16 = 0;
        var row: usize = footer;
        for (labels, 0..) |label, index| {
            if (x > 0 and @as(usize, x) + label.len > inner.width) {
                row += 1;
                x = 0;
            }
            x = try self.actionButton(inner, row, x, label, self.update_focus == index, true, .dialog_action, 400 + index);
        }
        const hints = if (inner.width >= 80) "Tab Controls · Enter · j/k Scroll · Ctrl+U/D Page · Ctrl+G Top · Esc/q Back" else "Tab Controls · Enter · j/k Scroll · Esc/q Back";
        try self.line(inner, inner.height -| 1, try self.fitLine(inner, hints, inner.width), .muted);
    }
    fn acknowledgeNewMail(self: *App) void {
        self.last_interaction_at = Io.Timestamp.now(self.io, .real).toMilliseconds();
        self.new_mail.clear();
    }
    fn drawNewMail(self: *App, win: vaxis.Window) !void {
        if (!self.mainScreenNotice() or win.width < 16 or win.height < 9) return;
        const width: u16 = @min(win.width - 2, 54);
        const measure = win.child(.{ .width = width - 4 });
        var rows: usize = 0;
        for (self.new_mail.pending, 0..) |count, index| {
            if (count == 0 or index >= self.accounts.len) continue;
            const address = try safe(self.frame.allocator(), text(get(self.accounts[index], "address")), false);
            rows += positionAfter(measure, address).row + 2;
        }
        const height: u16 = @intCast(@min(rows + 2, win.height - 4));
        const rect: layout.Rect = .{ .x = win.width - width - 1, .y = 2, .width = width, .height = height };
        const area = win.child(.{ .x_off = rect.x, .y_off = rect.y, .width = rect.width, .height = rect.height });
        area.fill(.{ .style = self.style(.text) });
        const inner = self.panel(area, 0, width, " New mail ", true).child(.{ .x_off = 1, .width = width - 4 });
        var row: usize = 0;
        for (self.new_mail.pending, 0..) |count, index| {
            if (count == 0 or index >= self.accounts.len or row >= inner.height) continue;
            const address = try safe(self.frame.allocator(), text(get(self.accounts[index], "address")), false);
            _ = try self.flowTone(inner, address, 0, row, .sender);
            row += positionAfter(inner, address).row + 1;
            try self.line(inner, row, try std.fmt.allocPrint(self.frame.allocator(), "{d} new {s}", .{ count, if (count == 1) @as([]const u8, "message") else "messages" }), .accent);
            row += 1;
        }
        self.notice_rect = rect;
    }
    fn jumpFirstMail(self: *App) !void {
        if (self.follow_ups_list) {
            self.selected = 0;
            self.top = 0;
            return;
        }
        if (self.job.future != null and self.job.kind != .refresh and readOnlyJob(self.job.kind)) self.preemptReadOnly();
        self.completePageLoad();
        self.clearHistory();
        try self.cursor.set(self.allocator, "");
        try self.restore_message.set(self.allocator, "");
        self.selected = 0;
        self.top = 0;
        self.reader_scroll = 0;
        self.focus = .list;
        self.generation +%= 1;
        self.selection_generation +%= 1;
        self.view_ready = false;
        self.first_mail_pending = true;
        if (self.drafts_list) {
            self.pending_page = false;
            try self.next_cursor.set(self.allocator, "");
            try self.previous_cursor.set(self.allocator, "");
            try self.remote_cursor.set(self.allocator, "");
            return self.reloadWithRefresh(false);
        }
        const ready = self.loadCachedList("") catch |err| if (err == error.CacheBusy) false else return err;
        if (!ready and self.job.future == null) try self.reload();
    }
    fn account(self: *const App) []const u8 {
        return if (self.account_index < self.accounts.len) text(get(self.accounts[self.account_index], "address")) else "";
    }
    fn ensureMailSelection(self: *App) !void {
        var scope_buffer: [1024]u8 = undefined;
        const scope = try std.fmt.bufPrint(&scope_buffer, "{d}:{s}:{s}", .{ self.folder, @tagName(self.query_scope), self.activeLabel() });
        try self.mail_selection.ensureScope(self.account(), scope, self.query.value());
    }
    fn batchMail(self: *App, action: []const u8, unread: ?bool, starred: ?bool, add_labels: ?[]const []const u8, remove_labels: ?[]const []const u8) !void {
        if (!self.capabilities.mail_changes) return error.MailChangesUnavailable;
        if (self.drafts_list) return error.DraftNotMail;
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        try self.ensureMailSelection();
        if (self.action_scope_thread and self.mail_selection.count == 0 and !self.action_using_pinned and !self.label_picker) {
            const pending = try std.json.Stringify.valueAlloc(self.allocator, .{ .action = action, .unread = unread, .starred = starred }, .{});
            defer self.allocator.free(pending);
            try self.pending_triage.set(self.allocator, pending);
            self.triage_for_labels = false;
            self.triage_waiting = true;
            try self.triage_subject.set(self.allocator, if (self.focusedMessage()) |message| text(get(message, "subject")) else "");
            try self.pinned_targets.account.set(self.account());
            try self.start(.triage_scope, .{ .cmd = "mail.triage-scope", .account = self.account(), .messageId = self.readerReplyId(), .scope = "conversation" });
            self.say(false, "Resolving exact conversation targets…", .{});
            return;
        }
        var identifiers: [100][]const u8 = undefined;
        const pinned = self.action_using_pinned or self.label_picker or self.mode == .trash_confirm;
        if (pinned and !same(self.pinned_targets.account.slice(), self.account())) return error.AccountContextChanged;
        var count = if (pinned) self.pinned_targets.count else self.mail_selection.count;
        if (count > 0) {
            const selected = if (pinned) &self.pinned_targets else &self.mail_selection;
            for (selected.ids[0..count], 0..) |*identifier, index| identifiers[index] = identifier.slice();
        } else {
            const identifier = if (self.label_picker and self.label_target.value().len > 0) self.label_target.value() else self.readerReplyId();
            if (identifier.len == 0) return;
            identifiers[0] = identifier;
            count = 1;
        }
        try self.action_anchor.set(self.allocator, self.messageId());
        const neighbor = if (self.selected + 1 < self.messages.len) text(get(self.messages[self.selected + 1], "id")) else if (self.selected > 0 and self.selected - 1 < self.messages.len) text(get(self.messages[self.selected - 1], "id")) else "";
        try self.action_neighbor.set(self.allocator, neighbor);
        self.action_screen_row = self.selected -| self.top;
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        defer arena.deinit();
        const encoded = try std.json.Stringify.valueAlloc(arena.allocator(), .{
            .cmd = "mail.batch",
            .account = self.account(),
            .messageIds = identifiers[0..count],
            .action = action,
            .unread = unread,
            .starred = starred,
            .addLabels = add_labels,
            .removeLabels = remove_labels,
        }, .{ .emit_null_optional_fields = false });
        const request_value = try std.json.parseFromSliceLeaky(Value, arena.allocator(), encoded, .{});
        try self.start(.batch, request_value);
        self.label_picker = false;
    }
    fn undoMail(self: *App) !void {
        if (!self.capabilities.mail_changes) return error.MailChangesUnavailable;
        if (self.undo_token.value().len == 0 or !same(self.undo_account.value(), self.account())) {
            self.say(false, "No completed action to undo for this account", .{});
            return;
        }
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        try self.start(.undo, .{ .cmd = "mail.undo", .account = self.account(), .undoToken = self.undo_token.value() });
    }
    fn labelMatches(self: *App, label_value: Value) bool {
        return same(text(get(label_value, "type")), "user") and
            (cache_query.find(text(get(label_value, "name")), self.label_filter.value()) != null or self.label_filter.value().len == 0);
    }
    fn visibleLabelIndex(self: *App, selected: usize) ?usize {
        var found: usize = 0;
        for (self.labels, 0..) |label_value, index| if (self.labelMatches(label_value)) {
            if (found == selected) return index;
            found += 1;
        };
        return null;
    }
    fn visibleLabelCount(self: *App) usize {
        var count: usize = 0;
        for (self.labels) |label_value| if (self.labelMatches(label_value)) {
            count += 1;
        };
        return count;
    }
    fn replaceLabels(self: *App, response: []const u8) !void {
        self.reader_drag_anchor = null;
        self.reader_dragging = false;
        if (self.readerCopyVisible()) self.reader_copy_refresh = true;
        if (self.label_arena) |*arena| arena.deinit();
        self.labels = &.{};
        self.label_arena = .init(self.allocator);
        const result_value = try self.data(self.label_arena.?.allocator(), response);
        self.labels = items(get(result_value, "labels"));
        if (self.labels.len > 512) return error.LabelLimitExceeded;
        try self.labels_account.set(self.allocator, self.account());
        self.pending_labels = false;
        if (self.mode == .label_manager or (self.mode == .help and self.previous_mode == .label_manager)) try self.restoreManagerLabel();
    }
    fn prepareLabels(self: *App) !void {
        if (!self.capabilities.mail_changes) return;
        if (same(self.labels_account.value(), self.account()) and self.labels.len > 0) return;
        self.labels = &.{};
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        defer arena.deinit();
        const labels_response = self.cached(arena.allocator(), .{ .cmd = "labels.list", .account = self.account(), .cacheOnly = true }) catch null;
        if (labels_response) |response| self.replaceLabels(response) catch {};
        const missing = !same(self.labels_account.value(), self.account()) or self.labels.len == 0;
        self.pending_labels = missing and (self.capabilities.refresh_on_account_switch or self.label_picker or self.mode == .label_manager);
    }
    fn openLabelPicker(self: *App) !void {
        if (!self.capabilities.mail_changes) return error.MailChangesUnavailable;
        if (self.drafts_list) return;
        self.selection_generation +%= 1;
        try self.ensureMailSelection();
        try self.pinMailTargets();
        self.label_memberships.reset();
        self.pending_label_state = true;
        try self.label_target.set(self.allocator, self.readerReplyId());
        try self.label_filter.set(self.allocator, "");
        self.label_choice = 0;
        self.label_filtering = false;
        self.label_picker = true;
        self.dialog_focus.reset(.labels, 1);
        try self.prepareLabels();
        if (self.action_scope_thread and self.mail_selection.count == 0) {
            self.preemptReadOnly();
            self.triage_for_labels = true;
            self.triage_waiting = true;
            try self.triage_subject.set(self.allocator, if (self.focusedMessage()) |message| text(get(message, "subject")) else "");
            self.pending_label_state = false;
            try self.start(.triage_scope, .{ .cmd = "mail.triage-scope", .account = self.account(), .messageId = self.label_target.value(), .scope = "conversation" });
            return;
        }
        if (self.pending_labels) self.preemptReadOnly();
        try self.dispatchPending();
    }
    fn chooseLabel(self: *App, remove: bool) !void {
        if (!self.canManageLabels()) return error.PermissionDenied;
        const index = self.visibleLabelIndex(self.label_choice) orelse return;
        const label = text(get(self.labels[index], "id"));
        try self.label_memberships.stage(label, if (remove) .remove else .add);
        self.say(false, "{d} label change{s} staged · Apply submits · Cancel keeps labels", .{ self.label_memberships.changed(), if (self.label_memberships.changed() == 1) @as([]const u8, "") else "s" });
    }
    fn pinMailTargets(self: *App) !void {
        self.pinned_targets.clear();
        try self.pinned_targets.account.set(self.account());
        try self.triage_subject.set(self.allocator, if (self.focusedMessage()) |message| text(get(message, "subject")) else "");
        if (self.mail_selection.count > 0) {
            for (self.mail_selection.ids[0..self.mail_selection.count]) |id| try self.pinned_targets.toggle(id.slice());
        } else {
            const id = self.readerReplyId();
            if (id.len == 0) return error.MessageRequired;
            try self.pinned_targets.toggle(id);
        }
    }
    fn requestLabelState(self: *App) !void {
        if (self.pinned_targets.count == 0 or !same(self.pinned_targets.account.slice(), self.account())) return error.AccountContextChanged;
        var identifiers: [100][]const u8 = undefined;
        for (self.pinned_targets.ids[0..self.pinned_targets.count], 0..) |*id, index| identifiers[index] = id.slice();
        self.pending_label_state = false;
        try self.start(.label_state, .{ .cmd = "mail.label-state", .account = self.account(), .messageIds = identifiers[0..self.pinned_targets.count] });
    }
    fn applyLabels(self: *App) !void {
        if (!self.canManageLabels()) return error.PermissionDenied;
        if (!self.label_memberships.ready) return error.LabelStatePending;
        var additions: [512][]const u8 = undefined;
        var removals: [512][]const u8 = undefined;
        var added: usize = 0;
        var removed: usize = 0;
        for (self.label_memberships.entries[0..self.label_memberships.count]) |*entry| switch (entry.desired) {
            .add => {
                additions[added] = entry.id.slice();
                added += 1;
            },
            .remove => {
                removals[removed] = entry.id.slice();
                removed += 1;
            },
            .unchanged => {},
        };
        if (added + removed == 0) {
            self.label_picker = false;
            return;
        }
        self.action_using_pinned = true;
        defer self.action_using_pinned = false;
        try self.batchMail("mark", null, null, additions[0..added], removals[0..removed]);
    }
    fn cancelLabelPicker(self: *App) void {
        self.label_picker = false;
        self.pending_label_state = false;
        self.triage_waiting = false;
        self.selection_generation +%= 1;
        self.label_memberships.reset();
        if (self.job.future != null and (self.job.kind == .label_state or self.job.kind == .triage_scope)) self.preemptReadOnly();
    }
    fn onLabelPickerKey(self: *App, key: Key) !void {
        self.dialog_focus.ensure(.labels, 1);
        if (self.paste) {
            if (self.dialog_focus.index == 0) if (key.text) |raw| try self.label_filter.insert(self.allocator, try safe(self.frame.allocator(), raw, false), 256);
            return;
        }
        const count = self.visibleLabelCount();
        if (tabDirection(key)) |backwards| {
            var enabled: u8 = 0b100011;
            if (self.label_memberships.ready and self.canManageLabels()) {
                if (count > 0) enabled |= 0b001100;
                if (self.label_memberships.changed() > 0) enabled |= 0b010000;
            }
            self.dialog_focus.move(backwards, 6, enabled);
            self.label_filtering = self.dialog_focus.index == 0;
            return;
        }
        if (self.dialog_focus.index == 0) {
            if (key.matches(Key.escape, .{}) or key.matches(Key.enter, .{})) {
                self.dialog_focus.index = 1;
                self.label_filtering = false;
            } else {
                try self.label_filter.handleKey(self.allocator, key, false, 256);
                self.label_choice = 0;
            }
            return;
        }
        if (key.matches(Key.escape, .{}) or key.matches('q', .{})) {
            self.label_picker = false;
            self.pending_label_state = false;
            self.triage_waiting = false;
            self.selection_generation +%= 1;
            if (self.job.future != null and (self.job.kind == .label_state or self.job.kind == .triage_scope)) self.preemptReadOnly();
            self.label_memberships.reset();
        } else if (key.matches('r', .{ .ctrl = true })) {
            self.pending_label_state = true;
            self.preemptReadOnly();
            try self.dispatchPending();
        } else if (key.matches('/', .{})) {
            self.dialog_focus.index = 0;
            self.label_filtering = true;
        } else if (key.matches('j', .{}) or key.matches(Key.down, .{})) {
            self.dialog_focus.index = 1;
            self.label_choice = @min(self.label_choice +| 1, count -| 1);
        } else if (key.matches('k', .{}) or key.matches(Key.up, .{})) {
            self.dialog_focus.index = 1;
            self.label_choice -|= 1;
        } else if (key.matches(Key.home, .{}) or key.matches('g', .{ .ctrl = true })) self.label_choice = 0 else if (key.matches(Key.end, .{})) self.label_choice = count -| 1 else if (key.matches(Key.enter, .{})) {
            switch (self.dialog_focus.index) {
                1 => {
                    const at = self.visibleLabelIndex(self.label_choice) orelse return;
                    try self.label_memberships.toggle(text(get(self.labels[at], "id")));
                },
                2 => try self.chooseLabel(false),
                3 => try self.chooseLabel(true),
                4 => try self.applyLabels(),
                5 => self.cancelLabelPicker(),
                else => {},
            }
        } else if (key.matches(' ', .{})) {
            const at = self.visibleLabelIndex(self.label_choice) orelse return;
            try self.label_memberships.toggle(text(get(self.labels[at], "id")));
        } else if (key.matches('s', .{ .ctrl = true })) try self.applyLabels() else if (key.matches('+', .{})) try self.chooseLabel(false) else if (key.matches('-', .{})) try self.chooseLabel(true);
    }
    fn drawLabelPicker(self: *App, win: vaxis.Window) !void {
        if (!self.label_picker) return;
        self.dialog_focus.ensure(.labels, 1);
        const width = @min(win.width -| 2, 72);
        const height = @min(win.height -| 2, 24);
        if (width < 24 or height < 8) return;
        const area = win.child(.{ .x_off = @intCast((win.width - width) / 2), .y_off = @intCast((win.height - height) / 2), .width = width, .height = height });
        area.fill(.{ .style = self.style(.text) });
        const inner = self.panel(area, 0, width, " Labels · staged changes ", true);
        self.mouse_hits.clear();
        const compact = inner.width < 54;
        const count = self.visibleLabelCount();
        const changes = self.label_memberships.changed();
        const editable = self.label_memberships.ready and self.canManageLabels() and !self.labelManagerBusy();
        const can_stage = editable and count > 0;
        const can_apply = editable and changes > 0;
        if (((self.dialog_focus.index == 2 or self.dialog_focus.index == 3) and !can_stage) or (self.dialog_focus.index == 4 and !can_apply)) self.dialog_focus.index = 5;
        const target_count = self.pinned_targets.count;
        const conversation = self.action_scope_thread and self.mail_selection.count == 0;
        const scope = if (conversation) @as([]const u8, "Conversation · complete") else "Messages";
        const context = if (self.triage_waiting)
            try std.fmt.allocPrint(self.frame.allocator(), "Resolving thread · [{d}]", .{self.account_index + 1})
        else if (inner.width < 34)
            try std.fmt.allocPrint(self.frame.allocator(), "{d} {s} · [{d} {s}]", .{ target_count, if (conversation) @as([]const u8, "thread") else "msg", self.account_index + 1, std.mem.sliceTo(self.account(), '@') })
        else if (compact)
            try std.fmt.allocPrint(self.frame.allocator(), "{d} {s} · {s}", .{ target_count, if (conversation) @as([]const u8, "thread msg") else "messages", self.account() })
        else
            try std.fmt.allocPrint(self.frame.allocator(), "{s}: {d} · {s} · {d} changes", .{ scope, target_count, self.account(), changes });
        try self.line(inner, 0, try self.fitLine(inner, context, inner.width), .muted);
        const filtering = self.dialog_focus.index == 0;
        try self.line(inner, 1, try std.fmt.allocPrint(self.frame.allocator(), "Filter: {s}{s}", .{ self.label_filter.value(), if (filtering) "▏" else "" }), if (filtering) .selected else .muted);
        self.mouseRows(inner, 1, 1, .label_filter, 0);
        const button_rows: usize = if (compact) 2 else 1;
        const button_start: usize = inner.height -| (button_rows + 1);
        const rows: usize = button_start -| 2;
        self.label_choice = @min(self.label_choice, count -| 1);
        const first = if (self.label_choice >= rows and rows > 0) self.label_choice - rows + 1 else 0;
        if (count == 0 and rows > 0) try self.line(inner, 2, if (self.pending_labels or (self.job.future != null and self.job.kind == .labels_list)) "Loading labels…" else "No matching labels", .muted);
        for (first..@min(count, first + rows)) |choice| {
            const index = self.visibleLabelIndex(choice) orelse continue;
            const label = self.labels[index];
            const identifier = text(get(label, "id"));
            const marker = self.label_memberships.mark(identifier);
            const entry = self.label_memberships.get(identifier);
            const changed = if (entry) |value| value.desired != .unchanged else false;
            const colored = text(get(get(label, "color"), "backgroundColor")).len == 7;
            const caption = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}{s} {s}", .{ marker, if (changed) @as([]const u8, "*") else " ", if (colored) @as([]const u8, " ●") else "", text(get(label, "name")) });
            const focused = choice == self.label_choice and self.dialog_focus.index == 1;
            const tone: Tone = if (focused) .selected else if (!self.label_memberships.ready) .muted else if (choice == self.label_choice) .subject else .text;
            const row = inner.child(.{ .y_off = @intCast(choice - first + 2), .height = 1 });
            row.fill(.{ .style = self.style(tone) });
            try self.line(row, 0, try self.fitLine(row, caption, row.width), tone);
            if (colored and row.width > 5) _ = row.child(.{ .x_off = 5, .width = 1 }).printSegment(.{ .text = "●", .style = self.labelColorStyle(label, focused) }, .{ .wrap = .none });
            self.mouseArea(row, .label_choice, choice);
        }
        if (inner.height > 1) {
            var x = try self.actionButton(inner, button_start, 0, "[+ Add]", self.dialog_focus.index == 2, can_stage, .label_add, 0);
            x = try self.actionButton(inner, button_start, x, if (compact) "[- Rm]" else "[- Remove]", self.dialog_focus.index == 3, can_stage, .label_remove, 0);
            if (compact) x = 0;
            const apply_row = button_start + @as(usize, if (compact) 1 else 0);
            const apply_label = try std.fmt.allocPrint(self.frame.allocator(), "[Apply {d}]", .{changes});
            x = try self.actionButton(inner, apply_row, x, apply_label, self.dialog_focus.index == 4, can_apply, .dialog_action, 20);
            _ = try self.actionButton(inner, apply_row, x, "[Cancel]", self.dialog_focus.index == 5, true, .label_back, 0);
            const hint = if (!self.label_memberships.ready) @as([]const u8, "Reading current labels…") else if (!self.canManageLabels()) "Read-only · Cancel keeps labels" else if (compact) "Space Toggle · Tab · Esc" else "Space Toggle · +/- Stage · Ctrl+S Apply · Esc Cancel";
            try self.line(inner, inner.height - 1, try self.fitLine(inner, hint, inner.width), .muted);
        }
    }
    fn canManageLabels(self: *const App) bool {
        if (self.account_index >= self.accounts.len or self.label_unknown[self.account_index]) return false;
        for (items(get(self.accounts[self.account_index], "capabilities"))) |capability| if (same(text(capability), "mail-modify")) return true;
        return false;
    }
    fn labelManagerBusy(self: *const App) bool {
        return self.job.future != null and !readOnlyJob(self.job.kind);
    }
    fn rememberManagerLabel(self: *App) !void {
        const index = self.visibleLabelIndex(self.label_choice);
        try self.label_manager_selected.set(self.allocator, if (index) |at| text(get(self.labels[at], "id")) else "");
    }
    fn restoreManagerLabel(self: *App) !void {
        var visible: usize = 0;
        for (self.labels) |label_value| if (self.labelMatches(label_value)) {
            if (same(text(get(label_value, "id")), self.label_manager_selected.value())) {
                self.label_choice = visible;
                return;
            }
            visible += 1;
        };
        self.label_choice = @min(self.label_choice, visible -| 1);
        try self.rememberManagerLabel();
    }
    fn openLabelManager(self: *App) !void {
        if (!self.capabilities.mail_changes) return error.MailChangesUnavailable;
        self.label_picker = false;
        self.label_manager_page = .list;
        try self.label_manager_account.set(self.allocator, self.account());
        try self.label_manager_selected.set(self.allocator, "");
        try self.label_filter.set(self.allocator, "");
        self.label_choice = 0;
        self.mode = .label_manager;
        self.dialog_focus.reset(.label_manager, 1);
        try self.prepareLabels();
        try self.rememberManagerLabel();
        if (self.pending_labels) self.preemptReadOnly();
        try self.dispatchPending();
        if (self.label_unknown[self.account_index]) self.labelUnknownNotice() else if (!self.canManageLabels()) self.say(true, "Read-only labels · terminal access needs mail-modify", .{});
    }
    fn closeLabelManager(self: *App) void {
        self.mode = .browse;
        self.label_manager_page = .list;
    }
    fn labelUnknownNotice(self: *App) void {
        self.say(true, "Label outcome unknown · Ctrl+R checks receipt · do not retry · {s}", .{self.label_operations[self.account_index].value()});
        self.status_kind = .unknown;
    }
    fn editManagerLabel(self: *App, editor_page: LabelManagerPage) !void {
        if (!self.canManageLabels() or self.labelManagerBusy()) return;
        if (!same(self.label_manager_account.value(), self.account())) return error.WrongAccount;
        if (editor_page == .create) {
            try self.label_manager_id.set(self.allocator, "");
            try self.label_manager_name.set(self.allocator, "");
            try self.label_manager_input.set(self.allocator, "");
        } else {
            const index = self.visibleLabelIndex(self.label_choice) orelse return;
            try self.label_manager_id.set(self.allocator, text(get(self.labels[index], "id")));
            try self.label_manager_name.set(self.allocator, text(get(self.labels[index], "name")));
            try self.label_manager_input.set(self.allocator, self.label_manager_name.value());
        }
        self.label_manager_page = editor_page;
        self.label_delete_ready = false;
        self.dialog_focus.reset(if (editor_page == .delete) .label_delete else .label_name, 0);
    }
    fn submitManagerLabel(self: *App) !void {
        if (!self.canManageLabels() or self.labelManagerBusy()) return;
        if (!same(self.label_manager_account.value(), self.account())) return error.WrongAccount;
        const editor_page = self.label_manager_page;
        if (editor_page == .list) return;
        if (editor_page == .delete and !self.label_delete_ready) {
            self.say(true, "Resize to review label deletion before confirming", .{});
            return;
        }
        const name = std.mem.trim(u8, self.label_manager_input.value(), " \t\r\n");
        if (editor_page != .delete and name.len == 0) {
            self.say(true, "Enter a label name", .{});
            self.dialog_focus.index = 0;
            return;
        }
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        const id = try self.operationId(self.allocator);
        defer self.allocator.free(id);
        try self.label_operations[self.account_index].set(self.allocator, id);
        try self.label_errors[self.account_index].set(self.allocator, "");
        self.label_write_page[self.account_index] = editor_page;
        self.label_color_write[self.account_index] = false;
        if (editor_page == .create) try self.start(.label_write, .{ .cmd = "labels.create", .account = self.label_manager_account.value(), .name = name, .operationId = id }) else if (editor_page == .rename) try self.start(.label_write, .{ .cmd = "labels.rename", .account = self.label_manager_account.value(), .labelId = self.label_manager_id.value(), .name = name, .operationId = id }) else try self.start(.label_write, .{ .cmd = "labels.delete", .account = self.label_manager_account.value(), .labelId = self.label_manager_id.value(), .operationId = id, .confirmName = self.label_manager_name.value() });
    }
    fn labelColorStyle(self: *App, label: Value, focused: bool) vaxis.Style {
        var result = self.style(if (focused) .selected else .text);
        if (self.mono) return result;
        const color = get(label, "color");
        const background = text(get(color, "backgroundColor"));
        const foreground = text(get(color, "textColor"));
        if (background.len != 7 or background[0] != '#') return result;
        var rgb: [3]u8 = undefined;
        for (&rgb, 0..) |*channel, index| channel.* = std.fmt.parseInt(u8, background[1 + index * 2 .. 3 + index * 2], 16) catch return result;
        result.bg = .{ .rgb = rgb };
        if (foreground.len == 7 and foreground[0] == '#') {
            var ink: [3]u8 = undefined;
            for (&ink, 0..) |*channel, index| channel.* = std.fmt.parseInt(u8, foreground[1 + index * 2 .. 3 + index * 2], 16) catch return result;
            result.fg = .{ .rgb = ink };
        }
        return result;
    }
    fn openLabelColors(self: *App) !void {
        if (!self.canManageLabels() or self.labelManagerBusy()) return;
        if (!same(self.label_manager_account.value(), self.account())) return error.WrongAccount;
        const at = self.visibleLabelIndex(self.label_choice) orelse return;
        const label = self.labels[at];
        const identifier = text(get(label, "id"));
        if (!same(text(get(label, "type")), "user") or @import("labels.zig").reserved(identifier)) return error.SystemLabelImmutable;
        const current = text(get(get(label, "color"), "backgroundColor"));
        try self.ux_target.set(self.allocator, identifier);
        try self.beginUx(.label_colors, " Label color ");
        const a = self.ux_arena.?.allocator();
        self.ux_title = try std.fmt.allocPrint(a, " Color · {s} ", .{text(get(label, "name"))});
        for (@import("labels.zig").palette, 0..) |hex, position| {
            var rgb: [3]u8 = undefined;
            for (&rgb, 0..) |*channel, index| channel.* = try std.fmt.parseInt(u8, hex[1 + index * 2 .. 3 + index * 2], 16);
            var linear: [3]f64 = undefined;
            for (rgb, &linear) |channel, *value| {
                const srgb = @as(f64, @floatFromInt(channel)) / 255.0;
                value.* = if (srgb <= 0.04045) srgb / 12.92 else std.math.pow(f64, (srgb + 0.055) / 1.055, 2.4);
            }
            const luma = linear[0] * 0.2126 + linear[1] * 0.7152 + linear[2] * 0.0722;
            const light_text = luma < 0.179;
            const highest = @max(rgb[0], @max(rgb[1], rgb[2]));
            const lowest = @min(rgb[0], @min(rgb[1], rgb[2]));
            const delta = @as(f64, @floatFromInt(highest - lowest));
            var hue: f64 = 0;
            if (delta >= 20) {
                const red = @as(f64, @floatFromInt(rgb[0]));
                const green = @as(f64, @floatFromInt(rgb[1]));
                const blue = @as(f64, @floatFromInt(rgb[2]));
                hue = if (highest == rgb[0]) 60 * (green - blue) / delta else if (highest == rgb[1]) 120 + 60 * (blue - red) / delta else 240 + 60 * (red - green) / delta;
                if (hue < 0) hue += 360;
            }
            const name: []const u8 = if (delta < 20) (if (highest > 230) "White" else if (highest < 70) "Black" else "Grey") else if (hue < 15 or hue >= 345) "Red" else if (hue < 45) "Orange" else if (hue < 75) "Yellow" else if (hue < 165) "Green" else if (hue < 205) "Teal" else if (hue < 255) "Blue" else if (hue < 290) "Purple" else "Pink";
            const selected = std.ascii.eqlIgnoreCase(current, hex);
            const caption = try std.fmt.allocPrint(a, "{s} {s}{s}", .{ name, hex, if (selected) @as([]const u8, " · current") else "" });
            try self.uxRow(.{ .label = caption, .detail = if (light_text) "White text on this label color" else "Black text on this label color", .value = hex, .index = if (light_text) 0 else 1 });
            if (selected) self.ux_selected = position;
        }
        // Opening color management must not submit on an unprompted Enter.
        self.ux_focus = 3;
    }
    fn managerListAction(self: *App, index: usize) !void {
        switch (index) {
            2 => try self.editManagerLabel(.create),
            3 => try self.editManagerLabel(.rename),
            4 => try self.openLabelColors(),
            5 => try self.editManagerLabel(.delete),
            1, 6 => {
                if (self.labelManagerBusy()) return;
                const at = self.visibleLabelIndex(self.label_choice) orelse return;
                self.closeLabelManager();
                try self.chooseCustomLabel(at);
            },
            7 => self.closeLabelManager(),
            else => {},
        }
    }
    fn managerEnabled(self: *App) u8 {
        const have_label = self.visibleLabelCount() > 0;
        const can_write = self.canManageLabels() and !self.labelManagerBusy();
        return @as(u8, 0b10000011) | (if (have_label and !self.labelManagerBusy()) @as(u8, 0b01000000) else 0) | (if (can_write) @as(u8, 0b00000100) else 0) | (if (can_write and have_label) @as(u8, 0b00111000) else 0);
    }
    fn onLabelManagerKey(self: *App, key: Key) !void {
        if (!same(self.label_manager_account.value(), self.account())) {
            self.closeLabelManager();
            return;
        }
        if (self.paste) {
            const field: ?*Field = if (self.label_manager_page == .list and self.dialog_focus.index == 0) &self.label_filter else if ((self.label_manager_page == .create or self.label_manager_page == .rename) and self.dialog_focus.index == 0 and !self.labelManagerBusy()) &self.label_manager_input else null;
            if (field) |target| if (key.text) |raw| {
                try target.insert(self.allocator, try safe(self.frame.allocator(), raw, false), 256);
                if (self.label_manager_page == .list) {
                    self.label_choice = 0;
                    try self.rememberManagerLabel();
                }
            };
            return;
        }
        if (key.matches('c', .{ .ctrl = true }) or key.matches('q', .{ .ctrl = true })) {
            self.closeLabelManager();
            return;
        }
        if (self.label_manager_page != .list) {
            const deleting = self.label_manager_page == .delete;
            if (tabDirection(key)) |backwards| {
                self.dialog_focus.move(backwards, if (deleting) 2 else 3, if (self.labelManagerBusy()) (if (deleting) @as(u8, 0b01) else 0b100) else if (deleting) (if (self.label_delete_ready) @as(u8, 0b11) else 0b01) else 0b111);
            } else if (key.matches(Key.escape, .{}) or (deleting and (key.matches('q', .{}) or key.matches('n', .{}))) or (key.matches(Key.enter, .{}) and self.dialog_focus.index == (if (deleting) @as(usize, 0) else 2))) {
                self.label_manager_page = .list;
                self.dialog_focus.reset(.label_manager, 1);
            } else if (self.labelManagerBusy()) return else if (deleting) {
                if (key.matches('y', .{}) or (key.matches(Key.enter, .{}) and self.dialog_focus.index == 1)) try self.submitManagerLabel();
            } else if (key.matches('s', .{ .ctrl = true }) or (key.matches(Key.enter, .{}) and self.dialog_focus.index == 1)) try self.submitManagerLabel() else if (self.dialog_focus.index == 0) {
                // Enter in Name moves to Save; typing never invokes action letters.
                if (key.matches(Key.enter, .{})) self.dialog_focus.index = 1 else try self.label_manager_input.handleKey(self.allocator, key, false, 256);
            }
            return;
        }
        if (tabDirection(key)) |backwards| {
            self.dialog_focus.move(backwards, 8, self.managerEnabled());
            return;
        }
        if (self.dialog_focus.index == 0) {
            if (key.matches(Key.enter, .{}) or key.matches(Key.escape, .{})) self.dialog_focus.index = 1 else {
                try self.label_filter.handleKey(self.allocator, key, false, 256);
                self.label_choice = 0;
                try self.rememberManagerLabel();
            }
            return;
        }
        if (key.matches(Key.escape, .{}) or key.matches('q', .{})) self.closeLabelManager() else if (key.matches('/', .{})) self.dialog_focus.index = 0 else if (key.matches('j', .{}) or key.matches(Key.down, .{}) or key.matches('k', .{}) or key.matches(Key.up, .{})) {
            self.dialog_focus.index = 1;
            self.label_choice = if (key.matches('j', .{}) or key.matches(Key.down, .{})) @min(self.label_choice +| 1, self.visibleLabelCount() -| 1) else self.label_choice -| 1;
            try self.rememberManagerLabel();
        } else if (key.matches('g', .{ .ctrl = true })) {
            self.label_choice = 0;
            try self.rememberManagerLabel();
        } else if (key.matches('n', .{})) try self.managerListAction(2) else if (key.matches('r', .{})) try self.managerListAction(3) else if (key.matches('c', .{})) try self.managerListAction(4) else if (key.matches('d', .{})) try self.managerListAction(5) else if (key.matches('o', .{})) try self.managerListAction(6) else if (key.matches(Key.enter, .{})) try self.managerListAction(self.dialog_focus.index) else if (key.matches('r', .{ .ctrl = true })) {
            if (self.label_unknown[self.account_index]) {
                self.preemptReadOnly();
                if (self.job.future == null) try self.start(.label_receipt, .{ .cmd = "operation.read", .account = self.account(), .operationId = self.label_operations[self.account_index].value() });
            } else {
                self.pending_labels = true;
                self.preemptReadOnly();
                try self.dispatchPending();
            }
        } else if (key.matches('?', .{})) try self.openHelp();
    }
    fn applyManagerLabel(self: *App, response: []const u8) !void {
        const result = try self.data(self.job_arena.allocator(), response);
        const index = self.job.account_index;
        if (index != self.account_index) return;
        const outcome = text(get(result, "outcome"));
        const operation_id = text(get(result, "operationId"));
        const raw_id = text(get(result, "id"));
        if (operation_id.len > 0) try self.label_operations[index].set(self.allocator, operation_id) else if (raw_id.len > 0) try self.label_operations[index].set(self.allocator, raw_id);
        if (same(outcome, "unknown")) {
            self.label_unknown[index] = true;
            try self.label_errors[index].set(self.allocator, text(get(result, "errorCode")));
            self.label_manager_page = .list;
            self.dialog_focus.reset(.label_manager, 1);
            self.labelUnknownNotice();
            return;
        }
        if (same(outcome, "rejected")) {
            self.label_unknown[index] = false;
            const code = text(get(result, "errorCode"));
            try self.label_errors[index].set(self.allocator, code);
            self.sayError(if (code.len > 0) code else "ProviderRejected");
            return;
        }
        if (!same(outcome, "applied")) {
            self.label_unknown[index] = true;
            self.label_manager_page = .list;
            self.dialog_focus.reset(.label_manager, 1);
            self.labelUnknownNotice();
            return;
        }
        self.label_unknown[index] = false;
        const deleting = truth(get(result, "deleted"));
        const label_id = text(get(result, "labelId"));
        try self.label_manager_selected.set(self.allocator, if (deleting) "" else label_id);
        if (self.label_write_page[index] == .create) try self.label_filter.set(self.allocator, "");
        self.label_manager_page = .list;
        self.dialog_focus.reset(.label_manager, 1);
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        defer arena.deinit();
        const cached_labels = self.cached(arena.allocator(), .{ .cmd = "labels.list", .account = self.account(), .cacheOnly = true }) catch null;
        if (cached_labels) |labels_response| try self.replaceLabels(labels_response) else self.pending_labels = true;
        if (deleting) {
            const selected_message = try arena.allocator().dupe(u8, self.messageId());
            if (same(self.custom_label.value(), label_id)) {
                try self.custom_label.set(self.allocator, "");
                self.folder = 0;
                self.drafts_list = false;
                self.query_scope = .cache;
                try self.query.set(self.allocator, "");
                self.selected = 0;
                self.top = 0;
            }
            self.clearHistory();
            try self.cursor.set(self.allocator, "");
            self.generation +%= 1;
            self.clearReader();
            _ = self.loadCachedList(selected_message) catch |err| if (err == error.CacheBusy) false else return err;
        }
        if (self.label_color_write[index]) self.sayAction(false, "Label color: applied", .{}) else self.sayAction(false, "Label {s} · emails kept", .{if (deleting) @as([]const u8, "deleted") else if (self.label_write_page[index] == .create) "created" else "renamed"});
        self.label_color_write[index] = false;
    }
    fn labelManagerButtonRows(self: *App, win: vaxis.Window) usize {
        _ = self;
        const short = win.width < 64;
        const tiny = win.width < 30;
        const labels = [_][]const u8{ "[n New]", if (short) "[r Ren]" else "[r Rename]", if (short) "[c Col]" else "[c Color]", if (short) "[d Del]" else "[d Delete]", if (tiny) "[o Op]" else "[o Open]", "[q Back]" };
        var rows: usize = 1;
        var x: usize = 0;
        for (labels) |label| {
            if (x > 0 and x + label.len > win.width) {
                rows += 1;
                x = 0;
            }
            x += label.len + @as(usize, if (win.width < 26) 1 else 2);
        }
        return rows;
    }
    fn drawLabelManager(self: *App, win: vaxis.Window) !void {
        if (self.mode != .label_manager) return;
        const width = @min(win.width -| 2, 74);
        const height = @min(win.height -| 2, if (self.label_manager_page == .list) @as(u16, 26) else if (self.label_manager_page == .delete) @as(u16, 20) else 11);
        const area = win.child(.{ .x_off = @intCast((win.width - width) / 2), .y_off = @intCast((win.height - height) / 2), .width = width, .height = height });
        area.fill(.{ .style = self.style(.text) });
        const title = switch (self.label_manager_page) {
            .list => " Manage labels ",
            .create => " New label ",
            .rename => " Rename label ",
            .delete => " Delete label? ",
        };
        const inner = self.panel(area, 0, width, title, true);
        self.mouse_hits.clear();
        const account_line = try std.fmt.allocPrint(self.frame.allocator(), "Account: {s}", .{self.label_manager_account.value()});
        if (self.label_manager_page == .list) {
            try self.line(inner, 0, try self.fitLine(inner, account_line, inner.width), .muted);
            try self.line(inner, 1, try std.fmt.allocPrint(self.frame.allocator(), "Filter: {s}{s}", .{ self.label_filter.value(), if (self.dialog_focus.index == 0) "▏" else "" }), if (self.dialog_focus.index == 0) .selected else .muted);
            self.mouseRows(inner, 1, 1, .label_manager_filter, 0);
            const button_rows = self.labelManagerButtonRows(inner);
            const button_start = inner.height -| (button_rows + 1);
            const rows = button_start -| 2;
            const count = self.visibleLabelCount();
            self.label_choice = @min(self.label_choice, count -| 1);
            const first = if (self.label_choice >= rows and rows > 0) self.label_choice - rows + 1 else 0;
            if (count == 0 and rows > 0) try self.line(inner, 2, if (self.pending_labels or (self.job.future != null and self.job.kind == .labels_list)) "Loading labels…" else if (self.label_filter.value().len > 0) "No matching labels" else "No custom labels · n New", .muted);
            for (first..@min(count, first + rows)) |choice| {
                const at = self.visibleLabelIndex(choice) orelse continue;
                const label = self.labels[at];
                const colored = text(get(get(label, "color"), "backgroundColor")).len == 7;
                const focused = choice == self.label_choice and self.dialog_focus.index == 1;
                const tone: Tone = if (focused) .selected else if (choice == self.label_choice) .subject else .text;
                const item = inner.child(.{ .y_off = @intCast(choice - first + 2), .height = 1 });
                item.fill(.{ .style = self.style(tone) });
                const caption = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}{s}", .{ if (choice == self.label_choice) @as([]const u8, "> ") else "  ", if (colored) @as([]const u8, "● ") else "", text(get(label, "name")) });
                try self.line(item, 0, try self.fitLine(item, caption, item.width), tone);
                if (colored and item.width > 2) _ = item.child(.{ .x_off = 2, .width = 1 }).printSegment(.{ .text = "●", .style = self.labelColorStyle(label, focused) }, .{ .wrap = .none });
                self.mouseArea(item, .label_manager_choice, choice);
            }
            const short = inner.width < 64;
            const tiny = inner.width < 30;
            const labels = [_][]const u8{ "[n New]", if (short) "[r Ren]" else "[r Rename]", if (short) "[c Col]" else "[c Color]", if (short) "[d Del]" else "[d Delete]", if (tiny) "[o Op]" else "[o Open]", "[q Back]" };
            var x: u16 = 0;
            var row: usize = button_start;
            const enabled = self.managerEnabled();
            for (labels, 0..) |label, offset| {
                if (x > 0 and x + label.len > inner.width) {
                    row += 1;
                    x = 0;
                }
                const index = offset + 2;
                x = try self.actionButton(inner, row, x, label, self.dialog_focus.index == index, enabled & (@as(u8, 1) << @intCast(index)) != 0, .label_manager_action, index);
            }
            try self.line(inner, inner.height -| 1, if (self.label_unknown[self.account_index]) "Unknown · Ctrl+R Receipt" else if (!self.canManageLabels()) "Read-only · mail-modify needed" else if (inner.width < 50) "/ Filter · Tab · Enter · Esc" else "Tab Controls · Enter Open · c Color · Ctrl+R Refresh", .muted);
            return;
        }
        if (self.label_manager_page == .delete) {
            self.label_delete_ready = false;
            const details = try std.fmt.allocPrint(self.frame.allocator(), "{s}\nLabel: {s}\n\nEmails are kept; this removes the label from all messages.", .{ account_line, self.label_manager_name.value() });
            const clean = try safe(self.frame.allocator(), details, true);
            const needed = positionAfter(inner, clean).row + 1;
            if (needed <= inner.height -| 3) {
                _ = try self.flow(inner, clean, 0, 0);
                self.label_delete_ready = true;
            } else {
                _ = try self.flow(inner.child(.{ .height = inner.height -| 3 }), clean, 0, 0);
                try self.line(inner, inner.height -| 3, "Resize to review deletion", .warning);
            }
            const x = try self.actionButton(inner, inner.height -| 2, 0, "[Cancel]", self.dialog_focus.index == 0, true, .label_manager_action, 0);
            _ = try self.actionButton(inner, inner.height -| 2, x, "[y Delete]", self.dialog_focus.index == 1, self.label_delete_ready and !self.labelManagerBusy() and self.canManageLabels(), .label_manager_action, 1);
            try self.line(inner, inner.height -| 1, "Tab · Enter · Esc Cancel", .muted);
            return;
        }
        try self.line(inner, 0, try self.fitLine(inner, account_line, inner.width), .muted);
        if (self.label_manager_page == .rename) try self.line(inner, 1, try self.fitLine(inner, try std.fmt.allocPrint(self.frame.allocator(), "Was: {s}", .{self.label_manager_name.value()}), inner.width), .muted);
        const name_row: usize = if (self.label_manager_page == .rename) 2 else 1;
        try self.editLine(inner, name_row, "Name", &self.label_manager_input, self.dialog_focus.index == 0, if (self.dialog_focus.index == 0) .selected else .text);
        self.mouseRows(inner, name_row, 1, .label_manager_name, 0);
        const x = try self.actionButton(inner, inner.height -| 2, 0, "[Save Ctrl+S]", self.dialog_focus.index == 1, !self.labelManagerBusy() and self.canManageLabels(), .label_manager_action, 1);
        _ = try self.actionButton(inner, inner.height -| 2, x, "[Cancel]", self.dialog_focus.index == 2, true, .label_manager_action, 2);
        try self.line(inner, inner.height -| 1, if (inner.width < 40) "Tab · Enter · Esc · q is text" else "Tab Controls · Enter Save · Esc Cancel · q is text", .muted);
    }
    fn onMailControls(self: *App, key: Key) !bool {
        if (self.mode != .browse) return false;
        try self.ensureMailSelection();
        if ((key.matches('q', .{}) or key.matches(Key.escape, .{})) and self.mail_selection.count > 0) {
            self.mail_selection.clear();
            self.say(false, "Selection cleared", .{});
            return true;
        }
        if (key.matches(' ', .{}) and self.focus == .list and !self.drafts_list and !self.follow_ups_list) {
            const id = self.messageId();
            if (id.len > 0) {
                try self.mail_selection.toggle(id);
                try self.move(true, 1);
            }
            self.say(false, "{d} selected · x Archive · D Trash · m Label · :undo", .{self.mail_selection.count});
            return true;
        }
        if (key.matches('a', .{ .ctrl = true }) and self.focus == .list and !self.drafts_list and !self.follow_ups_list) {
            self.mail_selection.clear();
            for (self.messages) |message| try self.mail_selection.toggle(text(get(message, "id")));
            self.say(false, "{d} selected on this page", .{self.mail_selection.count});
            return true;
        }
        if (key.matches('z', .{ .ctrl = true })) {
            try self.undoMail();
            return true;
        }
        if (key.matches('m', .{})) {
            try self.openLabelPicker();
            return true;
        }
        if (key.matches('x', .{})) {
            try self.batchMail("archive", null, null, null, null);
            return true;
        }
        if (key.matches('D', .{}) or key.matches('d', .{ .shift = true })) {
            if (self.action_scope_thread and self.mail_selection.count == 0) {
                try self.batchMail("trash", null, null, null, null);
                return true;
            }
            try self.pinMailTargets();
            self.mode = .trash_confirm;
            self.dialog_focus.reset(.trash, 0);
            return true;
        }
        if (key.matches('U', .{}) or key.matches('u', .{ .shift = true })) {
            try self.batchMail(if (self.folder == 5) @as([]const u8, "unspam") else "restore", null, null, null, null);
            return true;
        }
        if (key.matches('s', .{})) {
            var starred = false;
            if (self.focusedMessage()) |message| for (items(get(message, "labels"))) |label| {
                if (same(text(label), "STARRED")) starred = true;
            };
            try self.batchMail("mark", null, !starred, null, null);
            return true;
        }
        if (key.matches('u', .{})) {
            try self.batchMail("mark", if (self.focusedMessage()) |message| !messageUnread(message) else true, null, null, null);
            return true;
        }
        return false;
    }

    fn userLabelCount(self: *App) usize {
        var count: usize = 0;
        for (self.labels) |label_value| {
            if (same(text(get(label_value, "type")), "user")) count += 1;
        }
        return count;
    }
    fn userLabelIndex(self: *App, selected: usize) ?usize {
        var count: usize = 0;
        for (self.labels, 0..) |label_value, index| {
            if (!same(text(get(label_value, "type")), "user")) continue;
            if (count == selected) return index;
            count += 1;
        }
        return null;
    }
    fn gmailCopyWarning(self: *const App) bool {
        return if (self.compose.gmail_link) |link| link.phase != .rejected and !link.paused else false;
    }
    fn openGmailDraft(self: *App) !void {
        if (browser_target) return error.UnsupportedCommand;
        if (!self.compose_active or self.compose.id.value().len == 0) return error.DraftNotFound;
        if (self.compose.unknown_outcome) {
            // An unconfirmed send is never uploaded. Stay on the protected
            // draft so the refusal is not mistaken for a lost draft.
            self.mode = .compose;
            self.say(true, "Gmail upload blocked · send outcome unknown · draft kept in Drafts{s}", .{if (self.capabilities.open_urls) @as([]const u8, " · p HTML preview") else ""});
            self.status_kind = .unknown;
            self.diagnostic("UnknownOutcome");
            return;
        }
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        self.mode = .compose;
        if (!self.compose.gmailPaused() and self.compose.revision != self.compose.saved_revision) try self.saveDraft(.save_gmail) else try self.requestGmailDraftInfo();
    }
    fn requestGmailDraftInfo(self: *App) !void {
        self.cancelAutosaveTimer();
        self.autosave_due = false;
        try self.start(.gmail_draft_info, .{ .cmd = "draft.gmail-info", .account = self.account(), .draftId = self.compose.id.value() });
    }
    fn presentGmailDraft(self: *App) !void {
        try self.beginUx(.gmail_draft, " Continue in Gmail ");
        try self.ux_target.set(self.allocator, self.compose.id.value());
        self.ux_focus = 1;
        self.gmail_scroll = 0;
        self.gmail_review_ready = false;
        try self.uxRow(.{ .label = "Back to local draft", .index = 0 });
        const permitted = self.hasCapability("mail-drafts") or self.hasCapability("mail-modify");
        const link = self.compose.gmail_link;
        if (link == null or link.?.phase == .rejected) {
            if (permitted) try self.uxRow(.{ .label = "Upload once · pause local edits", .index = 1 });
        } else {
            try self.uxRow(.{ .label = "Open Gmail Drafts", .index = 2 });
            if (permitted) {
                try self.uxRow(.{ .label = if (link.?.phase == .unknown) "Check upload status" else "Check Gmail draft", .index = 3 });
                if (link.?.phase != .unknown and self.gmail_remote_version.value().len > 0) try self.uxRow(.{ .label = "Import Gmail changes as a new draft", .index = 5 });
                if (link.?.paused and link.?.phase != .unknown) try self.uxRow(.{ .label = if (same(self.gmail_draft_outcome.value(), "changed")) "Keep local copy + Gmail edits" else if (same(self.gmail_draft_outcome.value(), "missing")) "Keep local · I checked Gmail" else "Take back · keep Gmail copy", .index = 4 });
            }
        }
        self.say(false, "Continue in Gmail · Tab / j/k Choose · Enter Activate · Esc Back", .{});
    }
    fn activateGmailDraft(self: *App) !void {
        _ = self.cancelMeetingRead();
        if (!same(self.ux_account.value(), self.account()) or !same(self.ux_target.value(), self.compose.id.value())) return error.DraftChanged;
        const row = self.uxAt(self.ux_selected) orelse return;
        if (row.index == 0) {
            self.dismissGmailDraft();
            return;
        }
        if ((row.index == 1 or row.index == 4 or row.index == 5) and !self.gmail_review_ready) {
            self.say(false, "Read the handoff details · Ctrl+D scrolls", .{});
            return;
        }
        if (self.job.future != null) return error.OperationPending;
        if (row.index == 2) {
            var bytes: [2048]u8 = undefined;
            var writer: Io.Writer = .fixed(&bytes);
            try writer.writeAll("https://mail.google.com/mail/u/0/?authuser=");
            try @import("../open_target.zig").encode(&writer, self.account());
            try writer.writeAll("#drafts");
            self.closeUx();
            try self.start(.open, .{ .cmd = "browser.open", .account = self.account(), .url = writer.buffered() });
            return;
        }
        const expected: u64 = if (self.compose.gmail_link) |link| link.version else 0;
        const choice = row.index;
        const changed = same(self.gmail_draft_outcome.value(), "changed");
        const missing = same(self.gmail_draft_outcome.value(), "missing");
        self.closeUx();
        if (choice == 1) {
            self.compose.gmail_guard_unknown = true;
            try self.start(.gmail_draft_action, .{ .cmd = "draft.gmail-save", .account = self.account(), .draftId = self.compose.id.value(), .expectedVersion = expected, .expectedDigest = self.gmail_content_digest.value() });
        } else if (choice == 3) {
            try self.start(.gmail_draft_action, .{ .cmd = "draft.gmail-status", .account = self.account(), .draftId = self.compose.id.value(), .expectedVersion = expected });
        } else if (choice == 5) {
            try self.start(.gmail_draft_action, .{ .cmd = "draft.gmail-import", .account = self.account(), .draftId = self.compose.id.value(), .expectedVersion = expected, .expectedRemoteMessageId = self.gmail_remote_version.value() });
        } else if (choice == 4) {
            try self.start(.gmail_draft_action, .{ .cmd = "draft.gmail-take-back", .account = self.account(), .draftId = self.compose.id.value(), .expectedVersion = expected, .keepLocalAfterChange = changed, .expectedRemoteMessageId = self.gmail_remote_version.value(), .acknowledgeMissingCopy = missing });
        }
    }
    fn drawGmailDraft(self: *App, win: vaxis.Window) !void {
        self.mouse_hits.clear();
        const width = @min(win.width -| 2, 78);
        const height = @min(win.height -| 2, 24);
        if (width < 26 or height < 10) return;
        const area = win.child(.{ .x_off = @intCast((win.width - width) / 2), .y_off = @intCast((win.height - height) / 2), .width = width, .height = height });
        area.fill(.{ .style = self.style(.text) });
        const inner = self.panel(area, 0, width, " Continue in Gmail ", true);
        const linked = self.compose.gmail_link;
        const permitted = self.hasCapability("mail-drafts") or self.hasCapability("mail-modify");
        const explanation: []const u8 = if (!permitted) "Permission needed: add mail-drafts to this account's authorization (gmail.compose), or use its existing mail-modify grant. See Help (?) / Gmail drafts. Existing authorization remains usable until the new grant succeeds." else if (linked == null or linked.?.phase == .rejected) "Upload this saved draft once to Gmail, then continue on Gmail or your phone. Local edits and sending pause. Your local Markdown source, original formatting and files are retained. Nothing is sent." else if (linked.?.phase == .unknown) "Upload not confirmed. The Gmail copy may exist or may already have been sent. Check upload status or inspect Gmail; an empty search is not proof of failure. Omagma will not upload again. Local edits remain paused." else if (!linked.?.paused) "This local copy can be edited again. The Gmail copy was kept and may still be edited or sent there. Before sending locally, check Gmail and acknowledge the copy warning in Review send." else if (same(self.gmail_draft_outcome.value(), "changed")) "Gmail has newer edits. Import creates a new local draft. Text stays editable; many inline images keep their formatting as a protected original below a new note; your original local source and Gmail copy stay intact. Keep local copy resumes the original source instead. Check both copies before sending." else if (same(self.gmail_draft_outcome.value(), "missing")) "Gmail draft is missing. It may have been sent or deleted; this is not delivery confirmation. Check Gmail Drafts and Sent first. Keeping the local copy enables editing, with a duplicate-send warning." else "Draft is available in Gmail. Local edits and sending are paused. Import creates a new local draft, preserving both existing copies. Text stays editable; many inline images are kept as a protected original below a new note. Take back rechecks Gmail and resumes this local source. No Gmail draft is deleted or overwritten.";
        const omitted_original: []const u8 = if (self.compose.original != null and !self.compose.include_original) "\nImported Gmail copies contain only what was uploaded. To restore the omitted original, take back or open this original local draft.\n" else "";
        const description = try std.fmt.allocPrint(self.frame.allocator(), "Account: {s}\nSubject: {s}\nFiles: {d}\n\n{s}\n{s}", .{ self.account(), self.compose.fields[3].value(), self.compose.attachments.len, explanation, omitted_original });
        const count = self.uxCount();
        const content_height = inner.height -| @as(u16, @intCast(count + 2));
        const content = inner.child(.{ .height = content_height });
        const lines = try self.flowTone(content, description, self.gmail_scroll, 0, if (linked != null and linked.?.phase == .unknown) .warning else .text);
        self.gmail_description_lines = lines;
        self.gmail_description_height = content.height;
        self.gmail_scroll = @min(self.gmail_scroll, lines -| @as(usize, content.height));
        if (content.height > 0 and self.gmail_scroll + content.height >= lines) self.gmail_review_ready = true;
        for (self.ux_rows.items, 0..) |row, index| {
            const label = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}", .{ if (index == self.ux_selected) @as([]const u8, "› ") else "  ", row.label });
            try self.line(inner, content_height + index, try self.fitLine(inner, label, inner.width), if (index == self.ux_selected and self.ux_focus != 3) .selected else .text);
            self.mouseRows(inner, content_height + index, 1, .dialog_action, 100 + index);
        }
        const x = try self.actionButton(inner, inner.height -| 2, 0, "[Enter Choose]", self.ux_focus == 2, true, .dialog_action, 12);
        _ = try self.actionButton(inner, inner.height -| 2, x, "[Esc Back]", self.ux_focus == 3, true, .dialog_action, 13);
        try self.line(inner, inner.height -| 1, try self.fitLine(inner, if (self.gmail_review_ready) "j/k Choose · Tab · Ctrl+D/U Text" else "Ctrl+D Read more · Esc Back", inner.width), .muted);
    }
    fn followUpEntry(self: *const App, id: []const u8) ?Value {
        if (!same(self.follow_up_account.value(), self.account())) return null;
        for (self.follow_up_entries) |entry| if (same(text(get(entry, "messageId")), id)) return entry;
        return null;
    }
    fn followUpToday(self: *App) ![]const u8 {
        return @import("follow_up.zig").dateForDay(self.frame.allocator(), try self.zone.localDay(Io.Timestamp.now(self.io, .real).toMilliseconds()));
    }
    fn followUpDueCount(self: *App) usize {
        if (!same(self.follow_up_account.value(), self.account())) return 0;
        const today = self.followUpToday() catch return 0;
        var count: usize = 0;
        for (self.follow_up_entries) |entry| if (std.mem.order(u8, text(get(entry, "dueDate")), today) != .gt) {
            count += 1;
        };
        return count;
    }
    fn replaceFollowUps(self: *App, response: []const u8) !void {
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        var transferred = false;
        defer if (!transferred) arena.deinit();
        const result = try self.data(arena.allocator(), response);
        const entries = items(get(result, "entries"));
        if (entries.len > @import("follow_up.zig").limit) return error.FollowUpStoreCorrupt;
        for (entries) |entry| {
            try @import("../bounded.zig").identifier(text(get(entry, "messageId")));
            try @import("follow_up.zig").date(text(get(entry, "dueDate")));
            if (integer(get(entry, "version")) <= 0) return error.FollowUpStoreCorrupt;
        }
        try self.follow_up_account.set(self.allocator, self.account());
        if (self.follow_up_arena) |*old| old.deinit();
        self.follow_up_arena = arena;
        transferred = true;
        self.follow_up_entries = entries;
        self.follow_up_checked_at = Io.Timestamp.now(self.io, .awake).toMilliseconds();
        if (self.follow_ups_list) {
            try self.replaceList(.follow_up_list, response);
            if (self.messages.len > 0) try self.preview(false);
        }
    }
    fn loadFollowUps(self: *App) !void {
        if (browser_target or self.account().len == 0) return;
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        defer arena.deinit();
        const response = try self.cached(arena.allocator(), .{ .cmd = "reminder.list", .account = self.account() }) orelse return;
        try self.replaceFollowUps(response);
    }
    fn followUpTick(self: *App) void {
        if (browser_target or self.job.future != null or self.ux_overlay != .none or self.mode != .browse or self.calendar.open) return;
        const now = Io.Timestamp.now(self.io, .awake).toMilliseconds();
        if (now -| self.follow_up_checked_at < 60000) return;
        // Local read only; the existing minute event also redraws due counts at
        // midnight. Failed reads wait until the next tick, without provider work.
        self.follow_up_checked_at = now;
        self.loadFollowUps() catch {};
    }
    fn openFollowUps(self: *App) !void {
        if (browser_target) return error.NativeOnly;
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        self.rememberWorkingContext();
        self.closeCalendar();
        self.closeUx();
        self.clearReader();
        self.clearHistory();
        self.mail_selection.clear();
        try self.query.set(self.allocator, "");
        try self.cursor.set(self.allocator, "");
        self.follow_ups_list = true;
        self.drafts_list = false;
        self.mode = .browse;
        self.focus = .list;
        self.expanded = false;
        self.selected = 0;
        self.top = 0;
        self.messages = &.{};
        self.pending_list = false;
        self.pending_remote_list = false;
        self.pending_cached_list = false;
        self.pending_read = false;
        self.pending_thread = false;
        self.pending_page = false;
        self.pending_window_provider = false;
        self.generation +%= 1;
        try self.loadFollowUps();
        self.say(false, "Follow-ups · {s} · {d} due · local to this computer", .{ self.account(), self.followUpDueCount() });
    }
    fn editFollowUp(self: *App) !void {
        if (browser_target) return error.NativeOnly;
        if (self.drafts_list or self.compose_active) return error.DraftNotMail;
        if (self.mail_selection.count > 0) return error.FollowUpSingleMessage;
        const message = self.focusedMessage() orelse return error.MessageRequired;
        // Pin before refreshing the reminder list: a concurrent completion can
        // change its selection, but cannot change this editor's target.
        try self.ux_target.set(self.allocator, text(get(message, "id")));
        try self.follow_up_subject.set(self.allocator, text(get(message, "subject")));
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        try self.loadFollowUps();
        const entry = self.followUpEntry(self.ux_target.value());
        self.follow_up_version = if (entry) |value| integer(get(value, "version")) else 0;
        try self.beginUx(.follow_up, " Follow up ");
        const day = try self.zone.localDay(Io.Timestamp.now(self.io, .real).toMilliseconds());
        const today = try @import("follow_up.zig").dateForDay(self.frame.allocator(), day);
        const tomorrow = try @import("follow_up.zig").dateForDay(self.frame.allocator(), day + 1);
        try self.ux_query.set(self.allocator, if (entry) |value| text(get(value, "dueDate")) else tomorrow);
        try self.uxRow(.{ .label = "Today", .value = today });
        try self.uxRow(.{ .label = "Tomorrow", .value = tomorrow });
        if (entry != null) try self.uxRow(.{ .label = "Done · remove this local reminder", .value = "done" });
        self.ux_focus = if (entry != null) 0 else 1;
        self.ux_selected = self.ux_rows.items.len;
        for (self.ux_rows.items, 0..) |row, index| if (same(row.value, self.ux_query.value())) {
            self.ux_selected = index;
            break;
        };
    }
    fn selectFollowUpPreset(self: *App, index: usize) !void {
        self.ux_selected = @min(index, self.ux_rows.items.len -| 1);
        const row = self.uxAt(self.ux_selected) orelse return;
        if (!same(row.value, "done")) try self.ux_query.set(self.allocator, row.value);
    }
    fn saveFollowUp(self: *App, allow_done: bool) !void {
        if (!same(self.ux_account.value(), self.account())) return error.AccountContextChanged;
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        const selected = if (self.ux_focus == 1) self.uxAt(self.ux_selected) else null;
        const done_choice = allow_done and selected != null and same(selected.?.value, "done");
        const value = self.ux_query.value();
        if (done_choice) {
            try self.start(.follow_up_write, .{ .cmd = "reminder.done", .account = self.account(), .messageId = self.ux_target.value(), .expectedVersion = self.follow_up_version });
        } else {
            try @import("follow_up.zig").date(value);
            try self.start(.follow_up_write, .{ .cmd = "reminder.set", .account = self.account(), .messageId = self.ux_target.value(), .dueDate = value, .expectedVersion = self.follow_up_version });
        }
        self.closeUx();
    }
    fn completeFollowUp(self: *App) !void {
        const entry = self.followUpEntry(self.messageId()) orelse return error.MessageRequired;
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        try self.start(.follow_up_write, .{ .cmd = "reminder.done", .account = self.account(), .messageId = text(get(entry, "messageId")), .expectedVersion = integer(get(entry, "version")) });
    }
    fn drawFollowUpEditor(self: *App, win: vaxis.Window) !void {
        self.mouse_hits.clear();
        const width = @min(win.width -| 2, 76);
        const height = @min(win.height -| 2, 13);
        if (width < 28 or height < 10) return;
        const area = win.child(.{ .x_off = @intCast((win.width - width) / 2), .y_off = @intCast((win.height - height) / 2), .width = width, .height = height });
        area.fill(.{ .style = self.style(.text) });
        const inner = self.panel(area, 0, width, " Follow up ", true);
        try self.line(inner, 0, try self.fitLine(inner, self.follow_up_subject.value(), inner.width), .subject);
        try self.line(inner, 1, try self.fitLine(inner, self.ux_account.value(), inner.width), .muted);
        try self.editLine(inner, 2, "Date YYYY-MM-DD", &self.ux_query, self.ux_focus == 0, if (self.ux_focus == 0) .selected else .text);
        self.mouseRows(inner, 2, 1, .dialog_action, 10);
        for (self.ux_rows.items, 0..) |entry, index| {
            try self.line(inner, 3 + index, entry.label, if (self.ux_focus == 1 and self.ux_selected == index) .selected else .text);
            self.mouseRows(inner, 3 + index, 1, .dialog_action, 100 + index);
        }
        try self.line(inner, inner.height -| 3, try self.fitLine(inner, "Local reminder on this computer · Gmail is unchanged", inner.width), .muted);
        const x = try self.actionButton(inner, inner.height -| 2, 0, if (inner.width >= 32) "[Ctrl+S Save date]" else "[Enter Save]", self.ux_focus == 2, true, .dialog_action, 12);
        _ = try self.actionButton(inner, inner.height -| 2, x, "[Esc Cancel]", self.ux_focus == 3, true, .dialog_action, 13);
        try self.line(inner, inner.height -| 1, try self.fitLine(inner, "Tab Controls · Enter Choose · Ctrl+S Save date · Esc Cancel", inner.width), .muted);
    }
    fn drawFollowUpRow(self: *App, win: vaxis.Window, row: usize, index: usize) !void {
        if (row >= win.height or index >= self.messages.len) return;
        const message = self.messages[index];
        const due = text(get(message, "followUpDate"));
        const today = self.followUpToday() catch "";
        const status = if (std.mem.lessThan(u8, due, today)) "Overdue" else if (same(due, today)) "Today" else "Upcoming";
        const item = win.child(.{ .y_off = @intCast(row), .height = @intCast(@min(@min(self.mailRowStride(), 2), win.height - row)) });
        if (index == self.selected) item.fill(.{ .style = self.listStyle(.text, true) });
        const title = try std.fmt.allocPrint(self.frame.allocator(), "{s} · {s} · {s}", .{ due, status, text(get(message, "subject")) });
        _ = item.printSegment(.{ .text = try self.fitLine(item, title, item.width), .style = self.listStyle(if (std.mem.order(u8, due, today) != .gt) .accent else .subject, index == self.selected) }, .{ .wrap = .none });
        if (self.mailRowStride() > 1 and item.height > 1) _ = item.printSegment(.{ .text = try self.fitLine(item, text(get(get(message, "from"), "name")), item.width), .style = self.listStyle(.muted, index == self.selected) }, .{ .row_offset = 1, .wrap = .none });
        self.mouseRows(win, row, @intCast(self.mailRowStride()), .mail, index);
    }
    fn mailboxTitle(self: *App) []const u8 {
        if (self.follow_ups_list) return "Follow-ups";
        if (self.custom_label.value().len == 0) return folders[self.folder];
        for (self.labels) |label_value| if (same(text(get(label_value, "id")), self.custom_label.value())) return text(get(label_value, "name"));
        return self.custom_label.value();
    }
    fn chooseCustomLabel(self: *App, index: usize) !void {
        if (index >= self.labels.len) return;
        if (!same(text(get(self.labels[index], "type")), "user")) return;
        self.rememberWorkingContext();
        try self.custom_label.set(self.allocator, text(get(self.labels[index], "id")));
        self.folder = 6;
        self.query_scope = .cache;
        try self.query.set(self.allocator, "");
        self.clearHistory();
        try self.cursor.set(self.allocator, "");
        self.selected = 0;
        self.top = 0;
        self.generation +%= 1;
        self.focus = .list;
        try self.reload();
    }
    fn activeLabel(self: *const App) []const u8 {
        return if (self.custom_label.value().len > 0) self.custom_label.value() else folder_labels[self.folder];
    }
    fn say(self: *App, warning: bool, comptime format: []const u8, args: anytype) void {
        var buffer: [1024]u8 = undefined;
        var writer = Io.Writer.fixed(&buffer);
        var overflow = false;
        writer.print(format, args) catch {
            overflow = true;
        };
        const value_in = if (writer.buffered().len != 0) writer.buffered() else "Status unavailable";
        if (self.action_notice and !warning) return;
        if (self.status_kind == .unknown and (self.compose.unknown_outcome or self.invitation_unknown or self.label_unknown[self.account_index]) and !warning) return;
        if (warning) self.action_notice = false;
        const shortened = overflow or value_in.len > self.status.len;
        var end = @min(value_in.len, self.status.len - @as(usize, if (shortened) 3 else 0));
        while (end > 0 and !std.unicode.utf8ValidateSlice(value_in[0..end])) end -= 1;
        @memcpy(self.status[0..end], value_in[0..end]);
        if (shortened) @memcpy(self.status[end..][0..3], "…");
        self.status_len = end + @as(usize, if (shortened) 3 else 0);
        self.warning = warning;
        self.status_kind = if (warning) .failure else .view;
        self.status_owner = self.statusContext();
        self.status_error_len = 0;
    }
    fn statusContext(self: *const App) StatusOwner {
        return .{ .mode = switch (self.mode) {
            .help, .command, .search => self.previous_mode,
            .attachment => .compose,
            else => self.mode,
        }, .account = self.account_index, .selection = self.selection_generation, .overlay = self.reader_overlay, .labels = self.label_picker };
    }
    fn clearObsoleteStatus(self: *App) void {
        if (self.status_kind == .action or self.status_kind == .unknown or self.action_notice) return;
        const current = self.statusContext();
        if (!std.meta.eql(current, self.status_owner)) self.say(false, "Ready", .{});
    }
    fn keepBackgroundDiagnostic(self: *const App, kind: JobKind) bool {
        // Incidental cache/label/identity readiness must not erase the current
        // field/action diagnostic in that exact context. A foreground label
        // picker, explicit actions/retry results and changed contexts retain
        // normal status behavior; errors never become globally sticky.
        const background = kind == .recipient_cache or kind == .recipient_refresh or kind == .identities or (kind == .labels_list and !self.label_picker);
        return background and (self.status_kind == .failure or self.status_kind == .unknown) and std.meta.eql(self.statusContext(), self.status_owner);
    }
    fn diagnostic(self: *App, code: []const u8) void {
        self.status_error_len = 0;
        if (!validDiagnosticCode(code)) return;
        @memcpy(self.status_error_code[0..code.len], code);
        self.status_error_len = code.len;
    }
    fn sayError(self: *App, code: []const u8) void {
        if (self.calendar.open) {
            self.calendar.error_code.set(code[0..@min(code.len, 128)]) catch {};
            self.calendar.notice.set("Calendar operation failed · retained data kept") catch {};
        }
        if (validDiagnosticCode(code)) self.say(true, "{s} · {s}", .{ humanError(code), code }) else self.say(true, "{s}", .{humanError(code)});
        self.diagnostic(code);
        if (same(code, "UnknownOutcome")) self.status_kind = .unknown;
    }
    fn sayFailure(self: *App, prefix: []const u8, code: []const u8) void {
        if (validDiagnosticCode(code)) self.say(true, "{s} · {s} · {s}", .{ prefix, humanError(code), code }) else self.say(true, "{s} · {s}", .{ prefix, humanError(code) });
        self.diagnostic(code);
        if (same(code, "UnknownOutcome")) self.status_kind = .unknown;
    }
    fn sayAction(self: *App, warning: bool, comptime format: []const u8, args: anytype) void {
        self.say(warning, format, args);
        self.status_kind = .action;
        self.action_notice = true;
    }
    fn editorNoticeProtected(self: *const App) bool {
        return self.status_kind == .unknown and (self.compose.unknown_outcome or self.invitation_unknown);
    }
    fn sayEditorResult(self: *App, exit_code: u8) void {
        if (self.editorNoticeProtected()) return;
        // The local editor result is an action outcome, not a view hint.
        // Unrelated label/recipient refreshes must not replace it with Ready.
        self.action_notice = false;
        if (exit_code == 0) self.sayAction(false, "Editor returned · draft retained · Ctrl+S Review send", .{}) else self.sayAction(true, "Editor exited {d} · changed text retained · Ctrl+S Review send", .{exit_code});
    }
    fn sayEditorFailure(self: *App, err: anyerror) void {
        if (self.editorNoticeProtected()) return;
        self.action_notice = false;
        self.sayAction(true, "Editor: {s} · draft retained", .{@errorName(err)});
        self.diagnostic(@errorName(err));
    }
    fn reloadTheme(self: *App) void {
        self.loadTheme(true);
    }
    fn activeTheme(self: *const App) theme.Mode {
        return if (self.mode == .theme) self.theme_choice else self.ui_preferences.theme;
    }
    fn loadTheme(self: *App, announce_error: bool) void {
        if (browser_target) {
            self.palette = .{};
            self.omarchy_theme_available = false;
            self.theme_warning = false;
            return;
        }
        const chosen = self.activeTheme();
        self.theme_following.store(chosen == .follow_omarchy, .release);
        self.palette = theme.loadMode(self.io, self.allocator, self.environ, chosen) catch |err| {
            self.palette = .{};
            self.omarchy_theme_available = false;
            self.theme_warning = true;
            if (announce_error) self.say(true, "Omarchy theme unavailable · using Omagma colors · {s}", .{@errorName(err)});
            return;
        };
        if (chosen == .follow_omarchy) self.omarchy_theme_available = self.palette.from_omarchy;
        // A machine without Omarchy uses the normal built-in palette; the
        // picker labels that fallback without making every sync status warn.
        self.theme_warning = false;
    }
    fn pollTheme(self: *App) bool {
        if (browser_target) return false;
        if (self.activeTheme() != .follow_omarchy) return false;
        const changed = self.theme_watch.changed(self.io, Io.Timestamp.now(self.io, .awake).toMilliseconds()) catch return false;
        if (changed) self.loadTheme(false);
        return changed;
    }
    fn openThemePicker(self: *App) void {
        if (!browser_target and self.ui_preferences.theme == .omagma) self.omarchy_theme_available = (theme.load(self.io, self.allocator, self.environ) catch theme.Palette{}).from_omarchy;
        self.theme_choice = self.ui_preferences.theme;
        self.theme_save_failed = false;
        self.mode = .theme;
        self.dialog_focus.reset(.theme, 0);
    }
    fn previewTheme(self: *App, chosen: theme.Mode) void {
        if (chosen == self.theme_choice) return;
        self.theme_choice = chosen;
        self.theme_save_failed = false;
        self.loadTheme(false);
    }
    fn cancelThemePicker(self: *App) void {
        self.mode = .browse;
        self.theme_save_failed = false;
        self.loadTheme(false);
    }
    fn applyThemePicker(self: *App) void {
        const saved = self.ui_preferences.theme;
        if (self.theme_choice != saved) {
            self.ui_preferences.theme = self.theme_choice;
            self.saveUiPreferences();
            if (self.preferences_warning) {
                self.ui_preferences.theme = saved;
                self.theme_save_failed = true;
                return;
            }
        }
        self.mode = .browse;
        self.say(false, "Theme: {s}{s}", .{ theme.name(self.ui_preferences.theme), if (self.ui_preferences.theme == .follow_omarchy and !self.palette.from_omarchy) @as([]const u8, " · using Omagma colors") else "" });
    }
    fn onThemePickerKey(self: *App, key: Key) void {
        self.dialog_focus.ensure(.theme, 0);
        if (tabDirection(key)) |backwards| {
            self.dialog_focus.move(backwards, 3, 0b111);
        } else if (key.matches(Key.escape, .{}) or key.matches('q', .{}) or key.matches('c', .{ .ctrl = true })) {
            self.cancelThemePicker();
        } else if (key.matches('l', .{ .ctrl = true })) {
            self.loadTheme(false);
            self.vx.queueRefresh();
        } else if (key.matches(Key.enter, .{})) {
            if (self.dialog_focus.index == 2) self.cancelThemePicker() else self.applyThemePicker();
        } else if (self.dialog_focus.index == 0) {
            if (key.matches('j', .{}) or key.matches(Key.down, .{})) self.previewTheme(.follow_omarchy) else if (key.matches('k', .{}) or key.matches(Key.up, .{})) self.previewTheme(.omagma);
        }
    }
    fn loadRemotePreferences(self: *App) !void {
        var scratch: std.heap.ArenaAllocator = .init(self.allocator);
        defer scratch.deinit();
        const a = scratch.allocator();
        const response = try @import("backend_retry.zig").call(self.io, self.allocator, a, self.client, "{\"cmd\":\"preferences.get\"}", 35000);
        const result = try self.data(a, response);
        if (result != .object or !result.object.contains("preferences")) return error.InvalidPreferencesResponse;
        const value = get(result, "preferences");
        if (value != .null) {
            if (value != .object) return error.InvalidPreferencesResponse;
            const bytes = try @import("json.zig").encodeAlloc(a, value, .{});
            const parsed_preferences = try preferences.parse(self.allocator, bytes);
            self.ui_preferences.calendar.deinit();
            self.ui_preferences = parsed_preferences;
        }
        self.reader_layout = self.ui_preferences.readerLayout;
        self.remote_preferences_loaded = true;
        self.preferences_warning = false;
    }
    fn remotePreferencesRequest(self: *App, a: Allocator) !Value {
        if (!self.remote_preferences_loaded) return error.PreferencesNotLoaded;
        const bytes = try preferences.encode(a, &self.ui_preferences);
        const value = try std.json.parseFromSliceLeaky(Value, a, bytes, .{});
        return @import("json.zig").value(a, .{ .cmd = "preferences.set", .preferences = value });
    }
    fn flushRemotePreferences(self: *App) !void {
        if (!self.options.remote_preferences or self.preferences_revision == self.preferences_saved_revision) return;
        var scratch: std.heap.ArenaAllocator = .init(self.allocator);
        defer scratch.deinit();
        const a = scratch.allocator();
        const request = try @import("json.zig").encodeAlloc(a, try self.remotePreferencesRequest(a), .{});
        const response = try @import("backend_retry.zig").call(self.io, self.allocator, a, self.client, request, 35000);
        const result = try self.data(a, response);
        if (!truth(get(result, "saved"))) return error.InvalidPreferencesResponse;
        self.preferences_saved_revision = self.preferences_revision;
        self.remote_preferences_pending = false;
        self.remote_preferences_retry_after = 0;
        self.preferences_warning = false;
    }
    fn finishRemotePreferences(self: *App) void {
        // A failed admission or connection leaves the latest snapshot pending.
        // Never discard a newer edit merely because an older save completed.
        self.remote_preferences_pending = true;
        self.remote_preferences_retry_after = Io.Timestamp.now(self.io, .awake).toMilliseconds() + 2000;
        if (self.job.failure) |err| {
            self.preferences_warning = true;
            self.sayFailure("UI preferences not saved", @errorName(err));
            return;
        }
        const result = self.data(self.job_arena.allocator(), self.job.response orelse "") catch {
            self.preferences_warning = true;
            return;
        };
        if (!truth(get(result, "saved"))) {
            self.preferences_warning = true;
            self.sayFailure("UI preferences not saved", "InvalidPreferencesResponse");
            return;
        }
        self.preferences_saved_revision = self.job.preferences_revision;
        self.remote_preferences_pending = self.preferences_saved_revision != self.preferences_revision;
        self.remote_preferences_retry_after = 0;
        self.preferences_warning = false;
    }
    fn loadPreferences(self: *App) void {
        if (browser_target) return;
        if (self.options.remote_preferences) {
            self.loadRemotePreferences() catch |err| {
                self.preferences_warning = true;
                self.sayFailure("Encrypted UI preferences unavailable", @errorName(err));
            };
            return;
        }
        const filename = preferences.path(self.allocator, self.environ, self.options.ui_file) catch |err| {
            self.preferences_warning = true;
            self.say(true, "UI preferences fallback · {s}", .{@errorName(err)});
            return;
        };
        defer self.allocator.free(filename);
        self.preferences_file.set(self.allocator, filename) catch {
            self.preferences_warning = true;
            self.say(true, "UI preferences fallback · OutOfMemory", .{});
            return;
        };
        const saved = preferences.load(self.io, self.allocator, filename) catch |err| {
            self.preferences_warning = true;
            self.say(true, "UI preferences fallback · {s}", .{@errorName(err)});
            return;
        };
        self.ui_preferences.calendar.deinit();
        self.ui_preferences = saved;
        self.reader_layout = saved.readerLayout;
        self.preferences_warning = false;
    }
    fn setReaderLayout(self: *App, value_in: layout.ReaderLayout) void {
        self.reader_layout = value_in;
        const label = @tagName(value_in);
        self.saveUiPreferences();
        self.say(self.preferences_warning, "Reader {s} · {s}", .{ label, if (self.preferences_warning) "preference not saved" else "preference saved" });
    }
    fn saveUiPreferences(self: *App) void {
        if (browser_target) {
            self.ui_preferences.readerLayout = self.reader_layout;
            self.preferences_warning = false;
            return;
        }
        if (self.options.remote_preferences) {
            if (!self.remote_preferences_loaded) {
                self.preferences_warning = true;
                self.sayFailure("UI preferences not saved", "PreferencesNotLoaded");
                return;
            }
            self.ui_preferences.readerLayout = self.reader_layout;
            self.preferences_revision +%= 1;
            self.remote_preferences_pending = true;
            self.preferences_warning = false;
            return;
        }
        if (self.preferences_file.value().len == 0) {
            self.preferences_warning = true;
            return;
        }
        self.ui_preferences.readerLayout = self.reader_layout;
        preferences.save(self.io, self.allocator, self.preferences_file.value(), self.ui_preferences) catch |err| {
            self.preferences_warning = true;
            self.say(true, "UI preferences not saved · {s}", .{@errorName(err)});
            return;
        };
        self.preferences_warning = false;
    }
    fn rememberWorkingContext(self: *App) void {
        if (self.account().len == 0 or self.compose_active or self.follow_ups_list or self.query.value().len > 0) return;
        var slot: ?usize = null;
        for (&self.ui_preferences.contexts, 0..) |*entry, index| {
            if (entry.*) |*context| {
                if (same(context.account.slice(), self.account())) {
                    slot = index;
                    break;
                }
            } else if (slot == null) slot = index;
        }
        const index = slot orelse return;
        var value: preferences.Context = .{ .folder = @intCast(self.folder), .selected = @intCast(@min(self.selected, 9999)), .readerScroll = @intCast(@min(self.reader_scroll, 10000000)) };
        value.account.set(self.account()) catch return;
        value.label.set(self.custom_label.value()) catch return;
        value.message.set(self.messageId()) catch return;
        self.ui_preferences.contexts[index] = value;
        self.ui_preferences.lastAccount.set(self.account()) catch {};
    }
    fn restoreWorkingContext(self: *App) !void {
        for (&self.ui_preferences.contexts) |*entry| if (entry.*) |*context| {
            if (!same(context.account.slice(), self.account())) continue;
            self.folder = context.folder;
            try self.custom_label.set(self.allocator, context.label.slice());
            self.selected = context.selected;
            self.restore_reader_scroll = context.readerScroll;
            try self.restore_message.set(self.allocator, context.message.slice());
            self.view_ready = false;
            break;
        };
    }
    fn restoreInitialContext(self: *App) !void {
        if (self.options.account == null and self.ui_preferences.lastAccount.len > 0) {
            for (self.accounts, 0..) |entry, index| if (same(text(get(entry, "address")), self.ui_preferences.lastAccount.slice())) {
                self.account_index = index;
                break;
            };
        }
        try self.restoreWorkingContext();
        try self.prepareLabels();
    }
    fn normalizeBrowseKey(self: *App, key: Key) Key {
        if (self.mode != .browse or self.paste or self.reader_overlay != .none) return key;
        for (&self.ui_preferences.bindings) |*entry| if (entry.*) |*binding| {
            const raw = binding.key.slice();
            const ctrl = std.mem.startsWith(u8, raw, "Ctrl+");
            const character = if (ctrl) raw[5..] else raw;
            if (!key.matches(character[0], .{ .ctrl = ctrl })) continue;
            const codepoint: u21 = switch (binding.action) {
                .down => 'j',
                .up => 'k',
                .left => 'h',
                .right => 'l',
                .next_mail => 'J',
                .previous_mail => 'K',
                .compose => 'c',
                .reply => 'r',
                .reply_all => 'R',
                .contacts => 'a',
                .calendar => 'C',
                .follow_up => 'b',
                .cache_search => '/',
                .server_search => '\\',
                .layout => 'v',
                .expand => 'z',
                .help => '?',
                .thread_next => '}',
                .thread_previous => '{',
                .thread_fold => 't',
                .quote_fold => 'Q',
                .signature_fold => 'S',
                .links => 'L',
                .attachments => 'B',
            };
            return .{ .codepoint = codepoint };
        };
        return key;
    }
    fn onReaderCommand(self: *App, command: []const u8) !bool {
        if (same(command, "thread-older") or same(command, "thread-newer")) {
            try self.loadThreadWindow(same(command, "thread-newer"));
            return true;
        }
        if (std.mem.startsWith(u8, command, "density ")) {
            const chosen = std.meta.stringToEnum(preferences.Density, std.mem.trim(u8, command[8..], " ")) orelse return error.InvalidDensity;
            self.ui_preferences.density = chosen;
            self.readerLayoutChanged();
            self.saveUiPreferences();
            self.say(self.preferences_warning, "Density {s} · {s}", .{ @tagName(chosen), if (self.preferences_warning) "preference not saved" else if (browser_target) "this session" else "preference saved" });
            return true;
        }
        if (same(command, "headers")) {
            try self.toggleReaderHeaders();
            return true;
        }
        if (std.mem.startsWith(u8, command, "received ")) {
            const raw = std.mem.trim(u8, command[9..], " ");
            const mode: ReceivedView = if (same(raw, "auto")) .automatic else std.meta.stringToEnum(ReceivedView, raw) orelse return error.InvalidReceivedView;
            try self.setReceivedView(mode);
            return true;
        }
        if (same(command, "calendar")) {
            try self.openCalendar(false);
            return true;
        }
        if (same(command, "calendar-import")) {
            try self.openCalendar(true);
            return true;
        }
        if (same(command, "view-editor")) {
            self.viewReaderEditor() catch |err| switch (err) {
                error.MessageRequired, error.ReaderMessageChanging => self.say(false, "Current message is still loading · wait for this preview", .{}),
                else => return err,
            };
            return true;
        }
        if (same(command, "copy-message")) {
            self.copyReaderMessage() catch |err| switch (err) {
                error.MessageRequired, error.ReaderMessageChanging => self.say(false, "Current message is still loading · wait for this preview", .{}),
                else => return err,
            };
            return true;
        }
        if (try self.onUxCommand(command)) return true;
        if (same(command, "labels")) {
            if (self.mode != .browse and !(self.mode == .command and self.previous_mode == .browse)) return error.NotMailbox;
            try self.openLabelManager();
            return true;
        }
        if (std.mem.startsWith(u8, command, "split ")) {
            var parts = std.mem.tokenizeScalar(u8, command[6..], ' ');
            const orientation = parts.next() orelse return error.InvalidPaneRatio;
            const percent = try std.fmt.parseInt(u8, parts.next() orelse return error.InvalidPaneRatio, 10);
            if (percent < 25 or percent > 75 or parts.next() != null) return error.InvalidPaneRatio;
            if (same(orientation, "right")) self.ui_preferences.listWidthPercent = percent else if (same(orientation, "below")) self.ui_preferences.listHeightPercent = percent else return error.InvalidPaneRatio;
            self.saveUiPreferences();
            self.say(false, "Mail pane {s}: {d}% · preference saved", .{ orientation, percent });
            return true;
        }
        if (std.mem.startsWith(u8, command, "bind ")) {
            var parts = std.mem.tokenizeScalar(u8, command[5..], ' ');
            const name = parts.next() orelse return error.InvalidKeyBinding;
            const action = std.meta.stringToEnum(preferences.Action, parts.next() orelse return error.InvalidKeyBinding) orelse return error.InvalidKeyBinding;
            if (!preferences.validKey(name) or parts.next() != null) return error.InvalidKeyBinding;
            var slot: ?usize = null;
            for (&self.ui_preferences.bindings, 0..) |*entry, index| {
                if (entry.*) |*binding| {
                    if (same(binding.key.slice(), name)) {
                        slot = index;
                        break;
                    }
                } else if (slot == null) slot = index;
            }
            var binding: preferences.Binding = .{ .action = action };
            try binding.key.set(name);
            self.ui_preferences.bindings[slot orelse return error.TooManyKeyBindings] = binding;
            self.saveUiPreferences();
            self.say(false, "Bound {s} to {s} in mailbox mode", .{ name, @tagName(action) });
            return true;
        }
        if (std.mem.startsWith(u8, command, "unbind ")) {
            const name = std.mem.trim(u8, command[7..], " ");
            for (&self.ui_preferences.bindings) |*entry| if (entry.*) |*binding| if (same(binding.key.slice(), name)) {
                entry.* = null;
                break;
            };
            self.saveUiPreferences();
            self.say(false, "Removed binding {s}", .{name});
            return true;
        }
        if (same(command, "links")) {
            try self.openReaderLinks();
            return true;
        }
        if (same(command, "attachments")) {
            self.openReaderAttachments();
            return true;
        }
        return false;
    }
    fn dismissGmailDraft(self: *App) void {
        self.closeUx();
        self.say(false, "{s}", .{if (self.compose.gmailPaused()) @as([]const u8, "Draft paused in Gmail · g Status or takeback") else if (self.gmailCopyWarning()) "Local draft · Gmail copy kept" else "Local draft · no mail sent"});
    }
    fn closeUx(self: *App) void {
        if (self.ux_arena) |*arena| arena.deinit();
        self.ux_arena = null;
        self.ux_rows = .empty;
        self.ux_overlay = .none;
        self.ux_selected = 0;
        self.ux_focus = 0;
    }
    fn beginUx(self: *App, kind: UxOverlay, title: []const u8) !void {
        self.closeUx();
        self.ux_arena = .init(self.allocator);
        self.ux_overlay = kind;
        self.ux_title = title;
        try self.ux_query.set(self.allocator, "");
        try self.ux_account.set(self.allocator, self.account());
        self.ux_focus = if (kind == .discard or kind == .triage_review or kind == .draft_conflict) 3 else if (kind == .scope) 1 else 0;
    }
    fn uxRow(self: *App, row: UxRow) !void {
        if (self.ux_rows.items.len == 128) return error.DialogLimitExceeded;
        const a = self.ux_arena.?.allocator();
        try self.ux_rows.append(a, .{ .label = try a.dupe(u8, row.label), .detail = try a.dupe(u8, row.detail), .value = try a.dupe(u8, row.value), .index = row.index });
    }
    fn uxFilter(self: *const App) bool {
        return switch (self.ux_overlay) {
            .actions, .aliases, .history, .saved, .contact_addresses, .label_colors => true,
            else => false,
        };
    }
    fn uxInput(self: *const App) bool {
        return self.ux_overlay != .draft_conflict and self.ux_overlay != .gmail_draft and self.ux_overlay != .scope and self.ux_overlay != .discard and self.ux_overlay != .triage_review;
    }
    fn uxMatches(self: *const App, row: UxRow) bool {
        return !self.uxFilter() or self.ux_query.value().len == 0 or cache_query.find(row.label, self.ux_query.value()) != null or cache_query.find(row.detail, self.ux_query.value()) != null;
    }
    fn uxCount(self: *const App) usize {
        var count: usize = 0;
        for (self.ux_rows.items) |row| if (self.uxMatches(row)) {
            count += 1;
        };
        return count;
    }
    fn uxAt(self: *const App, wanted: usize) ?UxRow {
        var count: usize = 0;
        for (self.ux_rows.items) |row| if (self.uxMatches(row)) {
            if (count == wanted) return row;
            count += 1;
        };
        return null;
    }
    fn openActions(self: *App) !void {
        const composing = self.mode == .compose or (self.mode == .command and self.previous_mode == .compose);
        const received = !composing and !self.drafts_list and self.thread.len > 0 and self.reader_card < self.thread.len and same(self.reader_account.value(), self.account()) and same(self.reader_message.value(), self.messageId());
        const context: action_palette.Context = .{ .received = received, .mail = !composing and !self.drafts_list and self.readerReplyId().len > 0, .composing = composing, .draft = composing or self.drafts_list, .search = self.query.value().len > 0, .writable = self.capabilities.mail_changes and self.canManageLabels(), .contacts_write = self.capabilities.contacts_write and self.hasCapability("contacts-write") };
        try self.beginUx(.actions, " Actions ");
        for (action_palette.entries, 0..) |entry, index| {
            if (!entry.available(context) or (composing and (entry.id == .compose or entry.id == .theme))) continue;
            if (composing and self.compose.gmailPaused() and entry.id != .gmail_draft and entry.id != .help) continue;
            const supported = switch (entry.id) {
                .calendar, .follow_up, .follow_ups, .gmail_draft => !browser_target,
                .updates => self.capabilities.updates,
                .files, .save_all => self.capabilities.files,
                .sender => self.capabilities.aliases,
                .preview_browser => self.capabilities.open_urls,
                .view_editor => self.capabilities.editor,
                .copy_message, .select_text => self.capabilities.clipboard,
                .manage_labels, .scope => self.capabilities.mail_changes,
                .send_grace, .resume_send, .cancel_send => self.capabilities.send_queue,
                else => true,
            };
            if (!supported) continue;
            if (!self.pausedGraceForCompose() and (entry.id == .resume_send or entry.id == .cancel_send)) continue;
            const caption = try std.fmt.allocPrint(self.ux_arena.?.allocator(), "{s}{s}{s}", .{ entry.name, if (entry.keys.len > 0) @as([]const u8, " · ") else "", entry.keys });
            try self.uxRow(.{ .label = caption, .detail = entry.detail, .index = index });
        }
    }
    fn hasCapability(self: *const App, capability: []const u8) bool {
        if (self.account_index >= self.accounts.len) return false;
        for (items(get(self.accounts[self.account_index], "capabilities"))) |value| if (same(text(value), capability)) return true;
        return false;
    }
    fn openSearches(self: *App, named: bool) !void {
        try self.beginUx(if (named) .saved else .history, if (named) " Saved searches " else " Search history ");
        const entries = if (named) &self.ui_preferences.savedSearches else &self.ui_preferences.searchHistory;
        for (entries, 0..) |optional, index| if (optional) |entry| {
            if (!same(entry.account.slice(), self.account())) continue;
            const caption = if (named) entry.name.slice() else entry.query.slice();
            const detail = try std.fmt.allocPrint(self.ux_arena.?.allocator(), "{s} · {s}", .{ if (entry.mode == .cache) @as([]const u8, "Cache") else "Gmail", entry.query.slice() });
            try self.uxRow(.{ .label = caption, .detail = detail, .value = entry.query.slice(), .index = if (entry.mode == .cache) 0 else 1 });
            _ = index;
        };
    }
    fn rememberSearch(self: *App) void {
        if (self.query.value().len == 0) return;
        preferences.rememberSearch(&self.ui_preferences, self.account(), self.query.value(), if (self.query_scope == .cache) .cache else .server, null) catch |err| {
            self.sayFailure("Search history not saved", @errorName(err));
            return;
        };
        self.saveUiPreferences();
    }
    fn onUxCommand(self: *App, command: []const u8) !bool {
        if (same(command, "resolve-draft") or same(command, "reload-draft") or same(command, "save-copy")) {
            if (self.mode == .command) self.mode = self.previous_mode;
            if (same(command, "resolve-draft")) try self.openDraftConflict() else if (same(command, "reload-draft")) try self.reloadChangedDraft() else try self.saveLocalDraftCopy();
            return true;
        }
        if (same(command, "meeting")) {
            if (self.mode == .command) self.mode = self.previous_mode;
            self.focusMeeting();
            return true;
        }
        if (same(command, "gmail-draft")) {
            try self.openGmailDraft();
            return true;
        }
        if (same(command, "follow-ups")) {
            try self.openFollowUps();
            return true;
        }
        if (same(command, "follow-up")) {
            try self.editFollowUp();
            return true;
        }
        if (same(command, "updates")) {
            self.openUpdates();
            return true;
        }
        if (same(command, "resume-send")) {
            if (!self.capabilities.send_queue) return error.SendQueueUnavailable;
            if (!self.pausedGraceForCompose()) return error.NoPendingSend;
            self.preemptReadOnly();
            try self.start(.grace_resume, .{ .cmd = "queue.resume", .account = self.grace_account.value(), .queueId = self.grace_queue.value(), .delaySeconds = self.ui_preferences.sendGraceSeconds });
            return true;
        }
        if (same(command, "cancel-send")) {
            if (!self.capabilities.send_queue) return error.SendQueueUnavailable;
            if (self.grace_active) try self.cancelGrace(false) else {
                if (!self.pausedGraceForCompose()) return error.NoPendingSend;
                self.preemptReadOnly();
                try self.start(.grace_cancel, .{ .cmd = "queue.cancel", .account = self.grace_account.value(), .queueId = self.grace_queue.value() });
            }
            return true;
        }
        if (same(command, "actions")) {
            try self.openActions();
            return true;
        }
        if (same(command, "search-history")) {
            try self.openSearches(false);
            return true;
        }
        if (same(command, "saved-searches")) {
            try self.openSearches(true);
            return true;
        }
        if (same(command, "save-search") or std.mem.startsWith(u8, command, "save-search ")) {
            if (self.query.value().len == 0) return error.NoCurrentSearch;
            if (command.len > 12) {
                try preferences.rememberSearch(&self.ui_preferences, self.account(), self.query.value(), if (self.query_scope == .cache) .cache else .server, std.mem.trim(u8, command[12..], " "));
                self.saveUiPreferences();
                self.say(false, "Search saved for this account", .{});
            } else try self.beginUx(.save_search, " Save search · name ");
            return true;
        }
        if (same(command, "scope") or std.mem.startsWith(u8, command, "scope ")) {
            if (!self.capabilities.mail_changes) return error.MailChangesUnavailable;
            const wanted = if (command.len > 6) std.mem.trim(u8, command[6..], " ") else "";
            if (wanted.len == 0) {
                try self.beginUx(.scope, " Mail action scope ");
                try self.uxRow(.{ .label = "This message", .detail = "Act on the focused message", .value = "message" });
                try self.uxRow(.{ .label = "Whole conversation", .detail = "Resolve and review every message before changes", .value = "thread" });
                self.ux_selected = @intFromBool(self.action_scope_thread);
            } else if (same(wanted, "thread") or same(wanted, "conversation") or same(wanted, "message")) {
                self.action_scope_thread = !same(wanted, "message");
                self.say(false, "Actions: {s}", .{if (self.action_scope_thread) @as([]const u8, "whole conversation · exact targets reviewed") else "this message"});
            } else return error.InvalidMailScope;
            return true;
        }
        if (same(command, "send-grace") or std.mem.startsWith(u8, command, "send-grace ")) {
            if (!self.capabilities.send_queue) return error.SendQueueUnavailable;
            if (command.len > 11) {
                const seconds = try std.fmt.parseInt(u8, std.mem.trim(u8, command[11..], " "), 10);
                if (seconds > 30) return error.InvalidSendGrace;
                self.ui_preferences.sendGraceSeconds = seconds;
                self.saveUiPreferences();
                self.say(false, "Send cancellation period: {d}s", .{seconds});
            } else {
                try self.beginUx(.grace, " Send cancellation period · seconds ");
                try self.ux_query.set(self.allocator, try std.fmt.allocPrint(self.frame.allocator(), "{d}", .{self.ui_preferences.sendGraceSeconds}));
            }
            return true;
        }
        if (same(command, "spam") or same(command, "unspam")) {
            try self.batchMail(command, null, null, null, null);
            return true;
        }
        if (same(command, "sender")) {
            try self.cycleComposeIdentity();
            return true;
        }
        if (same(command, "discard-draft")) {
            try self.openDiscardDraft();
            return true;
        }
        if (same(command, "preview-browser")) {
            try self.previewComposeInBrowser();
            return true;
        }
        if (same(command, "add-contact")) {
            try self.addCurrentSender();
            return true;
        }
        if (same(command, "find") or std.mem.startsWith(u8, command, "find ")) {
            if (command.len > 5) try self.startReaderFind(command[5..]) else try self.beginUx(.find, " Find in message ");
            return true;
        }
        if (same(command, "next-unread") or same(command, "previous-unread")) {
            try self.navigateUnread(same(command, "next-unread"));
            return true;
        }
        if (same(command, "save-all") or std.mem.startsWith(u8, command, "save-all ")) {
            try self.openSaveAll(if (command.len > 9) command[9..] else null);
            return true;
        }
        return false;
    }
    fn activateUx(self: *App) !void {
        if (!same(self.ux_account.value(), self.account())) {
            self.closeUx();
            return error.AccountContextChanged;
        }
        const kind = self.ux_overlay;
        if (kind == .draft_conflict) {
            if (!same(self.ux_target.value(), self.compose.id.value())) return error.DraftChanged;
            const copy = self.ux_selected == 0;
            self.closeUx();
            if (copy) try self.saveLocalDraftCopy() else try self.reloadChangedDraft();
            return;
        }
        if (kind == .gmail_draft) return self.activateGmailDraft();
        if (kind == .follow_up) return self.saveFollowUp(true);
        if (kind == .save_all) {
            const folder = try self.allocator.dupe(u8, self.ux_query.value());
            defer self.allocator.free(folder);
            self.closeUx();
            try self.startSaveAll(folder);
            return;
        }
        if (kind == .find) {
            const needle = try self.allocator.dupe(u8, self.ux_query.value());
            defer self.allocator.free(needle);
            self.closeUx();
            try self.startReaderFind(needle);
            return;
        }
        if (kind == .save_search or kind == .grace) {
            const argument = try self.allocator.dupe(u8, self.ux_query.value());
            defer self.allocator.free(argument);
            self.closeUx();
            const command = try std.fmt.allocPrint(self.allocator, "{s} {s}", .{ if (kind == .save_search) @as([]const u8, "save-search") else "send-grace", argument });
            defer self.allocator.free(command);
            _ = try self.onUxCommand(command);
            return;
        }
        const row = self.uxAt(self.ux_selected) orelse return;
        if (kind == .label_colors) {
            if (!self.canManageLabels() or self.labelManagerBusy()) return;
            if (!same(self.label_manager_account.value(), self.account())) return error.WrongAccount;
            self.preemptReadOnly();
            if (self.job.future != null) return error.OperationPending;
        }
        const value = try self.allocator.dupe(u8, row.value);
        defer self.allocator.free(value);
        const index = row.index;
        self.closeUx();
        if (kind == .actions) {
            const action = action_palette.entries[index].id;
            const key: ?u21 = switch (action) {
                .compose => 'c',
                .reply => 'r',
                .reply_all => 'R',
                .forward => 'f',
                .archive => 'x',
                .trash => 'D',
                .star => 's',
                .unread => 'u',
                .labels => 'm',
                .files => 'B',
                else => null,
            };
            if (key) |letter| return self.onKey(.{ .codepoint = letter });
            switch (action) {
                .calendar => try self.openCalendar(false),
                .follow_up => try self.editFollowUp(),
                .follow_ups => try self.openFollowUps(),
                .updates => self.openUpdates(),
                .manage_labels => try self.openLabelManager(),
                .scope => {
                    _ = try self.onUxCommand("scope");
                },
                .search_history => try self.openSearches(false),
                .saved_searches => try self.openSearches(true),
                .save_search => {
                    _ = try self.onUxCommand("save-search");
                },
                .send_grace => {
                    _ = try self.onUxCommand("send-grace");
                },
                .spam => try self.batchMail("spam", null, null, null, null),
                .unspam => try self.batchMail("unspam", null, null, null, null),
                .undo => try self.undoMail(),
                .help => try self.openHelp(),
                .theme => self.openThemePicker(),
                .contacts => {
                    self.picker = self.compose_active;
                    self.mode = .contacts;
                    try self.loadContacts("");
                },
                else => try self.runExtendedAction(action),
            }
        } else if (kind == .scope) {
            self.action_scope_thread = same(value, "thread");
            self.say(false, "Actions: {s}", .{if (self.action_scope_thread) @as([]const u8, "whole conversation · exact targets reviewed") else "this message"});
        } else if (kind == .history or kind == .saved) {
            try self.beginSearch(if (index == 0) .cache else .server);
            try self.query.set(self.allocator, value);
            self.query_scope = if (index == 0) .cache else .server;
            self.mode = .browse;
            self.rememberSearch();
            self.selected = 0;
            self.top = 0;
            self.clearHistory();
            self.generation +%= 1;
            try self.reload();
        } else try self.activateExtendedUx(kind, index, value);
    }
    fn onUxKey(self: *App, key: Key) !void {
        if (self.ux_overlay == .gmail_draft) {
            if (self.job.future != null) return;
            if (key.matches(Key.page_down, .{}) or key.matches('d', .{ .ctrl = true })) {
                self.gmail_scroll = @min(self.gmail_scroll +| @max(self.gmail_description_height, 1), self.gmail_description_lines -| self.gmail_description_height);
                return;
            }
            if (key.matches(Key.page_up, .{}) or key.matches('u', .{ .ctrl = true })) {
                self.gmail_scroll -|= @max(self.gmail_description_height, 1);
                return;
            }
        }
        if (self.ux_overlay == .follow_up and key.matches('s', .{ .ctrl = true })) {
            return self.saveFollowUp(false);
        }
        if (self.ux_overlay == .save_all and self.ux_focus == 1 and key.matches(' ', .{})) {
            if (self.uxAt(self.ux_selected)) |selected| {
                self.bulk_save_flags[selected.index] = !self.bulk_save_flags[selected.index];
                const object = try std.json.parseFromSliceLeaky(Value, self.ux_arena.?.allocator(), self.bulk_save_items.items[selected.index], .{});
                self.ux_rows.items[self.ux_selected].label = try std.fmt.allocPrint(self.ux_arena.?.allocator(), "{s} {s}", .{ if (self.bulk_save_flags[selected.index]) @as([]const u8, "[x]") else "[ ]", text(get(object, "filename")) });
            }
            return;
        }
        if (key.matches(Key.escape, .{}) or key.matches('c', .{ .ctrl = true }) or (self.ux_focus != 0 and key.matches('q', .{}))) {
            if (self.ux_overlay == .gmail_draft) self.dismissGmailDraft() else self.closeUx();
            return;
        }
        const rows = self.uxCount();
        if (tabDirection(key)) |backwards| {
            for (0..4) |_| {
                self.ux_focus = if (backwards) (self.ux_focus + 3) % 4 else (self.ux_focus + 1) % 4;
                if (self.ux_focus != 0 or self.uxInput()) break;
            }
            return;
        }
        if (key.matches(Key.enter, .{})) {
            if (self.ux_focus == 3) self.closeUx() else if ((self.ux_overlay == .discard or self.ux_overlay == .triage_review) and self.ux_focus != 2) self.ux_focus = 2 else try self.activateUx();
            return;
        }
        if (key.matches('n', .{ .ctrl = true }) or key.matches(Key.down, .{}) or (self.ux_focus == 1 and key.matches('j', .{}))) {
            const was_list = self.ux_focus == 1;
            self.ux_focus = 1;
            if (self.ux_overlay == .follow_up) {
                const next = if (self.ux_selected >= rows) @as(usize, 0) else if (was_list) @min(self.ux_selected +| 1, rows -| 1) else self.ux_selected;
                try self.selectFollowUpPreset(next);
            } else self.ux_selected = @min(self.ux_selected +| 1, rows -| 1);
        } else if (key.matches('p', .{ .ctrl = true }) or key.matches(Key.up, .{}) or (self.ux_focus == 1 and key.matches('k', .{}))) {
            const was_list = self.ux_focus == 1;
            self.ux_focus = 1;
            if (self.ux_overlay == .follow_up) {
                const previous = if (self.ux_selected >= rows) @as(usize, 1) else if (was_list) self.ux_selected -| 1 else self.ux_selected;
                try self.selectFollowUpPreset(previous);
            } else self.ux_selected -|= 1;
        } else if (self.ux_focus == 0) {
            if (key.matches('u', .{ .ctrl = true })) try self.ux_query.set(self.allocator, "") else try self.ux_query.handleKey(self.allocator, key, false, 4096);
            self.ux_selected = if (self.ux_overlay == .follow_up) self.ux_rows.items.len else 0;
        }
    }
    fn drawUx(self: *App, win: vaxis.Window) !void {
        if (self.ux_overlay == .none) return;
        if (self.ux_overlay == .follow_up) return self.drawFollowUpEditor(win);
        if (self.ux_overlay == .gmail_draft) return self.drawGmailDraft(win);
        self.mouse_hits.clear();
        const width = @min(win.width -| 2, 72);
        const desired_height: usize = @as(usize, @min(self.uxCount(), 12)) + 7;
        const height = @min(win.height -| 2, @max(desired_height, 8));
        if (width < 26 or height < 8) return;
        const area = win.child(.{ .x_off = @intCast((win.width - width) / 2), .y_off = @intCast((win.height - height) / 2), .width = width, .height = @intCast(height) });
        area.fill(.{ .style = self.style(.text) });
        const inner = self.panel(area, 0, width, self.ux_title, true);
        const prompt = if (self.ux_overlay == .save_search) "Name" else if (self.ux_overlay == .grace) "Seconds" else if (self.ux_overlay == .find) "Find" else if (self.ux_overlay == .save_all) "Folder" else "Filter";
        if (self.uxInput()) {
            try self.editLine(inner, 0, prompt, &self.ux_query, self.ux_focus == 0, if (self.ux_focus == 0) .selected else .text);
            self.mouseRows(inner, 0, 1, .dialog_action, 10);
        } else try self.line(inner, 0, if (self.ux_overlay == .draft_conflict) "Keep local text or load the saved version" else if (self.ux_overlay == .scope) "Choose what mail actions affect" else "Review the pinned target before confirming", .subject);
        try self.line(inner, 1, try self.fitLine(inner, self.ux_account.value(), inner.width), .muted);
        self.ux_height = inner.height -| 5;
        const count = self.uxCount();
        self.ux_selected = @min(self.ux_selected, count -| 1);
        const first_position = self.ux_selected -| (self.ux_height -| 1);
        if (count == 0 and self.uxFilter()) try self.line(inner, 2, "No matching actions or entries", .muted);
        for (first_position..@min(count, first_position + self.ux_height)) |position| {
            const entry = self.uxAt(position) orelse continue;
            const label = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}", .{ if (position == self.ux_selected) @as([]const u8, "› ") else "  ", entry.label });
            try self.line(inner, position - first_position + 2, try self.fitLine(inner, label, inner.width), if (position == self.ux_selected) (if (self.ux_focus == 1) .selected else .subject) else .text);
            self.mouseRows(inner, position - first_position + 2, 1, .dialog_action, position + 100);
        }
        const primary = if (self.ux_overlay == .draft_conflict) "[Use choice]" else if (self.ux_overlay == .actions) "[Run]" else if (self.ux_overlay == .aliases or self.ux_overlay == .contact_addresses) "[Use]" else if (self.ux_overlay == .discard) "[Discard]" else if (self.ux_overlay == .triage_review) "[Confirm]" else if (self.ux_overlay == .save_search or self.ux_overlay == .grace or self.ux_overlay == .save_all) "[Save]" else if (self.ux_overlay == .find) "[Find]" else if (self.ux_overlay == .label_colors) "[Save color]" else "[Open]";
        if (inner.height >= 6) if (self.uxAt(self.ux_selected)) |selected_row| {
            try self.line(inner, inner.height - 3, try self.fitLine(inner, selected_row.detail, inner.width), .muted);
        };
        const x = try self.actionButton(inner, inner.height - 2, 0, primary, self.ux_focus == 2, count > 0 or !self.uxFilter(), .dialog_action, 12);
        _ = try self.actionButton(inner, inner.height - 2, x, if (self.ux_overlay == .discard or self.ux_overlay == .triage_review) "[Cancel]" else "[Back]", self.ux_focus == 3, true, .dialog_action, 13);
        try self.line(inner, inner.height - 1, try self.fitLine(inner, if (self.uxFilter()) "Type filter · Ctrl+N/P Choose · Tab Controls · Enter · Esc Back" else "Tab Controls · Enter Activate · Esc Back", inner.width), .muted);
    }
    fn runExtendedAction(self: *App, action: action_palette.Id) !void {
        switch (action) {
            .sender => try self.cycleComposeIdentity(),
            .preview_browser => if (self.compose_active and self.compose.unknown_outcome) try self.openProtectedPreview() else try self.saveDraft(.save_browser),
            .gmail_draft => try self.openGmailDraft(),
            .discard_draft => try self.openDiscardDraft(),
            .add_contact => try self.addCurrentSender(),
            .save_all => try self.openSaveAll(null),
            .find => try self.beginUx(.find, " Find in message "),
            .copy_message => try self.copyReaderMessage(),
            .view_editor => try self.viewReaderEditor(),
            .select_text => try self.requestReaderCopy(.cursor, self.reader_scroll, 0),
            .next_unread => try self.navigateUnread(true),
            .previous_unread => try self.navigateUnread(false),
            .resume_send => {
                _ = try self.onUxCommand("resume-send");
            },
            .cancel_send => {
                _ = try self.onUxCommand("cancel-send");
            },
            else => return error.UnknownAction,
        }
    }
    fn activateExtendedUx(self: *App, kind: UxOverlay, index: usize, value: []const u8) !void {
        switch (kind) {
            .aliases => try self.useComposeIdentity(index),
            .contact_addresses => {
                try self.useContactAddress(value);
            },
            .discard => {
                if (self.compose_active and self.compose.unknown_outcome) return error.UnknownOutcome;
                self.preemptReadOnly();
                try self.start(.draft_discard, .{ .cmd = "draft.discard", .account = self.account(), .draftId = self.ux_target.value() });
            },
            .triage_review => {
                const request = try std.json.parseFromSliceLeaky(Value, self.frame.allocator(), self.pending_triage.value(), .{});
                self.action_using_pinned = true;
                defer self.action_using_pinned = false;
                try self.batchMail(text(get(request, "action")), if (get(request, "unread") == .bool) truth(get(request, "unread")) else null, if (get(request, "starred") == .bool) truth(get(request, "starred")) else null, null, null);
            },
            .label_colors => {
                const operation = try self.operationId(self.allocator);
                defer self.allocator.free(operation);
                try self.label_operations[self.account_index].set(self.allocator, operation);
                try self.label_errors[self.account_index].set(self.allocator, "");
                self.label_write_page[self.account_index] = .rename;
                self.label_color_write[self.account_index] = true;
                try self.start(.label_color, .{ .cmd = "labels.color", .account = self.account(), .labelId = self.ux_target.value(), .color = .{ .backgroundColor = value, .textColor = if (index == 0) @as([]const u8, "#ffffff") else "#000000" }, .operationId = operation });
            },
            .save_all => try self.startSaveAll(value),
            else => return error.UnknownAction,
        }
    }
    fn addCurrentSender(self: *App) !void {
        const message = self.focusedMessage() orelse return error.MessageRequired;
        const sender = get(message, "from");
        const addresses = [_]types.Address{.{ .address = text(get(sender, "address")), .name = text(get(sender, "name")) }};
        const value = try @import("json.zig").value(self.frame.allocator(), types.Contact{ .name = text(get(sender, "name")), .emails = &addresses });
        self.picker = false;
        try self.editContact(value);
    }
    fn openDiscardDraft(self: *App) !void {
        const draft = if (self.compose_active) self.compose.id.value() else if (self.drafts_list) self.messageId() else return error.DraftRequired;
        if (draft.len == 0) return error.DraftRequired;
        if (self.compose_active and self.compose.unknown_outcome) return error.UnknownOutcome;
        try self.beginUx(.discard, " Discard local draft · emails are kept ");
