            if (self.job.kind == .grace_cancel) {
                self.graceCancelUnconfirmed(@errorName(err));
                return;
            }
            if (self.job.kind == .attachments_save) {
                self.abortSaveAll(@errorName(err));
                return;
            }
            if (self.job.kind == .attachment_import) self.pending_file_count = 0;
            if (self.pageLoadCurrent() and self.page_loading_generation == self.job.generation) self.rollbackPageLoad();
            if (self.job.kind == .label_write or self.job.kind == .label_color) {
                self.label_unknown[self.job.account_index] = true;
                self.label_errors[self.job.account_index].set(self.allocator, @errorName(err)) catch {};
                self.label_manager_page = .list;
                self.dialog_focus.reset(.label_manager, 1);
                self.labelUnknownNotice();
            } else if (self.job.kind == .label_receipt) {
                self.sayFailure("Label receipt lookup failed · do not retry the write", @errorName(err));
            } else if (self.job.kind == .send or self.job.kind == .grace_process or self.job.kind == .invitation) {
                (if (self.job.kind != .invitation) &self.compose.operation_error else &self.invitation_operation_error).set(self.allocator, @errorName(err)) catch {};
                self.markUnknown(if (self.job.kind == .grace_process) .send else self.job.kind);
            } else if (self.job.kind == .invitation_reconcile) self.invitationCheckUncertain(@errorName(err)) else if (self.job.kind == .draft_operations) self.say(true, "Receipt lookup failed · draft remains protected", .{}) else if (err != error.Canceled) {
                if (self.job.kind == .list) self.syncFailed(self.job.account_index, @errorName(err));
                if (self.job.kind == .contacts) self.contacts_state = if (err == error.PermissionDenied) .denied else .failed;
                if (self.job.kind == .open and self.job.calendar_join_open) self.calendarJoinFailed(@errorName(err));
                if (self.job.kind == .open and self.job.calendar_browser_open) self.calendarBrowserFailed(@errorName(err));
                if (self.job.kind == .attachment_save) self.fileDialogFailure(err) else if (self.job.kind == .open and self.job.saved_attachment_open) self.attachmentOpenFailed(@errorName(err)) else self.sayError(@errorName(err));
            }
        } else if (self.job.response) |response| {
            self.apply(self.job.kind, response) catch |err| {
                if (completed_kind == .grace_process or completed_kind == .invitation) self.markUnknown(completed_kind);
                if (completed_kind == .invitation_reconcile) self.invitationCheckUncertain(@errorName(err));
                if (self.job.kind == .attachments_save) self.abortSaveAll(@errorName(err));
                if (self.job.kind == .attachment_import) self.pending_file_count = 0;
                return err;
            };
        }
        if (self.exit_persistence) return;
        if (self.pending_contacts and self.contactsOpen()) try self.dispatchPending();
        if (self.job.future != null) return;
        try self.retryLocalCache();
        try self.dispatchPending();
    }
    fn finishSend(self: *App) !void {
        // A provider may explicitly prove that preparation failed before any
        // submission. Handle that phase without allocating a receipt copy.
        if (self.job.failure) |failure| {
            if (failure == error.ReviewedDraftChanged) {
                self.client.sendReceipt(self.job.request, true);
                if (self.job.account_index == self.account_index and self.job.generation == self.generation and self.compose_active and same(self.job.draft_target.slice(), self.compose.id.value())) {
                    self.compose.unknown_outcome = false;
                    self.savedDraftChanged();
                    self.mode = .compose;
                }
                return;
            }
            if (failure == error.SendNotStarted) {
                self.client.sendReceipt(self.job.request, true);
                if (self.job.account_index == self.account_index and self.job.generation == self.generation and self.compose_active and same(self.job.draft_target.slice(), self.compose.id.value())) {
                    self.compose.unknown_outcome = false;
                    self.retireComposeMeasure();
                    self.mode = .compose;
                    self.say(true, "Send did not start · draft retained · review again", .{});
                }
                return;
            }
        }
        // Applying the receipt can replace job_arena with a mailbox follow-up.
        // Pin its original identity before any parsing or state allocation.
        const request = self.allocator.dupe(u8, self.job.request) catch |err| {
            self.client.sendReceipt(self.job.request, false);
            self.markUnknown(.send);
            return err;
        };
        defer self.allocator.free(request);
        var accepted = false;
        defer if (!accepted) {
            self.client.sendReceipt(request, false);
            self.markUnknown(.send);
        };
        if (self.job.account_index != self.account_index or self.job.generation != self.generation or !self.compose_active or !same(self.job.draft_target.slice(), self.compose.id.value())) return error.SendContextChanged;
        if (self.job.failure) |err| {
            self.compose.operation_error.set(self.allocator, @errorName(err)) catch {};
            return;
        }
        const response = self.job.response orelse return error.InvalidProviderResponse;
        try self.apply(.send, response);
        if (self.compose.unknown_outcome) return;
        self.client.sendReceipt(request, true);
        accepted = true;
    }
    fn retryLocalCache(self: *App) !void {
        // Retry only on an owned completion or subsequent user input. A busy
        // cache retains one local intent; it never schedules network fetching
        // merely because a short disk commit held the shared read lock.
        if (self.pending_cached_contacts and self.contactsOpen()) {
            try self.cachedContacts();
            return;
        }
        if (self.pending_cached_list) {
            _ = self.loadCachedList(self.messageId()) catch |err| if (err == error.CacheBusy) false else return err;
            return;
        }
        if (self.pending_cached_reader_refresh) {
            try self.refreshCachedReader();
            return;
        }
        if (self.pending_cached_read) {
            const full_thread = self.pending_cached_thread;
            try self.preview(full_thread);
        }
    }
    fn applyUncachedRefresh(self: *App, response: []const u8, generation: u64) !bool {
        if (generation != self.generation) return false;
        try self.replaceList(.list, response);
        self.cache_view_missing = false;
        self.pending_remote_list = false;
        self.pending_cached_list = false;
        self.sayFailure("Mail readable · browser cache unchanged", "BrowserCacheQuotaExceeded");
        return true;
    }
    fn dispatchPending(self: *App) !void {
        if (self.calendar.open) {
            if (try self.dispatchCalendarPending()) return;
            return self.dispatchMeetings();
        }
        if (self.gmail_reload_pending and self.compose_active and self.job.future == null) {
            self.gmail_reload_pending = false;
            try self.requestGmailDraftInfo();
            return;
        }
        if (self.compose_choice) return;
        if (try self.dispatchComposer()) return;
        // At most six coalesced flags exist. Local cache hits may complete
        // without starting a future, so drain them rather than leaving the
        // next intent waiting for an event that will never arrive.
        for (0..6) |_| {
            if (self.job.future != null) return;
            if ((self.label_picker or self.mode == .label_manager) and self.pending_labels) {
                self.pending_labels = false;
                try self.start(.labels_list, .{ .cmd = "labels.list", .account = self.account() });
            } else if (self.label_picker and self.pending_label_state) {
                try self.requestLabelState();
            } else if (self.bulk_save_pending) {
                try self.nextSaveAll();
            } else if (self.pending_contacts) {
                self.pending_contacts = false;
                if (self.contactsOpen() and same(self.contacts_account.value(), self.account())) {
                    self.contacts_state = if (self.contacts_cache_ready) .cached else .loading;
                    try self.start(.contacts, .{ .account = self.contacts_account.value(), .cmd = if (self.contacts_query.value().len == 0) "contacts.list" else "contacts.search", .query = self.contacts_query.value() });
                }
            } else if (self.pending_page) {
                try self.consumePendingPage();
            } else if (self.pending_window_provider) {
                try self.dispatchWindowProvider();
            } else if (self.pending_list) {
                self.pending_list = false;
                if (self.follow_ups_list) try self.loadFollowUps() else try self.reload();
            } else if (self.pending_remote_list) {
                self.pending_remote_list = false;
                try self.cursor.set(self.allocator, "");
                try self.fetchMailboxPage();
            } else if (self.pending_compose != .none) {
                try self.dispatchConversationCompose();
                if (self.compose_choice) return;
            } else if (self.pending_read) {
                self.pending_read = false;
                const full_thread = self.pending_thread;
                self.pending_thread = false;
                try self.preview(full_thread);
            } else if (self.pending_labels) {
                self.pending_labels = false;
                try self.start(.labels_list, .{ .cmd = "labels.list", .account = self.account() });
            } else if (self.remote_preferences_pending and Io.Timestamp.now(self.io, .awake).toMilliseconds() >= self.remote_preferences_retry_after) {
                var scratch: std.heap.ArenaAllocator = .init(self.allocator);
                defer scratch.deinit();
                const request = try self.remotePreferencesRequest(scratch.allocator());
                try self.start(.preferences_save, request);
                self.job.preferences_revision = self.preferences_revision;
                self.remote_preferences_pending = false;
                return;
            } else if (self.capabilities.updates and (!self.update_loaded or self.update_pending) and (self.ordinaryMailbox() or self.update_open)) {
                if (self.options.fixtures and !self.update_fixture_enabled) {
                    self.update_loaded = true;
                    self.update_pending = false;
                    return;
                }
                const kind: JobKind = if (!self.update_loaded) .updates_load else .updates_check;
                self.update_pending = false;
                if (kind == .updates_check) self.update_manual_check = false;
                if (kind == .updates_check) {
                    // A canceled check is still an attempt. Navigation must not
                    // restart network discovery on every following key press.
                    const attempted_at = updates.now(self.io);
                    self.update_snapshot.state.checkedAt = attempted_at;
                    self.update_snapshot.state.nextCheckAt = attempted_at + updates.daily_seconds;
                }
                try self.start(kind, .{ .cmd = "updates" });
                return;
            } else return self.dispatchMeetings();
        }
    }
    fn apply(self: *App, kind: JobKind, response: []const u8) !void {
        // Validate the envelope before replacing a valid cached view.
        _ = if (kind == .draft_measure) @as(Value, .null) else self.data(self.job_arena.allocator(), response) catch |err| {
            if (kind == .grace_cancel) {
                self.graceCancelUnconfirmed(if (err == error.OperationRejected) self.status_error_code[0..self.status_error_len] else @errorName(err));
                return;
            }
            if (kind == .grace_process and err != error.OperationRejected) {
                self.compose.operation_error.set(self.allocator, @errorName(err)) catch {};
                self.markUnknown(.send);
                return;
            }
            if (kind == .gmail_draft_action) {
                self.compose.gmail_guard_unknown = true;
                self.gmail_reload_pending = true;
            }
            if (err == error.OperationRejected) {
                if ((kind == .send or kind == .grace_stage) and same(self.status_error_code[0..self.status_error_len], "ReviewedDraftChanged")) {
                    if (!self.compose_active or self.job.account_index != self.account_index or self.job.generation != self.generation or !same(self.job.draft_target.slice(), self.compose.id.value())) return error.SendContextChanged;
                    self.compose.unknown_outcome = false;
                    self.savedDraftChanged();
                    self.mode = .compose;
                    return;
                }
                if (same(self.status_error_code[0..self.status_error_len], "ArchivedDraftReadOnly") and try self.recoverSettledDraft(kind)) return;
                if (kind == .follow_up_write and same(self.status_error_code[0..self.status_error_len], "FollowUpChanged")) {
                    self.loadFollowUps() catch {};
                    self.sayError("FollowUpChanged");
                    return;
                }
                if (kind == .attachments_save) self.abortSaveAll(self.status_error_code[0..self.status_error_len]);
                if (kind == .attachment_import) self.pending_file_count = 0;
                if (kind == .attachment_save) try self.file_browser_error.set(self.allocator, humanError(self.status_error_code[0..self.status_error_len]));
                if (kind == .open and self.job.calendar_join_open) self.calendarJoinFailed(self.status_error_code[0..self.status_error_len]);
                if (kind == .open and self.job.calendar_browser_open) self.calendarBrowserFailed(self.status_error_code[0..self.status_error_len]);
                if (kind == .open and self.job.saved_attachment_open) {
                    var code_buffer: [64]u8 = undefined;
                    const code = self.status_error_code[0..self.status_error_len];
                    @memcpy(code_buffer[0..code.len], code);
                    self.attachmentOpenFailed(code_buffer[0..code.len]);
                }
                if (self.pageLoadCurrent() and (kind == .list or kind == .cached_search or kind == .drafts)) self.rollbackPageLoad();
                // markUnknown replaces the status diagnostic; keep the code as the receipt reason.
                if ((kind == .send or kind == .grace_process) and self.status_error_len > 0) self.compose.operation_error.set(self.allocator, self.status_error_code[0..self.status_error_len]) catch {};
                if (kind == .send or kind == .grace_process or kind == .invitation) self.markUnknown(kind);
                if (kind == .list) self.syncFailed(self.job.account_index, self.status_error_code[0..self.status_error_len]);
                if (kind == .contacts) self.contacts_state = if (same(self.status_error_code[0..self.status_error_len], "PermissionDenied")) .denied else .failed;
                if ((kind == .label_write or kind == .label_color) and same(self.status_error_code[0..self.status_error_len], "UnknownOutcome")) {
                    self.label_unknown[self.job.account_index] = true;
                    self.label_manager_page = .list;
                    self.dialog_focus.reset(.label_manager, 1);
                    self.labelUnknownNotice();
                }
                return;
            }
            return err;
        };
        switch (kind) {
            .follow_up_list => try self.replaceFollowUps(response),
            .follow_up_write => {
                const result = try self.data(self.job_arena.allocator(), response);
                const completed = truth(get(result, "done"));
                try self.loadFollowUps();
                self.say(false, "{s} · Gmail is unchanged", .{if (completed) @as([]const u8, "Follow-up done · local reminder removed") else "Local follow-up saved"});
            },
            .preferences_save => return error.InvalidPreferencesResponse,
            .calendar_list, .calendar_agenda, .calendar_event, .calendar_plan, .calendar_review, .calendar_apply, .calendar_reconcile, .calendar_event_edit, .calendar_event_review, .calendar_event_apply, .calendar_event_reconcile, .calendar_event_pending, .calendar_event_retry, .calendar_event_abandon, .calendar_guest_contacts => return error.InvalidCalendarResponse,
            .updates_load, .updates_check, .meeting_calendars, .meeting_agenda, .meeting_open => return error.InvalidUpdateResponse,
            .labels_list => {
                try self.replaceLabels(response);
                if (!self.keepBackgroundDiagnostic(.labels_list)) self.say(false, "{s}", .{if (self.label_picker) "Choose label · Enter Add · - Remove" else "Ready"});
            },
            .label_state => {
                const result = try self.data(self.job_arena.allocator(), response);
                if (!self.label_picker or !same(self.pinned_targets.account.slice(), self.account())) return;
                if (!truth(get(result, "complete")) or integer(get(result, "count")) != self.pinned_targets.count) return error.IncompleteLabelScope;
                const confirmed_ids = items(get(result, "messageIds"));
                if (confirmed_ids.len != self.pinned_targets.count) return error.IncompleteLabelScope;
                for (confirmed_ids) |id| if (!self.pinned_targets.contains(text(id))) return error.IncompleteLabelScope;
                self.label_memberships.reset();
                self.label_memberships.targets = self.pinned_targets.count;
                for (items(get(result, "labels"))) |item| {
                    const applied = integer(get(item, "appliedCount"));
                    if (applied < 0) return error.InvalidLabelState;
                    try self.label_memberships.add(text(get(item, "id")), @intCast(applied));
                }
                self.label_memberships.ready = true;
                self.say(false, "Labels for {d} messages · Space Toggle · Apply commits", .{self.pinned_targets.count});
            },
            .triage_scope => {
                const result = try self.data(self.job_arena.allocator(), response);
                if (!self.triage_waiting or !same(self.pinned_targets.account.slice(), self.account())) return;
                self.triage_waiting = false;
                if (!truth(get(result, "complete"))) return error.IncompleteConversation;
                self.pinned_targets.clear();
                for (items(get(result, "messageIds"))) |id| try self.pinned_targets.toggle(text(id));
                if (self.pinned_targets.count == 0 or integer(get(result, "count")) != self.pinned_targets.count) return error.IncompleteConversation;
                if (self.triage_for_labels) self.pending_label_state = true else {
                    try self.beginUx(.triage_review, " Review conversation action ");
                    const summary = try std.fmt.allocPrint(self.frame.allocator(), "{d} messages · exact targets pinned", .{self.pinned_targets.count});
                    try self.uxRow(.{ .label = summary, .detail = "New arrivals are excluded from this change" });
                    try self.uxRow(.{ .label = self.triage_subject.value() });
                }
            },
            .unread_navigation => {
                const result = try self.data(self.job_arena.allocator(), response);
                const matches = items(get(result, "messages"));
                if (matches.len == 0) {
                    self.say(false, "No more unread mail in this cached view", .{});
                    return;
                }
                const target = try self.allocator.dupe(u8, text(get(matches[0], "id")));
                defer self.allocator.free(target);
                if (self.cacheSearch() and cache_query.needsBody(self.query.value())) {
                    // Keep the anchored body-query page on the worker, and
                    // move only after that page is ready to display.
                    try self.startTarget(.cached_search, .{ .cmd = "mail.search", .account = self.account(), .cacheOnly = true, .label = self.activeLabel(), .query = self.query.value(), .limit = @as(usize, 32), .anchorMessageId = target }, target);
                    return;
                }
                if (!try self.loadCachedListImpl(target, true)) return error.AnchorNotCached;
                try self.revealUnreadTarget(target);
            },
            .draft_discard => {
                _ = try self.data(self.job_arena.allocator(), response);
                if (self.compose_active and same(self.compose.id.value(), self.ux_target.value())) {
                    self.cancelAutosaveTimer();
                    self.clearGraceRecovery();
                    self.clearComposePreview();
                    self.compose.deinit(self.allocator);
                    self.compose = .{};
                    self.compose_active = false;
                }
                self.mode = .browse;
                self.generation +%= 1;
                _ = try self.loadCachedList("");
                self.say(false, "Local draft discarded · email kept", .{});
            },
            .attachment_import => {
                const result = try self.data(self.job_arena.allocator(), response);
                const attachment = try std.json.parseFromValueLeaky(types.Attachment, self.frame.allocator(), result, .{ .allocate = .alloc_always });
                if (self.compose.attachments.len >= types.Limits.attachments) return error.TooManyAttachments;
                const related_count = if (self.compose.include_original) (if (self.compose.original) |original| original.resources.len else 0) else 0;
                try types.Limits.validateComposeParts(self.compose.attachments.len + 1, related_count);
                const selected_attachments = try self.frame.allocator().alloc(types.Attachment, self.compose.attachments.len + 1);
                @memcpy(selected_attachments[0..self.compose.attachments.len], self.compose.attachments);
                selected_attachments[self.compose.attachments.len] = attachment;
                var aggregate: usize = 0;
                for (selected_attachments[0 .. self.compose.attachments.len + 1]) |item| aggregate = std.math.add(usize, aggregate, item.size) catch return error.AttachmentsTooLarge;
                if (if (self.compose.include_original) self.compose.original else null) |original| for (original.resources) |item| {
                    aggregate = std.math.add(usize, aggregate, item.size) catch return error.AttachmentsTooLarge;
                };
                if (aggregate > types.Limits.attachment_bytes) {
                    self.pending_file_count = 0;
                    return error.AttachmentsTooLarge;
                }
                try self.compose.replaceAttachments(self.allocator, selected_attachments[0 .. self.compose.attachments.len + 1]);
                try self.composerChanged();
                self.pending_file_position += 1;
                if (self.pending_file_position < self.pending_file_count) try self.importNextFile() else {
                    self.pending_file_count = 0;
                    self.mode = .compose;
                    self.compose.insert_mode = false;
                    try self.saveDraft(.save);
                }
            },
            .attachments_save => {
                const result = try self.data(self.job_arena.allocator(), response);
                if (!truth(get(result, "saved"))) return error.AttachmentSaveFailed;
                self.bulk_save_written += 1;
                self.bulk_save_position += 1;
                try self.nextSaveAll();
            },
            .grace_stage, .grace_resume => {
                const result = try self.data(self.job_arena.allocator(), response);
                if (!same(text(get(result, "state")), "queued")) return error.InvalidQueueState;
                try self.grace_queue.set(self.allocator, text(get(result, "queueId")));
                try self.grace_draft.set(self.allocator, text(get(result, "draftId")));
                try self.grace_account.set(self.allocator, self.account());
                self.grace_due = integer(get(result, "dueAtMs"));
                self.grace_resume_required = truth(get(result, "resumeRequired"));
                if (self.grace_resume_required) {
                    self.grace_active = false;
                    self.grace_recovery = true;
                    self.grace_pending.store(false, .release);
                    self.mode = .compose;
                    self.say(false, "Imported send paused · Ctrl+S Review · :resume-send / :cancel-send", .{});
                    return;
                }
                self.grace_active = true;
                self.grace_focus = 0;
                self.grace_recovery = false;
                self.grace_pending.store(true, .release);
                self.mode = .compose;
                self.compose.insert_mode = false;
                self.say(false, "Queued · nothing sent yet · Ctrl+Z Undo · Ctrl+S Send now", .{});
            },
            .grace_cancel => {
                const result = try self.data(self.job_arena.allocator(), response);
                if (!same(text(get(result, "state")), "canceled")) {
                    self.graceCancelUnconfirmed("InvalidQueueState");
                    return;
                }
                self.grace_active = false;
                self.grace_recovery = false;
                self.grace_pending.store(false, .release);
                self.mode = .compose;
                self.retireComposeMeasure();
                self.say(false, "Send cancelled · draft retained", .{});
                if (self.grace_close) self.quit = true;
            },
            .grace_process => try self.applyGraceResult(response),
            .queue_inspect => {
                const result = try self.data(self.job_arena.allocator(), response);
                self.clearGraceRecovery();
                self.compose.unknown_outcome = self.receipt_unknown;
                for (items(get(result, "queue"))) |entry| {
                    if (!same(text(get(entry, "draftId")), self.compose.id.value())) continue;
                    const state = text(get(entry, "state"));
                    if (same(state, "queued") or same(state, "submitting") or same(state, "unknown")) {
                        try self.grace_queue.set(self.allocator, text(get(entry, "queueId")));
                        try self.grace_draft.set(self.allocator, text(get(entry, "draftId")));
                        try self.grace_account.set(self.allocator, self.account());
                        if (same(state, "queued")) {
                            self.grace_recovery = true;
                            self.grace_resume_required = truth(get(entry, "resumeRequired"));
                            self.grace_due = integer(get(entry, "dueAtMs"));
                        } else {
                            self.compose.unknown_outcome = true;
                            try self.retainSendReceipt(entry);
                        }
                    }
                }
                if (self.compose.unknown_outcome) self.markUnknown(.send) else if (self.grace_recovery) self.say(false, "{s}", .{if (self.grace_resume_required) @as([]const u8, "Imported send paused · Ctrl+S Review · :resume-send / :cancel-send") else "Queued send paused · :resume-send / :cancel-send · no automatic send"}) else self.say(false, "Receipts checked · Ctrl+S Review send", .{});
            },
            .label_write, .label_receipt, .label_color => try self.applyManagerLabel(response),
            .batch, .undo => {
                const result_value = try self.data(self.job_arena.allocator(), response);
                if (kind == .batch and text(get(result_value, "undoToken")).len > 0) {
                    try self.undo_token.set(self.allocator, text(get(result_value, "undoToken")));
                    try self.undo_account.set(self.allocator, self.account());
                }
                self.mail_selection.clear();
                self.mode = .browse;
                self.say(truth(get(result_value, "partial")), "{s}: {d} applied, {d} restored{s} · :undo", .{
                    if (kind == .undo) "Undo" else "Mail action", integer(get(result_value, "appliedCount")), integer(get(result_value, "restoredCount")),
                    if (truth(get(result_value, "partial"))) " · some outcomes need review" else "",
                });
                self.generation +%= 1;
                self.action_notice = true;
                self.status_kind = .action;
                try self.cursor.set(self.allocator, "");
                self.clearHistory();
                const retained = if (self.action_anchor.value().len > 0) self.action_anchor.value() else self.action_neighbor.value();
                _ = try self.loadCachedList(retained);
                if (self.selectedMessage()) |selected_message| {
                    if (!same(text(get(selected_message, "id")), retained) and self.action_neighbor.value().len > 0) _ = try self.loadCachedList(self.action_neighbor.value());
                }
                self.top = self.selected -| self.action_screen_row;
                self.pending_list = true;
            },
            .refresh => unreachable, // Refresh metadata/merge is handled by finish.
            .recipient_cache => {
                try self.replaceRecipients(response);
            },
            .recipient_refresh => {
                self.pending_recipient_cache = true;
            },
            .cached_search => {
                self.pending_cached_list = false;
                if (self.job.unread_target.len > 0) {
                    const result = try self.data(self.job_arena.allocator(), response);
                    var present = false;
                    for (items(get(result, "messages"))) |message| present = present or same(text(get(message, "id")), self.job.unread_target.slice());
                    if (!present) return error.AnchorNotCached;
                    try self.replaceList(.cached_search, response);
                    try self.revealUnreadTarget(self.job.unread_target.slice());
                    return;
                }
                try self.replaceList(.cached_search, response);
                if (!self.compose_active and self.messages.len > 0 and self.thread.len == 0) self.pending_read = true;
            },
            .list, .drafts => {
                try self.replaceList(kind, response);
                if (kind == .list) {
                    self.sync[self.account_index].state = .current;
                    // A provider page outside newest-N retention is still a
                    // valid visible page. Never erase it with an empty local
                    // subset just because those older IDs were evicted.
                    self.pending_remote_list = false;
                    if (!self.compose_active and self.messages.len > 0 and self.thread.len == 0) self.pending_read = true;
                }
            },
            .read, .thread => {
                try self.replaceReader(kind == .thread, response, false);
            },
            .compose, .draft_read => {
                if (kind == .draft_read and self.job.reload_conflict) {
                    if (!self.compose_active or self.job.account_index != self.account_index or self.job.generation != self.generation or !same(self.job.draft_target.slice(), self.compose.id.value())) return;
                    if (self.compose.revision != self.job.reload_revision or self.compose.revision != self.compose.saved_revision) {
                        self.savedDraftChanged();
                        try self.openDraftConflict();
                        return;
                    }
                }
                if (kind == .draft_read) self.compose_intent = .none;
                const result = self.data(self.job_arena.allocator(), response) catch |err| {
                    if (err == error.OperationRejected) return;
                    return err;
                };
                self.cancelAutosaveTimer();
                self.autosave_due = false;
                self.clearGraceRecovery();
                // The replaced composer's preview is released even if loading fails.
                self.clearComposePreview();
                try self.compose.load(self.allocator, result);
                self.compose_measure = .{};
                self.requestComposeMeasure();
                self.compose_view = .rendered;
                self.compose_preview_full = false;
                self.compose_original_folded = null;
                self.compose_policy_undo = null;
                self.compose_policy_redo = null;
                self.compose_preview_scroll = 0;
                self.compose_plain_scroll = 0;
                self.compose_snapshot_scroll = 0;
                self.compose.new_draft = kind == .compose;
                if (kind == .compose) self.positionReplyBody();
                if (self.compose.from.value().len == 0) {
                    try self.compose.from.set(self.allocator, self.account());
                    try self.compose.from_name.set(self.allocator, text(get(self.accounts[self.account_index], "senderName")));
                }
                self.compose_active = true;
                self.completion_open = false;
                self.completion_dismissed = false;
                self.review_ready = false;
                self.mode = .compose;
                self.pending_read = false;
                self.pending_thread = false;
                if (self.compose.original != null) {
                    self.compose_original = true;
                    self.compose_source_mode = .formatted;
                    if (kind == .draft_read) self.compose_intent = if (self.compose.thread.value().len == 0) .forward else .reply;
                    self.clearReader();
                } else if (kind == .draft_read or !self.compose_original) {
                    self.compose_original = false;
                    self.clearReader();
                }
                if (kind == .draft_read and self.compose.original == null) {
                    self.compose_source_mode = .text;
                    for (self.compose.attachments) |attachment| {
                        if (originalAttachment(attachment)) {
                            self.compose_source_mode = .attached;
                            self.compose_intent = .forward;
                            break;
                        }
                    }
                }
                if (kind == .compose and self.compose_intent == .new and self.pending_contact_generation == self.job.generation and same(self.pending_contact_account.value(), self.account()) and self.pending_contact_address.value().len > 0) {
                    const display = try self.allocator.dupe(u8, self.pending_contact_address.value());
                    defer self.allocator.free(display);
                    self.clearContactComposeIntent();
                    self.picker = true;
                    try self.useContactAddress(display);
                }
                self.composeCachedContacts();
                self.pending_identities = self.capabilities.aliases;
                if (kind == .compose) {
                    const signature_in = text(get(self.accounts[self.account_index], "signature"));
                    if (signature_in.len > 0) {
                        try self.setComposeSignature(signature_in);
                        try self.composerChanged();
                    }
                }
                self.say(false, "Draft retained · i Edit · e $EDITOR · Ctrl+S Review send", .{});
                if (kind == .draft_read) {
                    self.compose.unknown_outcome = true;
                    try self.inspectDraftOperations();
                } else _ = try self.dispatchComposer();
            },
            .identities => {
                try self.replaceIdentities(response);
                if (self.ux_overlay == .aliases) {
                    self.ux_rows.clearRetainingCapacity();
                    try self.senderRows();
                }
                if (self.compose_active and self.compose.new_draft and self.compose.revision == 0 and !self.compose.unknown_outcome) {
                    for (self.identities) |identity| if (std.ascii.eqlIgnoreCase(text(get(identity, "address")), self.compose.from.value())) {
                        const signature_in = text(get(identity, "signature"));
                        if (signature_in.len > 0) {
                            try self.setComposeSignature(signature_in);
                            try self.composerChanged();
                        }
                        break;
                    };
                }
                if (!self.keepBackgroundDiagnostic(.identities)) self.say(false, "Verified sending identities ready · f chooses From", .{});
            },
            .draft_measure => {
                if (!self.composeMeasureJobCurrent()) return;
                // This background diagnostic must not replace an explicit
                // preview/save notice when unfinished addresses prevent sizing.
                const envelope = try std.json.parseFromSliceLeaky(Value, self.job_arena.allocator(), response, .{});
                if (get(envelope, "ok") == .bool and !truth(get(envelope, "ok"))) {
                    const code = text(get(get(envelope, "error"), "code"));
                    if (validDiagnosticCode(code)) try self.compose_measure.failure.set(code);
                    return;
                }
                const result = get(envelope, "data");
                if (!self.compose_active or !same(self.job.draft_target.slice(), self.compose.id.value()) or !same(self.compose_measure.draft.slice(), self.compose.id.value()) or self.compose_measure.revision != self.compose.revision or self.compose.saved_revision != self.compose.revision or !same(text(get(result, "operationId")), self.compose_measure.operation.slice()) or get(result, "revision") != .integer or integer(get(result, "revision")) != self.compose.revision) return;
                if (self.compose_measure.content_digest.len != 64 or !same(text(get(result, "contentDigest")), self.compose_measure.content_digest.slice())) {
                    self.savedDraftChanged();
                    return error.DraftChanged;
                }
                const exact = truth(get(result, "exact"));
                const over_limit = truth(get(result, "overLimit"));
                if (get(result, "maxBytes") != .integer or integer(get(result, "maxBytes")) <= 0) return error.SizeUnavailable;
                if (exact) {
                    if (get(result, "bytes") != .integer or integer(get(result, "bytes")) < 0) return error.SizeUnavailable;
                } else if (!over_limit or get(result, "bytes") != .null or !renderedSizeFailure(text(get(result, "admissionError")))) return error.SizeUnavailable;
                self.compose_measure.bytes = if (exact) @intCast(integer(get(result, "bytes"))) else null;
                self.compose_measure.max_bytes = @intCast(integer(get(result, "maxBytes")));
                self.compose_measure.exact = exact;
                self.compose_measure.measured = true;
                self.compose_measure.measured_operation = self.compose_measure.operation;
                self.compose_measure.pending = false;
                self.compose_measure.over_limit = over_limit;
                self.compose_measure.sendable = exact and !over_limit and truth(get(result, "sendable"));
                self.compose_measure.without_original = if (get(result, "withoutOriginalBytes") == .integer and integer(get(result, "withoutOriginalBytes")) >= 0) @intCast(integer(get(result, "withoutOriginalBytes"))) else null;
                self.compose_measure.failure = .{};
                const admission = text(get(result, "admissionError"));
                if (validDiagnosticCode(admission)) try self.compose_measure.failure.set(admission);
            },
            .autosave => {
                const result = try self.data(self.job_arena.allocator(), response);
                try self.compose.id.set(self.allocator, text(get(result, "id")));
                self.compose.saved_revision = self.autosave_revision;
                self.requestComposeMeasure();
                self.say(false, "{s}", .{if (self.compose.revision == self.compose.saved_revision) (if (self.capabilities.durable_drafts) "Draft saved locally · no mail sent" else "Draft saved in this tab · reload/disconnect discards it") else "Earlier changes saved · newer edits pending"});
            },
            .draft_operations => {
                const result = try self.data(self.job_arena.allocator(), response);
                if (get(result, "operations") != .array) return error.InvalidProviderResponse;
                var uncertain: ?Value = null;
                for (items(get(result, "operations"))) |operation| if (same(text(get(operation, "draftId")), self.compose.id.value()) and same(text(get(operation, "outcome")), "unknown")) {
                    uncertain = operation;
                    break;
                };
                self.compose.unknown_outcome = uncertain != null;
                if (uncertain) |operation| {
                    const id = text(get(operation, "id"));
                    const code = text(get(operation, "errorCode"));
                    // The journal may lack a code it failed to persist; keep the
                    // reason already known for this same operation.
                    const keep = code.len == 0 and id.len > 0 and same(id, self.compose.operation_id.value());
                    if (!keep) try self.compose.operation_error.set(self.allocator, code);
                    try self.compose.operation_id.set(self.allocator, id);
                } else {
                    try self.compose.operation_id.set(self.allocator, "");
                    try self.compose.operation_error.set(self.allocator, "");
                }
                self.receipt_unknown = self.compose.unknown_outcome;
                self.compose.unknown_outcome = true;
                try self.start(.queue_inspect, .{ .cmd = "queue.list", .account = self.account() });
            },
            .gmail_draft_info, .gmail_draft_action => {
                const result = try self.data(self.job_arena.allocator(), response);
                if (!same(text(get(result, "draftId")), self.compose.id.value())) return error.DraftChanged;
                try self.compose.replaceGmailLink(self.allocator, get(result, "link"));
                try self.gmail_draft_outcome.set(self.allocator, text(get(result, "outcome")));
                try self.gmail_content_digest.set(self.allocator, text(get(result, "contentDigest")));
                try self.gmail_remote_version.set(self.allocator, text(get(get(result, "remote"), "messageId")));
                self.mode = .compose;
                self.gmail_send_ack = false;
                const imported_id = text(get(result, "importedDraftId"));
                if (imported_id.len > 0) {
                    self.closeUx();
                    self.say(false, "{s} · original local and Gmail copies kept", .{if (truth(get(result, "importedOriginal"))) @as([]const u8, "Gmail formatting preserved as an original · write a new note above it") else "Imported as a new Plain draft"});
                    try self.start(.draft_read, .{ .cmd = "draft.read", .account = self.account(), .draftId = imported_id });
                } else try self.presentGmailDraft();
            },
            .save, .save_review, .save_back, .save_browser, .save_gmail => {
                if (self.job.save_copy) return self.acceptLocalDraftCopy(response);
                if (self.job.recovery_fork) return self.acceptRecoveredFork(response);
                const result = self.data(self.job_arena.allocator(), response) catch |err| {
                    if (err == error.OperationRejected) return;
                    return err;
                };
                try self.compose.id.set(self.allocator, text(get(result, "id")));
                self.compose.saved_revision = self.autosave_revision;
                self.requestComposeMeasure();
                self.mode = if (kind == .save_review) .review else if (kind == .save_back) .browse else .compose;
                if (kind == .save_review) {
                    self.gmail_send_ack = false;
                    self.review_ready = false;
                    self.dialog_focus.reset(.send, 0);
                }
                if (kind == .save_back) {
                    self.clearGraceRecovery();
                    self.closeComposer();
                }
                if (kind == .save and self.editor_exit != null) {
                    const exit_code = self.editor_exit.?;
                    self.editor_exit = null;
                    self.sayEditorResult(exit_code);
                } else self.say(false, "{s}", .{if (kind == .save_review) "Review send · y Send · Esc Return to draft" else if (self.capabilities.durable_drafts) "Draft saved locally" else "Draft saved in this tab · reload/disconnect discards it"});
                if (kind == .save_review) self.compose_preview_scroll = 0;
                if (kind == .save_back and self.folder == 2) self.pending_list = true;
                if (kind == .save_back) try self.resumeMailboxReader();
                if (kind == .save_browser) try self.start(.open, .{ .cmd = "draft.open-preview", .account = self.account(), .draftId = self.compose.id.value() });
                if (kind == .save_gmail) try self.requestGmailDraftInfo();
            },
            .invitation_inspect, .invitation_reconcile => {
                const result = try self.data(self.job_arena.allocator(), response);
                self.invitation_review = .{};
                try self.invitation_review.uid.set(text(get(result, "uid")));
                try self.invitation_review.organizer.set(text(get(result, "organizer")));
                try self.invitation_review.attendee.set(text(get(result, "attendee")));
                try self.invitation_review.summary.set(text(get(result, "summary")));
                try self.invitation_review.start.set(text(get(result, "start")));
                try self.invitation_review.recurrence_id.set(text(get(result, "recurrenceId")));
                try self.loadInvitationPresentation(result);
                self.invitation_scroll = 0;
                self.invitation_confirm_ready = false;
                self.mode = .invitation;
                self.dialog_focus.reset(.invitation, 0);
                self.say(false, "{s}", .{if (self.invitation_response_unknown) "RSVP not confirmed · C Check Sent · no automatic resend" else if (self.invitationCalendarUnknown()) "RSVP confirmed · Calendar not confirmed · C Check status" else if (self.invitation_confirmed_status.len > 0) "Previous RSVP confirmed · review before changing your response" else if (self.invitation_review.canRespond()) "Review RSVP · a Accept · t Tentative · d Decline · Esc Cancel" else "Calendar notice · Esc Back"});
            },
            .send, .invitation => {
                const result = self.data(self.job_arena.allocator(), response) catch |err| {
                    if (err == error.OperationRejected) return;
                    return err;
                };
                const outcome = text(get(result, "outcome"));
                if (kind == .invitation and same(outcome, "blocked")) {
                    self.invitation_unknown = false;
                    self.invitation_calendar_blocked = true;
                    try self.invitation_operation_id.set(self.allocator, "");
                    try self.invitation_operation_error.set(self.allocator, "");
                    try self.loadInvitationCalendarSync(get(result, "calendarSync"));
                    self.mode = .invitation;
                    self.dialog_focus.reset(.invitation, 0);
                    self.say(true, "RSVP not sent · Calendar needs attention · review or explicitly send RSVP only", .{});
                    return;
                }
                if (kind == .invitation) self.invitation_calendar_blocked = false;
                const operation_id = text(get(result, "id"));
                if (operation_id.len > 0) try (if (kind == .send) &self.compose.operation_id else &self.invitation_operation_id).set(self.allocator, operation_id);
                try (if (kind == .send) &self.compose.operation_error else &self.invitation_operation_error).set(self.allocator, text(get(result, "errorCode")));
                if (!same(outcome, "applied") and !same(outcome, "rejected")) {
                    self.markUnknown(kind);
                } else if (same(outcome, "rejected")) {
                    if (kind == .send) {
                        self.compose.unknown_outcome = false;
                        self.retireComposeMeasure();
                    } else self.invitation_unknown = false;
                    self.mode = if (kind == .send) .compose else .browse;
                    if (kind == .send and same(self.compose.operation_error.value(), "SendCanceledBeforeSubmission")) {
                        self.review_ready = false;
                        self.say(false, "Send canceled · draft retained", .{});
                    } else self.sayFailure(if (kind == .send) "Submission rejected · draft retained" else "RSVP submission rejected", if (kind == .send) self.compose.operation_error.value() else self.invitation_operation_error.value());
                } else {
                    self.mode = .browse;
                    if (kind == .send) self.closeComposer();
                    if (kind == .invitation) {
                        try self.loadInvitationCalendarSync(get(result, "calendarSync"));
                        const calendar_state = self.invitation_calendar_sync_state.slice();
                        const calendar_notice = self.invitationCalendarNotice();
                        if (same(self.invitation_calendar_sync_error.slice(), "RsvpOnlyRequested")) {
                            self.sayAction(false, "RSVP sent · Calendar left unchanged as requested", .{});
                        } else if (same(calendar_state, "applied") or same(calendar_state, "existing")) {
                            self.sayAction(false, "RSVP sent · {s}", .{calendar_notice});
                        } else if (calendar_notice.len > 0) {
                            self.sayAction(true, "RSVP sent · Calendar {s} · I for details", .{if (self.invitationCalendarUnknown()) @as([]const u8, "not confirmed") else "not updated"});
                        } else self.sayAction(false, "RSVP sent", .{});
                    } else {
                        self.sayAction(false, "{s}", .{if (self.options.fixtures) "Saved by mock provider" else "Submitted; recipient delivery is not confirmed"});
                        try self.resumeMailboxReader();
                    }
                }
            },
            .contacts => {
                try self.replaceContacts(response, false);
                self.say(false, "{d} contacts available", .{self.contacts.len});
            },
            .contact_write => {
                _ = self.data(self.job_arena.allocator(), response) catch |err| {
                    if (err == error.OperationRejected) return;
                    return err;
                };
                self.sayAction(false, "Contact saved", .{});
                if (self.contactsOpen()) try self.loadContacts("");
            },
            .mutation => {
                _ = self.data(self.job_arena.allocator(), response) catch |err| {
                    if (err == error.OperationRejected) return;
                    return err;
                };
                self.mode = .browse;
                self.pending_list = true;
                self.sayAction(false, "Change applied", .{});
            },
            .open => {
                self.action_notice = false;
                if (self.job.protected_preview) {
                    if (self.compose.unknown_outcome) {
                        // Opening a preview resolves nothing; uncertainty stays.
                        self.say(true, "{s} · send outcome still unknown · draft unchanged", .{if (self.options.fixtures) @as([]const u8, "Mock HTML preview validated") else "HTML preview opened"});
                        self.status_kind = .unknown;
                    } else self.sayAction(false, "Local copy opened · Gmail may be newer", .{});
                    return;
                }
                if (self.job.calendar_browser_open) {
                    const result = try self.data(self.job_arena.allocator(), response);
                    try self.calendar.notice.set(if (truth(get(result, "fixture"))) "Google Calendar target validated · correct account Chrome profile" else "Opened Google Calendar in the event account's Chrome profile");
                    self.calendar.error_code = .{};
                }
                if (self.job.calendar_join_open) {
                    const result = try self.data(self.job_arena.allocator(), response);
                    const raw_profile = text(get(result, "profile"));
                    const prefix = "--profile-directory=";
                    const profile = if (std.mem.startsWith(u8, raw_profile, prefix)) raw_profile[prefix.len..] else raw_profile;
                    const message = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}{s}", .{ if (truth(get(result, "fixture"))) @as([]const u8, "Join target validated") else "Join link opened in Chrome", if (profile.len > 0) @as([]const u8, " · ") else "", profile[0..@min(profile.len, 120)] });
                    try self.calendar.notice.set(message);
                    self.calendar.error_code = .{};
                    self.sayAction(false, "{s}", .{message});
                    return;
                }
                if (self.job.saved_attachment_open) self.sayAction(false, "{s}", .{if (self.options.fixtures) "Attachment saved · mock file-open validated" else "Attachment saved and opened"}) else self.sayAction(false, "{s}", .{if (self.options.fixtures) "Mock browser target validated" else "Opened in the configured browser profile"});
            },
            .attachment_save => {
                self.closeReaderOverlay();
                self.sayAction(false, "Saved attachment ({s}) to {s}", .{ try attachmentSizeLabel(self.frame.allocator(), self.attachment_expected_size), self.attachment_destination.value() });
                try self.finishReaderAttachment();
            },
        }
    }
    fn chooseAccount(self: *App, index: usize) !void {
        if (index >= self.accounts.len or self.mode == .compose or self.mode == .review or self.mode == .contact_edit) return;
        if (self.job.future != null and self.job.kind != .refresh and self.job.kind != .list and self.job.kind != .cached_search and self.job.kind != .recipient_cache and self.job.kind != .recipient_refresh and self.job.kind != .drafts and self.job.kind != .read and self.job.kind != .thread and self.job.kind != .contacts and self.job.kind != .labels_list and self.job.kind != .identities) {
            self.say(true, "Wait for the current account's change to finish", .{});
            return;
        }
        if (self.job.future != null and (self.job.kind == .cached_search or self.job.kind == .recipient_cache or self.job.kind == .recipient_refresh or self.job.kind == .labels_list or self.job.kind == .identities)) self.preemptReadOnly();
        self.clearContactComposeIntent();
        self.search_saved_valid = false;
        self.search_restore_pending = false;
        self.clearGraceRecovery();
        self.rememberWorkingContext();
        self.saveUiPreferences();
        self.account_positions[self.account_index] = self.selected;
        self.account_index = index;
        self.contacts_generation +%= 1;
        self.pending_contacts = false;
        self.pending_cached_contacts = false;
        self.pending_compose = .none;
        self.compose_choice = false;
        self.compose_source_probe = false;
        self.selected = self.account_positions[index];
        self.generation +%= 1;
        self.clearHistory();
        try self.cursor.set(self.allocator, "");
        try self.query.set(self.allocator, "");
        self.query_scope = .cache;
        self.input_query_scope = .cache;
        self.messages = &.{};
        self.clearReader();
        self.view_ready = false;
        self.sync[index].state = .cached;
        try self.restoreWorkingContext();
        try self.prepareLabels();
        try self.reloadWithRefresh(self.capabilities.refresh_on_account_switch);
        self.loadFollowUps() catch {};
    }
    fn providerPageCursor(self: *const App, cursor_value: []const u8) bool {
        return std.mem.startsWith(u8, cursor_value, "L:") or (self.options.fixtures and std.mem.startsWith(u8, cursor_value, "1:"));
    }
    fn pageLoadCurrent(self: *const App) bool {
        return self.page_loading and self.page_loading_account == self.account_index and self.page_loading_generation == self.generation;
    }
    fn completePageLoad(self: *App) void {
        self.page_loading = false;
        self.page_relative = false;
        if (self.page_popped_cursor) |previous| self.allocator.free(previous);
        self.page_popped_cursor = null;
    }
    fn rollbackPageLoad(self: *App) void {
        if (!self.page_loading) return;
        if (self.pageLoadCurrent()) {
            self.cursor.set(self.allocator, self.page_previous_cursor.value()) catch {};
            self.selected = @min(self.page_previous_selected, self.messages.len -| 1);
            self.top = self.page_previous_top;
            self.generation = self.page_previous_generation;
            if (self.page_loading_forward) {
                while (self.previous_cursors.items.len > self.page_previous_stack_depth) {
                    self.allocator.free(self.previous_cursors.pop().?);
                }
            } else if (self.page_popped_cursor) |previous| {
                self.previous_cursors.append(self.allocator, previous) catch {
                    self.allocator.free(previous);
                };
                self.page_popped_cursor = null;
            }
        }
        self.completePageLoad();
    }
    fn queueNextPage(self: *App) !void {
        return self.queuePage(true, false);
    }
    fn queuePage(self: *App, forward: bool, automatic: bool) !void {
        if (self.pending_page and self.pending_page_account == self.account_index and self.pending_page_generation == self.generation and self.pending_page_forward == forward) return;
        if (self.messages.len == 0) return;
        try self.pending_page_boundary.set(self.allocator, text(get(self.messages[if (forward) self.messages.len - 1 else 0], "id")));
        self.pending_page_account = self.account_index;
        self.pending_page_generation = self.generation;
        self.pending_page_forward = forward;
        self.pending_page_automatic = automatic;
        const received = get(self.messages[if (forward) self.messages.len - 1 else 0], "receivedAt");
        self.pending_page_received_at = if (received == .integer) received.integer else 0;
        self.pending_page = true;
        self.say(false, "{s} page queued · {s} remain usable", .{ if (forward) @as([]const u8, "Next") else "Previous", if (self.drafts_list) @as([]const u8, "drafts") else "cached messages" });
    }
    fn consumePendingPage(self: *App) !void {
        if (!self.pending_page) return;
        if (self.pending_page_account != self.account_index or self.pending_page_generation != self.generation or self.mode != .browse) {
            self.pending_page = false;
            return;
        }
        if (self.drafts_list) {
            const forward = self.pending_page_forward;
            const automatic = self.pending_page_automatic;
            self.pending_page = false;
            self.pending_page_automatic = false;
            if (automatic) try self.scrollWindow(forward) else try self.page(forward);
            return;
        }
        var boundary: ?usize = null;
        for (self.messages, 0..) |message, index| if (same(text(get(message, "id")), self.pending_page_boundary.value())) {
            boundary = index;
            break;
        };
        if (boundary == null) {
            if (self.pending_page_automatic) {
                const forward = self.pending_page_forward;
                self.pending_page = false;
                try self.cacheWindow(forward, true, .{ .id = self.pending_page_boundary.value(), .received_at = self.pending_page_received_at });
                return;
            }
            _ = self.loadCachedList(self.pending_page_boundary.value()) catch false;
            if (self.job.future != null) return;
            for (self.messages, 0..) |message, index| if (same(text(get(message, "id")), self.pending_page_boundary.value())) {
                boundary = index;
                break;
            };
        }
        self.pending_page = false;
        if (boundary) |index| {
            if (self.pending_page_forward and index + 1 < self.messages.len) {
                self.selected = index + 1;
                self.selection_generation +%= 1;
                self.top = self.selected;
                try self.preview(false);
            } else if (!self.pending_page_forward and self.pending_page_automatic and index > 0) {
                self.selected = index - 1;
                self.selection_generation +%= 1;
                self.top = self.selected;
                try self.preview(false);
            } else if (self.pending_page_automatic) try self.scrollWindow(self.pending_page_forward) else try self.page(self.pending_page_forward);
        } else self.say(false, "Mail changed · scroll again to continue", .{});
    }
    fn scrollWindow(self: *App, forward: bool) !void {
        if (self.follow_ups_list) return;
        if (self.drafts_list) {
            try self.page(forward);
            if (self.pageLoadCurrent()) self.page_select_nearest = true;
            if (self.pending_page) self.pending_page_automatic = true;
            return;
        }
        try self.cacheWindow(forward, true, null);
    }
    fn dispatchWindowProvider(self: *App) !void {
        if (!self.pending_window_provider or self.job.future != null) return;
        self.pending_window_provider = false;
        if (self.pageLoadCurrent() and !self.cacheSearch() and self.providerPageCursor(self.cursor.value())) {
            try self.fetchMailboxPage();
        } else self.rollbackPageLoad();
    }
    fn cacheWindow(self: *App, forward: bool, nearest: bool, boundary_override: ?ScrollBoundary) !void {
        if (self.pageLoadCurrent()) {
            if (forward == self.page_loading_forward) return;
            self.preemptReadOnly();
        }
        if (self.view_ready and self.view_generation != self.generation) {
            self.say(false, "Loading search results · retained mail remains usable", .{});
            return;
        }
        if (self.messages.len == 0 and boundary_override == null) return;
        if (!forward and self.has_more_cached_before == false and boundary_override == null) return;
        if (forward and self.cacheSearch() and self.has_more_cached_after == false and boundary_override == null) return;
        if (self.job.future != null) {
            if (self.job.kind == .refresh) {
                if (self.cacheSearch() and cache_query.needsBody(self.query.value())) {
                    try self.queuePage(forward, nearest);
                    return;
                }
            } else if (readOnlyJob(self.job.kind)) self.preemptReadOnly() else {
                try self.queuePage(forward, nearest);
                return;
            }
        }
        const boundary = boundary_override orelse blk: {
            const message = self.messages[if (forward) self.messages.len - 1 else 0];
            const received = get(message, "receivedAt");
            break :blk ScrollBoundary{ .id = text(get(message, "id")), .received_at = if (received == .integer) received.integer else 0 };
        };
        if (boundary.id.len == 0) return;
        if (forward and self.previous_cursors.items.len >= types.Limits.metadata_hard) return error.CursorHistoryTooLarge;
        try self.page_relative_boundary.set(self.allocator, boundary.id);
        try self.page_previous_cursor.set(self.allocator, self.cursor.value());
        self.page_previous_selected = self.selected;
        self.page_previous_top = self.top;
        self.page_previous_generation = self.generation;
        self.page_previous_stack_depth = self.previous_cursors.items.len;
        self.page_loading_account = self.account_index;
        self.page_loading_generation = self.generation;
        self.page_loading_forward = forward;
        self.page_select_nearest = nearest;
        self.page_relative = true;
        self.page_relative_received_at = boundary.received_at;
        self.page_loading = true;
        errdefer self.rollbackPageLoad();
        if (forward) {
            const previous = try self.allocator.dupe(u8, self.cursor.value());
            self.previous_cursors.append(self.allocator, previous) catch |err| {
                self.allocator.free(previous);
                return err;
            };
        } else self.page_popped_cursor = self.previous_cursors.pop();
        self.generation +%= 1;
        self.page_loading_generation = self.generation;
        self.pending_page = false;
        self.pending_page_automatic = false;
        self.pending_read = false;
        self.pending_thread = false;
        _ = try self.loadCachedList("");
        try self.dispatchWindowProvider(); // Local response arena has finished; no idle intent.
        if (self.pending_read and self.job.future == null) {
            self.pending_read = false;
            try self.preview(false);
        }
        if (self.page_loading) self.say(false, "Loading {s} cached mail…", .{if (forward) "older" else "newer"});
    }
    fn page(self: *App, forward: bool) anyerror!void {
        if (self.follow_ups_list) return self.move(forward, self.mail_page_size);
        if (!forward) {
            const previous = if (self.previous_cursor.value().len > 0) self.previous_cursor.value() else if (self.previous_cursors.items.len > 0) self.previous_cursors.items[self.previous_cursors.items.len - 1] else "";
            if (self.providerPageCursor(previous)) return self.cacheWindow(false, false, null);
        }
        if (self.pageLoadCurrent()) {
            if (!forward) self.preemptReadOnly();
            return; // One page per demand, even when several wheel events arrive.
        }
        if (self.view_ready and self.view_generation != self.generation) {
            self.say(false, "Loading search results · retained mail remains usable", .{});
            return;
        }
        const next = if (self.next_cursor.value().len > 0) self.next_cursor.value() else if (!self.cacheSearch()) self.remote_cursor.value() else "";
        if (forward and (next.len == 0 or same(next, self.cursor.value()))) return;
        if (forward and self.cacheSearch() and self.providerPageCursor(next)) return; // Cache search never downloads older mail.
        if (self.job.future != null) {
            if (self.job.kind == .refresh) {
                if (self.providerPageCursor(next) or (self.cacheSearch() and cache_query.needsBody(self.query.value()))) {
                    try self.queuePage(forward, false);
                    return;
                }
            } else if (readOnlyJob(self.job.kind)) self.preemptReadOnly() else {
                try self.queuePage(forward, false);
                return;
            }
        }
        if (forward and self.previous_cursors.items.len >= types.Limits.metadata_hard) return error.CursorHistoryTooLarge;
        try self.page_previous_cursor.set(self.allocator, self.cursor.value());
        self.page_previous_selected = self.selected;
        self.page_previous_top = self.top;
        self.page_previous_generation = self.generation;
        self.page_previous_stack_depth = self.previous_cursors.items.len;
        self.page_loading_account = self.account_index;
        self.page_loading_generation = self.generation;
        self.page_loading_forward = forward;
        self.page_select_nearest = false;
        self.page_relative = false;
        self.page_loading = true;
        errdefer self.rollbackPageLoad();
        if (forward) {
            const previous = try self.allocator.dupe(u8, self.cursor.value());
            self.previous_cursors.append(self.allocator, previous) catch |err| {
                self.allocator.free(previous);
                return err;
            };
            try self.cursor.set(self.allocator, next);
        } else if (self.previous_cursor.value().len > 0) {
            try self.cursor.set(self.allocator, self.previous_cursor.value());
            self.page_popped_cursor = self.previous_cursors.pop();
        } else {
            const previous = self.previous_cursors.pop() orelse {
                self.completePageLoad();
                return;
            };
            self.page_popped_cursor = previous;
            try self.cursor.set(self.allocator, previous);
        }
        self.generation +%= 1;
        self.page_loading_generation = self.generation;
        self.pending_page = false;
        self.pending_read = false;
        self.pending_thread = false;
        if (self.drafts_list or (self.query.value().len > 0 and self.query_scope == .server) or self.providerPageCursor(self.cursor.value())) {
            try self.reload();
        } else {
            _ = try self.loadCachedList("");
            if (self.pending_read and self.job.future == null) {
                self.pending_read = false;
                try self.preview(false);
            }
        }
        if (self.page_loading) self.say(false, "Loading {s} {s} page…", .{ if (forward) @as([]const u8, "next") else "previous", if (self.drafts_list) @as([]const u8, "draft") else "mail" });
    }
    fn composeNew(self: *App, reply_all: ?bool) !void {
        self.clearContactComposeIntent();
        if (reply_all) |all| return self.requestConversationCompose(if (all) .reply_all else .reply);
        self.compose_intent = .new;
        self.compose_original = false;
        self.compose_choice = false;
        self.compose_source_mode = .text;
        if (self.job.future != null and readOnlyJob(self.job.kind)) self.preemptReadOnly();
        if (self.job.future != null) {
            try self.pinComposeTarget(.new, "");
            self.say(false, "Draft requested · waiting for the current operation", .{});
            return;
        }
        try self.start(.compose, .{ .account = self.account(), .cmd = "draft.create", .draft = types.Draft{ .bodyFormat = .markdown } });
    }
    fn composeForward(self: *App) !void {
        return self.requestConversationCompose(.forward);
    }
    fn pinComposeTarget(self: *App, intent: PendingCompose, id: []const u8) !void {
        if (self.account().len > self.pending_compose_account.len or id.len > self.pending_compose_id.len) return error.InvalidIdentity;
        @memcpy(self.pending_compose_account[0..self.account().len], self.account());
        self.pending_compose_account_len = self.account().len;
        @memcpy(self.pending_compose_id[0..id.len], id);
        self.pending_compose_id_len = id.len;
        self.pending_compose = intent;
    }
    fn inspectComposeSource(self: *App, message: Value) !void {
        if (!same(text(get(message, "id")), self.pending_compose_id[0..self.pending_compose_id_len])) return error.InvalidIdentity;
        self.compose_source_html = text(get(message, "bodyHtml")).len != 0;
        self.compose_source_resources = 0;
        self.compose_source_format_error = null;
        self.compose_source_original_too_large = false;
        const values = items(get(message, "attachments"));
        var lower_bound: usize = 0;
        for (values) |attachment| {
            const size = get(attachment, "size");
            if (size == .integer and size.integer >= 0 and @as(u64, @intCast(size.integer)) <= std.math.maxInt(usize)) lower_bound +|= @intCast(size.integer);
        }
        // The RAW original contains every file. This is only a definite lower
        // bound; a smaller descriptor total does not promise a usable .eml.
        self.compose_source_original_too_large = lower_bound > self.capabilities.source_attachment_bytes;
        self.compose_source_omit_files = lower_bound > self.capabilities.source_attachment_bytes or values.len > types.Limits.attachments;
        self.compose_source_forward_over_quota = lower_bound > self.capabilities.source_attachment_bytes or values.len > types.Limits.attachments + types.Limits.related_resources;
        if (self.compose_source_html) preflight: {
            if (truth(get(message, "bodyHtmlAmbiguous"))) {
                self.compose_source_format_error = error.AmbiguousOriginalHtml;
                break :preflight;
            }
            if (values.len > types.Limits.message_attachments) {
                self.compose_source_format_error = error.TooManyAttachments;
                break :preflight;
            }
            // Descriptors borrow the message's strings; only this actual-length
            // array is allocated, never a worst-case copy on the stack.
            const backing = composeBacking(self.allocator);
            const metadata = try backing.alloc(types.Attachment, values.len);
            defer backing.free(metadata);
            for (values, metadata) |value, *descriptor| {
                const size = get(value, "size");
                if (size != .integer or size.integer < 0 or @as(u64, @intCast(size.integer)) > std.math.maxInt(usize)) {
                    self.compose_source_format_error = error.InvalidAttachment;
                    break :preflight;
                }
                descriptor.* = .{
                    .id = text(get(value, "id")),
                    .filename = text(get(value, "filename")),
                    .mimeType = text(get(value, "mimeType")),
                    .size = @intCast(size.integer),
                    .contentId = if (get(value, "contentId") == .string) text(get(value, "contentId")) else null,
                    .disposition = if (get(value, "disposition") == .string) text(get(value, "disposition")) else null,
                    .contentLocation = if (get(value, "contentLocation") == .string) text(get(value, "contentLocation")) else null,
                };
            }
            const plan = original_mail.resourcePlanWithLimit(text(get(message, "bodyHtml")), metadata, self.capabilities.source_attachment_bytes) catch |err| {
                self.compose_source_format_error = err;
                break :preflight;
            };
            self.compose_source_resources = plan.count;
            self.compose_source_forward_over_quota = self.compose_source_forward_over_quota or values.len - plan.count > types.Limits.attachments;
        }
        try self.compose_source_subject.set(self.allocator, text(get(message, "subject")));
        self.compose_source_ready = true;
    }
    fn requestConversationCompose(self: *App, intent: PendingCompose) !void {
        // Cancellation clears queued compose state, so yield the speculative
        // refresh before pinning the user's reply/forward identity.
        if (self.job.future != null and self.job.kind == .refresh) self.preemptReadOnly();
        const target = self.readerReplyId();
        if (target.len == 0) return;
        if (self.pending_compose != .none or self.compose_source_probe) {
            self.say(false, "Draft source already selected · waiting for its read", .{});
            return;
        }
        try self.pinComposeTarget(intent, target);
        self.compose_intent = intent;
        self.compose_original = true;
        self.compose_source_mode = .choose;
        self.compose_source_ready = false;
        if (!outgoing_native and same(self.reader_account.value(), self.account())) for (self.thread) |message| {
            if (same(text(get(message, "id")), target)) {
                try self.inspectComposeSource(message);
                break;
            }
        };
        // The identity is copied before a worker or cache merge can replace
        // the reader. An uncached original gets a pinned read before choosing.
        if (self.job.future == null) try self.dispatchConversationCompose() else self.say(false, "Draft requested · waiting for the current read", .{});
    }
    fn dispatchConversationCompose(self: *App) !void {
        if (self.job.future != null or self.compose_choice or self.pending_compose == .none) return;
        if (!same(self.account(), self.pending_compose_account[0..self.pending_compose_account_len])) {
            self.pending_compose = .none;
            self.say(false, "Queued draft discarded after account change", .{});
            return;
        }
        if (self.pending_compose == .new) {
            self.pending_compose = .none;
            return self.start(.compose, .{ .account = self.account(), .cmd = "draft.create", .draft = types.Draft{ .bodyFormat = .markdown } });
        }
        self.pending_read = false;
        self.pending_thread = false;
        if (self.compose_source_mode == .choose) {
            // Native capture needs the complete source, never a bounded or
            // refused reader body: always refresh it by ID before offering
            // Keep formatting. Browser builds may reuse the pinned reader body.
            if (!self.compose_source_ready and !outgoing_native) {
                // A previous worker may just have supplied the pinned body.
                if (same(self.reader_account.value(), self.account())) for (self.thread) |message| {
                    if (same(text(get(message, "id")), self.pending_compose_id[0..self.pending_compose_id_len])) {
                        try self.inspectComposeSource(message);
                        break;
                    }
                };
            }
            if (!self.compose_source_ready) {
                self.compose_source_probe = true;
                self.start(.read, .{ .account = self.pending_compose_account[0..self.pending_compose_account_len], .cmd = if (outgoing_native) @as([]const u8, "mail.compose-source") else "mail.read", .messageId = self.pending_compose_id[0..self.pending_compose_id_len] }) catch |err| {
                    self.compose_source_probe = false;
                    self.pending_compose = .none;
                    return err;
                };
                return;
            }
            if (self.compose_source_html or (self.pending_compose == .forward and self.capabilities.original_attachment)) {
                self.compose_choice = true;
                self.dialog_focus.reset(.compose_format, self.composeChoiceInitial());
                self.say(false, "Choose original format · Tab controls · Enter chooses · Esc Back", .{});
                return;
            }
            self.compose_source_mode = .text;
        }
        const intent = self.pending_compose;
        self.pending_compose = .none;
        const pinned_account = self.pending_compose_account[0..self.pending_compose_account_len];
        const id = self.pending_compose_id[0..self.pending_compose_id_len];
        if (intent == .forward) {
            try self.start(.compose, .{ .account = pinned_account, .cmd = "mail.forward", .messageId = id, .bodyFormat = "markdown", .preserveFormatting = self.compose_source_mode == .formatted, .original = self.compose_source_mode == .attached, .omitAttachments = self.compose_source_mode == .text and self.compose_source_omit_files });
        } else try self.start(.compose, .{ .account = pinned_account, .cmd = "mail.reply", .messageId = id, .all = intent == .reply_all, .bodyFormat = "markdown", .preserveFormatting = self.compose_source_mode == .formatted });
    }
    fn onComposeChoiceKey(self: *App, key: Key) !void {
        if (self.paste) return;
        const forward = self.compose_intent == .forward;
        const count: usize = if (forward) 4 else 3;
        self.dialog_focus.ensure(.compose_format, self.composeChoiceInitial());
        if (tabDirection(key)) |backwards| {
            self.dialog_focus.move(backwards, count, self.composeChoiceMask());
            return;
        }
        const back = key.matches(Key.escape, .{}) or key.matches('q', .{}) or key.matches('c', .{ .ctrl = true }) or (key.matches(Key.enter, .{}) and self.dialog_focus.index == count - 1);
        if (back) {
            self.compose_choice = false;
            self.pending_compose = .none;
            self.say(false, "Draft canceled · no local draft created", .{});
            return;
        }
        const selected: ?ComposeSourceMode = if (key.matches('k', .{})) .formatted else if (key.matches('t', .{})) .text else if (forward and key.matches('e', .{})) .attached else if (key.matches(Key.enter, .{})) switch (self.dialog_focus.index) {
            0 => .formatted,
            1 => .text,
            2 => if (forward) .attached else null,
            else => null,
        } else null;
        if (selected) |choice| {
            const index: usize = switch (choice) {
                .formatted => 0,
                .text => 1,
                .attached => 2,
                .choose => unreachable,
            };
            if (!self.composeChoiceEnabled(index)) {
                self.dialog_focus.index = self.composeChoiceInitial();
                self.say(false, "{s}", .{self.composeChoiceReason(index).?});
                return;
            }
            self.compose_source_mode = choice;
            self.compose_choice = false;
            try self.dispatchConversationCompose();
        }
    }
    fn drawComposeChoice(self: *App, win: vaxis.Window) !void {
        if (!self.compose_choice) return;
        self.mouse_hits.clear();
        const width = @min(win.width -| 2, @as(u16, 70));
        const height = @min(win.height -| 2, @as(u16, 12));
        const outer = win.child(.{ .x_off = (win.width - width) / 2, .y_off = (win.height - height) / 2, .width = width, .height = height });
        outer.fill(.{ .style = self.style(.text) });
        const title = try std.fmt.allocPrint(self.frame.allocator(), " {s} · original format ", .{self.composeIntentLabel()});
        const inner = self.panel(outer, 0, width, title, true);
        inner.fill(.{ .style = self.style(.text) });
        const forward = self.compose_intent == .forward;
        const count: usize = if (forward) 4 else 3;
        self.dialog_focus.ensure(.compose_format, self.composeChoiceInitial());
        // One action per row keeps every choice reachable even at 30 columns.
        const first: usize = if (inner.height >= count + 3) 2 else 0;
        if (first != 0) {
            try self.line(inner, 0, try self.fitLine(inner, self.compose_source_subject.value(), inner.width), .subject);
            try self.line(inner, 1, if (!self.compose_source_html) "Plain text · original .eml available" else if (self.compose_source_format_error != null) "HTML · Keep formatting unavailable" else try std.fmt.allocPrint(self.frame.allocator(), "HTML · {d} embedded resources", .{self.compose_source_resources}), .muted);
        }
        for (0..count) |index| {
            const label: []const u8 = if (index == 0) "[Keep formatting k]" else if (index == 1) (if (forward and self.compose_source_omit_files) "[Text quote · omit files t]" else "[Text quote t]") else if (forward and index == 2) "[Attach original .eml e]" else "[Back Esc/q]";
            _ = try self.actionButton(inner, @intCast(first + index), 0, label, self.dialog_focus.index == index, self.composeChoiceEnabled(index), .dialog_action, index);
        }
        if (self.composeChoiceReason(0) orelse self.composeChoiceReason(2)) |reason| {
            var next = try self.flowTone(inner, reason, 0, first + count, .warning);
            if (self.compose_source_format_error != null) if (self.composeChoiceReason(2)) |original_reason| {
                if (next < inner.height) next = try self.flowTone(inner, original_reason, 0, next, .warning);
            };
            if (next < inner.height) try self.line(inner, next, "Tab / Shift+Tab · Enter", .muted);
            return;
        }
        const explanation: []const u8 = if (self.dialog_focus.index == 0) "Original HTML below your Omagma-styled note" else if (self.dialog_focus.index == 1) (if (forward and self.compose_source_omit_files) "Source files exceed this platform's limit; files will be omitted" else "Editable text copy of the original") else if (forward and self.dialog_focus.index == 2) "Recipient opens the attached email" else "Return without creating a draft";
        if (first + count < inner.height) try self.line(inner, first + count, try self.fitLine(inner, explanation, inner.width), .muted);
        if (first + count + 1 < inner.height) try self.line(inner, first + count + 1, "Tab / Shift+Tab · Enter", .muted);
    }
    fn composeChoiceInitial(self: *const App) usize {
        return if (self.composeChoiceEnabled(0)) 0 else 1;
    }
    fn composeChoiceEnabled(self: *const App, index: usize) bool {
        return if (index == 0) self.capabilities.original_formatting and self.compose_source_html and self.compose_source_format_error == null and !(self.compose_intent == .forward and self.compose_source_forward_over_quota) else if (index == 2 and self.compose_intent == .forward) self.capabilities.original_attachment and !self.compose_source_original_too_large else true;
    }
    fn composeChoiceMask(self: *const App) u8 {
        var mask: u8 = 0;
        for (0..(if (self.compose_intent == .forward) @as(usize, 4) else 3)) |index| if (self.composeChoiceEnabled(index)) {
            mask |= @as(u8, 1) << @intCast(index);
        };
        return mask;
    }
    fn composeChoiceReason(self: *const App, index: usize) ?[]const u8 {
        if (index == 0 and !self.capabilities.original_formatting) return "Original formatting unavailable here · choose Text quote";
        if (index == 0 and !self.compose_source_html) return "Plain-text source · choose Text quote or .eml";
        if (index == 2 and self.compose_intent == .forward and !self.capabilities.original_attachment) return "Original attachment unavailable here · choose Text quote";
        if (index == 0) if (self.compose_source_format_error) |err| return switch (err) {
            error.AttachmentsTooLarge => "Embedded images exceed this platform's limit · choose Text quote",
            error.TooManyAttachments => "Too many embedded images · choose Text quote",
            error.AmbiguousOriginalHtml => "Several HTML bodies · choose Text quote",
            error.AmbiguousContentId => "Several images share a reference · choose Text quote",
            error.OriginalResourceUnavailable, error.InvalidContentId => "Original images are unavailable · choose Text quote",
            error.BodyTooLarge => std.fmt.comptimePrint("Original HTML exceeds {d} MiB · choose Text quote", .{types.Limits.compose_body_bytes / (1024 * 1024)}),
            else => "Original formatting is unavailable · choose Text quote",
        };
        if (index == 0 and self.compose_intent == .forward and self.compose_source_forward_over_quota) return "Forward files exceed this platform's limit · Text quote omits files";
        if (index == 2 and self.compose_intent == .forward and self.compose_source_original_too_large) return "Original email exceeds this platform's limit · choose Text quote";
        return null;
    }
    fn composeIntentLabel(self: *const App) []const u8 {
        return switch (self.compose_intent) {
            .new => "New message",
            .reply => "Reply",
            .reply_all => "Reply all",
            .forward => "Forward",
            .none => "Draft",
        };
    }
    fn positionReplyBody(self: *App) void {
        if (self.compose_intent == .reply or self.compose_intent == .reply_all or self.compose_intent == .forward) {
            self.compose.fields[4].cursor = 0;
            self.compose.body_scroll = 0;
        }
    }
    /// Preview, original and native source pages live only while a composer
    /// is open. Every close path returns them; the saved draft stays durable.
    fn closeComposer(self: *App) void {
        self.compose_active = false;
        self.compose_measure = .{};
        self.clearComposePreview();
        // The next draw repaints every cell before rendering, so the previous
        // frame's composer copies are no longer referenced.
        self.releaseComposeFrame();
        self.compose.releaseOutgoing(self.allocator);
    }
    fn clearComposePreview(self: *App) void {
        self.compose_preview_display.deinit();
        self.compose_original_display.deinit();
        if (self.compose_preview) |*prepared| prepared.deinit();
        self.compose_preview = null;
        if (self.compose_original_preview) |*prepared| prepared.deinit();
        self.compose_original_preview = null;
        if (self.compose_preview_arena) |*arena| arena.deinit();
        self.compose_preview_arena = null;
        self.compose_preview_plain = "";
        self.compose_preview_digest = null;
        self.compose_preview_key = null;
        self.compose_preview_error = null;
        self.compose_preview_semantic_limited = false;
    }
    fn releaseComposeFrame(self: *App) void {
        if (self.compose_frame) |*arena| arena.deinit();
        self.compose_frame = null;
    }
    /// Cleaned display copies of a large native source must not consume the
    /// fixed frame heap. Browser builds keep using the frame arena.
    fn composeFrameAllocator(self: *App) Allocator {
        if (comptime !outgoing_native) return self.frame.allocator();
        if (self.compose_frame == null) self.compose_frame = .init(composeBacking(self.allocator));
        return self.compose_frame.?.allocator();
    }
    fn limitSemanticComposePreview(self: *App) void {
        if (self.compose_preview) |*prepared| prepared.deinit();
        self.compose_preview = null;
        self.compose_preview_semantic_limited = true;
    }
    fn ensureComposePreview(self: *App) !void {
        const source = self.compose.fields[4].value();
        const key: @typeInfo(@TypeOf(self.compose_preview_key)).optional.child = .{ .version = self.compose.fields[4].version, .format = self.compose.body_format, .original = if (self.compose.original != null) self.compose.original_digest else null, .include_original = self.compose.include_original, .folded_tail = self.quotedTail() != null and self.originalFolded() };
        if (self.compose_preview_key) |previous| if (std.meta.eql(previous, key)) {
            if (self.compose_preview_error) |err| return err;
            return;
        };
        var digest: [32]u8 = undefined;
        var identity = std.crypto.hash.sha2.Sha256.init(.{});
        identity.update(source);
        identity.update(if (self.compose.original != null) "\x00original\x00" else "\x00no-original\x00");
        identity.update(if (self.compose.include_original) "\x00included\x00" else "\x00excluded\x00");
        identity.update(if (key.folded_tail) "\x00folded\x00" else "\x00expanded\x00");
        if (self.compose.original != null) identity.update(&self.compose.original_digest);
        identity.final(&digest);
        if (self.compose_preview_digest) |previous| {
            if (self.compose_preview_format == self.compose.body_format and std.mem.eql(u8, &previous, &digest)) {
                self.compose_preview_key = key;
                if (self.compose_preview_error) |err| return err;
                return;
            }
        }
        self.clearComposePreview();
        self.compose_preview_digest = digest;
        self.compose_preview_key = key;
        self.compose_preview_format = self.compose.body_format;
        self.compose_preview_builds += 1;
        self.buildComposePreview(source) catch |err| {
            self.clearComposePreview();
            self.compose_preview_digest = digest;
            self.compose_preview_key = key;
            self.compose_preview_format = self.compose.body_format;
            self.compose_preview_error = err;
            return err;
        };
    }
    fn buildComposePreview(self: *App, source: []const u8) !void {
        // The rendered note, plain alternative and semantic layouts belong to
        // this revision. Replacement, a format/source change or closing the
        // composer releases them through clearComposePreview.
        const backing = composeBacking(self.allocator);
        self.compose_preview_arena = .init(backing);
        const owned = self.compose_preview_arena.?.allocator();
        const output = try markdown_mail.prepare(owned, .{ .bodyFormat = self.compose.body_format, .bodyText = source, .original = self.compose.original, .includeOriginal = self.compose.include_original });
        // Plain prepare borrows the editable field. Own it here so a later
        // field reallocation can never invalidate a retained preview.
        self.compose_preview_plain = try owned.dupe(u8, output.plain);
        if (self.compose.original != null and self.compose.include_original) {
            const note = try markdown_mail.renderNote(owned, source, self.compose.body_format);
            self.compose_preview = try self.semanticComposePreview(backing, note.html);
        } else if (self.quotedTail()) |tail| {
            if (self.originalFolded() and self.compose.body_format == .markdown) {
                const note = try markdown_mail.render(owned, source[0..tail.start]);
                self.compose_preview = try self.semanticComposePreview(backing, note.html);
            } else if (output.html) |html| self.compose_preview = try self.semanticComposePreview(backing, html);
        } else if (output.html) |html| self.compose_preview = try self.semanticComposePreview(backing, html);
    }
    /// markdown_mail.prepare above has already validated the complete
    /// outgoing message. Only the viewer's own bounded limits fall back.
    fn semanticComposePreview(self: *App, backing: Allocator, generated: []const u8) !?html_view.Prepared {
        return html_view.Prepared.initGeneratedMarkdown(backing, generated) catch |err| {
            if (!semanticViewLimit(err)) return err;
            self.compose_preview_semantic_limited = true;
            return null;
        };
    }
    fn requireComposePreview(self: *App) !void {
        try self.ensureComposePreview();
        if (self.compose_preview) |*prepared| prepared.ensure(80, .unicode) catch |err| {
            if (semanticViewLimit(err)) return self.limitSemanticComposePreview();
            self.compose_preview_error = err;
            return err;
        };
    }
    fn toggleComposeFormat(self: *App) !void {
        if (self.compose.gmailPaused()) return error.DraftPausedInGmail;
        if (!self.capabilities.markdown) return error.MarkdownUnavailable;
        if (self.compose.unknown_outcome) return;
        self.compose.body_format = if (self.compose.body_format == .markdown) .plain else .markdown;
        try self.composerChanged();
        if (self.compose.original != null) self.say(false, "Note: {s} · original unchanged", .{if (self.compose.body_format == .markdown) @as([]const u8, "Markdown") else "plain text"}) else self.say(false, "{s} · source unchanged · Ctrl+S reviews outgoing mail", .{if (self.compose.body_format == .markdown) @as([]const u8, "Markdown → HTML + plain text") else "Plain text"});
    }
    fn originalPolicyUnlocked(self: *const App) bool {
        return self.compose_active and self.compose.original != null and (self.compose_intent == .reply or self.compose_intent == .reply_all) and !self.compose.unknown_outcome and !self.compose.gmailPaused() and !self.grace_active and !self.grace_recovery;
    }
    fn originalPolicyMutable(self: *const App) bool {
        return self.originalPolicyUnlocked() and (self.job.future == null or readOnlyJob(self.job.kind));
    }
    fn setOriginalIncluded(self: *App, included: bool, remember: bool) !void {
        if (self.compose.original == null) {
            self.say(false, "Quote is part of your note · edit it to shorten", .{});
            return;
        }
        if (!self.originalPolicyMutable()) {
            self.say(true, "{s}", .{if (self.compose_intent == .forward) @as([]const u8, "Forward keeps its original · z only folds the view") else if (self.compose.gmailPaused()) "Original locked · paused in Gmail · g Status" else "Original locked · send pending or outcome unknown"});
            return;
        }
        if (self.compose.include_original == included) return;
        const previous = self.compose.include_original;
        self.compose.include_original = included;
        try self.composerChanged();
        if (remember) {
            self.compose_policy_undo = previous;
            self.compose_policy_redo = null;
        }
        self.compose_policy_revision = self.compose.revision;
        if (included) {
            self.validateOriginalReinclusion() catch |err| {
                self.sayAction(true, "Original included · {s} · reduce files or Q to omit before Send", .{@errorName(err)});
                return;
            };
        }
        self.sayAction(false, "{s}", .{if (included) @as([]const u8, "Original included · sent with your note") else "Original omitted · kept in draft · Q or Ctrl+Z restores"});
    }
    fn validateOriginalReinclusion(self: *const App) !void {
        const original = self.compose.original orelse return;
        try types.Limits.validateComposeParts(self.compose.attachments.len, original.resources.len);
        var total: u64 = 0;
        for ([_][]const types.Attachment{ self.compose.attachments, original.resources }) |list| for (list) |attachment| {
            if (attachment.size > types.Limits.attachment_bytes -| total) return error.AttachmentsTooLarge;
            total += attachment.size;
        };
    }
    fn quotedTail(self: *App) ?QuotedTail {
        if (self.compose.original != null) return null;
        if (self.compose.quote_version == self.compose.fields[4].version) return self.compose.quote_tail;
        self.compose.quote_version = self.compose.fields[4].version;
        self.compose.quote_scans += 1;
        const body = self.compose.fields[4].value();
        var quote_start = body.len;
        var count: usize = 0;
        var end = body.len;
        while (end > 0) {
            if (body[end - 1] == '\n') end -= 1;
            const at = if (std.mem.lastIndexOfScalar(u8, body[0..end], '\n')) |index| index + 1 else 0;
            const quote_line = std.mem.trimStart(u8, body[at..end], " \t");
            if (!std.mem.startsWith(u8, quote_line, ">")) break;
            quote_start = at;
            count += 1;
            end = at;
        }
        self.compose.quote_tail = if (count > 12) .{ .start = quote_start, .lines = count } else null;
        return self.compose.quote_tail;
    }
    fn originalFolded(self: *App) bool {
        if (self.compose_original_folded) |folded| return folded;
        if (self.compose.original) |original| return original.bodyText.len > 2048 or self.compose.original_lines > 13 or original.bodyHtml.len > 4096;
        return self.quotedTail() != null;
    }
    fn canFoldOriginal(self: *App) bool {
        return self.compose.original != null or self.quotedTail() != null;
    }
    fn foldControlAvailable(self: *App) bool {
        return self.canFoldOriginal() and (self.compose.original == null or self.compose.include_original or self.compose_view == .original);
    }
    fn toggleOriginalFold(self: *App) void {
        if (!self.canFoldOriginal()) return;
        if (self.compose.unknown_outcome) {
            self.say(false, "Saved original protected · P opens the local preview", .{});
            return;
        }
        if (self.compose.original != null and !self.compose.include_original) self.compose_view = .original;
        if (self.mode == .compose and self.compose_layout_width > 0 and self.compose_layout_width < 90) {
            self.compose_preview_full = true;
            self.compose.insert_mode = false;
            self.compose.attachment_focus = false;
            self.dialog_focus.reset(.preview, 6);
        }
        self.compose_original_folded = !self.originalFolded();
        self.compose_preview_scroll = 0;
        self.compose_plain_scroll = 0;
        self.compose_snapshot_scroll = 0;
        self.say(false, "{s} {s} · outgoing unchanged", .{ if (self.compose.original != null) @as([]const u8, "Original") else "Quoted text", if (self.originalFolded()) @as([]const u8, "folded in preview") else "expanded in preview" });
    }
    fn cycleComposePreview(self: *App) void {
        const narrow = self.vx.window().width < 90;
        if (narrow and !self.compose_preview_full) {
            self.compose_preview_full = true;
            self.compose.insert_mode = false;
            self.compose.attachment_focus = false;
            self.dialog_focus.reset(.preview, 0);
            return;
        }
        self.compose_view = switch (self.compose_view) {
            .rendered => if (self.compose.original != null or (self.compose_original and self.thread.len > 0)) .original else .plain,
            .original => .plain,
            .plain => .rendered,
        };
        if (narrow and self.compose_view == .rendered) self.compose_preview_full = false;
    }
    fn composePreviewTitle(self: *const App) []const u8 {
        return switch (self.compose_view) {
            .rendered => if ((self.compose.original != null and self.compose.include_original) or self.compose.body_format == .markdown) " Outgoing preview · HTML + plain text " else " Draft preview · plain text ",
            .original => if (self.compose.original != null) " Original message · saved snapshot " else " Original message ",
            .plain => " Plain-text alternative ",
        };
    }
    fn composeOutgoingDraw(self: *App, win: vaxis.Window, offset: usize, base_row: usize, plain_only: bool) !usize {
        self.ensureComposePreview() catch |err| {
            if (renderedSizeFailure(@errorName(err))) return self.flowTone(win, "Rendered message exceeds the outgoing limit.\nComplete source retained · Send unavailable.\nReturn to the draft to shorten your note or explicitly omit the reply's original.\n", offset, base_row, .warning);
            const message = try std.fmt.allocPrint(self.frame.allocator(), "Preview unavailable: {s}\nSource retained · sending is blocked.\nCtrl+T explicitly switches to plain text.", .{@errorName(err)});
            return self.flowTone(win, message, offset, base_row, .warning);
        };
        if (!plain_only and self.originalFolded()) if (self.quotedTail()) |tail| {
            var rows = base_row;
            var semantic_ready = false;
            if (self.compose_preview) |*prepared| semantic_note: {
                if (win.width == 0) return base_row;
                prepared.ensure(@min(win.width, max_cols), win.screen.width_method) catch |err| {
                    if (semanticViewLimit(err)) {
                        self.limitSemanticComposePreview();
                        break :semantic_note;
                    }
                    self.compose_preview_error = err;
                    return self.flowTone(win, try std.fmt.allocPrint(self.frame.allocator(), "Preview unavailable: {s}\nSource retained · Ctrl+T chooses plain text.", .{@errorName(err)}), offset, base_row, .warning);
                };
                rows = prepared.draw(win, offset, rows, self.palette, self.mono);
                semantic_ready = true;
            }
            if (!semantic_ready) rows = try self.composeCachedTextDraw(&self.compose_preview_display, win, self.compose.fields[4].value()[0..tail.start], offset, rows);
            return self.foldedQuoteDraw(win, offset, rows, self.compose.fields[4].value()[tail.start..], tail.lines);
        };
        if (!plain_only) if (self.compose_preview) |*prepared| semantic: {
            if (win.width == 0) return base_row;
            prepared.ensure(@min(win.width, max_cols), win.screen.width_method) catch |err| {
                if (semanticViewLimit(err)) {
                    self.limitSemanticComposePreview();
                    break :semantic;
                }
                self.compose_preview_error = err;
                return self.flowTone(win, try std.fmt.allocPrint(self.frame.allocator(), "Preview unavailable: {s}\nSource retained · Ctrl+T chooses plain text.", .{@errorName(err)}), offset, base_row, .warning);
            };
            const rows = prepared.draw(win, offset, base_row, self.palette, self.mono);
            if (self.compose.original != null and !self.compose.include_original) return self.flowTone(win, "\nOriginal omitted · retained in draft · not sent\n", offset, rows, .muted);
            return if (self.compose.original != null) self.composeOriginalDraw(win, offset, rows) else rows;
        };
        var rows = base_row;
        if (!plain_only and self.compose_preview_semantic_limited) rows = try self.flowTone(win, "Formatted view exceeds this terminal viewer's limits · showing the complete plain-text alternative · outgoing HTML is validated and unchanged\n\n", offset, rows, .warning);
        if (self.compose.original != null) {
            if (!self.compose.include_original) rows = try self.flowTone(win, "Original omitted · retained in draft · not sent\n\n", offset, rows, .muted);
            if ((plain_only or self.compose_preview == null) and self.compose.include_original and self.originalFolded()) {
                const original = self.compose.original.?;
                // prepare appends the exact retained plaintext last. Fold that
                // suffix while leaving the actual outgoing note/headers visible.
                const prefix = self.compose_preview_plain[0 .. self.compose_preview_plain.len - original.bodyText.len];
                rows = try self.composeCachedTextDraw(&self.compose_preview_display, win, prefix, offset, rows);
                return self.foldedQuoteDraw(win, offset, rows, original.bodyText, self.compose.original_lines);
            }
        }
        if (self.originalFolded()) if (self.quotedTail()) |tail| {
            rows = try self.composeCachedTextDraw(&self.compose_preview_display, win, self.compose.fields[4].value()[0..tail.start], offset, rows);
            return self.foldedQuoteDraw(win, offset, rows, self.compose.fields[4].value()[tail.start..], tail.lines);
        };
        return self.composeCachedTextDraw(&self.compose_preview_display, win, self.compose_preview_plain, offset, rows);
    }
    fn composeOriginalDraw(self: *App, win: vaxis.Window, offset: usize, base_row: usize) !usize {
        const original = self.compose.original orelse return base_row;
        const header = try std.fmt.allocPrint(self.frame.allocator(), "\n── Original message · protected ──\nFrom: {s} <{s}>\nDate: {s}\nSubject: {s}\nEmbedded resources: {d} · saved snapshot\n", .{ original.from.name, original.from.address, original.date, original.subject, original.resources.len });
        var rows = try self.flowTone(win, header, offset, base_row, .muted);
        if (self.originalFolded()) return self.foldedQuoteDraw(win, offset, rows, original.bodyText, self.compose.original_lines);
        if (self.compose_original_preview == null and original.bodyHtml.len > 0) self.compose_original_preview = html_view.Prepared.init(composeBacking(self.allocator), original.bodyHtml) catch null;
        for (original.resources) |resource| {
            rows = try self.flowTone(win, try std.fmt.allocPrint(self.frame.allocator(), "▣ {s} · embedded\n", .{resource.filename}), offset, rows, .muted);
        }
        if (self.compose_original_preview) |*prepared| {
            if (win.width != 0) {
                prepared.ensure(@min(win.width, max_cols), win.screen.width_method) catch {
                    return self.composeCachedTextDraw(&self.compose_original_display, win, original.bodyText, offset, rows);
                };
                return prepared.draw(win, offset, rows, self.palette, self.mono);
            }
        }
        return self.composeCachedTextDraw(&self.compose_original_display, win, original.bodyText, offset, rows);
    }
    fn composeCachedTextDraw(self: *App, cache: *compose_text.Cache, win: vaxis.Window, source: []const u8, offset: usize, base_row: usize) !usize {
        try cache.ensure(composeBacking(self.allocator), source, self.compose.fields[4].version, win.width, win.screen.width_method);
        var iterator = cache.viewport(offset -| base_row);
        while (iterator.next()) |glyph| {
            const row = base_row + glyph.position.row;
            if (row < offset) continue;
            if (row - offset >= win.height) break;
            if (glyph.columns > win.width) continue;
            win.writeCell(glyph.position.column, @intCast(row - offset), .{ .char = .{ .grapheme = glyph.text, .width = @intCast(@min(glyph.columns, 255)) }, .style = self.style(.text) });
        }
        return base_row + cache.rows;
    }
    fn foldedQuoteDraw(self: *App, win: vaxis.Window, offset: usize, base_row: usize, source: []const u8, lines: usize) !usize {
        var end: usize = 0;
        var count: usize = 0;
        while (end < source.len and end < 512 and count < 3) : (end += 1) if (source[end] == '\n') {
            count += 1;
        };
        while (end > 0 and end < source.len and source[end] & 0xc0 == 0x80) end -= 1;
        var rows = try self.flowTone(win, source[0..end], offset, base_row, .muted);
        const label = try std.fmt.allocPrint(self.frame.allocator(), "\n… {d} lines retained · z Expand\nFolding changes this view only.\n", .{lines});
        rows = try self.flowTone(win, label, offset, rows, .muted);
        return rows;
    }
    fn composeOriginalControlsDraw(self: *App, win: vaxis.Window, row: u16, narrow: bool) !void {
        if (row >= win.height or !self.canFoldOriginal()) return;
        const has_original = self.compose.original != null;
        const label: []const u8 = if (has_original) (if (self.compose.include_original) "Included" else "Omitted") else "Quote";
        try self.line(win, row, label, .muted);
        var x: u16 = @intCast(label.len + 1);
        if (has_original and self.compose_intent != .forward) {
            const policy_label: []const u8 = if (win.width >= 62) (if (self.compose.include_original) (if (self.compose.insert_mode) "[  Reply without original]" else "[Q Reply without original]") else (if (self.compose.insert_mode) "[  Include original]" else "[Q Include original]")) else if (self.compose.include_original) (if (self.compose.insert_mode) "[  Omit]" else "[Q Omit]") else (if (self.compose.insert_mode) "[  Include]" else "[Q Include]");
            if (x + policy_label.len <= win.width) {
                const focused = if (narrow) self.dialog_focus.index == 5 else self.compose.attachment_focus and self.compose.attachment_cursor == self.compose.attachments.len + 6;
                x = try self.actionButton(win, row, x, policy_label, focused, self.originalPolicyMutable(), .compose_original_policy, 0);
                self.compose_original_drawn = true;
            }
        }
        const fold_label: []const u8 = if (self.originalFolded()) (if (self.compose.insert_mode) "[  Expand]" else "[z Expand]") else (if (self.compose.insert_mode) "[  Fold]" else "[z Fold]");
        if (self.foldControlAvailable() and x + fold_label.len <= win.width) {
            const focused = if (narrow) self.dialog_focus.index == 6 else self.compose.attachment_focus and self.compose.attachment_cursor == self.compose.attachments.len + 7;
            _ = try self.actionButton(win, row, x, fold_label, focused, true, .compose_original_fold, 0);
            self.compose_fold_drawn = true;
        }
    }
    fn composePreviewDraw(self: *App, win: vaxis.Window) !void {
        self.mouseArea(win, .compose_preview_scroll, 0);
        const narrow = self.compose_preview_full and self.vx.window().width < 90;
        if (narrow) {
            self.dialog_focus.ensure(.preview, 0);
            const x = try self.actionButton(win, 0, 0, "[Preview p]", self.dialog_focus.index == 1, true, .compose_preview_toggle, 0);
            _ = try self.actionButton(win, 0, x, "[Back]", self.dialog_focus.index == 2, true, .compose_preview_back, 0);
            try self.composeOriginalControlsDraw(win, 1, true);
        } else if (self.compose.original == null and self.quotedTail() != null) {
            const x = try self.actionButton(win, 0, 0, if (self.compose.insert_mode) "[  Preview]" else "[p Preview]", self.compose.attachment_focus and self.compose.attachment_cursor == self.compose.attachments.len + 2, true, .compose_preview_toggle, 0);
            const label = if (self.originalFolded()) (if (self.compose.insert_mode) "[  Expand quote]" else "[z Expand quote]") else if (self.compose.insert_mode) "[  Fold quote]" else "[z Fold quote]";
            if (x + label.len <= win.width) {
                _ = try self.actionButton(win, 0, x, label, self.compose.attachment_focus and self.compose.attachment_cursor == self.compose.attachments.len + 7, true, .compose_original_fold, 0);
                self.compose_fold_drawn = true;
            }
        } else try self.line(win, 0, if (self.compose.insert_mode or self.compose.attachment_focus) "Preview · Esc returns to normal controls" else if (self.compose_view == .original and self.compose.original == null and win.width >= 48) "p Preview · Ctrl+D/U Scroll · L Links · B Files" else if (win.width >= 34) "p Next preview · Ctrl+D/U Scroll" else "p Next preview", .accent);
        const body = win.child(.{ .y_off = @min(@as(u16, 2), win.height) });
        if (self.compose_view == .original and self.compose.original == null) return self.readerDraw(body);
        const scroll = if (self.compose_view == .plain) &self.compose_plain_scroll else if (self.compose_view == .original) &self.compose_snapshot_scroll else &self.compose_preview_scroll;
        self.compose_preview_height = body.height;
        const painted_scroll = scroll.*;
        if (self.compose_view == .original) try self.ensureComposePreview();
        self.compose_preview_lines = if (self.compose_view == .original) try self.composeOriginalDraw(body, scroll.*, 0) else try self.composeOutgoingDraw(body, scroll.*, 0, self.compose_view == .plain);
        scroll.* = @min(scroll.*, readerEnd(self.compose_preview_lines, self.compose_preview_height));
        if (scroll.* != painted_scroll) {
            body.fill(.{ .style = self.style(.text) });
            _ = if (self.compose_view == .original) try self.composeOriginalDraw(body, scroll.*, 0) else try self.composeOutgoingDraw(body, scroll.*, 0, self.compose_view == .plain);
        }
    }
    fn cancelAutosaveTimer(self: *App) void {
        if (self.autosave_timer) |*future| future.cancel(self.io);
        self.autosave_timer = null;
    }
    fn autosaveTimer(self: *App, started: i64) void {
        while (true) {
            const deadline = @min(self.autosave_last_edit.load(.acquire) + 1500, started + 10000);
            const remaining = deadline - Io.Timestamp.now(self.io, .awake).toMilliseconds();
            if (remaining <= 0) break;
            self.io.sleep(.fromMilliseconds(remaining), .awake) catch return;
        }
        platform.postEventBlocking(self.loop, .compose_idle) catch {};
    }
    fn armAutosave(self: *App) !void {
        if (browser_target) {
            const now = Io.Timestamp.now(self.io, .awake).toMilliseconds();
            if (!self.autosave_due) self.autosave_started = now;
            self.browser_autosave_last_edit = now;
            self.autosave_due = true;
            return;
        }
        if (@import("builtin").is_test) return;
        const now = Io.Timestamp.now(self.io, .awake).toMilliseconds();
        self.autosave_last_edit.store(now, .release);
        if (self.autosave_timer == null) {
            self.autosave_started = now;
            self.autosave_timer = try self.io.concurrent(autosaveTimer, .{ self, now });
        }
    }
    fn onComposeIdle(self: *App) !void {
        if (browser_target) {
            if (self.browserAutosaveDelay() != 0) return;
            return self.autosaveDraft();
        }
        self.cancelAutosaveTimer();
        const now = Io.Timestamp.now(self.io, .awake).toMilliseconds();
        if (now - self.autosave_last_edit.load(.acquire) < 1500 and now - self.autosave_started < 10000) {
            if (!@import("builtin").is_test) self.autosave_timer = try self.io.concurrent(autosaveTimer, .{ self, self.autosave_started });
            return;
        }
        try self.autosaveDraft();
    }
    fn composerChanged(self: *App) !void {
        if (self.compose.gmailPaused()) return error.DraftPausedInGmail;
        self.gmail_send_ack = false;
        self.completion_dismissed = false;
        self.review_ready = false;
        self.compose_measure = .{};
        self.compose.revision +%= 1;
        self.compose.completion_selected = 0;
        if (self.compose.saved_changed) {
            self.compose_measure.failure.set("DraftChanged") catch unreachable;
            self.say(false, "Local edits kept · saved draft changed · :resolve-draft", .{});
            return;
        }
        self.say(false, "Draft changed · autosave pending · no mail sent", .{});
        try self.armAutosave();
    }
    fn browserDraftDirty(self: *const App) bool {
        return self.compose_active and !self.compose.unknown_outcome and
            self.compose.revision != self.compose.saved_revision;
    }
    fn browserAutosaveDelay(self: *const App) u32 {
        if (!self.browserDraftDirty() or !self.autosave_due) return 0;
        const now = Io.Timestamp.now(self.io, .awake).toMilliseconds();
        const deadline = @min(self.browser_autosave_last_edit + 1500, self.autosave_started + 10000);
        return @intCast(std.math.clamp(deadline - now, 0, 1500));
    }
    fn autosaveDraft(self: *App) !void {
        if (self.compose.saved_changed) {
            self.cancelAutosaveTimer();
            self.autosave_due = false;
            return;
        }
        if (self.compose.gmailPaused()) return;
        self.cancelAutosaveTimer();
        if (self.paste) {
            self.autosave_due = true;
            return;
        }
        if (!self.compose_active or self.compose.unknown_outcome or self.compose.id.value().len == 0 or self.compose.revision == self.compose.saved_revision or self.mode == .review or self.mode == .browse) return;
        if (self.job.future != null) {
            self.autosave_due = true;
            return;
        }
        self.autosave_due = false;
        var fields: [5][]const u8 = undefined;
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        defer arena.deinit();
        self.autosave_revision = self.compose.revision;
        try self.start(.autosave, .{ .account = self.account(), .cmd = "draft.recovery-save", .draftId = self.compose.id.value(), .draft = try self.compose.updateValue(arena.allocator(), self.compose.recovery(&fields)), .acknowledgementOnly = true });
        self.say(false, "{s}", .{if (self.capabilities.durable_drafts) "Saving draft locally… · typing remains available" else "Saving draft in this tab…"});
    }
    fn composeCompletions(self: *const App) completion.Matches {
        if (!self.compose.insert_mode or self.compose.selected >= 3 or self.compose.unknown_outcome) return .{ .range = .{ .start = 0, .end = 0, .query = "" } };
        if (self.completion_dismissed) return .{ .range = .{ .start = 0, .end = 0, .query = "" } };
        const field = &self.compose.fields[self.compose.selected];
        if (self.completion_open and completion.token(field.value(), field.cursor).query.len == 0) {
            var matches: completion.Matches = .{ .range = completion.token(field.value(), field.cursor) };
            if (same(self.recipient_account.value(), self.account())) for (self.recipient_values) |value| {
                const address = text(get(value, "address"));
                recipients.validateAddress(address) catch continue;
                if (std.ascii.eqlIgnoreCase(address, self.account())) continue;
                var duplicate = false;
                for (matches.slice()) |previous| duplicate = duplicate or std.ascii.eqlIgnoreCase(previous.address, address);
                if (duplicate) continue;
                matches.values[matches.len] = .{ .address = address, .name = text(get(value, "name")) };
                matches.len += 1;
                if (matches.len == completion.max_matches) break;
            };
            return matches;
        }
        return completion.collectKnown(if (same(self.recipient_account.value(), self.account())) self.recipient_values else &.{}, if (same(self.contacts_account.value(), self.account()) and self.contacts_query.value().len == 0) self.contacts else &.{}, self.account(), field.value(), field.cursor);
    }
    fn acceptCompletion(self: *App, index: usize) !void {
        const matches = self.composeCompletions();
        if (index >= matches.len) return;
        const field = &self.compose.fields[self.compose.selected];
        const suffix_length = field.value().len - matches.range.end;
        const updated = try completion.replaceCandidate(self.allocator, field.value(), matches.range, matches.values[index]);
        defer self.allocator.free(updated);
        if (updated.len > mail_limits.header_value_bytes) return error.InputTooLarge;
        try field.history.record(self.allocator, field.value(), field.cursor);
        try field.assign(self.allocator, updated);
        field.cursor = updated.len - suffix_length;
        try self.composerChanged();
        self.completion_open = false;
        self.completion_dismissed = true;
    }
    fn composeCachedContacts(self: *App) void {
        if (!same(self.recipient_account.value(), self.account())) {
            self.recipient_values = &.{};
            self.recipient_ready = false;
            self.recipient_account.set(self.allocator, self.account()) catch return;
        }
        self.pending_recipient_cache = true;
        if (self.capabilities.background_recipients and !self.recipient_refreshed[self.account_index]) self.pending_recipient_refresh = true;
    }
    fn replaceRecipients(self: *App, response: []const u8) !void {
        var replacement: std.heap.ArenaAllocator = .init(self.allocator);
        defer replacement.deinit();
        const result = try self.data(replacement.allocator(), response);
        const values = get(result, "recipients");
        if (values != .array or values.array.items.len > @import("recipient_cache.zig").max_candidates) return error.InvalidRecipientCandidates;
        for (values.array.items) |value| {
            try recipients.validateAddress(text(get(value, "address")));
            try recipients.validateHeader(text(get(value, "name")));
        }
        if (self.recipient_arena) |*previous| previous.deinit();
        self.recipient_arena = replacement;
        replacement = .init(self.allocator);
        self.recipient_values = values.array.items;
        try self.recipient_account.set(self.allocator, self.account());
        self.recipient_ready = true;
    }
    fn recipientHint(self: *const App) []const u8 {
        if (self.pending_recipient_cache or self.pending_recipient_refresh or (self.job.future != null and (self.job.kind == .recipient_cache or self.job.kind == .recipient_refresh))) return "Fetching recent-mail suggestions… · keep typing";
        return "No matching recent-mail recipient · type an address";
    }
    fn replaceIdentities(self: *App, response: []const u8) !void {
        var replacement: std.heap.ArenaAllocator = .init(self.allocator);
        defer replacement.deinit();
        const result = try self.data(replacement.allocator(), response);
        const values = get(result, "identities");
        if (values != .array or values.array.items.len > 32) return error.InvalidIdentities;
        for (values.array.items) |identity| {
            try recipients.validateAddress(text(get(identity, "address")));
            try recipients.validateHeader(text(get(identity, "name")));
            if (text(get(identity, "signature")).len > 8192) return error.InvalidSignature;
        }
        if (self.identity_arena) |*previous| previous.deinit();
        self.identity_arena = replacement;
        replacement = .init(self.allocator);
        self.identities = values.array.items;
        try self.identities_account.set(self.allocator, self.account());
    }
    fn setComposeSignature(self: *App, signature_in: []const u8) !void {
        if (self.compose.gmailPaused()) return error.DraftPausedInGmail;
        if (signature_in.len > 8192) return error.InvalidSignature;
        const literal_signature = try safe(self.frame.allocator(), signature_in, true);
        const clean = if (self.compose.body_format == .markdown) try markdown_mail.escapeSource(self.frame.allocator(), literal_signature) else literal_signature;
        const field = &self.compose.fields[4];
        const previous = self.compose.signature.value();
        const body = field.value();
        var insert_at = std.mem.indexOf(u8, body, "\n\n> ") orelse std.mem.indexOf(u8, body, "\n\n---------- Forwarded message ----------") orelse body.len;
        var suffix_at = insert_at;
        if (previous.len > 0) {
            const marker = try std.fmt.allocPrint(self.frame.allocator(), "\n\n-- \n{s}\n\n", .{previous});
            if (std.mem.count(u8, body, marker) != 1) {
                self.compose.signature_custom = true;
                return;
            }
            insert_at = std.mem.indexOf(u8, body, marker).?;
            suffix_at = insert_at + marker.len;
        }
        const marker = if (clean.len > 0) try std.fmt.allocPrint(self.frame.allocator(), "\n\n-- \n{s}\n\n", .{clean}) else "";
        // A reply may quote a long thread. Build the changed source once in a
        // scoped composer-backed buffer instead of the fixed frame heap.
        if (insert_at + marker.len + (body.len - suffix_at) > types.Limits.compose_body_bytes) return error.BodyTooLarge;
        var scratch: std.heap.ArenaAllocator = .init(composeBacking(self.allocator));
        defer scratch.deinit();
        const changed = try std.fmt.allocPrint(scratch.allocator(), "{s}{s}{s}", .{ body[0..insert_at], marker, body[suffix_at..] });
        const old_cursor = field.cursor;
        try field.set(self.allocator, changed);
        field.cursor = if (old_cursor <= insert_at) old_cursor else if (old_cursor >= suffix_at) insert_at + marker.len + (old_cursor - suffix_at) else insert_at + @min(old_cursor - insert_at, marker.len);
        self.compose.signature_custom = false;
        try self.compose.signature.set(self.allocator, clean);
    }
    fn cycleComposeIdentity(self: *App) !void {
        if (!self.capabilities.aliases) return error.SenderAliasesUnavailable;
        if (!self.canEditAttachments()) return;
        try self.beginUx(.aliases, " Choose sender · verified identities ");
        if (!same(self.identities_account.value(), self.account()) or self.identities.len == 0) {
            self.pending_identities = true;
            self.say(false, "Loading verified sending identities…", .{});
            _ = try self.dispatchComposer();
            return;
        }
        try self.senderRows();
    }
    fn senderRows(self: *App) !void {
        for (self.identities, 0..) |identity, index| {
            const address = text(get(identity, "address"));
            const display = try recipients.formatDisplay(self.ux_arena.?.allocator(), address, text(get(identity, "name")));
            const caption = try std.fmt.allocPrint(self.ux_arena.?.allocator(), "{s}{s}", .{ if (std.ascii.eqlIgnoreCase(address, self.compose.from.value())) @as([]const u8, "● ") else "  ", display });
            try self.uxRow(.{ .label = caption, .detail = "Verified sending identity", .index = index });
            if (std.ascii.eqlIgnoreCase(address, self.compose.from.value())) self.ux_selected = index;
        }
    }
    fn useComposeIdentity(self: *App, chosen: usize) !void {
        if (!self.canEditAttachments() or !same(self.identities_account.value(), self.account()) or chosen >= self.identities.len) return error.IdentityUnavailable;
        // Reopened drafts carry the body itself. Recognize only the exact
        // generated block for the currently verified identity; never infer
        // that an arbitrary user-written footer should be removed.
        if (self.compose.signature.value().len == 0) for (self.identities) |identity| {
            if (!std.ascii.eqlIgnoreCase(text(get(identity, "address")), self.compose.from.value())) continue;
            const signature_in = text(get(identity, "signature"));
            if (signature_in.len == 0) break;
            const literal_signature = try safe(self.frame.allocator(), signature_in, true);
            const source_signature = if (self.compose.body_format == .markdown) try markdown_mail.escapeSource(self.frame.allocator(), literal_signature) else literal_signature;
            const marker = try std.fmt.allocPrint(self.frame.allocator(), "\n\n-- \n{s}\n\n", .{source_signature});
            if (std.mem.count(u8, self.compose.fields[4].value(), marker) == 1) try self.compose.signature.set(self.allocator, source_signature);
            break;
        };
        const identity = self.identities[chosen];
        try self.compose.from.set(self.allocator, text(get(identity, "address")));
        try self.compose.from_name.set(self.allocator, text(get(identity, "name")));
        if (self.compose.new_draft or self.compose.signature.value().len > 0 or self.compose.fields[4].value().len == 0) try self.setComposeSignature(text(get(identity, "signature"))) else self.compose.signature_custom = true;
        try self.composerChanged();
        self.say(false, "From: {s} · {s}", .{ self.compose.from.value(), if (self.compose.signature_custom) "edited body/signature retained" else "verified identity · draft changed" });
    }
    fn dispatchComposer(self: *App) !bool {
        if (self.job.future != null) return false;
        if (self.autosave_due and (!browser_target or self.browserAutosaveDelay() == 0)) {
            try self.autosaveDraft();
            return self.job.future != null;
        }
        if (self.pending_recipient_cache and self.compose_active and !self.compose.unknown_outcome) {
            self.pending_recipient_cache = false;
            try self.start(.recipient_cache, .{ .account = self.account(), .cmd = "mail.recipients", .cacheOnly = true });
            return true;
        }
        if (self.pending_identities and self.compose_active and !self.compose.unknown_outcome) {
            self.pending_identities = false;
            try self.start(.identities, .{ .account = self.account(), .cmd = "accounts.identities" });
            return true;
        }
        if (self.pending_recipient_refresh and self.compose_active and !self.compose.unknown_outcome) {
            self.pending_recipient_refresh = false;
            self.recipient_refreshed[self.account_index] = true;
            // One bounded metadata-only Sent head per account/session. Never
            // search the provider on keystrokes or fetch full mailbox history.
            try self.start(.recipient_refresh, .{ .account = self.account(), .cmd = "mail.list", .label = "SENT", .limit = @as(usize, 32) });
            return true;
        }
        if (!browser_target and self.compose_measure.pending and self.compose_active and !self.compose.saved_changed and !self.compose.unknown_outcome and !self.compose.gmailPaused() and self.compose.revision == self.compose.saved_revision and !self.grace_active and !self.grace_recovery) {
            self.startComposeMeasure() catch |err| {
                // A background diagnostic must neither exit the editor nor
                // leave an empty receipt labelled as an active calculation.
                self.compose_measure = .{};
                self.compose_measure.failure.set(@errorName(err)) catch {};
                self.review_ready = false;
                return false;
            };
            return true;
        }
        return false;
    }
    fn startComposeMeasure(self: *App) !void {
        self.compose_measure = .{};
        var scratch: std.heap.ArenaAllocator = .init(composeBacking(self.allocator));
        defer scratch.deinit();
        const local = try self.compose.draft(scratch.allocator());
        const digest = try @import("draft_link.zig").contentDigest(scratch.allocator(), local, self.account());
        try self.compose_measure.content_digest.set(&digest);
        const id = try self.operationId(self.frame.allocator());
        try self.compose_measure.operation.set(id);
        try self.compose_measure.draft.set(self.compose.id.value());
        self.compose_measure.revision = self.compose.revision;
        try self.start(.draft_measure, .{ .account = self.account(), .cmd = "draft.measure", .draftId = self.compose.id.value(), .operationId = id, .revision = self.compose.revision });
        self.job.measure_operation = self.compose_measure.operation;
        self.job.measure_revision = self.compose.revision;
    }
    fn requestComposeMeasure(self: *App) void {
        if (!browser_target and !self.compose.saved_changed and !self.composeMeasureCurrent()) self.compose_measure.pending = true;
    }
    fn composeMeasureJobCurrent(self: *const App) bool {
        return self.compose_active and self.job.account_index == self.account_index and self.compose_measure.operation.len != 0 and same(self.job.draft_target.slice(), self.compose.id.value()) and same(self.compose_measure.draft.slice(), self.compose.id.value()) and self.compose_measure.revision == self.compose.revision and self.job.measure_revision == self.compose.revision and same(self.job.measure_operation.slice(), self.compose_measure.operation.slice());
    }
    fn retireComposeMeasure(self: *App) void {
        self.compose_measure = .{};
        self.compose_measure.failure.set("ReviewRequired") catch unreachable;
        self.review_ready = false;
    }
    fn composeMeasureCurrent(self: *const App) bool {
        return self.compose_measure.measured and same(self.compose_measure.measured_operation.slice(), self.compose_measure.operation.slice()) and self.compose_measure.revision == self.compose.revision and self.compose.saved_revision == self.compose.revision and same(self.compose_measure.draft.slice(), self.compose.id.value());
    }
    fn composeSizeLabel(self: *App, exact: bool) ![]const u8 {
        if (self.compose.saved_changed) return "Saved draft changed elsewhere · :resolve-draft";
        if (!self.composeMeasureCurrent() and (self.compose.unknown_outcome or self.compose.gmailPaused() or self.grace_active or self.grace_recovery)) return "Saved local copy · size not measured";
        if (!self.composeMeasureCurrent()) {
            const failure = self.compose_measure.failure.slice();
            if (same(failure, "DraftChanged")) return "Saved draft changed · reopen before Send";
            if (same(failure, "ReviewRequired")) return "Message size: review again before Send";
            if (failure.len > 0) return std.fmt.allocPrint(self.frame.allocator(), "Message size unavailable: {s}", .{failure});
            if (!self.compose_measure.pending and self.compose_measure.operation.len == 0 and self.compose.revision == self.compose.saved_revision) return "Message size: review to calculate";
            return if (self.compose.revision != self.compose.saved_revision) "Message size: saving changes…" else "Message size: calculating…";
        }
        const limit = self.compose_measure.max_bytes;
        if (!self.compose_measure.exact) return if (exact) std.fmt.allocPrint(self.frame.allocator(), "MIME exceeds {d} bytes · exact size unavailable\n", .{limit}) else std.fmt.allocPrint(self.frame.allocator(), "MIME > {d} MiB · too large", .{limit / (1024 * 1024)});
        const bytes = self.compose_measure.bytes.?;
        if (exact) return std.fmt.allocPrint(self.frame.allocator(), "MIME: {d} / {d} bytes · exact{s}\n", .{ bytes, limit, if (self.compose_measure.over_limit) @as([]const u8, " · OVER LIMIT") else "" });
        const tenth_mib = (bytes * 10 + (1024 * 1024 - 1)) / (1024 * 1024);
        const limit_tenth = (limit * 10) / (1024 * 1024);
        return std.fmt.allocPrint(self.frame.allocator(), "MIME: {d}.{d} / {d}.{d} MiB{s}", .{ tenth_mib / 10, tenth_mib % 10, limit_tenth / 10, limit_tenth % 10, if (self.compose_measure.over_limit) @as([]const u8, " · TOO LARGE") else if (bytes >= limit - limit / 5) " · near limit" else "" });
    }
    fn renderedSizeFailure(code: []const u8) bool {
        return same(code, "RenderedBodyTooLarge") or same(code, "BodyTooLarge");
    }
    fn validateComposeReview(self: *App) !void {
        var arena: std.heap.ArenaAllocator = .init(composeBacking(self.allocator));
        defer arena.deinit();
        const draft = try self.compose.draft(arena.allocator());
        try @import("core.zig").validateDraft(draft, false);
        if (draft.to.len + draft.cc.len + draft.bcc.len == 0) {
            self.mode = .compose;
            self.compose.selected = 0;
            self.compose.attachment_focus = false;
            self.compose.insert_mode = true;
            return error.MissingRecipient;
        }
        self.compose_portable_warning = draftExceedsPortableTransport(draft);
    }
    fn validateComposeSend(self: *App) !void {
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        defer arena.deinit();
        const draft = try self.compose.draft(arena.allocator());
        @import("core.zig").validateDraft(draft, true) catch |err| {
            if (err == error.MissingRecipient) {
                self.mode = .compose;
                self.compose.selected = 0;
                self.compose.attachment_focus = false;
                self.compose.insert_mode = true;
            }
            return err;
        };
        self.compose_portable_warning = draftExceedsPortableTransport(draft);
    }
    fn savedDraftChanged(self: *App) void {
        self.compose.saved_changed = true;
        self.cancelAutosaveTimer();
        self.autosave_due = false;
        self.retireComposeMeasure();
        self.compose_measure.failure.set("DraftChanged") catch unreachable;
        self.gmail_send_ack = false;
        self.say(true, "Saved draft changed elsewhere · local text kept · :resolve-draft", .{});
    }
    fn openDraftConflict(self: *App) !void {
        if (!self.compose_active or !self.compose.saved_changed) return error.DraftRequired;
        try self.beginUx(.draft_conflict, " Saved draft changed elsewhere · choose a local resolution ");
        try self.ux_target.set(self.allocator, self.compose.id.value());
        try self.uxRow(.{ .label = "Save local copy", .detail = "Keep this exact text and original as a new draft; the other draft stays unchanged" });
        try self.uxRow(.{ .label = "Reload saved draft", .detail = if (self.compose.revision == self.compose.saved_revision) "Replace this unchanged view with the current saved draft" else "Local edits are unsaved: save a local copy first" });
    }
    fn reloadChangedDraft(self: *App) !void {
        if (!self.compose_active or !self.compose.saved_changed) return error.DraftRequired;
        if (self.compose.revision != self.compose.saved_revision) {
            self.say(true, "Local edits are unsaved · choose Save local copy before reloading", .{});
            return;
        }
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        self.closeUx();
        self.review_ready = false;
        self.gmail_send_ack = false;
        self.mode = .compose;
        self.compose.insert_mode = false;
        try self.start(.draft_read, .{ .account = self.account(), .cmd = "draft.read", .draftId = self.compose.id.value() });
        self.job.reload_conflict = true;
        self.job.reload_revision = self.compose.revision;
        try self.job.draft_target.set(self.compose.id.value());
    }
    fn saveLocalDraftCopy(self: *App) !void {
        if (browser_target or !self.compose_active or !self.compose.saved_changed) return error.DraftRequired;
        if (self.compose.unknown_outcome or self.compose.gmailPaused() or self.grace_active or self.grace_recovery) return error.UnknownOutcome;
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        self.cancelAutosaveTimer();
        self.autosave_due = false;
        var arena: std.heap.ArenaAllocator = .init(composeBacking(self.allocator));
        defer arena.deinit();
        var fields: [5][]const u8 = undefined;
        var copy = self.compose.recovery(&fields);
        copy.id = "";
        var snapshot = try @import("mail_response_value.zig").borrowed(arena.allocator(), copy);
        // A copy is the exact local snapshot, including absence of an original.
        // Omission would ask the backend to inherit the other client's source.
        if (copy.original == null) try snapshot.object.put(arena.allocator(), "original", .null);
        self.autosave_revision = self.compose.revision;
        try self.start(.save, .{ .account = self.account(), .cmd = "draft.recovery-save", .copyFromDraftId = self.compose.id.value(), .draftId = "", .draft = snapshot, .acknowledgementOnly = true });
        self.job.save_copy = true;
        self.mode = .compose;
        self.review_ready = false;
        self.closeUx();
    }
    fn localCopyAcknowledged(envelope: Value, expected_account: []const u8, old_id: []const u8) bool {
        const result = get(envelope, "data");
        const id = text(get(result, "id"));
        return truth(get(envelope, "ok")) and same(text(get(envelope, "account")), expected_account) and same(text(get(result, "copiedFrom")), old_id) and id.len > 0 and id.len <= 128 and !same(id, old_id);
    }
    /// Prepare every owned value before changing the source identity. Link
    /// strings outlive worker scratch; the commit below only swaps ownership.
    fn adoptRecoveryIdentity(self: *App, result: Value) !void {
        const id = text(get(result, "id"));
        const raw_digest = get(result, "contentDigest");
        if (raw_digest != .null and raw_digest != .string) return error.DraftPersistenceFailed;
        const digest = text(raw_digest);
        if (digest.len != 0) {
            if (digest.len != 64) return error.DraftPersistenceFailed;
            for (digest) |byte| if (!std.ascii.isHex(byte)) return error.DraftPersistenceFailed;
        }
        var staged_arena: ?std.heap.ArenaAllocator = std.heap.ArenaAllocator.init(self.allocator);
        defer if (staged_arena) |*arena| arena.deinit();
        const raw_link = get(result, "gmailLink");
        const staged_link: ?@import("draft_link.zig").Link = if (raw_link == .null) null else std.json.parseFromValueLeaky(@import("draft_link.zig").Link, staged_arena.?.allocator(), raw_link, .{ .allocate = .alloc_always }) catch |err| return if (err == error.OutOfMemory) error.OutOfMemory else error.DraftPersistenceFailed;
        if (staged_link) |inherited| {
            inherited.validate() catch return error.DraftPersistenceFailed;
            if (!same(inherited.draftId, id) or inherited.paused or (inherited.phase != .linked and inherited.phase != .missing) or inherited.version != 1 or inherited.sendAcknowledgedDigest.len != 0 or inherited.lastImportedDraftId.len != 0 or inherited.lastImportedMessageId.len != 0) return error.DraftPersistenceFailed;
        }
        var staged_id: Field = .{};
        defer staged_id.deinit(self.allocator);
        var staged_digest: Field = .{};
        defer staged_digest.deinit(self.allocator);
        try staged_id.set(self.allocator, id);
        try staged_digest.set(self.allocator, digest);
        staged_id.version = self.compose.id.version +% 1;
        staged_digest.version = self.gmail_content_digest.version +% 1;

        // No allocation or validation can fail after the first live swap.
        std.mem.swap(Field, &self.compose.id, &staged_id);
        std.mem.swap(Field, &self.gmail_content_digest, &staged_digest);
        std.mem.swap(?std.heap.ArenaAllocator, &self.compose.gmail_arena, &staged_arena);
        self.compose.gmail_link = staged_link;
        self.compose.gmail_guard_unknown = false;
        self.compose.operation_id.deinit(self.allocator);
        self.compose.operation_error.deinit(self.allocator);
        self.gmail_draft_outcome.deinit(self.allocator);
        self.gmail_remote_version.deinit(self.allocator);
    }
    fn acceptLocalDraftCopy(self: *App, response: []const u8) !void {
        if (!self.compose_active or self.job.account_index != self.account_index or self.job.generation != self.generation or !same(self.job.draft_target.slice(), self.compose.id.value())) return error.DraftChanged;
        self.gmail_send_ack = false;
        self.gmail_review_ready = false;
        self.review_ready = false;
        self.compose_measure = .{};
        const envelope = std.json.parseFromSliceLeaky(Value, self.job_arena.allocator(), response, .{}) catch |err| return if (err == error.OutOfMemory) error.OutOfMemory else error.DraftPersistenceFailed;
        if (!localCopyAcknowledged(envelope, self.account(), self.compose.id.value())) return error.DraftPersistenceFailed;
        try self.adoptRecoveryIdentity(get(envelope, "data"));
        self.gmail_reload_pending = false;
        self.gmail_review_ready = false;
        self.gmail_send_ack = false;
        self.compose.saved_changed = false;
        self.compose.saved_revision = self.autosave_revision;
        self.compose_measure = .{};
        self.review_ready = false;
        self.mode = .compose;
        if (self.compose.revision != self.compose.saved_revision and !self.exit_persistence) self.autosave_due = true;
        self.say(false, "Local edits saved as a new draft · other draft unchanged · review before Send", .{});
    }
    fn draftSaveJob(kind: JobKind) bool {
        return switch (kind) {
            .autosave, .save, .save_review, .save_back, .save_browser, .save_gmail => true,
            else => false,
        };
    }
    /// Another process may have sent this saved source while this view still
    /// owns newer edits. Only the backend can prove that a recovery fork is
    /// safe; never turn an uncertain send or remote-owned draft into a copy.
    fn recoverSettledDraft(self: *App, kind: JobKind) !bool {
        if (browser_target or !draftSaveJob(kind) or self.job.recovery_fork or self.job.future != null or !self.compose_active or self.compose.id.value().len == 0 or self.job.account_index != self.account_index or self.job.generation != self.generation or !same(self.job.draft_target.slice(), self.compose.id.value()) or self.compose.unknown_outcome or self.compose.gmailPaused() or self.grace_active or self.grace_recovery) return false;
        self.cancelAutosaveTimer();
        self.autosave_due = false;
        self.review_ready = false;
        self.gmail_send_ack = false;
        self.compose_measure = .{};
        if (kind != .autosave) self.mode = .compose;
        var arena: std.heap.ArenaAllocator = .init(composeBacking(self.allocator));
        defer arena.deinit();
        var fields: [5][]const u8 = undefined;
        self.autosave_revision = self.compose.revision;
        try self.start(.save, .{ .account = self.account(), .cmd = "draft.recovery-save", .draftId = self.compose.id.value(), .draft = try self.compose.updateValue(arena.allocator(), self.compose.recovery(&fields)), .acknowledgementOnly = true, .forkIfSettled = true });
        self.job.recovery_fork = true;
        self.job.recovery_return_to_mail = kind == .save_back;
        self.job.recovery_from_autosave = kind == .autosave;
        self.say(false, "Previous draft sent elsewhere · preserving edits locally…", .{});
        return true;
    }
    fn recoveredForkAcknowledged(envelope: Value, expected_account: []const u8, old_id: []const u8) bool {
        const result = get(envelope, "data");
        const id = text(get(result, "id"));
        return truth(get(envelope, "ok")) and same(text(get(envelope, "account")), expected_account) and same(text(get(result, "forkedFrom")), old_id) and id.len > 0 and id.len <= 128 and !same(id, old_id);
    }
    fn acceptRecoveredFork(self: *App, response: []const u8) !void {
        if (!self.compose_active or self.job.account_index != self.account_index or self.job.generation != self.generation or !same(self.job.draft_target.slice(), self.compose.id.value())) return error.DraftChanged;
        self.gmail_send_ack = false;
        self.gmail_review_ready = false;
        self.review_ready = false;
        self.compose_measure = .{};
        const envelope = std.json.parseFromSliceLeaky(Value, self.job_arena.allocator(), response, .{}) catch |err| return if (err == error.OutOfMemory) error.OutOfMemory else error.DraftPersistenceFailed;
        if (!recoveredForkAcknowledged(envelope, self.account(), self.compose.id.value())) return error.DraftPersistenceFailed;
        try self.adoptRecoveryIdentity(get(envelope, "data"));
        self.gmail_reload_pending = false;
        self.gmail_review_ready = false;
        self.gmail_send_ack = false;
        self.receipt_unknown = false;
        self.compose.unknown_outcome = false;
        self.review_ready = false;
        self.compose_measure = .{};
        self.compose.saved_revision = self.autosave_revision;
        if (!self.job.recovery_from_autosave) {
            self.compose.insert_mode = false;
            self.mode = .compose;
        }
        if (self.compose.revision != self.compose.saved_revision and !self.exit_persistence) self.autosave_due = true;
        self.clearGraceRecovery();
        if (self.job.recovery_return_to_mail and self.compose.revision == self.compose.saved_revision) {
            self.mode = .browse;
            self.closeComposer();
            if (self.folder == 2) self.pending_list = true;
            try self.resumeMailboxReader();
        }
        self.say(false, "Previous draft sent elsewhere; edits saved as a new draft", .{});
    }
    fn saveDraft(self: *App, kind: JobKind) !void {
        if (self.compose.saved_changed) return self.openDraftConflict();
        if (self.compose.gmailPaused()) {
            if (kind == .save_back) {
                self.clearGraceRecovery();
                self.mode = .browse;
                self.closeComposer();
                self.say(false, "Draft kept · local editing is paused in Gmail", .{});
                try self.resumeMailboxReader();
                return;
            }
            return error.DraftPausedInGmail;
        }
        if (kind == .save_browser and !self.capabilities.open_urls) return error.LinksUnavailable;
        if (self.compose.unknown_outcome) {
            if (kind == .save_back) {
                self.clearGraceRecovery();
                self.mode = .browse;
                self.closeComposer();
                self.say(true, "Outcome unknown · protected draft kept in Drafts · check Gmail Sent before resending", .{});
                try self.resumeMailboxReader();
            } else self.markUnknown(.send);
            return;
        }
        if (kind == .save_review) {
            try self.validateComposeReview();
            self.requireComposePreview() catch |err| {
                if (browser_target or !renderedSizeFailure(@errorName(err))) return err;
            };
        }
        self.preemptReadOnly();
        self.cancelAutosaveTimer();
        self.autosave_due = false;
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        defer arena.deinit();
        self.autosave_revision = self.compose.revision;
        const draft_value = self.compose.draft(arena.allocator()) catch |err| {
            if (kind == .save_review) return err;
            var fields: [5][]const u8 = undefined;
            try self.start(kind, .{ .account = self.account(), .cmd = "draft.recovery-save", .draftId = self.compose.id.value(), .draft = try self.compose.updateValue(arena.allocator(), self.compose.recovery(&fields)), .acknowledgementOnly = true });
            return;
        };
        try self.start(kind, .{ .account = self.account(), .cmd = "draft.update", .draftId = self.compose.id.value(), .draft = try self.compose.updateValue(arena.allocator(), draft_value), .acknowledgementOnly = true });
    }
    /// Renders the saved protected draft into the private HTML preview. The
    /// composer is never saved first, so the draft stays exactly as submitted;
    /// no send, upload or draft write is requested.
    fn openProtectedPreview(self: *App) !void {
        if (browser_target or !self.capabilities.open_urls) return error.LinksUnavailable;
        if (!self.compose_active or (!self.compose.unknown_outcome and !self.compose.gmailPaused()) or self.compose.id.value().len == 0) return error.DraftNotFound;
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        try self.start(.open, .{ .cmd = "draft.open-preview", .account = self.account(), .draftId = self.compose.id.value() });
        self.job.protected_preview = true;
    }
    fn previewComposeInBrowser(self: *App) !void {
        if (browser_target or !self.capabilities.open_urls) return error.LinksUnavailable;
        if (self.compose.unknown_outcome or self.compose.gmailPaused()) return self.openProtectedPreview();
        return self.saveDraft(.save_browser);
    }
    fn persistDraftAtExit(self: *App) !void {
        if (!self.compose_active or self.compose.id.value().len == 0 or self.compose.unknown_outcome or self.compose.gmailPaused()) return;
        // Only the local save/recovery acknowledgement matters at exit. Do
        // not launch fresh size measurements or unrelated background reads.
        self.exit_persistence = true;
        defer self.exit_persistence = false;
        // A signal/EOF can arrive while text insertion or the picker is open.
        // Preserve valid edited fields through the same local draft operation.
        if (self.compose.saved_changed) try self.saveLocalDraftCopy() else try self.saveDraft(.save);
        // One refused update may start an explicit local recovery fork. Wait
        // for its acknowledgement too before allowing signal/EOF to exit.
        for (0..2) |_| {
            if (self.job.future) |*future| future.await(self.io);
            const saved = self.draftSaveConfirmed();
            try self.finish();
            if (saved) return;
            if (self.job.future == null or !self.job.recovery_fork) break;
        }
        return error.DraftPersistenceFailed;
    }
    /// A failed frame/input/pending operation can leave edits newer than the
    /// last autosave. Join every producer before a final synchronous recovery
    /// write; neither the exhausted UI heap nor another UI worker is needed.
    /// This path never applies a receipt, dispatches follow-ups or submits mail.
    fn preserveDraftAfterFailure(self: *App) !void {
        if (browser_target) return;
        self.loop.stop();
        self.cache_watch.stop();
        self.cancelAutosaveTimer();
        const pending = if (self.job.future != null) @as(?JobKind, self.job.kind) else null;
        self.cancelJob();
        // A submitted/queued/Gmail-owned draft already has a durable snapshot.
        // Cancellation is not proof that its write did not reach the backend.
        if (pending) |kind| switch (kind) {
            .send => {
                self.client.sendReceipt(self.job.request, false);
                self.markUnknown(.send);
                return;
            },
            .grace_process => {
                self.markUnknown(.send);
                return;
            },
            .grace_stage, .grace_resume, .grace_cancel, .gmail_draft_action => return,
            else => {},
        };
        if (!self.compose_active or self.compose.id.value().len == 0 or self.compose.revision == self.compose.saved_revision or self.compose.unknown_outcome or self.compose.gmailPaused() or self.grace_active or self.grace_recovery) return;
        self.job.request = "";
        self.job.response = null;
        _ = self.job_arena.reset(.free_all);
        var arena: std.heap.ArenaAllocator = .init(composeBacking(self.allocator));
        defer arena.deinit();
        const a = arena.allocator();
        var fields: [5][]const u8 = undefined;
        var retained = self.compose.recovery(&fields);
        if (self.compose.saved_changed) retained.id = "";
        var snapshot = if (self.compose.saved_changed) try @import("mail_response_value.zig").borrowed(a, retained) else try self.compose.updateValue(a, retained);
        if (self.compose.saved_changed and retained.original == null) try snapshot.object.put(a, "original", .null);
        const request = try encodeJobRequest(a, .{ .account = self.account(), .cmd = "draft.recovery-save", .draftId = if (self.compose.saved_changed) @as([]const u8, "") else self.compose.id.value(), .copyFromDraftId = if (self.compose.saved_changed) @as(?[]const u8, self.compose.id.value()) else null, .draft = snapshot, .acknowledgementOnly = true, .forkIfSettled = !self.compose.saved_changed }, outgoing_native);
        const response = try self.client.call(a, request);
        if (response.len > response_limit) return error.DraftPersistenceFailed;
        const envelope = try std.json.parseFromSliceLeaky(Value, a, response, .{ .allocate = .alloc_if_needed, .max_value_len = response_limit });
        const owner = text(get(envelope, "account"));
        const same_id = same(text(get(get(envelope, "data"), "id")), self.compose.id.value());
        if (self.compose.saved_changed) {
            if (!localCopyAcknowledged(envelope, self.account(), self.compose.id.value())) return error.DraftPersistenceFailed;
        } else if (!truth(get(envelope, "ok")) or (owner.len != 0 and !same(owner, self.account())) or (!same_id and !recoveredForkAcknowledged(envelope, self.account(), self.compose.id.value()))) return error.DraftPersistenceFailed;
        self.compose.saved_revision = self.compose.revision;
    }
    fn draftSaveConfirmed(self: *App) bool {
        if (self.job.kind != .save or !self.job.done.load(.acquire) or self.job.failure != null or self.job.account_index != self.account_index) return false;
        const response = self.job.response orelse return false;
        if (response.len > response_limit) return false;
        const result = std.json.parseFromSliceLeaky(Value, self.job_arena.allocator(), response, .{ .allocate = .alloc_always, .max_value_len = response_limit }) catch return false;
        if (get(result, "ok") != .bool or !truth(get(result, "ok"))) return false;
        const acknowledged_account = text(get(result, "account"));
        if (acknowledged_account.len != 0 and !same(acknowledged_account, self.account())) return false;
        const id = text(get(get(result, "data"), "id"));
        if (self.job.save_copy) return localCopyAcknowledged(result, self.account(), self.compose.id.value());
        if (self.job.recovery_fork) return recoveredForkAcknowledged(result, self.account(), self.compose.id.value());
        return id.len != 0 and same(id, self.compose.id.value());
    }
    fn canEditAttachments(self: *const App) bool {
        return !self.compose.gmailPaused() and !self.compose.unknown_outcome and (self.job.future == null or readOnlyJob(self.job.kind));
    }
    fn promptAttachment(self: *App) !void {
        if (browser_target) return error.FileAccessUnavailable;
        if (!self.capabilities.files) return error.FileAccessUnavailable;
        if (!self.canEditAttachments()) return;
        self.previous_mode = .compose;
        self.mode = .attachment;
        self.path_candidates.reset();
        try self.input.set(self.allocator, "");
        self.beginFileDialog(.open, ".");
    }
    fn fileDialogActive(self: *const App) bool {
        return self.mode == .attachment or self.reader_overlay == .save_attachment or self.reader_overlay == .open_attachment;
    }
    fn fileDialogField(self: *App) *Field {
        return if (self.mode == .attachment) &self.input else &self.reader_path;
    }
    fn beginFileDialog(self: *App, mode: file_dialog.Mode, path: []const u8) void {
        self.file_browser.reset();
        self.selected_file_count = 0;
        for (self.selected_files.items) |*field| {
            field.bytes.clearRetainingCapacity();
            field.cursor = 0;
        }
        self.file_focus = .path;
        self.file_browser.mode = mode;
        if (mode == .save) self.file_browser.setFilename(std.fs.path.basename(path)) catch {};
        self.file_browser_error.set(self.allocator, "") catch {};
        self.file_browser.open(self.io, self.allocator, mode, path) catch |err| {
            self.file_browser_error.set(self.allocator, humanError(@errorName(err))) catch {};
        };
    }
    fn fileDialogFailure(self: *App, err: anyerror) void {
        self.file_browser_error.set(self.allocator, humanError(@errorName(err))) catch {};
        self.sayFailure("File not selected", @errorName(err));
    }
    fn fileDialogLocation(self: *App, field: *Field) !void {
        const destination = if (self.file_browser.mode == .save) try self.file_browser.destination() else try std.fmt.allocPrint(self.frame.allocator(), "{s}/", .{self.file_browser.directory()});
        try field.set(self.allocator, destination);
        self.path_candidates.reset();
        try self.file_browser_error.set(self.allocator, "");
    }
    fn fileDialogHome(self: *App, field: *Field) !void {
        try self.file_browser.browse(self.io, self.allocator, self.environ.get("HOME") orelse ".");
        try self.fileDialogLocation(field);
    }
    fn fileDialogSelect(self: *App, index: usize, field: *Field) !void {
        self.file_browser.select(index);
        if (self.file_browser.selected >= self.file_browser.entries.len) return;
        const entry = self.file_browser.entries[self.file_browser.selected];
        const path = if (entry.directory) try std.fmt.allocPrint(self.frame.allocator(), "{s}/", .{entry.path}) else entry.path;
        try field.set(self.allocator, path);
        if (!entry.directory and self.file_browser.mode == .save) try self.file_browser.setFilename(entry.name);
        self.path_candidates.reset();
    }
    fn fileDialogMarked(self: *const App, path: []const u8) ?usize {
        for (self.selected_files.items[0..self.selected_file_count], 0..) |*field, index| if (same(field.value(), path)) return index;
        return null;
    }
    fn ensureFileFields(self: *App, fields: *std.ArrayList(Field), count: usize) !void {
        if (count > types.Limits.attachments) return error.TooManyAttachments;
        if (count <= fields.items.len) return;
        const old_len = fields.items.len;
        try fields.resize(self.allocator, count);
        @memset(fields.items[old_len..], .{});
    }
    fn toggleFileDialogMark(self: *App, index: usize, field: *Field) !void {
        if (self.mode != .attachment or index >= self.file_browser.entries.len) return;
        const entry = self.file_browser.entries[index];
        if (entry.directory) return;
        try self.fileDialogSelect(index, field);
        if (self.fileDialogMarked(entry.path)) |marked| {
            for (marked..self.selected_file_count - 1) |slot| std.mem.swap(Field, &self.selected_files.items[slot], &self.selected_files.items[slot + 1]);
            self.selected_file_count -= 1;
            self.selected_files.items[self.selected_file_count].bytes.clearRetainingCapacity();
            self.selected_files.items[self.selected_file_count].cursor = 0;
        } else {
            if (self.selected_file_count + self.compose.attachments.len >= types.Limits.attachments) return error.TooManyAttachments;
            try self.ensureFileFields(&self.selected_files, self.selected_file_count + 1);
            try self.selected_files.items[self.selected_file_count].set(self.allocator, entry.path);
            self.selected_file_count += 1;
        }
        try self.file_browser_error.set(self.allocator, "");
    }
    fn attachFileSelection(self: *App) !void {
        if (!self.canEditAttachments()) return error.OperationPending;
        if (self.selected_file_count == 0) return error.InvalidFilePath;
        const related = if (if (self.compose.include_original) self.compose.original else null) |original| original.resources else &.{};
        try types.Limits.validateComposeParts(self.compose.attachments.len + self.selected_file_count, related.len);
        var combined: u64 = 0;
        for ([_][]const types.Attachment{ self.compose.attachments, related }) |list| for (list) |attachment| {
            combined += attachment.size;
        };
        // Validate the complete explicit set before starting any import. Each
        // import then pins immutable bytes, so later source changes cannot
        // alter an attachment that has already been retained by the draft.
        for (self.selected_files.items[0..self.selected_file_count]) |*field| {
            const file = try files.openRegular(self.io, self.allocator, Io.Dir.cwd(), field.value());
            defer file.close(self.io);
            const stat = try file.stat(self.io);
            if (stat.size > types.Limits.attachment_bytes -| combined) return error.AttachmentsTooLarge;
            combined += stat.size;
        }
        try self.ensureFileFields(&self.pending_files, self.selected_file_count);
        for (self.selected_files.items[0..self.selected_file_count], 0..) |*field, index| try self.pending_files.items[index].set(self.allocator, field.value());
        self.pending_file_count = self.selected_file_count;
        self.pending_file_position = 0;
        try self.importNextFile();
        self.file_browser.reset();
        self.selected_file_count = 0;
    }
    fn confirmFileDialog(self: *App, field: *Field, receiving: bool) !void {
        if (!receiving and self.selected_file_count > 0 and self.file_focus == .confirm) return self.attachFileSelection();
        if (field.value().len == 0 and self.file_browser.entries.len > 0) try self.fileDialogSelect(self.file_browser.selected, field);
        const raw = field.value();
        if (raw.len == 0) return error.InvalidFilePath;
        // An existing directory is navigation, never an attachment or a save.
        const directory = path_completion.openDirectory(self.io, raw, false) catch |err| switch (err) {
            error.NotDir, error.FileNotFound => null,
            else => return err,
        };
        if (directory) |dir| {
            dir.close(self.io);
            try self.file_browser.browse(self.io, self.allocator, raw);
            return self.fileDialogLocation(field);
        }
        if (!receiving) {
            if (self.selected_file_count > 0) return self.attachFileSelection();
            try self.attachFile(raw);
            self.file_browser.reset();
            return;
        }
        if (!std.fs.path.isAbsolute(raw) or raw.len > 4096) return error.AttachmentSaveSyntax;
        if (std.fs.path.dirname(raw)) |parent| if (same(parent, self.reader_default_directory.value())) {
            var dir = try path_completion.openDirectory(self.io, parent, true);
            dir.close(self.io);
        };
        self.preemptReaderAction();
        if (self.job.future != null) return error.OperationPending;
        try self.attachment_destination.set(self.allocator, raw);
        self.attachment_expected_size = self.reader_attachment_size;
        self.attachment_open_after = self.reader_overlay == .open_attachment;
        try self.start(.attachment_save, .{ .cmd = "mail.attachment-save", .account = self.account(), .messageId = self.reader_attachment_message.value(), .attachmentId = self.reader_attachment_id.value(), .path = self.attachment_destination.value() });
    }
    fn onFileDialogKey(self: *App, key: Key, field: *Field, receiving: bool) !void {
        if (browser_target) return error.FileAccessUnavailable;
        if (!self.capabilities.files) return error.FileAccessUnavailable;
        self.handleFileDialogKey(key, field, receiving) catch |err| self.fileDialogFailure(err);
    }
    fn handleFileDialogKey(self: *App, key: Key, field: *Field, receiving: bool) !void {
        if (self.job.future != null and (self.job.kind == .attachment_import or self.job.kind == .attachment_save)) return;
        if (key.matches(Key.escape, .{}) or key.matches('c', .{ .ctrl = true })) {
            if (self.path_candidates.candidates.len > 1 and self.path_candidates.active(field.value())) {
                self.path_candidates.reset();
                return;
            }
            self.file_browser.reset();
            self.path_candidates.reset();
            self.selected_file_count = 0;
            if (receiving) self.reader_overlay = .attachments else self.mode = self.previous_mode;
            return;
        }
        if (key.matches(Key.tab, .{}) or key.matches(Key.tab, .{ .shift = true })) {
            const current: usize = @backingInt(self.file_focus);
            self.file_focus = @fromBackingInt(@intCast((current + (if (key.mods.shift) @as(usize, 6) else 1)) % 7));
            return;
        }
        if (key.matches('f', .{ .ctrl = true }) or key.matches('F', .{ .ctrl = true, .shift = true }) or key.matches('f', .{ .ctrl = true, .shift = true })) {
            self.file_focus = .path;
            return self.completePath(field, key.mods.shift);
        }
        if (key.matches('s', .{ .ctrl = true })) {
            self.file_focus = .confirm;
            return self.confirmFileDialog(field, receiving);
        }
        if (!receiving and self.file_focus == .listing and key.matches(' ', .{})) return self.toggleFileDialogMark(self.file_browser.selected, field);
        if (key.matches(Key.enter, .{})) {
            switch (self.file_focus) {
                .parent => {
                    try self.file_browser.parent(self.io, self.allocator);
                    return self.fileDialogLocation(field);
                },
                .home => return self.fileDialogHome(field),
                .hidden => return self.file_browser.toggleHidden(self.io, self.allocator),
                .cancel => {
                    self.file_browser.reset();
                    self.path_candidates.reset();
                    self.selected_file_count = 0;
                    if (receiving) self.reader_overlay = .attachments else self.mode = self.previous_mode;
                    return;
                },
                .listing => {
                    try self.fileDialogSelect(self.file_browser.selected, field);
                    return self.confirmFileDialog(field, receiving);
                },
                .path, .confirm => return self.confirmFileDialog(field, receiving),
            }
        }
        if (key.matches(Key.down, .{}) or key.matches(Key.up, .{}) or key.matches('n', .{ .ctrl = true }) or key.matches('p', .{ .ctrl = true })) {
            self.file_focus = .listing;
            self.file_browser.move(if (key.matches(Key.down, .{}) or key.matches('n', .{ .ctrl = true })) 1 else -1);
            return self.fileDialogSelect(self.file_browser.selected, field);
        }
        if (key.matches(Key.page_down, .{}) or key.matches(Key.page_up, .{})) {
            self.file_browser.move(if (key.matches(Key.page_down, .{})) 8 else -8);
            return self.fileDialogSelect(self.file_browser.selected, field);
        }
        if (key.matches('o', .{ .ctrl = true })) {
            try self.file_browser.parent(self.io, self.allocator);
            return self.fileDialogLocation(field);
        }
        if (key.matches('g', .{ .ctrl = true })) return self.fileDialogHome(field);
        if (key.matches('t', .{ .ctrl = true })) return self.file_browser.toggleHidden(self.io, self.allocator);
        if (key.matches('u', .{ .ctrl = true })) {
            self.path_candidates.reset();
            self.file_focus = .path;
            try field.set(self.allocator, "");
            if (self.file_browser.directory().len > 0) try self.file_browser.setFilter(self.io, self.allocator, "");
            return;
        }
        if (self.file_focus != .path) {
            if (self.file_focus == .listing and (key.matches('j', .{}) or key.matches('k', .{}))) {
                self.file_browser.move(if (key.matches('j', .{})) 1 else -1);
                try self.fileDialogSelect(self.file_browser.selected, field);
            }
            return;
        }
        self.path_candidates.reset();
        try field.handleKey(self.allocator, key, false, 4096);
        // Typing filters only this directory. A pasted absolute destination
        // is still accepted directly; directory entry happens on Enter.
        const parent = std.fs.path.dirname(field.value());
        if (self.file_browser.directory().len > 0 and (parent == null or same(parent.?, self.file_browser.directory()))) {
            const fragment = std.fs.path.basename(field.value());
            if (fragment.len <= file_dialog.max_filter) try self.file_browser.setFilter(self.io, self.allocator, fragment);
        }
        if (receiving and !std.mem.endsWith(u8, field.value(), "/")) self.file_browser.setFilename(std.fs.path.basename(field.value())) catch {};
    }
    fn onFileDialogMouse(self: *App, mouse: vaxis.Mouse, wheel: ?bool) !void {
        if (browser_target) return error.FileAccessUnavailable;
        if (!self.capabilities.files) return error.FileAccessUnavailable;
        if (self.job.future != null and (self.job.kind == .attachment_save or self.job.kind == .attachment_import)) return;
        const field = self.fileDialogField();
        if (wheel) |down| {
            self.file_focus = .listing;
            self.file_browser.move(if (down) 3 else -3);
            try self.fileDialogSelect(self.file_browser.selected, field);
            return;
        }
        const hit = self.mouse_hits.at(mouse.col, mouse.row) orelse return;
        switch (hit.kind) {
            .file_row => {
                self.file_focus = .listing;
                try self.fileDialogSelect(hit.index, field);
            },
            .file_mark => {
                self.file_focus = .listing;
                try self.toggleFileDialogMark(hit.index, field);
            },
            .file_parent => {
                self.file_focus = .parent;
                try self.file_browser.parent(self.io, self.allocator);
                try self.fileDialogLocation(field);
            },
            .file_home => {
                self.file_focus = .home;
                try self.fileDialogHome(field);
            },
            .file_hidden => {
                self.file_focus = .hidden;
                try self.file_browser.toggleHidden(self.io, self.allocator);
            },
            .file_confirm => {
                self.file_focus = .confirm;
                try self.confirmFileDialog(field, self.mode != .attachment);
            },
            .file_cancel => {
                self.file_focus = .cancel;
                try self.handleFileDialogKey(.{ .codepoint = Key.enter }, field, self.mode != .attachment);
            },
            .file_location => self.file_focus = .path,
            else => {},
        }
    }
    fn drawFileDialog(self: *App, win: vaxis.Window) !void {
        if (browser_target) return;
        if (!self.fileDialogActive()) return;
        self.mouse_hits.clear();
        const width = @min(win.width -| 2, 92);
        const height = fileDialogHeight(self.file_browser.entries.len, win.height -| 2);
        if (width < 25 or height < 8) return;
        const area = win.child(.{ .x_off = @intCast((win.width - width) / 2), .y_off = @intCast((win.height - height) / 2), .width = width, .height = height });
        area.fill(.{ .style = self.style(.text) });
        win.hideCursor();
        const receiving = self.mode != .attachment;
        const inner = self.panel(area, 0, width, if (receiving) " Save attachment · new file " else " Attach file · local draft ", true);
        const field = self.fileDialogField();
        try self.editLine(inner, 0, "Path", field, self.file_focus == .path, if (self.file_focus == .path) .selected else .text);
        self.mouseRows(inner, 0, 1, .file_location, 0);
        try self.line(inner, 1, try self.fitLine(inner, try std.fmt.allocPrint(self.frame.allocator(), "Folder: {s}{s}", .{ self.file_browser.directory(), if (self.file_browser.show_hidden) @as([]const u8, " · Hidden on") else "" }), inner.width), .muted);
        const compact = inner.width < 52;
        const controls = [_]struct { label: []const u8, kind: layout.HitKind }{ .{ .label = if (compact) "[Up]" else "[Up] Ctrl+O", .kind = .file_parent }, .{ .label = if (compact) "[Home]" else "[Home] Ctrl+G", .kind = .file_home }, .{ .label = if (compact) (if (inner.width < 26) "[Hidden]" else if (self.file_browser.show_hidden) "[Hidden on]" else "[Hidden off]") else if (self.file_browser.show_hidden) "[Hidden on] Ctrl+T" else "[Hidden off] Ctrl+T", .kind = .file_hidden } };
        var column: u16 = 0;
        for (controls) |control| {
            const w: u16 = @intCast(control.label.len);
            if (column + w > inner.width) break;
            const button = inner.child(.{ .x_off = column, .y_off = 2, .width = w, .height = 1 });
            const focused = (control.kind == .file_parent and self.file_focus == .parent) or (control.kind == .file_home and self.file_focus == .home) or (control.kind == .file_hidden and self.file_focus == .hidden);
            try self.line(button, 0, control.label, if (focused) .selected else .accent);
            self.mouseArea(button, control.kind, 0);
            column += w + 2;
        }
        if (!receiving) {
            var combined: u64 = 0;
            for (self.compose.attachments) |attachment| combined += attachment.size;
            if (if (self.compose.include_original) self.compose.original else null) |original| for (original.resources) |attachment| {
                combined += attachment.size;
            };
            var unavailable = false;
            for (self.selected_files.items[0..self.selected_file_count]) |*selected_file| {
                const selected_input = files.openRegular(self.io, self.frame.allocator(), Io.Dir.cwd(), selected_file.value()) catch {
                    unavailable = true;
                    continue;
                };
                defer selected_input.close(self.io);
                const stat = selected_input.stat(self.io) catch {
                    unavailable = true;
                    continue;
                };
                combined +|= stat.size;
            }
            const summary = try std.fmt.allocPrint(self.frame.allocator(), "{d} selected · {s} combined / 25 MiB{s}", .{ self.selected_file_count, try attachmentSizeLabel(self.frame.allocator(), combined), if (unavailable) @as([]const u8, " · file unavailable") else "" });
            try self.line(inner, 3, try self.fitLine(inner, summary, inner.width), if (unavailable or combined > types.Limits.attachment_bytes) .warning else .muted);
        }
        const rows = inner.height -| 7;
        const top = self.file_browser.selected -| (rows -| 1);
        const end = @min(top + rows, self.file_browser.entries.len);
        for (self.file_browser.entries[top..end], top..) |entry, index| {
            const item = inner.child(.{ .y_off = @intCast(4 + index - top), .height = 1 });
            const size = if (entry.directory) "Folder" else if (entry.size) |bytes| try attachmentSizeLabel(self.frame.allocator(), bytes) else "";
            const name_width = item.width -| @as(u16, @intCast(@min(size.len + 2, item.width)));
            const focused = index == self.file_browser.selected and self.file_focus == .listing;
            item.fill(.{ .style = self.style(if (focused) .selected else .text) });
            const marker: []const u8 = if (receiving) "" else if (entry.directory) "    " else if (self.fileDialogMarked(entry.path) != null) "[x] " else "[ ] ";
            try self.line(item.child(.{ .width = name_width }), 0, try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}{s}", .{ marker, entry.name, if (entry.directory) @as([]const u8, "/") else "" }), if (focused) .selected else .text);
            try self.line(item.child(.{ .x_off = name_width }), 0, size, .muted);
            self.mouseArea(item, .file_row, index);
            if (!receiving and !entry.directory) self.mouseArea(item.child(.{ .width = 3, .height = 1 }), .file_mark, index);
        }
        if (self.file_browser.entries.len == 0) try self.line(inner, 4, if (self.file_browser.directory().len == 0) "Edit the path to choose a folder or file" else "No matching files · hidden files stay hidden", .muted);
        const pending = self.job.future != null and (self.job.kind == .attachment_save or self.job.kind == .attachment_import);
        const detail = if (pending) (if (receiving) @as([]const u8, "Saving attachment…") else "Importing selected files…") else if (self.file_browser_error.value().len > 0) self.file_browser_error.value() else if (self.file_browser.truncated or self.file_browser.scan_limited) "First matching files · type a name to narrow the list" else if (receiving) "Creates a new file · existing files are preserved" else "Space checks files · keep selections across folders";
        try self.line(inner, inner.height - 3, try self.fitLine(inner, detail, inner.width), if (self.file_browser_error.value().len > 0) .warning else .muted);
        const confirm = if (receiving) (if (self.reader_overlay == .open_attachment) "[Save & open]" else "[Save]") else "[Attach]";
        const button_width: u16 = @intCast(confirm.len);
        const button = inner.child(.{ .y_off = inner.height - 2, .width = button_width, .height = 1 });
        try self.line(button, 0, confirm, if (pending) .muted else if (self.file_focus == .confirm) .selected else .accent);
        if (!pending) self.mouseArea(button, .file_confirm, 0);
        const cancel = inner.child(.{ .x_off = button_width + 2, .y_off = inner.height - 2, .width = 8, .height = 1 });
        try self.line(cancel, 0, "[Cancel]", if (!pending and self.file_focus == .cancel) .selected else .muted);
        if (!pending) self.mouseArea(cancel, .file_cancel, 0);
        try self.line(inner, inner.height - 1, try self.fitLine(inner, self.fileDialogHints(inner.width), inner.width), .muted);
    }
    fn fileDialogHints(self: *const App, width: u16) []const u8 {
        if (width < 40) return switch (self.file_focus) {
            .path => "Ctrl+F Match · Esc Back",
            .parent => "Ctrl+O Up · Enter Up",
            .home => "Ctrl+G Home · Esc Back",
            .hidden => "Ctrl+T Hidden · Enter",
            .listing => if (self.mode == .attachment) "Space Check · Enter Choose" else "j/k Move · Enter Choose",
            .confirm => "Ctrl+S Choose · Esc Back",
            .cancel => "Enter Cancel · Esc Back",
        };
        if (width < 60) return switch (self.file_focus) {
            .path => "Ctrl+F Complete · Ctrl+U Clear · Tab",
            .parent => "Ctrl+O Up · Tab Controls · Enter Up",
            .home => "Ctrl+G Home · Tab Controls · Enter Home",
            .hidden => "Ctrl+T Hidden · Tab Controls · Enter",
            .listing => if (self.mode == .attachment) "j/k Move · Space Check · Enter Choose" else "Ctrl+N/P Rows · Enter Choose · Tab",
            .confirm => "Ctrl+S Confirm · Tab Controls · Esc Back",
            .cancel => "Tab Controls · Enter Cancel · Esc Back",
        };
        return if (self.file_focus == .path)
            "Ctrl+F Complete · Ctrl+Shift+F Prev · Ctrl+U Clear · Tab"
        else if (self.file_focus == .listing and self.mode == .attachment)
            "j/k Move · Space Check · Enter Choose · Tab Attach · Esc"
        else
            "Ctrl+S Confirm · Ctrl+N/P Rows · Tab · Enter Choose · Esc";
    }
    fn completePath(self: *App, field: *Field, backwards: bool) !void {
        if (browser_target) return error.FileAccessUnavailable;
        if (!self.capabilities.files) return error.FileAccessUnavailable;
        const result = if (backwards) try self.path_candidates.shiftTab(self.io, self.allocator, field.value()) else try self.path_candidates.tab(self.io, self.allocator, field.value());
        if (result.path) |path| try field.set(self.allocator, path);
        if (self.fileDialogActive()) {
            const path = field.value();
            const parent = if (std.mem.endsWith(u8, path, "/")) path else std.fs.path.dirname(path) orelse ".";
            self.file_browser.browse(self.io, self.allocator, parent) catch |err| {
                self.fileDialogFailure(err);
                return;
            };
            const fragment = if (std.mem.endsWith(u8, path, "/")) "" else std.fs.path.basename(path);
            if (fragment.len <= file_dialog.max_filter) try self.file_browser.setFilter(self.io, self.allocator, fragment);
            if (self.file_browser.mode == .save and fragment.len > 0) self.file_browser.setFilename(fragment) catch {};
        }
        if (result.matches == 0) self.say(false, "No matching regular files or directories", .{}) else self.say(false, "{d} path match{s} · Ctrl+F cycles · Enter accepts{s}", .{ result.matches, if (result.matches == 1) @as([]const u8, "") else "es", if (result.truncated) @as([]const u8, " · scan limit reached") else "" });
    }
    fn drawPathCandidates(self: *App, win: vaxis.Window, field: *const Field, first_row: usize, available: usize) !void {
        if (!self.path_candidates.active(field.value()) or self.path_candidates.candidates.len <= 1 or first_row >= win.height or available == 0) return;
        const visible = @min(@as(usize, 6), @min(available, self.path_candidates.candidates.len));
        const top = if (self.path_candidates.selected) |selected| selected -| (visible - 1) else 0;
        for (self.path_candidates.candidates[top .. top + visible], top..) |candidate, index| {
            const label = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}", .{ candidate.name, if (candidate.directory) @as([]const u8, "/") else "" });
            try self.line(win, first_row + index - top, try self.fitLine(win, label, win.width), if (self.path_candidates.selected != null and self.path_candidates.selected.? == index) .selected else .text);
        }
    }
    fn drawPathCompletion(self: *App, win: vaxis.Window) !void {
        if (self.mode != .attachment or !self.path_candidates.active(self.input.value()) or self.path_candidates.candidates.len <= 1) return;
        const width = @min(win.width -| 2, 78);
        const height = @min(win.height -| 4, 10);
        if (width < 10 or height < 4) return;
        const area = win.child(.{ .x_off = @intCast((win.width - width) / 2), .y_off = win.height - height - 2, .width = width, .height = height });
        area.fill(.{ .style = self.style(.text) });
        const inner = self.panel(area, 0, width, " Files · Tab cycles · literal paths ", true);
        try self.drawPathCandidates(inner, &self.input, 0, inner.height -| 1);
        try self.line(inner, inner.height - 1, if (self.path_candidates.truncated) "First matches · scan limit reached · Esc Back" else "Tab Next match · Enter Attach · Esc Back", .muted);
    }
    fn composeControlEnabled(self: *const App, index: usize) bool {
        if (index == self.compose.attachments.len + 4) return self.compose_action_mask & 1 != 0;
        if (index == self.compose.attachments.len + 5) return self.compose_action_mask & 2 != 0;
        if (index == self.compose.attachments.len + 6) return self.compose_original_drawn and self.originalPolicyMutable();
        if (index == self.compose.attachments.len + 7) return self.compose_fold_drawn;
        if (self.compose.unknown_outcome) return false;
        if (self.compose.gmailPaused()) return index == self.compose.attachments.len + 2;
        if (index == 0) return self.capabilities.attachments and self.capabilities.files;
        if (index <= self.compose.attachments.len) return self.capabilities.attachments;
        if (index == self.compose.attachments.len + 1) return self.capabilities.markdown;
        if (index == self.compose.attachments.len + 2) return true;
        return index == self.compose.attachments.len + 3 and self.capabilities.aliases;
    }
    fn composeControlFocusable(self: *const App, index: usize) bool {
        if (index == self.compose.attachments.len + 6) return self.compose_original_drawn and self.originalPolicyUnlocked();
        if (index == self.compose.attachments.len + 4) return self.compose_action_drawn & 1 != 0;
        if (index == self.compose.attachments.len + 5) return self.compose_action_drawn & 2 != 0;
        return self.composeControlEnabled(index);
    }
    // Keep stable control IDs while placing source controls before the footer.
    fn composeControlOrder(self: *const App, index: usize) usize {
        const base = self.compose.attachments.len;
        if (index == base + 4 or index == base + 5) return index + 2;
        if (index == base + 6 or index == base + 7) return index - 2;
        return index;
    }
    fn adjacentComposeControl(self: *const App, from: usize, backwards: bool) ?usize {
        const count = self.compose.attachments.len + 8;
        var index = self.composeControlOrder(from);
        while (true) {
            if (backwards) {
                if (index == 0) return null;
                index -= 1;
            } else {
                index += 1;
                if (index >= count) return null;
            }
            const control = self.composeControlOrder(index);
            if (self.composeControlFocusable(control)) return control;
        }
    }
    fn focusComposeAttachments(self: *App, cursor: usize) void {
        if (!self.compose.attachment_focus) self.compose.attachment_return_insert = self.compose.insert_mode;
        const wanted = @min(cursor, self.compose.attachments.len + 7);
        self.compose.attachment_focus = true;
        self.compose.attachment_cursor = if (self.composeControlFocusable(wanted)) wanted else self.adjacentComposeControl(wanted, false) orelse self.adjacentComposeControl(wanted, true) orelse wanted;
        self.compose.insert_mode = false;
    }
    fn leaveComposeAttachments(self: *App, field: usize, restore_insert: bool) void {
        self.compose.attachment_focus = false;
        self.compose.selected = field;
        self.compose.insert_mode = restore_insert and self.compose.attachment_return_insert;
    }
    fn onComposeAttachmentKey(self: *App, key: Key) !void {
        const count = self.compose.attachments.len + 7;
        self.compose.attachment_cursor = @min(self.compose.attachment_cursor, count);
        if (key.matches(Key.escape, .{}) or key.matches('q', .{})) return self.leaveComposeAttachments(4, false);
        if (key.matches(Key.tab, .{})) {
            if (self.adjacentComposeControl(self.compose.attachment_cursor, false)) |index| self.compose.attachment_cursor = index else self.leaveComposeAttachments(0, true);
            return;
        }
        if (key.matches(Key.tab, .{ .shift = true })) {
            if (self.adjacentComposeControl(self.compose.attachment_cursor, true)) |index| self.compose.attachment_cursor = index else self.leaveComposeAttachments(4, true);
            return;
        }
        if (key.matches(Key.enter, .{}) and self.compose.attachment_cursor == self.compose.attachments.len + 6 and self.composeControlEnabled(self.compose.attachment_cursor)) return self.setOriginalIncluded(!self.compose.include_original, true);
        if (key.matches(Key.enter, .{}) and self.compose.attachment_cursor == self.compose.attachments.len + 7 and self.composeControlEnabled(self.compose.attachment_cursor)) return self.toggleOriginalFold();
        if (key.matches(Key.enter, .{}) and self.compose.attachment_cursor == self.compose.attachments.len + 4 and self.composeControlEnabled(self.compose.attachment_cursor)) return self.previewComposeInBrowser();
        if (key.matches(Key.enter, .{}) and self.compose.attachment_cursor == self.compose.attachments.len + 5 and self.composeControlEnabled(self.compose.attachment_cursor)) return self.openGmailDraft();
        if (key.matches('j', .{}) or key.matches(Key.down, .{}) or key.matches('n', .{ .ctrl = true })) self.compose.attachment_cursor = self.adjacentComposeControl(self.compose.attachment_cursor, false) orelse self.compose.attachment_cursor else if (key.matches('k', .{}) or key.matches(Key.up, .{}) or key.matches('p', .{ .ctrl = true })) self.compose.attachment_cursor = self.adjacentComposeControl(self.compose.attachment_cursor, true) orelse self.compose.attachment_cursor else if (key.matches('A', .{}) or key.matches('a', .{ .shift = true }) or (key.matches(Key.enter, .{}) and self.compose.attachment_cursor == 0)) try self.promptAttachment() else if (key.matches(Key.enter, .{}) and self.compose.attachment_cursor == self.compose.attachments.len + 1) try self.toggleComposeFormat() else if (key.matches(Key.enter, .{}) and self.compose.attachment_cursor == self.compose.attachments.len + 2) self.cycleComposePreview() else if (key.matches(Key.enter, .{}) and self.compose.attachment_cursor == self.compose.attachments.len + 3) try self.cycleComposeIdentity() else if (self.compose.attachment_cursor > 0 and self.compose.attachment_cursor <= self.compose.attachments.len and (key.matches(Key.enter, .{}) or key.matches('x', .{}))) try self.detachAttachment(self.compose.attachment_cursor - 1);
    }
    fn detachAttachment(self: *App, index: usize) !void {
        if (!self.canEditAttachments()) return;
        if (index >= self.compose.attachments.len) return error.InvalidAttachment;
        const retained = try self.frame.allocator().alloc(types.Attachment, self.compose.attachments.len - 1);
        var count: usize = 0;
        for (self.compose.attachments, 0..) |item, attachment_index| if (attachment_index != index) {
            retained[count] = item;
            count += 1;
        };
        try self.compose.replaceAttachments(self.allocator, retained[0..count]);
        if (self.compose_source_mode == .attached) {
            var has_original = false;
            for (self.compose.attachments) |attachment| has_original = has_original or originalAttachment(attachment);
            if (!has_original) self.compose_source_mode = .text;
        }
        self.compose.attachment_scroll = @min(self.compose.attachment_scroll, count -| self.compose.attachment_height);
        if (self.compose.attachment_focus) self.compose.attachment_cursor = @min(self.compose.attachment_cursor, count);
        try self.composerChanged();
        self.say(false, "Attachment removed · local draft · Ctrl+S Review", .{});
    }
    fn attachFile(self: *App, path: []const u8) !void {
        if (browser_target) return error.FileAccessUnavailable;
        if (!self.capabilities.files) return error.FileAccessUnavailable;
        if (!self.canEditAttachments()) return error.OperationPending;
        if (self.compose.attachments.len >= types.Limits.attachments) return error.TooManyAttachments;
        const file = try files.openRegular(self.io, self.allocator, Io.Dir.cwd(), path);
        defer file.close(self.io);
        const stat = try file.stat(self.io);
        var combined: usize = 0;
        for (self.compose.attachments) |attachment| combined += attachment.size;
        if (if (self.compose.include_original) self.compose.original else null) |original| {
            try types.Limits.validateComposeParts(self.compose.attachments.len + 1, original.resources.len);
            for (original.resources) |attachment| combined += attachment.size;
        }
        if (stat.size > types.Limits.attachment_bytes -| combined) return error.AttachmentsTooLarge;
        try self.ensureFileFields(&self.pending_files, 1);
        try self.pending_files.items[0].set(self.allocator, path);
        self.pending_file_count = 1;
        self.pending_file_position = 0;
        try self.importNextFile();
    }
    fn importNextFile(self: *App) !void {
        if (self.pending_file_position >= self.pending_file_count) return;
        if (!self.canEditAttachments()) return error.OperationPending;
        self.preemptReadOnly();
        try self.start(.attachment_import, .{ .cmd = "attachment.import", .account = self.account(), .path = self.pending_files.items[self.pending_file_position].value() });
        self.say(false, "Importing attachment {d}/{d}…", .{ self.pending_file_position + 1, self.pending_file_count });
    }
    fn saveIncomingAttachment(self: *App, arguments_in: []const u8) !void {
        if (browser_target) return error.FileAccessUnavailable;
        if (!self.capabilities.files) return error.FileAccessUnavailable;
        const arguments_trimmed = std.mem.trimStart(u8, arguments_in, " \t");
        const separator = std.mem.indexOfAny(u8, arguments_trimmed, " \t") orelse return error.AttachmentSaveSyntax;
        const number = std.fmt.parseInt(usize, arguments_trimmed[0..separator], 10) catch return error.AttachmentSaveSyntax;
        // Everything after the numeric argument is a literal path, including
        // internal/trailing spaces. Quotes and variables are not interpreted.
        const path = std.mem.trimStart(u8, arguments_trimmed[separator..], " \t");
        if (number == 0 or path.len == 0 or path.len > 4096 or !std.fs.path.isAbsolute(path) or std.mem.indexOfScalar(u8, path, 0) != null) return error.AttachmentSaveSyntax;
        self.preemptReaderAction();
        if (self.job.future != null) return error.OperationBusy;
        self.attachment_open_after = false;
        var index: usize = 0;
        for (self.thread) |message| for (items(get(message, "attachments"))) |attachment| {
            index += 1;
            if (index != number) continue;
            const size = get(attachment, "size");
            if (size != .integer or size.integer < 0 or size.integer > @as(i64, @intCast(types.Limits.incoming_attachment_bytes))) return error.InvalidAttachment;
            const message_id = text(get(message, "id"));
            const attachment_id = text(get(attachment, "id"));
            if (message_id.len == 0 or attachment_id.len == 0 or attachment_id.len > 1024) return error.InvalidAttachment;
            try self.attachment_destination.set(self.allocator, path);
            self.attachment_expected_size = @intCast(size.integer);
            // start serializes these identities before the worker can run;
            // later cursor movement cannot retarget the request or destination.
            try self.start(.attachment_save, .{ .account = self.account(), .cmd = "mail.attachment-save", .messageId = message_id, .attachmentId = attachment_id, .path = self.attachment_destination.value() });
            return;
        };
        return error.AttachmentNotFound;
    }
    fn operationId(self: *App, allocator: Allocator) ![]const u8 {
        return platform.operationId(self.io, allocator, self.operation_nonce, &self.operation_sequence);
    }
    fn sendDraft(self: *App) !void {
        if (self.compose.saved_changed) return self.openDraftConflict();
        if (self.compose.gmailPaused()) return error.DraftPausedInGmail;
        if (self.gmailCopyWarning() and !self.gmail_send_ack) return error.GmailCopyUnchecked;
        if (self.compose.unknown_outcome) {
            self.markUnknown(.send);
            return;
        }
        try self.validateComposeSend();
        try self.requireComposePreview();
        if (!self.review_ready) return error.DraftReviewRequired;
        if (!browser_target and !self.composeMeasureCurrent()) {
            self.requestComposeMeasure();
            _ = try self.dispatchComposer();
            self.say(false, "Calculating exact size · review it before Send", .{});
            return;
        }
        if (!browser_target and (self.compose_measure.over_limit or !self.compose_measure.sendable)) return error.MessageTooLarge;
        // The digest encodes the complete source and original once; keep that
        // transient copy off the fixed frame heap and release it immediately.
        var digest_arena: std.heap.ArenaAllocator = .init(composeBacking(self.allocator));
        defer digest_arena.deinit();
        const gmail_digest = try @import("draft_link.zig").contentDigest(digest_arena.allocator(), try self.compose.draft(digest_arena.allocator()), self.account());
        if (!browser_target and !same(&gmail_digest, self.compose_measure.content_digest.slice())) return error.DraftChanged;
        const expected_digest: ?[]const u8 = if (browser_target) null else self.compose_measure.content_digest.slice();
        self.review_ready = false;
        const id = if (!browser_target) try self.allocator.dupe(u8, self.compose_measure.operation.slice()) else try self.operationId(self.allocator);
        defer self.allocator.free(id);
        try self.compose.operation_id.set(self.allocator, id);
        try self.compose.operation_error.set(self.allocator, "");
        if (!self.capabilities.send_queue or self.ui_preferences.sendGraceSeconds == 0) try self.start(.send, .{ .account = self.account(), .cmd = "draft.send", .draftId = self.compose.id.value(), .operationId = id, .acknowledgeGmailCopy = self.gmail_send_ack, .gmailCopyDigest = gmail_digest[0..], .expectedContentDigest = expected_digest }) else {
            self.cancelAutosaveTimer();
            self.autosave_due = false;
            try self.start(.grace_stage, .{ .account = self.account(), .cmd = "draft.queue", .draftId = self.compose.id.value(), .operationId = id, .delaySeconds = self.ui_preferences.sendGraceSeconds, .acknowledgeGmailCopy = self.gmail_send_ack, .gmailCopyDigest = gmail_digest[0..], .expectedContentDigest = expected_digest });
        }
    }
    fn pausedGraceForCompose(self: *const App) bool {
        return self.grace_recovery and self.compose_active and !self.compose.unknown_outcome and
            self.compose.id.value().len > 0 and self.grace_queue.value().len > 0 and
            same(self.compose.id.value(), self.grace_draft.value()) and
            same(self.account(), self.grace_account.value());
    }
    fn clearGraceRecovery(self: *App) void {
        self.grace_resume_required = false;
        // The durable queue stays paused. Only its association with this view
        // is cleared; an active countdown retains its cancellation owner.
        if (self.grace_active) return;
        self.grace_recovery = false;
        self.grace_queue.deinit(self.allocator);
        self.grace_account.deinit(self.allocator);
        self.grace_draft.deinit(self.allocator);
        self.grace_due = 0;
        self.grace_close = false;
        self.grace_rect = null;
        self.grace_pending.store(false, .release);
    }
    fn cancelGrace(self: *App, close: bool) !void {
        if (!self.grace_active or !self.grace_pending.load(.acquire)) return;
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        try self.start(.grace_cancel, .{ .cmd = "queue.cancel", .account = self.grace_account.value(), .queueId = self.grace_queue.value() });
        self.grace_close = close;
        self.grace_pending.store(false, .release);
    }
    fn graceTick(self: *App) !void {
        try self.processGrace(false);
    }
    fn graceCancelUnconfirmed(self: *App, code: []const u8) void {
        self.grace_active = false;
        self.grace_pending.store(false, .release);
        self.grace_recovery = false;
        self.compose.operation_error.set(self.allocator, code) catch {};
        self.markUnknown(.send);
        self.say(true, "Undo unconfirmed · draft protected · :receipt checks queue", .{});
        self.status_kind = .unknown;
        if (self.grace_close) self.quit = true;
    }
    fn processGrace(self: *App, send_now: bool) !void {
        if (self.grace_resume_required and !send_now) return;
        if (!self.grace_active or !self.grace_pending.load(.acquire) or self.grace_close) return;
        if (!send_now and Io.Timestamp.now(self.io, .real).toMilliseconds() < self.grace_due) return;
        self.preemptReadOnly();
        if (self.job.future != null) return;
        try self.start(.grace_process, .{ .cmd = if (send_now) @as([]const u8, "queue.send-now") else "queue.process", .account = self.grace_account.value(), .queueId = self.grace_queue.value() });
        self.grace_active = false;
        self.grace_pending.store(false, .release);
        self.grace_rect = null;
        self.say(false, "Submitting · waiting for the provider receipt", .{});
    }
    fn applyGraceResult(self: *App, response: []const u8) !void {
        const result = try self.data(self.job_arena.allocator(), response);
        const state = text(get(result, "state"));
        self.grace_active = false;
        self.grace_pending.store(false, .release);
        self.grace_resume_required = truth(get(result, "resumeRequired"));
        if (same(state, "queued") and self.grace_resume_required) {
            self.grace_recovery = true;
            self.compose.unknown_outcome = false;
            self.mode = .compose;
            self.say(false, "Imported send paused · Ctrl+S Review · :resume-send / :cancel-send", .{});
            return;
        }
        if (same(state, "applied")) {
            self.compose.unknown_outcome = false;
            self.closeComposer();
            self.mode = .browse;
            self.sayAction(false, "Send complete · provider accepted", .{});
            try self.resumeMailboxReader();
        } else if (same(state, "canceled")) {
            self.grace_recovery = false;
            self.compose.unknown_outcome = false;
            self.retireComposeMeasure();
            self.mode = .compose;
            self.say(false, "{s}", .{if (same(text(get(result, "errorCode")), "DraftChanged")) @as([]const u8, "Draft changed · send cancelled · review before sending again") else "Send cancelled · draft retained"});
        } else if (same(state, "rejected")) {
            self.retireComposeMeasure();
            self.mode = .compose;
            self.sayFailure("Submission rejected · draft retained", sendReceiptCode(result));
        } else {
            // A retained-reason failure must not delay the protection itself.
            self.retainSendReceipt(result) catch {};
            self.markUnknown(.send);
        }
    }
    /// Keeps the operation identity and reason of a send receipt. Blank or
    /// malformed fields never erase a reason recorded earlier.
    fn retainSendReceipt(self: *App, receipt: Value) !void {
        const id = sendReceiptOperation(receipt);
        if (id.len > 0) try self.compose.operation_id.set(self.allocator, id);
        const code = sendReceiptCode(receipt);
        if (code.len > 0) try self.compose.operation_error.set(self.allocator, code);
    }
    fn sendReasonText(self: *App) ![]const u8 {
        const code = self.compose.operation_error.value();
        if (code.len == 0) return "Not recorded · treat as possibly sent";
        if (!validDiagnosticCode(code)) return humanError(code);
        return std.fmt.allocPrint(self.frame.allocator(), "{s} ({s})", .{ humanError(code), code });
    }
    fn cancelGraceAtExit(self: *App) void {
        if (!self.grace_active or self.grace_queue.value().len == 0) return;
        self.grace_pending.store(false, .release);
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        defer arena.deinit();
        const request = std.json.Stringify.valueAlloc(arena.allocator(), .{ .cmd = "queue.cancel", .account = self.grace_account.value(), .queueId = self.grace_queue.value() }, .{}) catch return;
        _ = self.client.call(arena.allocator(), request) catch return;
        self.grace_active = false;
    }
    fn drawGrace(self: *App, win: vaxis.Window) !void {
        self.grace_rect = null;
        if (!self.grace_active or win.height < 3) return;
        const remaining = @max(self.grace_due - Io.Timestamp.now(self.io, .real).toMilliseconds(), 0);
        const bar = win.child(.{ .y_off = 1, .height = 1 });
        bar.fill(.{ .style = self.style(.selected) });
        const pending = self.grace_pending.load(.acquire);
        if (!pending) {
            try self.line(bar, 0, "Cancelling send · draft kept", .selected);
            return;
        }
        // Reserve the prefix slot rather than deriving hit positions from the
        // current digits: 10 -> 9 must never move a button under the pointer.
        const prefix_width: u16 = if (win.width >= 70) 36 else if (win.width >= 55) 34 else if (win.width >= 36) 18 else 12;
        const seconds = @divFloor(remaining + 999, 1000);
        const prefix = if (win.width >= 55) try std.fmt.allocPrint(self.frame.allocator(), " Sending in {d}s · nothing sent yet", .{seconds}) else if (win.width >= 36) try std.fmt.allocPrint(self.frame.allocator(), " Sending in {d}s", .{seconds}) else try std.fmt.allocPrint(self.frame.allocator(), " Sending {d}s", .{seconds});
        try self.line(bar.child(.{ .width = @min(prefix_width, bar.width) }), 0, prefix, .selected);
        const x = try self.actionButton(bar, 0, prefix_width, if (win.width >= 70) "[Undo Ctrl+Z]" else "[Undo]", self.grace_focus == 0, true, .dialog_action, 0);
        _ = try self.actionButton(bar, 0, x, if (win.width >= 70) "[Send now Ctrl+S]" else "[Send now]", self.grace_focus == 1, true, .dialog_action, 1);
        self.grace_rect = .{ .x = 0, .y = 1, .width = win.width, .height = 1 };
    }
    fn inspectDraftOperations(self: *App) !void {
        self.compose.unknown_outcome = true;
        try self.start(.draft_operations, .{ .account = self.account(), .cmd = "operation.list", .draftId = self.compose.id.value() });
    }
    fn invitationCheckUncertain(self: *App, code: []const u8) void {
        self.invitation_calendar_sync_state.set("unknown") catch {};
        self.invitation_calendar_sync_error.display(code);
        self.invitation_calendar_can_retry = true;
        self.mode = .invitation;
        self.say(true, "Status check not confirmed · C Check status · no RSVP resent", .{});
    }
    fn markUnknown(self: *App, kind: JobKind) void {
        if (kind == .send or kind == .grace_process) {
            self.compose_active = true;
            self.compose.unknown_outcome = true;
            self.review_ready = false;
            self.compose.insert_mode = false;
            self.mode = .compose;
            self.say(true, "Outcome unknown · {s} · draft kept in Drafts · :receipt checks · q keeps draft", .{if (validDiagnosticCode(self.compose.operation_error.value())) self.compose.operation_error.value() else "Unconfirmed"});
        } else {
            self.invitation_unknown = true;
            self.mode = .browse;
            self.say(true, "RSVP outcome unknown · {s} · operation {s} · inspect before retrying", .{ if (self.invitation_operation_error.value().len > 0) self.invitation_operation_error.value() else "Unconfirmed", self.invitation_operation_id.value()[0..@min(self.invitation_operation_id.value().len, 64)] });
        }
        self.status_kind = .unknown;
        self.diagnostic("UnknownOutcome");
    }
    fn reviewInvitation(self: *App) !void {
        if (!self.capabilities.invitations) return error.InvitationsUnavailable;
        const target = try self.allocator.dupe(u8, self.readerReplyId());
        defer self.allocator.free(target);
        if (target.len == 0) return;
        self.preemptReaderAction();
        if (self.job.future != null) {
            self.say(false, "Wait for the current change to finish", .{});
            return;
        }
        try self.invitation_inspected_id.set(self.allocator, target);
        try self.invitation_inspected_account.set(self.allocator, self.account());
        self.invitation_scroll = 0;
        self.invitation_confirm_ready = false;
        try self.start(.invitation_inspect, .{ .account = self.invitation_inspected_account.value(), .cmd = "invitation.inspect", .messageId = self.invitation_inspected_id.value() });
    }
    fn openCurrentMail(self: *App) !void {
        if (!self.capabilities.open_urls) return error.LinksUnavailable;
        const id = if (self.mode == .compose and self.compose.original != null) self.compose.original.?.sourceMessageId else if (self.mode == .compose and self.compose_original and self.reader_card < self.thread.len) text(get(self.thread[self.reader_card], "id")) else self.readerReplyId();
        const target = try self.allocator.dupe(u8, id);
        defer self.allocator.free(target);
        if (target.len == 0) {
            self.say(false, "Choose a message to open in Gmail", .{});
            return;
        }
        self.preemptReaderAction();
        if (self.job.future != null) {
            self.say(false, "Wait for the current change to finish", .{});
            return;
        }
        try self.start(.open, .{ .account = self.account(), .cmd = "mail.open", .messageId = target });
    }
    fn loadContacts(self: *App, query_in: []const u8) !void {
        try self.prepareContacts(query_in);
        if (self.job.future != null and self.job.kind == .refresh and self.job.waiting_external.load(.acquire)) {
            const pending = self.pending_contacts;
            const local = self.pending_cached_contacts;
            self.preemptReadOnly();
            self.pending_contacts = pending;
            self.pending_cached_contacts = local;
        }
        if (self.job.future == null) try self.dispatchPending();
    }
    fn contactsOpen(self: *const App) bool {
        return self.mode == .contacts or self.mode == .contact_edit or ((self.mode == .search or self.mode == .help) and self.previous_mode == .contacts);
    }
    fn replaceContacts(self: *App, response: []const u8, cached_view: bool) !void {
        var replacement: std.heap.ArenaAllocator = .init(self.allocator);
        defer replacement.deinit();
        const result = try self.data(replacement.allocator(), response);
        const contacts = items(get(result, "contacts"));
        if (contacts.len > 1024) return error.ContactListTooLarge;
        const warning_value = get(result, "contactWarnings");
        const warnings: types.ContactReadWarnings = if (warning_value == .null) .{} else try @import("json.zig").decode(types.ContactReadWarnings, replacement.allocator(), warning_value);
        const previous = self.contact_arena;
        self.contact_arena = replacement;
        replacement = previous;
        self.contacts = contacts;
        self.contacts_warnings = warnings;
        self.contacts_selected = @min(self.contacts_selected, contacts.len -| 1);
        self.contacts_cache_ready = !cached_view or truth(get(result, "cacheReady"));
        self.contacts_state = if (cached_view and self.contacts_cache_ready) .cached else if (cached_view) .loading else .current;
    }
    fn cachedContacts(self: *App) !void {
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        defer arena.deinit();
        const response = self.cached(arena.allocator(), .{ .account = self.contacts_account.value(), .cmd = if (self.contacts_query.value().len == 0) "contacts.list" else "contacts.search", .query = self.contacts_query.value() }) catch |err| {
            if (err == error.PermissionDenied) {
                self.contacts_state = .denied;
                self.pending_contacts = false;
                self.pending_cached_contacts = false;
                self.say(true, "Contacts permission required · contacts-read", .{});
                return;
            }
            if (err == error.CacheBusy) {
                self.contacts_state = .busy;
                self.pending_cached_contacts = true;
                self.say(false, "Cache busy · contacts retry locally", .{});
                return;
            }
            self.contacts_state = .failed;
            self.pending_contacts = false;
            return err;
        };
        self.pending_cached_contacts = false;
        if (response) |bytes| try self.replaceContacts(bytes, true);
        self.pending_contacts = true;
        self.say(false, "{s}", .{if (self.contacts_cache_ready) "Cached contacts · refresh queued" else "Loading contacts · request queued"});
    }
    fn prepareContacts(self: *App, query_in: []const u8) !void {
        if (self.job.future != null and self.job.kind == .cached_search) self.preemptReadOnly();
        if (query_in.len > 4096) return error.InvalidQuery;
        try self.contacts_query.set(self.allocator, query_in);
        try self.contacts_account.set(self.allocator, self.account());
        self.contacts_generation +%= 1;
        self.contacts_selected = 0;
        self.contacts = &.{};
        _ = self.contact_arena.reset(.retain_capacity);
        self.contacts_warnings = .{};
        self.contacts_cache_ready = false;
        self.contacts_state = .loading;
        self.pending_contacts = false;
        self.pending_cached_contacts = false;
        self.mode = .contacts;
        try self.cachedContacts();
    }
    fn leaveContacts(self: *App) void {
        self.picker_replace_token = false;
        self.contacts_generation +%= 1;
        self.pending_contacts = false;
        self.pending_cached_contacts = false;
        self.mode = backMode(.contacts, .browse, self.picker);
    }
    fn restrictContactViews(self: *App, index: usize, address: []const u8) void {
        // These bounded views can outlive the account currently on screen.
        // Revoke by their owner, including when permission changes elsewhere.
        if (same(self.contacts_account.value(), address)) {
            self.contacts = &.{};
            _ = self.contact_arena.reset(.free_all);
            self.contacts_warnings = .{};
            self.contacts_cache_ready = false;
            self.contacts_state = .denied;
            self.pending_contacts = false;
            self.pending_cached_contacts = false;
            self.contacts_generation +%= 1;
        }
        if (same(self.recipient_account.value(), address)) {
            self.recipient_values = &.{};
            self.recipient_ready = false;
            if (self.recipient_arena) |*arena| arena.deinit();
            self.recipient_arena = null;
        }
        if (index < self.recipient_refreshed.len) self.recipient_refreshed[index] = false;
        if (same(self.pending_contact_account.value(), address)) self.clearContactComposeIntent();
        if (self.ux_overlay == .contact_addresses and same(self.ux_account.value(), address)) self.closeUx();
        if (index < self.accounts.len and self.accounts[index] == .object and same(text(get(self.accounts[index], "address")), address)) {
            if (self.accounts[index].object.getPtr("capabilities")) |capabilities| if (capabilities.* == .array) {
                var retained: usize = 0;
                for (capabilities.array.items) |capability| {
                    if (same(text(capability), "contacts-read") or same(text(capability), "contacts-write")) continue;
                    capabilities.array.items[retained] = capability;
                    retained += 1;
                }
                capabilities.array.items.len = retained;
            };
        }
        if (index == self.account_index) {
            self.contacts_state = .denied;
            self.pending_contacts = false;
            self.pending_cached_contacts = false;
            self.pending_recipient_refresh = false;
            self.pending_recipient_cache = self.compose_active;
        }
    }
    fn readOnlyJob(kind: JobKind) bool {
        return switch (kind) {
            .follow_up_list, .calendar_guest_contacts, .calendar_list, .calendar_agenda, .calendar_event, .calendar_plan, .calendar_review, .calendar_event_edit, .calendar_event_review, .calendar_event_pending, .updates_load, .updates_check, .meeting_calendars, .meeting_agenda => true,
            .draft_measure, .refresh, .list, .cached_search, .recipient_cache, .recipient_refresh, .read, .thread, .drafts, .draft_read, .draft_operations, .queue_inspect, .contacts, .invitation_inspect, .identities, .autosave, .labels_list, .label_receipt, .triage_scope, .label_state, .unread_navigation => true,
            else => false,
        };
    }
    fn preemptReadOnly(self: *App) void {
        if (self.cancelMeetingRead()) return;
        if (self.job.future == null or !readOnlyJob(self.job.kind)) return;
        const index = self.job.account_index;
        if (self.job.kind == .draft_measure) self.requestComposeMeasure();
        const refresh = self.job.kind == .refresh;
        if (self.calendar.open and self.job.kind == .calendar_agenda and self.calendar.source_loading) {
            self.calendar.resume_sources = true;
            self.calendar.source_cursor -|= 1;
        }
        if (self.calendar.open and self.job.kind == .calendar_list) {
            self.calendar.resume_lists = true;
            if (self.calendar.listing_all) self.calendar.list_cursor -|= 1;
        }
        self.cancelJob();
        if (refresh) {
            self.sync[index].state = if (self.sync[index].cache_ready) .cached else .failed;
            self.sync[index].error_len = 0;
        }
    }
    fn clearSearch(self: *App) !bool {
        if (self.query.value().len == 0) return false;
        try self.query.set(self.allocator, "");
        self.query_scope = .cache;
        self.input_query_scope = .cache;
        try self.cursor.set(self.allocator, "");
        self.clearHistory();
        self.generation +%= 1;
        if (self.search_saved_valid and same(self.search_saved_account.value(), self.account())) {
            self.folder = self.search_saved_folder;
            try self.custom_label.set(self.allocator, self.search_saved_label.value());
            self.selected = self.search_saved_selected;
            self.top = self.search_saved_top;
            self.focus = self.search_saved_focus;
            self.expanded = self.search_saved_expanded;
            try self.restore_message.set(self.allocator, self.search_saved_message.value());
            self.restore_reader_scroll = self.search_saved_scroll;
            self.restore_reader_thread = self.search_saved_thread;
            self.search_restore_pending = true;
        } else {
            self.selected = 0;
            self.top = 0;
        }
        self.search_saved_valid = false;
        return true;
    }
    fn browseBack(self: *App) !void {
        if (self.follow_ups_list and self.job.future != null and !readOnlyJob(self.job.kind)) return error.OperationPending;
        if (self.follow_ups_list and self.focus != .reader and !self.expanded) {
            self.follow_ups_list = false;
            self.generation +%= 1;
            try self.restoreWorkingContext();
            return self.reloadWithRefresh(false);
        }
        if (self.expanded) {
            self.expanded = false;
            return;
        }
        if (self.focus != .list) {
            self.focus = .list;
            return;
        }
        if (try self.clearSearch()) {
            try self.reload();
            return;
        }
        if (self.job.future != null and !readOnlyJob(self.job.kind)) {
            self.say(true, "Operation pending · wait for its result", .{});
            return;
        }
        if (self.capabilities.quit) self.quit = true else self.say(false, "Mail retained in this session · close the tab to exit", .{});
    }
    fn editContact(self: *App, contact: ?Value) !void {
        if (!self.capabilities.contacts_write) return error.ContactWritesUnavailable;
        const value_in: Value = contact orelse .null;
        if (value_in != .null and get(value_in, "readWarnings") != .null) {
            var scratch: std.heap.ArenaAllocator = .init(self.allocator);
            defer scratch.deinit();
            const warnings = try @import("json.zig").decode(types.ContactReadWarnings, scratch.allocator(), get(value_in, "readWarnings"));
            if (warnings.any()) return error.IncompleteContact;
        }
        if (self.contact_snapshot) |*arena| arena.deinit();
        self.contact_snapshot = .init(self.allocator);
        const owned = self.contact_snapshot.?.allocator();
        const serialized = try std.json.Stringify.valueAlloc(owned, value_in, .{});
        self.contact_original = try std.json.parseFromSliceLeaky(Value, owned, serialized, .{ .allocate = .alloc_always });
        try self.contact_name.set(self.allocator, text(get(value_in, "name")));
        const emails = items(get(value_in, "emails"));
        _ = emails;
        const addresses = try Compose.mailboxes(self.allocator, get(value_in, "emails"));
        defer self.allocator.free(addresses);
        try self.contact_email.set(self.allocator, addresses);
        try self.contact_id.set(self.allocator, text(get(value_in, "resourceName")));
        try self.contact_etag.set(self.allocator, text(get(value_in, "etag")));
        self.contact_field = 0;
        self.mode = .contact_edit;
        self.say(false, "Edit contact · Tab Field · Ctrl+S Save · Esc Cancel", .{});
    }
    fn saveContact(self: *App) !void {
        if (!self.capabilities.contacts_write) return error.ContactWritesUnavailable;
        try recipients.validateHeader(self.contact_name.value());
        self.preemptReadOnly();
        var arena: std.heap.ArenaAllocator = .init(self.allocator);
        defer arena.deinit();
        const addresses = try Compose.addresses(arena.allocator(), self.contact_email.value());
        if (addresses.len == 0) return error.InvalidContact;
        const provider = get(self.contact_original, "provider");
        try self.start(.contact_write, .{
            .account = self.account(),
            .cmd = "contacts.upsert",
            .contact = types.Contact{ .name = self.contact_name.value(), .resourceName = self.contact_id.value(), .etag = self.contact_etag.value(), .emails = addresses, .provider = if (provider != .null) provider else null },
            .expectedEtag = self.contact_etag.value(),
        });
    }
    fn movePage(self: *App, down: bool, half: bool) !void {
        if (self.focus != .list) return self.move(down, @max(self.vx.window().height / 2, 1));
        const amount = @max(self.mail_page_size / @as(usize, if (half) 2 else 1), 1);
        const selected_before = self.selected;
        const top_before = self.top;
        const generation_before = self.generation;
        try self.move(down, amount);
        // Move the viewport with the selection. A cache-window transition
        // owns its new position; never apply an old window's offset to it.
        if (self.generation != generation_before or self.selected == selected_before) return;
        const moved = if (down) self.selected -| selected_before else selected_before -| self.selected;
        self.top = if (down) @min(top_before +| moved, self.messages.len -| self.mail_page_size) else top_before -| moved;
    }
    fn sidebarNavigation(self: *App) layout.Sidebar {
        return .{ .accounts = self.accounts.len, .folders = folders.len, .labels = self.capabilities.mail_changes, .user_labels = self.userLabelCount(), .native = !browser_target };
    }
    fn calendarNavigationIndex(self: *App) usize {
        return self.sidebarNavigation().calendar();
    }
    fn focusMailPane(self: *App, focus: Focus) void {
        self.focus = focus;
        if (focus == .navigation) self.navigation = self.sidebarNavigation().clamp(self.navigation);
    }
    fn move(self: *App, down: bool, amount: usize) !void {
        if (self.focus == .reader) {
            self.scrollReader(down, amount);
        } else if (self.focus == .navigation) {
            self.navigation = self.sidebarNavigation().step(self.navigation, down, amount);
        } else {
            if (self.pageLoadCurrent()) {
                if (down == self.page_loading_forward) return;
                self.preemptReadOnly();
            }
            const previous = self.selected;
            if (self.pending_page and down != self.pending_page_forward) self.pending_page = false;
            if (down and self.messages.len > 0 and previous +| amount >= self.messages.len and (!self.drafts_list or self.next_cursor.value().len > 0) and !self.follow_ups_list) {
                try self.scrollWindow(true);
                return;
            }
            if (!down and self.messages.len > 0 and amount > previous and (!self.drafts_list or self.previous_cursor.value().len > 0 or self.previous_cursors.items.len > 0) and !self.follow_ups_list) {
                try self.scrollWindow(false);
                return;
            }
            self.selected = if (down) @min(self.selected +| amount, self.messages.len -| 1) else self.selected -| amount;
            self.selection_generation +%= 1;
            try self.preview(false);
        }
    }
    fn adjacentMail(self: *App, next: bool) !void {
        if (self.drafts_list or self.messages.len == 0) return;
        const selected = layout.stepMessage(self.messages.len, self.selected, next);
        if (selected == self.selected) {
            self.focus = .reader;
            if (self.follow_ups_list) return;
            try self.scrollWindow(next);
            return;
        }
        self.selected = selected;
        self.selection_generation +%= 1;
        self.reader_scroll = 0;
        self.reader_card_pinned = false;
        self.focus = .reader;
        // Mail navigation shares cache-relative windows with the list; braces
        // remain the separate within-thread card navigation.
        try self.preview(false);
    }
    fn enter(self: *App) !void {
        if (self.focus == .navigation) {
            const sidebar = self.sidebarNavigation();
            self.navigation = sidebar.clamp(self.navigation);
            if (!browser_target and self.navigation == self.calendarNavigationIndex()) return self.openCalendar(false);
            if (!browser_target and self.navigation == self.calendarNavigationIndex() + 1) return self.openFollowUps();
            if (self.navigation < self.accounts.len) try self.chooseAccount(self.navigation) else if (self.navigation < self.accounts.len + folders.len) {
                self.rememberWorkingContext();
                try self.custom_label.set(self.allocator, "");
                self.folder = self.navigation - self.accounts.len;
                self.clearHistory();
                try self.cursor.set(self.allocator, "");
                self.selected = 0;
                self.top = 0;
                self.generation +%= 1;
                self.focus = .list;
                try self.reload();
            } else if (self.navigation == self.accounts.len + folders.len) {
                self.picker = false;
                try self.loadContacts("");
            } else if (sidebar.labels and self.navigation == sidebar.labelsHeader()) {
                try self.openLabelManager();
            } else if (sidebar.labels and self.navigation >= sidebar.labelsStart()) {
                if (self.userLabelIndex(self.navigation - sidebar.labelsStart())) |index| try self.chooseCustomLabel(index);
            }
        } else if (self.focus == .reader and self.reader_card < self.thread.len and self.retryableReaderBody()) {
            const id = text(get(self.thread[self.reader_card], "id"));
            if (id.len == 0) return error.MessageRequired;
            self.preemptReadOnly();
            try self.start(.read, .{ .account = self.account(), .cmd = "mail.read", .messageId = id });
        } else if (self.follow_ups_list) {
            self.focus = .reader;
            if (self.job.future != null and self.job.kind == .refresh) self.preemptReadOnly();
            if (self.messageId().len > 0) try self.start(.read, .{ .account = self.account(), .cmd = "mail.read", .messageId = self.messageId() });
        } else if (self.drafts_list) {
            if (self.messageId().len > 0) try self.start(.draft_read, .{ .account = self.account(), .cmd = "draft.read", .draftId = self.messageId() });
        } else {
            self.focus = .reader;
            try self.preview(true);
        }
    }
    fn retryableReaderBody(self: *const App) bool {
        if (self.reader_card >= self.thread.len) return false;
        const message = self.thread[self.reader_card];
        const code = text(get(message, "bodyCacheError"));
        return same(code, "BodyNotCached") or same(code, "ThreadBodyBudgetExceeded");
    }
    fn activateContact(self: *App) !void {
        if (self.contacts_selected >= self.contacts.len or self.contacts_state == .denied) return;
        if (!self.picker and self.capabilities.contacts_write) return self.editContact(self.contacts[self.contacts_selected]);
        self.picker = self.compose_active;
        const emails = items(get(self.contacts[self.contacts_selected], "emails"));
        if (emails.len > 1) {
            try self.beginUx(.contact_addresses, " Choose contact address ");
            const name = text(get(self.contacts[self.contacts_selected], "name"));
            for (emails, 0..) |email, index| {
                const display = try recipients.formatDisplay(self.ux_arena.?.allocator(), text(get(email, "address")), name);
                try self.uxRow(.{ .label = display, .value = display, .index = index });
            }
            return;
        }
        if (emails.len > 0) {
            const address = text(get(emails[0], "address"));
            try recipients.validateAddress(address);
            const display = try recipients.formatDisplay(self.allocator, address, text(get(self.contacts[self.contacts_selected], "name")));
            defer self.allocator.free(display);
            try self.useContactAddress(display);
        }
    }
    fn clearContactComposeIntent(self: *App) void {
        self.pending_contact_address.deinit(self.allocator);
        self.pending_contact_account.deinit(self.allocator);
        self.pending_contact_generation = 0;
    }
    fn useContactAddress(self: *App, display: []const u8) !void {
        if (!self.compose_active) {
            try self.composeNew(null);
            errdefer self.clearContactComposeIntent();
            try self.pending_contact_address.set(self.allocator, display);
            try self.pending_contact_account.set(self.allocator, self.account());
            self.pending_contact_generation = self.generation;
            return;
        }
        const target = &self.compose.fields[if (self.compose.selected < 3) self.compose.selected else 0];
        target.undo_enabled = true;
        if (self.picker_replace_token) {
            const range = completion.token(target.value(), target.cursor);
            const updated = try std.fmt.allocPrint(self.allocator, "{s}{s}{s}", .{ target.value()[0..range.start], display, target.value()[range.end..] });
            defer self.allocator.free(updated);
            if (updated.len > mail_limits.header_value_bytes) return error.InputTooLarge;
            const suffix = target.value().len - range.end;
            try target.history.record(self.allocator, target.value(), target.cursor);
            try target.assign(self.allocator, updated);
            target.cursor = updated.len - suffix;
        } else {
            target.cursor = target.value().len;
            if (target.value().len > 0) try target.insert(self.allocator, ", ", mail_limits.header_value_bytes);
            try target.insert(self.allocator, display, mail_limits.header_value_bytes);
        }
        self.picker_replace_token = false;
        try self.composerChanged();
        self.completion_open = false;
        self.completion_dismissed = true;
        self.leaveContacts();
    }
    fn onMouse(self: *App, mouse: vaxis.Mouse) !void {
        if (!self.options.no_mouse and mouse.type == .press) _ = self.cancelMeetingRead();
        if (try self.onMeetingMouse(mouse)) return;
        if (try self.onReaderCopyMouse(mouse)) return;
        if (self.grace_active) {
            if (!self.options.no_mouse and mouse.type == .press and mouse.button == .left and !mouse.mods.shift and !mouse.mods.alt and !mouse.mods.ctrl) if (self.grace_rect) |rect| if (mouse.col >= rect.x and mouse.col < rect.x + rect.width and mouse.row >= rect.y and mouse.row < rect.y + rect.height) {
                if (self.mouse_hits.at(mouse.col, mouse.row)) |hit| {
                    if (hit.kind == .dialog_action and hit.index == 1) {
                        try self.processGrace(true);
                        return;
                    }
                }
                try self.cancelGrace(false);
            };
            return;
        }
        if (!self.options.no_mouse and mouse.type == .press and !mouse.mods.shift and !mouse.mods.alt and !mouse.mods.ctrl) {
            if (self.update_open) {
                self.acknowledgeNewMail();
                if (mouse.button == .wheel_down) self.update_scroll = @min(self.update_scroll +| 3, self.update_lines -| self.update_height) else if (mouse.button == .wheel_up) self.update_scroll -|= 3 else if (mouse.button == .left) {
                    if (self.mouse_hits.at(mouse.col, mouse.row)) |hit| {
                        if (hit.kind == .dialog_action and hit.index >= 400 and hit.index < 407) {
                            self.update_focus = hit.index - 400;
                            try self.activateUpdate(self.update_focus);
                        }
                    }
                }
                return;
            }
            if (mouse.button == .left and self.updateVisible()) {
                if (self.mouse_hits.at(mouse.col, mouse.row)) |hit| {
                    if (hit.kind == .dialog_action and (hit.index == 300 or hit.index == 301)) {
                        self.acknowledgeNewMail();
                        try self.activateUpdateCard(hit.index - 300);
                        return;
                    }
                }
                if (self.update_rect) |rect| if (mouse.col >= rect.x and mouse.col < rect.x + rect.width and mouse.row >= rect.y and mouse.row < rect.y + rect.height) {
                    self.acknowledgeNewMail();
                    return;
                };
            }
        }
        if (mouse.type == .press and self.job.future != null and updateJob(self.job.kind)) self.preemptReadOnly();
        if (mouse.type == .press) {
            const notice = self.notice_rect;
            self.acknowledgeNewMail();
            if (notice) |rect| if (mouse.col >= rect.x and mouse.col < rect.x + rect.width and mouse.row >= rect.y and mouse.row < rect.y + rect.height) return;
        }
        self.action_notice = false;
        if (self.options.no_mouse or mouse.type != .press or mouse.mods.shift or mouse.mods.alt or mouse.mods.ctrl) return;
        const wheel: ?bool = switch (mouse.button) {
            .wheel_down => true,
            .wheel_up => false,
            .left => null,
            else => return,
        };
        if (self.calendar.open) {
            if (self.calendar_guests_open) return self.onCalendarGuestsMouse(mouse, wheel);
            if (self.calendarHelpVisible()) {
                if (wheel) |down| self.help_scroll = if (down) @min(self.help_scroll +| 3, self.help_lines -| self.help_height) else self.help_scroll -| 3 else if (self.mouse_hits.at(mouse.col, mouse.row)) |hit| {
                    if (hit.kind == .dialog_action and hit.index == 0) self.closeHelp();
                }
                return;
            }
            if (wheel) |down| {
                for (0..3) |_| try self.onCalendarKey(.{ .codepoint = if (down) 'j' else 'k' });
            } else if (self.mouse_hits.at(mouse.col, mouse.row)) |hit| {
                if (hit.kind == .dialog_action) {
                    try self.calendarActivate(hit.index);
                } else if (hit.kind == .calendar_week_event and self.calendar.page == .main) {
                    if (hit.index >= self.calendar_week_title_count) return;
                    const target = self.calendar_week_title_hits[hit.index];
                    self.calendar.selected = target.index;
                    self.calendar.week_reveal_selected = true;
                    self.calendar_week_reveal_bucket = target.bucket;
                    try self.calendarActivate(10);
                } else if (hit.kind == .contact) {
                    if (self.calendar.page == .calendars) {
                        self.calendar.picker = hit.index;
                        if (self.calendar.source_message.len == 0) try self.calendarToggleSource() else try self.selectCalendar(hit.index);
                    } else if (self.calendar.page == .overlaps) {
                        if (hit.index >= self.calendar_slots.events.len) return;
                        self.calendar_slots_selected = hit.index;
                        self.calendar_slots_drawn = try calendar_slot.Identity.init(self.calendar_slots.events[hit.index]);
                        try self.calendarSlotsChoose();
                    } else {
