            self.job.future.?.await(self.io);
            try self.finish();
        }
    }
    fn previewControlOrder(index: usize) usize {
        return switch (index) {
            3, 4 => index + 2,
            5, 6 => index - 2,
            else => index,
        };
    }
    fn onComposePreviewKey(self: *App, key: Key) !void {
