            const field = &self.compose.fields[self.compose.selected];
            if (field.recordUndo(self.allocator, field.value().len)) {
                self.paste_history_field = self.compose.selected;
                field.undo_enabled = false;
            } else |_| {}
        }
        self.paste = true;
    }
    fn pasteEnd(self: *App) void {
