        if (self.mode == .attachment and key.matches('u', .{ .ctrl = true })) {
            self.path_candidates.reset();
            return self.input.set(self.allocator, "");
        }
        if (self.mode == .search and self.previous_mode != .contacts and key.matches('g', .{ .ctrl = true })) {
            self.input_query_scope = if (self.input_query_scope == .cache) .server else .cache;
            self.say(false, "{s}", .{if (self.input_query_scope == .cache) @as([]const u8, "Search downloaded mail · Ctrl+G switches to Gmail") else "Search Gmail · Enter runs the query online"});
            return;
        }
        if (self.mode == .search or self.mode == .command or self.mode == .labels or self.mode == .attachment) {
            if (key.matches(Key.escape, .{})) self.mode = self.previous_mode else if (key.matches(Key.enter, .{})) {
                const previous_mode = self.previous_mode;
                if (self.mode == .attachment) {
                    try self.attachFile(self.input.value());
                } else if (self.mode == .command) {
                    if (same(self.input.value(), "theme") and previous_mode == .browse) {
                        self.openThemePicker();
                    } else if (same(self.input.value(), "undo") and previous_mode == .browse) {
                        try self.undoMail();
                    } else if (try self.onReaderCommand(self.input.value())) {} else if (same(self.input.value(), "layout right")) {
                        self.setReaderLayout(.right);
                    } else if (same(self.input.value(), "layout below")) {
                        self.setReaderLayout(.below);
                    } else if (std.mem.startsWith(u8, self.input.value(), "save-attachment ") or std.mem.startsWith(u8, self.input.value(), "save-attachment\t")) {
                        try self.saveIncomingAttachment(self.input.value()[16..]);
                    } else if (same(self.input.value(), "receipt") and previous_mode == .compose) {
                        try self.inspectDraftOperations();
                    } else if (same(self.input.value(), "send") and previous_mode == .compose) try self.saveDraft(.save_review) else if (std.mem.startsWith(u8, self.input.value(), "detach ") and previous_mode == .compose) {
                        const number = try std.fmt.parseInt(usize, std.mem.trim(u8, self.input.value()[7..], " \t"), 10);
                        if (number == 0) return error.InvalidAttachment;
                        try self.detachAttachment(number - 1);
                    } else if (same(self.input.value(), "q")) {
                        self.mode = previous_mode;
                        if (previous_mode == .compose) try self.saveDraft(.save_back) else if (previous_mode == .contacts) self.leaveContacts() else {
                            self.mode = .browse;
                            try self.browseBack();
                        }
                    } else self.say(true, "Commands: :theme; :layout right|below; :save-attachment NUMBER /path; :send; :detach NUMBER; :q", .{});
                    if (self.mode == .command) self.mode = previous_mode;
                } else if (self.mode == .labels) {
                    const raw_label = std.mem.trim(u8, self.input.value(), " \t");
                    if (raw_label.len == 0 or (raw_label.len == 1 and raw_label[0] == '-')) return error.InvalidLabel;
                    const remove = raw_label[0] == '-';
                    const labels = [_][]const u8{if (remove) raw_label[1..] else raw_label};
                    if (remove) try self.start(.mutation, .{ .account = self.account(), .cmd = "mail.mark", .messageId = self.messageId(), .removeLabels = &labels }) else try self.start(.mutation, .{ .account = self.account(), .cmd = "mail.mark", .messageId = self.messageId(), .addLabels = &labels });
                    self.mode = .browse;
                } else if (previous_mode == .contacts) try self.loadContacts(self.input.value()) else {
                    const retain_cached_view = self.view_ready and self.input_query_scope == .cache and cache_query.needsBody(self.input.value());
                    try self.query.set(self.allocator, self.input.value());
                    self.query_scope = self.input_query_scope;
                    self.rememberSearch();
                    self.clearHistory();
                    try self.cursor.set(self.allocator, "");
                    self.generation +%= 1;
                    if (!retain_cached_view) {
                        self.selected = 0;
                        self.top = 0;
                    }
                    self.focus = .list;
                    self.expanded = false;
                    self.mode = .browse;
                    try self.reload();
                }
            } else try self.input.handleKey(self.allocator, key, false, 4096);
            return;
        }
        if (self.mode == .contacts) {
            if (key.matches('r', .{ .ctrl = true })) return self.loadContacts(self.contacts_query.value());
            if (key.matches(Key.escape, .{}) or key.matches('q', .{})) self.leaveContacts() else if (key.matches('j', .{}) or key.matches(Key.down, .{})) self.contacts_selected = @min(self.contacts_selected +| 1, self.contacts.len -| 1) else if (key.matches('k', .{}) or key.matches(Key.up, .{})) self.contacts_selected -|= 1 else if (key.matches(Key.home, .{}) or key.matches('g', .{ .ctrl = true })) self.contacts_selected = 0 else if (key.matches(Key.end, .{})) self.contacts_selected = self.contacts.len -| 1 else if (key.matches('d', .{ .ctrl = true }) or key.matches(Key.page_down, .{})) self.contacts_selected = @min(self.contacts_selected +| 8, self.contacts.len -| 1) else if (key.matches('u', .{ .ctrl = true }) or key.matches(Key.page_up, .{})) self.contacts_selected -|= 8 else if (key.matches('/', .{})) {
                self.previous_mode = .contacts;
                self.mode = .search;
                try self.input.set(self.allocator, "");
            } else if (key.matches('n', .{}) and self.contacts_state != .denied) try self.editContact(null) else if (key.matches('e', .{}) and self.contacts_selected < self.contacts.len and self.contacts_state != .denied) try self.editContact(self.contacts[self.contacts_selected]) else if (key.matches(Key.enter, .{}) and self.contacts_selected < self.contacts.len) try self.activateContact();
            return;
        }
        if (self.mode == .browse and key.matches('v', .{})) {
            self.setReaderLayout(if (self.reader_layout == .right) .below else .right);
            return;
        }
        if (self.mode == .browse and (self.focus == .reader or self.expanded)) {
            if (key.matches('J', .{}) or key.matches('j', .{ .shift = true })) return self.adjacentMail(true);
            if (key.matches('K', .{}) or key.matches('k', .{ .shift = true })) return self.adjacentMail(false);
        }
        const now = Io.Timestamp.now(self.io, .awake).toMilliseconds();
        if (self.g_pending and now - self.g_at > 750) self.g_pending = false;
        if (try self.onReaderKey(key)) return;
        if (try self.onMailControls(key)) return;
        if (key.matches('f', .{}) or key.matches('F', .{}) or key.matches('f', .{ .shift = true })) return self.composeForward();
        if (key.matches('g', .{})) {
            if (self.g_pending) {
                self.g_pending = false;
                if (self.expanded and self.focus == .reader) self.reader_scroll = 0 else try self.jumpFirstMail();
            } else {
                self.g_pending = true;
                self.g_at = now;
            }
            return;
        }
        self.g_pending = false;
        if (key.matches('j', .{}) or key.matches(Key.down, .{})) try self.move(true, 1) else if (key.matches('k', .{}) or key.matches(Key.up, .{})) try self.move(false, 1) else if (key.matches('d', .{ .ctrl = true }) or key.matches(Key.page_down, .{})) try self.movePage(true, key.mods.ctrl) else if (key.matches('u', .{ .ctrl = true }) or key.matches(Key.page_up, .{})) try self.movePage(false, key.mods.ctrl) else if (key.matches('h', .{}) or key.matches(Key.left, .{})) self.focusMailPane(switch (self.focus) {
            .navigation => .navigation,
            .list => .navigation,
            .reader => .list,
        }) else if (key.matches(Key.tab, .{ .shift = true })) self.focusMailPane(switch (self.focus) {
            .navigation => .reader,
            .list => .navigation,
            .reader => .list,
        }) else if (key.matches('l', .{}) or key.matches(Key.right, .{}) or key.matches(Key.tab, .{})) self.focusMailPane(switch (self.focus) {
            .navigation => .list,
            .list => .reader,
            .reader => .navigation,
        }) else if (key.matches(Key.enter, .{})) try self.enter() else if (key.matches('G', .{}) or key.matches('g', .{ .shift = true }) or key.matches(Key.end, .{})) {
            if (self.focus == .reader) self.reader_scroll = readerEnd(self.reader_lines, self.reader_height) else {
                self.selected = self.messages.len -| 1;
                self.selection_generation +%= 1;
                try self.preview(false);
            }
        } else if (key.matches(Key.home, .{})) {
            if (self.focus == .reader) self.scrollReader(false, std.math.maxInt(usize)) else {
                self.selected = 0;
                self.top = 0;
                self.reader_scroll = 0;
                self.selection_generation +%= 1;
                try self.preview(false);
            }
        } else if (key.matches('[', .{})) try self.page(false) else if (key.matches(']', .{})) try self.page(true) else if (key.matches('/', .{})) {
            try self.beginSearch(.cache);
        } else if (key.matches('\\', .{})) {
            try self.beginSearch(.server);
        } else if (key.matches(':', .{})) {
            self.previous_mode = .browse;
            self.mode = .command;
            try self.input.set(self.allocator, "");
        } else if (key.matches('c', .{})) try self.composeNew(null) else if (key.matches('r', .{})) try self.composeNew(false) else if (key.matches('R', .{}) or key.matches('r', .{ .shift = true })) try self.composeNew(true) else if (key.matches('a', .{})) {
            self.picker = false;
            try self.loadContacts("");
        } else if (key.matches('C', .{}) or key.matches('c', .{ .shift = true })) {
            try self.openCalendar(false);
        } else if (key.matches('b', .{})) {
            try self.editFollowUp();
        } else if (self.follow_ups_list and key.matches('d', .{})) {
            try self.completeFollowUp();
        } else if (key.matches('A', .{}) or key.matches('a', .{ .shift = true })) {
            try self.openCalendar(true);
        } else if (key.matches('z', .{})) {
            self.expanded = !self.expanded;
            self.focus = .reader;
        } else if (key.matches('?', .{})) {
            try self.openHelp();
        } else if (key.matches('r', .{ .ctrl = true })) {
            if (self.follow_ups_list) try self.loadFollowUps() else if (self.cacheSearch()) try self.refreshMailbox() else try self.reload();
        } else if (key.matches('x', .{}) and self.messageId().len > 0) try self.start(.mutation, .{ .account = self.account(), .cmd = "mail.archive", .messageId = self.messageId() }) else if ((key.matches('D', .{}) or key.matches('d', .{ .shift = true })) and self.messageId().len > 0) self.mode = .trash_confirm else if (key.matches('U', .{}) or key.matches('u', .{ .shift = true })) try self.start(.mutation, .{ .account = self.account(), .cmd = "mail.restore", .messageId = self.messageId() }) else if (key.matches('s', .{}) and self.messageId().len > 0) {
            var starred = false;
            for (items(get(self.selectedMessage().?, "labels"))) |label| if (same(text(label), "STARRED")) {
                starred = true;
                break;
            };
            try self.start(.mutation, .{ .account = self.account(), .cmd = "mail.mark", .messageId = self.messageId(), .starred = !starred });
        } else if (key.matches('u', .{}) and self.messageId().len > 0) try self.start(.mutation, .{ .account = self.account(), .cmd = "mail.mark", .messageId = self.messageId(), .unread = !truth(get(self.selectedMessage().?, "unread")) }) else if (key.matches('m', .{}) and self.messageId().len > 0) {
            self.previous_mode = .browse;
            self.mode = .labels;
            try self.input.set(self.allocator, "");
        } else if ((key.matches('I', .{}) or key.matches('i', .{ .shift = true })) and self.messageId().len > 0) try self.reviewInvitation() else if (key.matches('o', .{})) try self.openCurrentMail() else if (key.matches('q', .{}) or key.matches(Key.escape, .{})) {
            try self.browseBack();
        } else for (0..self.accounts.len) |index| if ((key.matches(@intCast('1' + index), .{}) or key.matches(@intCast('1' + index), .{ .ctrl = true }))) {
            try self.chooseAccount(index);
            break;
        };
    }

    fn style(self: *App, color: Tone) vaxis.Style {
        const bold = color == .subject or color == .accent or color == .selected or color == .fetching or color == .current or color == .offline;
        if (self.mono) return .{ .reverse = color == .selected, .bold = bold or color == .warning };
        return .{
            .fg = .{ .rgb = switch (color) {
                .text, .subject, .selected => self.palette.foreground,
                .muted => self.palette.muted,
                .accent => self.palette.accent,
                .warning => self.palette.red,
                .sender, .fetching => self.palette.cyan,
                .current => self.palette.green,
                .offline => self.palette.yellow,
            } },
            .bg = .{ .rgb = if (color == .selected) self.palette.selection else self.palette.background },
            .bold = bold,
        };
    }
    fn line(self: *App, win: vaxis.Window, row: usize, raw: []const u8, color: Tone) !void {
        if (row >= win.height or win.width == 0) return;
        const child = win.child(.{ .y_off = @intCast(row), .height = 1 });
        if (color == .selected) child.fill(.{ .style = self.style(.selected) });
        _ = child.printSegment(.{ .text = try self.cellLine(win, try safe(self.frame.allocator(), raw, false)), .style = self.style(color) }, .{ .wrap = .none });
    }
    fn mouseArea(self: *App, win: vaxis.Window, kind: layout.HitKind, index: usize) void {
        if (win.x_off < 0 or win.y_off < 0) return;
        self.mouse_hits.add(.{ .x = @intCast(win.x_off), .y = @intCast(win.y_off), .width = win.width, .height = win.height }, kind, index);
    }
    fn actionButton(self: *App, win: vaxis.Window, row: usize, x: u16, label: []const u8, focused: bool, enabled: bool, kind: layout.HitKind, index: usize) !u16 {
        if (row >= win.height or x >= win.width) return x;
        const width: u16 = @intCast(@min(label.len, win.width - x));
        const button = win.child(.{ .x_off = x, .y_off = @intCast(row), .width = width, .height = 1 });
        try self.line(button, 0, label, if (!enabled) .muted else if (focused) .selected else .accent);
        if (enabled) self.mouseArea(button, kind, index);
        return x + width +| @as(u16, if (win.width < 26) 1 else 2);
    }
    fn mouseRows(self: *App, win: vaxis.Window, row: usize, height: u16, kind: layout.HitKind, index: usize) void {
        if (row >= win.height) return;
        self.mouseArea(win.child(.{ .y_off = @intCast(row), .height = height }), kind, index);
    }
    fn editLine(self: *App, win: vaxis.Window, row: usize, name: []const u8, field: *const Field, editing: bool, color: Tone) !void {
        if (!editing) return self.line(win, row, try std.fmt.allocPrint(self.frame.allocator(), "{s}: {s}", .{ name, field.value() }), color);
        if (row >= win.height or win.width == 0) return;
        const child = win.child(.{ .y_off = @intCast(row), .height = 1 });
        if (color == .selected) child.fill(.{ .style = self.style(color) });
        const label = try std.fmt.allocPrint(self.frame.allocator(), "{s}: ", .{name});
        _ = child.printSegment(.{ .text = label, .style = self.style(color) }, .{ .wrap = .none });
        const label_width: u16 = @intCast(@min(label.len, child.width));
        const content = child.child(.{ .x_off = label_width, .width = child.width - label_width });
        if (content.width == 0) return;
        const before = try safe(self.frame.allocator(), field.value()[0..field.cursor], false);
        const after = try safe(self.frame.allocator(), field.value()[field.cursor..], false);
        const viewport_start = horizontalStart(content, before, content.width -| 1);
        const shown = try std.fmt.allocPrint(self.frame.allocator(), "{s}▏{s}", .{ before[viewport_start..], after });
        _ = content.printSegment(.{ .text = shown, .style = self.style(color) }, .{ .wrap = .none });
    }
    fn panel(self: *App, win: vaxis.Window, x: u16, width: u16, title: []const u8, selected_panel: bool) vaxis.Window {
        const child = win.child(.{ .x_off = x, .width = width, .border = .{ .where = .all, .style = self.style(if (selected_panel) .accent else .muted) } });
        _ = win.child(.{ .x_off = x +| 2, .width = width -| 4, .height = 1 }).printSegment(.{ .text = title, .style = self.style(if (selected_panel) .accent else .muted) }, .{ .wrap = .none });
        return child.child(.{ .x_off = 1, .width = child.width -| 2 });
    }
    fn pane(self: *App, win: vaxis.Window, rect: layout.Rect, title: []const u8, selected_panel: bool) vaxis.Window {
        const area = win.child(.{ .x_off = rect.x, .y_off = rect.y, .width = rect.width, .height = rect.height });
        return self.panel(area, 0, rect.width, title, selected_panel);
    }
    fn cellLine(self: *App, win: vaxis.Window, clean: []const u8) ![]const u8 {
        var iterator = vaxis.unicode.graphemeIterator(clean);
        var output: std.ArrayList(u8) = .empty;
        var copied: usize = 0;
        while (iterator.next()) |gr| {
            const original = gr.bytes(clean);
            const shown = text_layout.cellGrapheme(original, win.screen.width_method);
            if (same(original, shown)) continue;
            try output.appendSlice(self.frame.allocator(), clean[copied..gr.start]);
            try output.appendSlice(self.frame.allocator(), shown);
            copied = gr.start + gr.len;
        }
        if (copied == 0) return clean;
        try output.appendSlice(self.frame.allocator(), clean[copied..]);
        return output.items;
    }
    fn fitLine(self: *App, win: vaxis.Window, raw: []const u8, columns: u16) ![]const u8 {
        if (columns == 0) return "";
        const clean = try self.cellLine(win, try safe(self.frame.allocator(), raw, false));
        var iterator = vaxis.unicode.graphemeIterator(clean);
        var width: usize = 0;
        var end: usize = 0;
        while (iterator.next()) |gr| {
            width += @max(win.gwidth(gr.bytes(clean)), 1);
            if (width > columns) break;
            end = gr.start + gr.len;
        }
        if (end == clean.len) return clean;
        iterator = vaxis.unicode.graphemeIterator(clean);
        width = 0;
        end = 0;
        while (iterator.next()) |gr| {
            width += @max(win.gwidth(gr.bytes(clean)), 1);
            if (width >= columns) break;
            end = gr.start + gr.len;
        }
        return std.fmt.allocPrint(self.frame.allocator(), "{s}…", .{clean[0..end]});
    }
    fn listStyle(self: *App, tone: Tone, selected: bool) vaxis.Style {
        var result = self.style(tone);
        if (selected) {
            if (self.mono) result.reverse = true else result.bg = .{ .rgb = self.palette.selection };
        }
        return result;
    }
    fn navigationLine(self: *App, win: vaxis.Window, offset: usize, row: usize, value: []const u8, tone: Tone, kind: ?layout.HitKind, index: usize) !void {
        if (row < offset or row - offset >= win.height) return;
        try self.line(win, row - offset, value, tone);
        if (kind) |hit_kind| self.mouseRows(win, row - offset, 1, hit_kind, index);
    }
    fn navigationDraw(self: *App, win: vaxis.Window) !void {
        if (win.width <= 2 or win.height == 0) return;
        const sidebar = self.sidebarNavigation();
        if (self.focus == .navigation) self.navigation = sidebar.clamp(self.navigation);
        const account_width = win.child(.{ .width = win.width - 2 });
        var row: usize = 1;
        var selected_row: usize = 0;
        for (self.accounts, 0..) |account_value, index| {
            const address = try safe(self.frame.allocator(), text(get(account_value, "address")), false);
            if (self.navigation == index) selected_row = row;
            row += positionAfter(account_width, address).row + 1;
        }
        const mailbox_row = row + 1;
        const folders_row = mailbox_row + 1;
        const contacts_row = folders_row + folders.len + 1;
        const labels_row = contacts_row + 2 + @as(usize, if (browser_target) 0 else 2);
        if (self.navigation >= self.accounts.len and self.navigation < sidebar.contacts()) selected_row = folders_row + self.navigation - self.accounts.len;
        if (self.navigation == sidebar.contacts()) selected_row = contacts_row;
        if (!browser_target and self.navigation == sidebar.calendar()) selected_row = contacts_row + 1;
        if (!browser_target and self.navigation == sidebar.followUps()) selected_row = contacts_row + 2;
        if (sidebar.labels and self.navigation >= sidebar.labelsHeader()) selected_row = labels_row + self.navigation - sidebar.labelsHeader();
        // Scroll the same sidebar, rather than replacing it with Labels. Its
        // selected destination and matching mouse target remain visible even
        // with wrapped accounts or a short laptop terminal.
        const offset = if (self.focus == .navigation and selected_row >= win.height) selected_row - win.height + 1 else 0;
        try self.navigationLine(win, offset, 0, "ACCOUNTS", .muted, null, 0);
        row = 1;
        for (self.accounts, 0..) |account_value, index| {
            const address = try safe(self.frame.allocator(), text(get(account_value, "address")), false);
            const actual_rows = positionAfter(account_width, address).row + 1;
            defer row += actual_rows;
            if (row + actual_rows <= offset or row >= offset + win.height) continue;
            const skip = offset -| row;
            const visible_start = @max(row, offset) - offset;
            const visible_rows: u16 = @intCast(@min(actual_rows - skip, win.height - visible_start));
            const account_win = win.child(.{ .y_off = @intCast(visible_start), .height = visible_rows });
            const address_win = account_win.child(.{ .x_off = 2, .width = win.width - 2 });
            const tone: Tone = if (self.focus == .navigation and self.navigation == index) .selected else if (index == self.account_index) .accent else .text;
            if (tone == .selected) account_win.fill(.{ .style = self.style(tone) });
            if (skip == 0) try self.line(account_win, 0, if (index == self.account_index) "> " else "  ", tone);
            _ = try self.flowTone(address_win, address, skip, 0, tone);
            self.mouseRows(win, visible_start, visible_rows, .account, index);
        }
        try self.navigationLine(win, offset, mailbox_row, "MAILBOXES", .muted, null, 0);
        for (folders, 0..) |name, index| {
            const value = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}", .{ if (index == self.folder) "> " else "  ", name });
            try self.navigationLine(win, offset, folders_row + index, value, if (self.focus == .navigation and self.navigation == self.accounts.len + index) .selected else if (index == self.folder) .accent else .text, .folder, index);
        }
        try self.navigationLine(win, offset, contacts_row, "Contacts", if (self.focus == .navigation and self.navigation == sidebar.contacts()) .selected else .text, .contacts, 0);
        if (!browser_target) {
            try self.navigationLine(win, offset, contacts_row + 1, "Calendar · C", if (self.focus == .navigation and self.navigation == sidebar.calendar()) .selected else .text, .sidebar, sidebar.calendar());
            const due = self.followUpDueCount();
            const label = if (due > 0) try std.fmt.allocPrint(self.frame.allocator(), "Follow-ups · {d} due", .{due}) else "Follow-ups";
            try self.navigationLine(win, offset, contacts_row + 2, label, if (self.focus == .navigation and self.navigation == sidebar.followUps()) .selected else if (due > 0) .accent else .text, .sidebar, sidebar.followUps());
        }
        if (!sidebar.labels) return;
        try self.navigationLine(win, offset, labels_row, "LABELS ›", if (self.focus == .navigation and self.navigation == sidebar.labelsHeader()) .selected else .accent, .labels_header, 0);
        for (0..self.userLabelCount()) |choice| {
            const index = self.userLabelIndex(choice) orelse continue;
            const label_value = self.labels[index];
            const label_active = same(self.custom_label.value(), text(get(label_value, "id")));
            try self.navigationLine(win, offset, labels_row + 1 + choice, try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}", .{ if (label_active) "> " else "  ", text(get(label_value, "name")) }), if (self.focus == .navigation and self.navigation == sidebar.labelsStart() + choice) .selected else if (label_active) .accent else .text, .custom_label, index);
        }
    }
    fn navigationWidth(self: *App, win: vaxis.Window) !u16 {
        var widest: u16 = 26;
        for (self.accounts) |account_value| {
            const clean = try safe(self.frame.allocator(), text(get(account_value, "address")), false);
            var columns: u16 = 6; // Selected prefix plus panel border and padding.
            var iterator = vaxis.unicode.graphemeIterator(clean);
            while (iterator.next()) |gr| columns +|= @max(win.gwidth(gr.bytes(clean)), 1);
            widest = @max(widest, columns);
        }
        return @min(widest, 36);
    }
    fn rowHasAttachments(value: Value) bool {
        return (get(value, "attachmentCount") == .integer and integer(get(value, "attachmentCount")) > 0) or items(get(value, "attachments")).len > 0;
    }
    fn draftRowName(value: Value) []const u8 {
        const link = get(value, "gmailLink");
        if (link == .null or same(text(get(link, "phase")), "rejected")) return "Draft";
        if (same(text(get(link, "phase")), "unknown")) return "Gmail: check status";
        return if (truth(get(link, "paused"))) "In Gmail · paused" else "Gmail copy kept";
    }
    fn drawMailRow(self: *App, win: vaxis.Window, row: usize, index: usize) !void {
        if (self.follow_ups_list) return self.drawFollowUpRow(win, row, index);
        if (row >= win.height or index >= self.messages.len) return;
        const value_in = self.messages[index];
        const sender = get(value_in, "from");
        const sender_text = if (text(get(sender, "name")).len > 0) text(get(sender, "name")) else text(get(sender, "address"));
        const selected = index == self.selected;
        if (self.ui_preferences.density == .compact) {
            const item = win.child(.{ .y_off = @intCast(row), .height = 1 });
            self.mouseArea(item, .mail, index);
            item.fill(.{ .style = self.style(if (selected) .selected else .text) });
            const stamp = try timestamp(self.frame.allocator(), &self.zone, get(value_in, "receivedAt"));
            const date = if (stamp.len >= 16) stamp[5..16] else stamp;
            const date_width: u16 = if (win.width >= 48) @intCast(date.len) else 0;
            const content_width = win.width -| date_width -| @as(u16, if (date_width > 0) 1 else 0);
            const raw_subject = text(get(value_in, "subject"));
            const subject = (try mail_display.decodePreview(self.frame.allocator(), raw_subject)) orelse raw_subject;
            const shown_sender = try self.fitLine(win, if (self.drafts_list) draftRowName(value_in) else sender_text, @min(content_width / 3, 22));
            const line_text = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}{s} {s} · {s}{s}", .{ if (self.mail_selection.contains(text(get(value_in, "id")))) @as([]const u8, "✓") else " ", if (messageUnread(value_in)) @as([]const u8, "●") else " ", if (messageHasLabel(value_in, "STARRED") or truth(get(value_in, "starred"))) @as([]const u8, "*") else " ", shown_sender, if (rowHasAttachments(value_in)) @as([]const u8, "📎 ") else "", if (subject.len == 0) @as([]const u8, "(no subject)") else subject });
            var appearance = self.listStyle(.subject, selected);
            appearance.bold = messageUnread(value_in);
            _ = item.child(.{ .width = content_width }).printSegment(.{ .text = try self.fitLine(win, line_text, content_width), .style = appearance }, .{ .wrap = .none });
            if (date_width > 0) _ = item.child(.{ .x_off = win.width - date_width, .width = date_width }).printSegment(.{ .text = date, .style = self.listStyle(.muted, selected) }, .{ .wrap = .none });
            return;
        }
        const item = win.child(.{ .y_off = @intCast(row), .height = @min(@as(u16, 2), win.height -| @as(u16, @intCast(row))) });
        self.mouseArea(item, .mail, index);
        item.fill(.{ .style = self.style(if (selected) .selected else .text) });
        const stamp = try timestamp(self.frame.allocator(), &self.zone, get(value_in, "receivedAt"));
        const compact = if (stamp.len >= 16) stamp[5..16] else stamp;
        const date_width: u16 = if (win.width >= 48) @intCast(compact.len) else 0;
        const subject_width = win.width -| date_width -| @as(u16, if (date_width > 0) 1 else 0);
        const raw_subject = text(get(value_in, "subject"));
        const subject = (try mail_display.decodePreview(self.frame.allocator(), raw_subject)) orelse raw_subject;
        // Bulk selection, unread state and stars have independent positions;
        // highlighting a read row must not make it look unread.
        const gutter_width: u16 = @min(@as(u16, 3), win.width);
        const gutter = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s} ", .{ if (self.mail_selection.contains(text(get(value_in, "id")))) @as([]const u8, "✓") else " ", if (messageUnread(value_in)) @as([]const u8, "●") else " " });
        _ = item.child(.{ .height = 1, .width = gutter_width }).printSegment(.{ .text = gutter, .style = self.listStyle(.accent, selected) }, .{ .wrap = .none });
        const subject_text = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}", .{ if (rowHasAttachments(value_in)) @as([]const u8, "📎 ") else "", if (subject.len == 0) @as([]const u8, "(no subject)") else subject });
        var subject_style = self.listStyle(.subject, selected);
        subject_style.bold = messageUnread(value_in);
        subject_style.italic = false;
        _ = item.child(.{ .x_off = gutter_width, .height = 1, .width = subject_width -| gutter_width }).printSegment(.{ .text = try self.fitLine(win, subject_text, subject_width -| gutter_width), .style = subject_style }, .{ .wrap = .none });
        if (date_width > 0) _ = item.child(.{ .x_off = win.width - date_width, .height = 1, .width = date_width }).printSegment(.{ .text = compact, .style = self.listStyle(.muted, selected) }, .{ .wrap = .none });
        if (item.height < 2) return;
        const sender_limit = @min((win.width -| gutter_width) / 2, 28);
        const shown_sender = try self.fitLine(win, if (self.drafts_list) draftRowName(value_in) else sender_text, sender_limit);
        if (messageHasLabel(value_in, "STARRED") or truth(get(value_in, "starred"))) {
            const star = if (item.gwidth("⭐") <= 2) "⭐" else "*";
            _ = item.child(.{ .y_off = 1, .height = 1, .width = gutter_width }).printSegment(.{ .text = star, .style = self.listStyle(.accent, selected) }, .{ .wrap = .none });
        }
        const sender_line = item.child(.{ .x_off = gutter_width, .y_off = 1, .height = 1 });
        const printed = sender_line.printSegment(.{ .text = shown_sender, .style = self.listStyle(.sender, selected) }, .{ .wrap = .none });
        var excerpt = self.searchExcerpt(value_in);
        var waiting = selected and self.loadingActive() and (self.job.kind == .read or self.job.kind == .thread);
        if (self.loadingActive()) for (&self.job.loading_rows.slots) |*slot| {
            const received = slot.metadata() orelse continue;
            if (!same(received.id.value(), text(get(value_in, "id")))) continue;
            switch (slot.bodyState()) {
                1 => {
                    if (slot.body_excerpt.value().len > 0) excerpt = slot.body_excerpt.value();
                    waiting = false;
                },
                0 => waiting = !truth(get(value_in, "bodyCached")),
                else => {},
            }
            break;
        };
        if (waiting) excerpt = try std.fmt.allocPrint(self.frame.allocator(), "Body pending {s}", .{loading.frame(self.loading_frame)});
        const warning = metadataWarning(value_in) orelse bodyRefusal(value_in);
        if (!waiting) if (warning) |code| {
            excerpt = try std.fmt.allocPrint(self.frame.allocator(), "Warning · {s}", .{decodeWarningLabel(code)});
        };
        if (printed.col +| 3 < sender_line.width) {
            const decoded = (try mail_display.decodePreview(self.frame.allocator(), excerpt)) orelse excerpt;
            const snippet = try self.fitLine(win, decoded, sender_line.width - printed.col - 3);
            _ = sender_line.child(.{ .x_off = printed.col }).printSegment(.{ .text = try std.fmt.allocPrint(self.frame.allocator(), " — {s}", .{snippet}), .style = self.listStyle(if (waiting) .fetching else if (warning != null) .warning else .muted, selected) }, .{ .wrap = .none });
        }
    }
    fn drawIncomingWindow(self: *App, win: vaxis.Window) !bool {
        if (!self.loadingActive() or (self.job.kind != .list and self.job.kind != .refresh)) return false;
        if (self.messages.len > 0 and !self.pageLoadCurrent()) return false;
        var row: usize = 0;
        if (self.messages.len > 0) {
            // Keep the old focused row and reader until the replacement is
            // committed. Provisional incoming IDs have no interactive hit.
            try self.drawMailRow(win, 0, @min(self.selected, self.messages.len - 1));
            row = self.mailRowStride();
        }
        const reported = self.job.progress.snapshot();
        const known = if (self.job.loading_rows.count() > 0) self.job.loading_rows.count() else if (reported.phase == .metadata) @min(reported.total, loading.window) else 0;
        const visible = self.mailRows(@as(usize, win.height) -| row);
        const count = if (known > 0) @min(known, visible) else @min(@as(usize, 3), visible);
        for (0..count) |index| {
            const current = row + index * self.mailRowStride();
            if (current >= win.height) break;
            const item = win.child(.{ .y_off = @intCast(current), .height = @min(@as(u16, if (self.ui_preferences.density == .compact) 1 else 2), win.height -| @as(u16, @intCast(current))) });
            item.fill(.{ .style = self.style(.text) });
            if (self.job.loading_rows.slots[index].metadata()) |received| {
                const subject = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}", .{ if (received.unread) @as([]const u8, "● ") else "  ", if (received.subject.value().len > 0) received.subject.value() else "(no subject)" });
                const stamp = try timestamp(self.frame.allocator(), &self.zone, .{ .integer = received.received_at });
                const compact = if (stamp.len >= 16) stamp[5..16] else stamp;
                const date_width: u16 = if (item.width >= 48) @intCast(compact.len) else 0;
                const subject_width = item.width -| date_width -| @as(u16, if (date_width > 0) 1 else 0);
                _ = item.child(.{ .height = 1, .width = subject_width }).printSegment(.{ .text = try self.fitLine(item, subject, subject_width), .style = self.style(.subject) }, .{ .wrap = .none });
                if (date_width > 0) _ = item.child(.{ .x_off = item.width - date_width, .height = 1, .width = date_width }).printSegment(.{ .text = compact, .style = self.style(.muted) }, .{ .wrap = .none });
                const slot = &self.job.loading_rows.slots[index];
                const sender = if (received.from_name.value().len > 0) received.from_name.value() else received.from_address.value();
                const detail = if (slot.bodyState() == 1) slot.body_excerpt.value() else received.snippet.value();
                const second = try std.fmt.allocPrint(self.frame.allocator(), "{s} — {s}{s}{s}", .{ sender, detail, if (slot.bodyState() == 0) " · " else "", if (slot.bodyState() == 0) loading.frame(self.loading_frame) else "" });
                try self.line(item, 1, try self.fitLine(item, second, item.width), if (slot.bodyState() == 1) .muted else .fetching);
            } else {
                try self.line(item, 0, try std.fmt.allocPrint(self.frame.allocator(), " {s} Fetching metadata…", .{loading.frame(self.loading_frame)}), .fetching);
                try self.line(item, 1, "   ▱▱▱▱▱▱▱▱▱▱▱▱  ▱▱▱▱▱▱▱▱", .muted);
            }
        }
        return true;
    }
    fn listDraw(self: *App, win: vaxis.Window) !void {
        self.mail_page_size = self.mailRows(win.height);
        self.mouseArea(win, .mail_scroll, 0);
        if (!self.follow_ups_list and try self.drawIncomingWindow(win)) return;
        const count = self.mail_page_size;
        if (self.selected < self.top) self.top = self.selected;
        if (self.selected >= self.top + count) self.top = self.selected + 1 - count;
        if (self.messages.len == 0) {
            if (self.follow_ups_list) {
                try self.line(win, 1, "No follow-ups · press b on a message to add one", .muted);
                return;
            }
            const state = self.sync[self.account_index].state;
            try self.line(win, 1, if (state == .fetching) "Fetching mail…" else if (self.job.future != null and self.drafts_list) "Loading drafts…" else if (state == .failed or self.warning) "Mail unavailable; see status below" else if (self.list_cached and self.list_partial) "No rows in cached subset" else "No matching messages", if (state == .fetching) .fetching else .muted);
            return;
        }
        var index = self.top;
        while (index < self.messages.len and index < self.top + count) : (index += 1) try self.drawMailRow(win, (index - self.top) * self.mailRowStride(), index);
    }
    fn mailRowStride(self: *const App) usize {
        return if (self.ui_preferences.density == .compact) 1 else 3;
    }
    fn mailRows(self: *const App, height: usize) usize {
        return if (self.ui_preferences.density == .compact) @max(height, 1) else mailRowCapacity(height);
    }
    fn searchExcerpt(self: *App, message: Value) []const u8 {
        for (self.search_matches) |match_value| {
            if (same(text(get(match_value, "messageId")), text(get(message, "id"))) and same(text(get(match_value, "field")), "body")) return text(get(match_value, "excerpt"));
        }
        return text(get(message, "snippet"));
    }
    fn flow(self: *App, win: vaxis.Window, value_in: []const u8, offset: usize, base_row: usize) !usize {
        return self.flowTone(win, value_in, offset, base_row, .text);
    }
    fn flowTone(self: *App, win: vaxis.Window, value_in: []const u8, offset: usize, base_row: usize, tone: Tone) !usize {
        return self.flowToneIn(self.frame.allocator(), win, value_in, offset, base_row, tone);
    }
    /// The allocator must outlive the next render, like frame.
    fn flowToneIn(self: *App, allocator: Allocator, win: vaxis.Window, value_in: []const u8, offset: usize, base_row: usize, tone: Tone) !usize {
        const clean = try safe(allocator, value_in, true);
        return self.flowClean(win, clean, offset, base_row, tone, .{});
    }
    fn caretPosition(self: *App, win: vaxis.Window, raw: []const u8, raw_cursor: usize) !TextPosition {
        return self.caretPositionIn(self.frame.allocator(), win, raw, raw_cursor);
    }
    fn caretPositionIn(self: *App, allocator: Allocator, win: vaxis.Window, raw: []const u8, raw_cursor: usize) !TextPosition {
        _ = self;
        const clean = try safe(allocator, raw, true);
        const prefix = try safe(allocator, raw[0..@min(raw_cursor, raw.len)], true);
        return text_layout.caret(clean, @min(prefix.len, clean.len), win.width, win.screen.width_method, .words);
    }
    fn flowCaret(self: *App, win: vaxis.Window, raw: []const u8, raw_cursor: usize, offset: usize) !usize {
        return self.flowCaretIn(self.frame.allocator(), win, raw, raw_cursor, offset);
    }
    fn flowCaretIn(self: *App, allocator: Allocator, win: vaxis.Window, raw: []const u8, raw_cursor: usize, offset: usize) !usize {
        const clean = try safe(allocator, raw, true);
        const prefix = try safe(allocator, raw[0..@min(raw_cursor, raw.len)], true);
        const rows = self.flowClean(win, clean, offset, 0, .text, .{});
        const caret = text_layout.caret(clean, @min(prefix.len, clean.len), win.width, win.screen.width_method, .words);
        if (caret.row >= offset and caret.row - offset < win.height and caret.column < win.width) {
            win.setCursorShape(.block);
            win.showCursor(caret.column, @intCast(caret.row - offset));
        }
        return @max(rows, caret.row + 1);
    }
    fn flowClean(self: *App, win: vaxis.Window, clean: []const u8, offset: usize, base_row: usize, tone: Tone, options: text_layout.Options) usize {
        return self.flowStyled(win, clean, offset, base_row, tone, options, &.{});
    }
    fn flowReaderText(self: *App, win: vaxis.Window, value_in: []const u8, offset: usize, base_row: usize) !usize {
        const clean = try safe(self.frame.allocator(), value_in, true);
        const display = try reader_tools.displayLinks(self.frame.allocator(), clean);
        self.reader_find_text = true;
        defer self.reader_find_text = false;
        return self.flowStyled(win, display.text, offset, base_row, .text, .{}, display.ranges);
    }
    fn preparedPlainDraw(self: *App, view: *ReaderMarkup, win: vaxis.Window, body: []const u8, base_row: usize) !usize {
        if (win.width == 0) return base_row;
        if (view.plain) |*plain| if (plain.quotes != self.fold_quotes or plain.signatures != self.fold_signatures) {
            plain.deinit();
            view.plain = null;
        };
        if (view.plain == null) {
            const clean = try safe(self.frame.allocator(), body, true);
            view.plain = try reader_plain.Prepared.init(self.allocator, clean, self.fold_quotes, self.fold_signatures);
        }
        const prepared = &view.plain.?;
        try prepared.ensure(win.width, win.screen.width_method);
        if (self.reader_find_collect or self.reader_copy_collect) {
            self.reader_find_text = true;
            defer self.reader_find_text = false;
            return self.flowStyled(win, prepared.text, self.reader_scroll, base_row, .text, .{}, prepared.links);
        }
        const end = base_row + prepared.rows;
        if (base_row >= self.reader_scroll +| win.height or end <= self.reader_scroll) return end;
        var iterator = prepared.iteratorAt(self.reader_scroll -| base_row);
        const highlight = if (!self.calendar.open and self.cacheSearch()) self.search_highlight.value() else "";
        // Bound highlighting to the visible source and enough preceding bytes
        // to cover a match spanning the first visible wrapped row.
        var scan = iterator;
        while (scan.next()) |glyph| if (base_row + glyph.position.row >= self.reader_scroll +| win.height) break;
        const visible_source = prepared.text[0..scan.offset];
        const match_start = iterator.offset -| (highlight.len *| 4);
        var match = cache_query.findRangeAt(visible_source, highlight, match_start);
        var link_index: usize = 0;
        var row = iterator.position.row;
        var shown_byte: usize = 0;
        while (iterator.next()) |glyph| {
            if (glyph.position.row != row) {
                row = glyph.position.row;
                shown_byte = 0;
            }
            const glyph_start = shown_byte;
            shown_byte += glyph.text.len;
            const absolute = base_row + row;
            if (absolute >= self.reader_scroll +| win.height) break;
            if (absolute < self.reader_scroll or glyph.columns > win.width) continue;
            while (link_index < prepared.links.len and glyph.byte_offset >= prepared.links[link_index].end) link_index += 1;
            while (match) |range| {
                if (glyph.byte_offset < range.end) break;
                match = cache_query.findRangeAt(visible_source, highlight, range.end);
            }
            var appearance = self.style(.text);
            if (link_index < prepared.links.len and glyph.byte_offset >= prepared.links[link_index].start) appearance = html_view.style(self.palette, self.mono, .{}, .link);
            if (match) |range| if (glyph.byte_offset < range.end and iterator.offset > range.start) {
                if (self.mono) appearance.reverse = true else {
                    appearance.bg = .{ .rgb = self.palette.yellow };
                    appearance.fg = .{ .rgb = self.palette.background };
                }
            };
            if (self.reader_find_paint and self.reader_find_scope) appearance = self.readerFindStyle(appearance, absolute, glyph_start, shown_byte);
            if (self.reader_copy_paint and self.reader_copy_scope) appearance = self.readerCopyStyle(appearance, absolute, glyph_start, shown_byte);
            win.writeCell(glyph.position.column, @intCast(absolute - self.reader_scroll), .{ .char = .{ .grapheme = glyph.text, .width = @intCast(@min(glyph.columns, 255)) }, .style = appearance });
        }
        return end;
    }
    fn flowStyled(self: *App, win: vaxis.Window, clean: []const u8, offset: usize, base_row: usize, tone: Tone, options: text_layout.Options, link_ranges: []const reader_tools.LinkRange) usize {
        if (win.width == 0) return base_row;
        const highlight = if (!self.calendar.open and self.cacheSearch()) self.search_highlight.value() else "";
        var next_match = cache_query.findRange(clean, highlight);
        var layout_options = options;
        layout_options.base_row = base_row;
        const find_here = self.reader_find_scope and (self.reader_find_text or tone == .subject);
        const copy_here = self.reader_copy_scope and self.reader_find_text;
        if ((self.reader_find_collect and find_here) or (self.reader_copy_collect and copy_here)) self.scanReaderFlow(clean, win, layout_options);
        var iterator = text_layout.Iterator.init(clean, win.width, win.screen.width_method, layout_options);
        var link_index: usize = 0;
        var shown_row = base_row;
        var shown_byte: usize = 0;
        while (iterator.next()) |glyph| {
            if (shown_row != glyph.position.row) {
                shown_row = glyph.position.row;
                shown_byte = 0;
            }
            const glyph_start = shown_byte;
            shown_byte += glyph.text.len;
            if (self.reader_find_collect or self.reader_copy_collect) continue;
            while (link_index < link_ranges.len and glyph.byte_offset >= link_ranges[link_index].end) link_index += 1;
            while (next_match) |match_at| {
                if (glyph.byte_offset < match_at.end) break;
                next_match = cache_query.findRangeAt(clean, highlight, match_at.end);
            }
            // Count every row/byte for the full-body scrollbar, but construct
            // styles only for cells that can actually reach this viewport.
            if (glyph.position.row < offset or glyph.position.row - offset >= win.height or glyph.columns > win.width) continue;
            var cell_style = self.style(if (glyph.marker) .accent else tone);
            if (!glyph.marker and link_index < link_ranges.len and glyph.byte_offset >= link_ranges[link_index].start) cell_style = html_view.style(self.palette, self.mono, .{}, .link);
            if (!glyph.marker) if (next_match) |match_at| if (glyph.byte_offset >= match_at.start and glyph.byte_offset < match_at.end) {
                if (self.mono) cell_style.reverse = true else {
                    cell_style.bg = .{ .rgb = self.palette.yellow };
                    cell_style.fg = .{ .rgb = self.palette.background };
                }
            };
            if (self.reader_find_paint and find_here and !glyph.marker) cell_style = self.readerFindStyle(cell_style, glyph.position.row, glyph_start, shown_byte);
            if (copy_here and !glyph.marker) cell_style = self.readerCopyStyle(cell_style, glyph.position.row, glyph_start, shown_byte);
            win.writeCell(glyph.position.column, @intCast(glyph.position.row - offset), .{ .char = .{ .grapheme = glyph.text, .width = @intCast(@min(glyph.columns, 255)) }, .style = cell_style });
        }
        return iterator.position.row + 1;
    }
    fn readerInvitationIndex(self: *App) ?usize {
        if (self.mode != .browse or !same(self.reader_account.value(), self.account())) return null;
        const target = self.readerReplyId();
        for (self.thread, 0..) |message, index| {
            if (!same(text(get(message, "id")), target)) continue;
            if (get(message, "invitation") != .null) return index;
            for (items(get(message, "attachments"))) |part| {
                if (mime.isCalendarPart(text(get(part, "mimeType")), text(get(part, "filename")))) return index;
            }
            return null;
        }
        return null;
    }
    fn prepareReaderInvitation(self: *App, message: Value) !void {
        const raw = text(get(message, "invitation"));
        const id = text(get(message, "id"));
        const subject = text(get(message, "subject"));
        var fingerprint = std.hash.Wyhash.init(@bitCast(integer(get(message, "receivedAt"))));
        fingerprint.update(raw);
        fingerprint.update(subject);
        var aliases: [recipients.max_recipients][]const u8 = undefined;
        var count: usize = 0;
        if (same(self.identities_account.value(), self.account())) for (self.identities) |identity| {
            const address = text(get(identity, "address"));
            if (count == aliases.len) break;
            if (address.len == 0) continue;
            fingerprint.update(address);
            aliases[count] = address;
            count += 1;
        };
        const hash = fingerprint.final();
        if (self.reader_invitation_cached and self.reader_invitation_hash == hash and same(self.reader_invitation_account.slice(), self.account()) and same(self.reader_invitation_message.slice(), id)) return;
        self.reader_invitation_cached = true;
        self.reader_invitation_hash = hash;
        try self.reader_invitation_account.set(self.account());
        try self.reader_invitation_message.set(id);
        self.reader_invitation_title.display(if (subject.len > 0) subject else "Meeting invitation");
        self.reader_invitation_when.display("Time details in review");
        self.reader_invitation_where.display("");
        self.reader_invitation_can_reply = false;
        self.reader_invitation_badge = "Invitation";
        self.reader_invitation_badge_tone = .sender;
        self.reader_invitation_has_join = false;
        var invite: invitation.Invitation = .{};
        invitation.parseDisplay(raw, self.account(), aliases[0..count], &invite) catch return;
        self.reader_invitation_can_reply = invite.canRespond();
        const a = self.frame.allocator();
        const presentation = if (browser_target) try invitation.friendly(a, &invite, &self.zone) else try invitation.friendlyNative(self.io, a, self.environ, &invite, &self.zone);
        self.reader_invitation_has_join = presentation.join_url.len > 0;
        self.reader_invitation_badge = if (invite.cancelled) "Cancelled" else if (invite.method == .reply) "RSVP received" else if (invite.method == .publish) "Calendar event" else "Invitation";
        self.reader_invitation_badge_tone = if (invite.cancelled) .warning else if (invite.method == .request) .sender else .muted;
        self.reader_invitation_title.display(if (invite.summary.len > 0) invite.summary.slice() else subject);
        if (presentation.start.len > 0) self.reader_invitation_when.display(try std.fmt.allocPrint(a, "{s}{s}{s}", .{ presentation.start, if (presentation.duration.len > 0) " · " else "", presentation.duration }));
        self.reader_invitation_where.display(try std.fmt.allocPrint(a, "{s}{s}Organizer: {s}", .{ presentation.location, if (presentation.location.len > 0) " · " else "", invite.organizer.slice() }));
    }
    fn drawJoinCamera(self: *App, win: vaxis.Window, x: u16, row: usize) !void {
        if (row >= win.height or @as(usize, x) + 3 > win.width or win.gwidth("") > 2) return;
        // Nerd Font U+F03D may overhang its first cell. Keep two cells and a gap.
        try self.line(win.child(.{ .x_off = x, .width = 2 }), row, " ", .accent);
    }
    fn measureCardBlocks(self: *App, win: vaxis.Window, blocks: []CardBlock) !usize {
        var rows: usize = 0;
        for (blocks) |*block| {
            block.text = try safe(self.frame.allocator(), block.text, true);
            rows += positionAfter(win, block.text).row + 1;
        }
        return rows;
    }
    fn drawCardBlocks(self: *App, win: vaxis.Window, blocks: []const CardBlock, scroll: usize) !void {
        var row: usize = 0;
        for (blocks) |block| row = try self.flowTone(win, block.text, scroll, row, block.tone);
    }
    fn readerInvitationDraw(self: *App, win: vaxis.Window, message_index: usize) !void {
        try self.prepareReaderInvitation(self.thread[message_index]);
        const bordered = win.height >= 5 and win.width >= 48;
        win.fill(.{ .style = self.style(.text) });
        const content = if (bordered) blk: {
            const inside = win.child(.{ .border = .{ .where = .all, .style = self.style(.muted) } });
            try self.line(win.child(.{ .x_off = 2, .width = win.width -| 4, .height = 1 }), 0, try std.fmt.allocPrint(self.frame.allocator(), " {s} ", .{self.reader_invitation_badge}), self.reader_invitation_badge_tone);
            break :blk inside.child(.{ .x_off = 1, .width = inside.width -| 2 });
        } else blk: {
            for (0..win.height) |row| win.writeCell(0, @intCast(row), .{ .char = .{ .grapheme = if (self.mono) "┃" else "▌", .width = 1 }, .style = self.style(self.reader_invitation_badge_tone) });
            break :blk win.child(.{ .x_off = 2, .width = win.width -| 3 });
        };
        const video_icon = self.reader_invitation_has_join and content.width >= 20 and content.gwidth("") <= 2;
        const icon_width: u16 = if (video_icon) 3 else 0;
        if (video_icon) try self.drawJoinCamera(content, 0, 0);
        const action = if (self.reader_invitation_can_reply) @as([]const u8, "I · Respond") else "I · Details";
        const action_width: u16 = @intCast(@min(content.width, content.gwidth(action)));
        const action_x = content.width - action_width;
        const title_win = content.child(.{ .x_off = icon_width, .width = action_x -| icon_width -| 1, .height = 1 });
        const when_text = self.reader_invitation_when.slice();
        const short_when = if (when_text.len >= 16 and when_text[4] == '-' and when_text[7] == '-' and when_text[10] == ' ' and when_text[13] == ':') when_text[5..16] else when_text;
        const title = if (content.height > 1) self.reader_invitation_title.slice() else try std.fmt.allocPrint(self.frame.allocator(), "{s} · {s}", .{ short_when, self.reader_invitation_title.slice() });
        const shown_title = if (!bordered and !same(self.reader_invitation_badge, "Invitation")) try std.fmt.allocPrint(self.frame.allocator(), "{s} · {s}", .{ self.reader_invitation_badge, title }) else title;
        try self.line(title_win, 0, try self.fitLine(title_win, shown_title, title_win.width), .subject);
        const actions = content.child(.{ .x_off = action_x, .width = action_width, .height = 1 });
        try self.line(actions, 0, action, .muted);
        var shortcut_style = self.style(.accent);
        shortcut_style.bold = true;
        if (self.mono) shortcut_style.reverse = true;
        actions.writeCell(0, 0, .{ .char = .{ .grapheme = "I", .width = 1 }, .style = shortcut_style });
        if (content.height > 1) try self.line(content, 1, try self.fitLine(content, when_text, content.width), .accent);
        if (content.height > 2) try self.line(content, 2, try self.fitLine(content, self.reader_invitation_where.slice(), content.width), .muted);
        self.mouseArea(win, .reader_invitation, message_index);
    }
    fn readerInvitationRows(win: vaxis.Window) u16 {
        if (win.height < 3 or win.width < 16) return 0;
        if (win.width >= 48 and win.height >= 20) return 5;
        if (win.width >= 40 and win.height >= 9) return 3;
        return if (win.height >= 6) 2 else 1;
    }
    fn startReaderFind(self: *App, query: []const u8) !void {
        if (query.len == 0) {
            self.clearReaderFind();
            return;
        }
        const target = self.readerReplyId();
        var index: ?usize = null;
        if (same(self.reader_account.value(), self.account())) for (self.thread, 0..) |message, candidate| {
            if (same(text(get(message, "id")), target)) {
                index = candidate;
                break;
            }
        };
        const chosen = index orelse return error.BodyNotCached;
        try self.reader_finder.reset(query);
        self.reader_find_layout_key = null;
        try self.reader_find_query.set(query);
        try self.reader_find_account.set(self.account());
        try self.reader_find_message.set(target);
        try self.reader_find_anchor_message.set(self.reader_message.value());
        self.reader_find_active = true;
        self.reader_find_refresh = false;
        self.reader_find_reveal = true;
        self.reader_find_width = 0;
        self.reader_card = chosen;
        self.reader_cards[chosen] = true;
        self.reader_anchor_card = false;
        self.reader_card_pinned = false;
        self.focus = .reader;
    }
    fn nextReaderFind(self: *App, forward: bool) !void {
        if (!self.reader_find_active) {
            self.say(false, "Find in this message · :find TEXT", .{});
            return;
        }
        _ = self.reader_finder.next(forward);
        self.reader_find_reveal = true;
    }
    fn readerCopyVisible(self: *const App) bool {
        return self.reader_copy.active() or self.reader_copy_request != null or self.reader_copy_mark != null;
    }
    fn readerCopyTarget(self: *App) !Value {
        if (self.mode != .browse and !(self.mode == .command and self.previous_mode == .browse)) return error.NotMailbox;
        if (self.compose_active or self.drafts_list or self.thread.len == 0 or self.reader_card >= self.thread.len) return error.MessageRequired;
        if (!same(self.reader_account.value(), self.account()) or !same(self.reader_message.value(), self.messageId())) return error.ReaderMessageChanging;
        return self.thread[self.reader_card];
    }
    fn readerCopyDigest(message: Value) [32]u8 {
        var hash = std.crypto.hash.sha2.Sha256.init(.{});
        hash.update(text(get(message, "bodyText")));
        hash.update("\x00");
        hash.update(text(get(message, "bodyHtml")));
        var result: [32]u8 = undefined;
        hash.final(&result);
        return result;
    }
    fn clearReaderCopy(self: *App) void {
        self.reader_copy.cancel();
        self.reader_copy_request = null;
        self.reader_copy_mark = null;
        self.reader_copy_account.wipe();
        self.reader_copy_message.wipe();
        self.reader_copy_source = null;
        self.reader_copy_refresh = false;
        self.reader_copy_focus = 0;
        self.reader_copy_g_pending = false;
        self.reader_drag_anchor = null;
        self.reader_dragging = false;
    }
    fn readerCopyChanged(self: *App) void {
        const visible = self.readerCopyVisible();
        self.clearReaderCopy();
        if (visible) self.say(false, "Selection cleared · message or layout changed", .{});
    }
    fn reconcileReaderCopy(self: *App) void {
        if (!self.readerCopyVisible()) return;
        const message = self.readerCopyTarget() catch {
            self.readerCopyChanged();
            return;
        };
        if (!same(self.reader_copy_account.slice(), self.account()) or !same(self.reader_copy_message.slice(), text(get(message, "id"))) or self.reader_copy_quotes != self.fold_quotes or self.reader_copy_signatures != self.fold_signatures) {
            self.readerCopyChanged();
            return;
        }
        if (self.reader_copy_refresh) {
            const digest = readerCopyDigest(message);
            if (self.reader_copy_source == null or !std.mem.eql(u8, &digest, &self.reader_copy_source.?)) {
                self.readerCopyChanged();
                return;
            }
            if (self.reader_copy.active()) self.reader_copy_mark = self.reader_copy.mark();
            self.reader_copy.ready = false;
            self.reader_copy_refresh = false;
        }
    }
    fn requestReaderCopy(self: *App, mode: reader_selection.Mode, row: usize, column: usize) !void {
        const message = try self.readerCopyTarget();
        if (self.reader_progressive and !truth(get(message, "bodyCached")) and text(get(message, "bodyCacheError")).len == 0) return error.ReaderMessageChanging;
        self.clearReaderCopy();
        try self.reader_copy_account.set(self.account());
        try self.reader_copy_message.set(text(get(message, "id")));
        self.reader_copy_source = readerCopyDigest(message);
        self.reader_copy_quotes = self.fold_quotes;
        self.reader_copy_signatures = self.fold_signatures;
        self.reader_copy.reset(self.allocator, self.reader_copy_generation, 0, .unicode);
        self.reader_copy_request = .{ .mode = mode, .row = row, .column = column };
        self.focus = .reader;
        self.reader_cards[self.reader_card] = true;
        self.reader_copy_focus = 0;
    }
    fn revealReaderCopyCursor(self: *App) void {
        const row = self.reader_copy.cursorRow() orelse return;
        if (row < self.reader_scroll) self.reader_scroll = row else if (row - self.reader_scroll >= self.reader_height) self.reader_scroll = row + 1 - @max(self.reader_height, 1);
        self.reader_anchor_card = false;
        self.reader_card_pinned = true;
    }
    fn emitReaderCopy(self: *App, value: []const u8) !void {
        if (!self.capabilities.clipboard) return error.ClipboardUnavailable;
        if (value.len == 0) return error.NoTextSelected;
        if (value.len > types.Limits.request_bytes) return error.ClipboardTextTooLarge;
        if (@import("builtin").is_test) {
            try self.reader_copy_test_value.set(self.allocator, value);
        } else {
            // The real terminal owns clipboard access. In fixture PTYs this
            // escape is captured by the test's master, never a desktop viewer.
            try self.vx.copyToSystemClipboard(self.tty.writer(), value, self.allocator);
            try self.tty.writer().flush();
        }
        self.sayAction(false, "Sent {s} to terminal clipboard · terminal support applies", .{try attachmentSizeLabel(self.frame.allocator(), value.len)});
    }
    fn copyReaderSelection(self: *App) !void {
        self.reconcileReaderCopy();
        if (!self.reader_copy.active() or self.reader_copy_mark != null) return error.NoTextSelected;
        if (!self.reader_copy.selecting()) {
            self.say(false, "Move to the starting point · V or Space selects from here", .{});
            return;
        }
        const value = try self.reader_copy.copy(self.frame.allocator());
        try self.emitReaderCopy(value);
        self.clearReaderCopy();
    }
    fn activateReaderCopyPrimary(self: *App) !void {
        if (self.reader_copy.active() and !self.reader_copy.selecting()) {
            self.reader_copy.startSelection();
            self.reader_copy_focus = 0;
        } else try self.copyReaderSelection();
    }
    fn readerSnapshot(self: *App) ![]const u8 {
        const message = try self.readerCopyTarget();
        if (self.reader_progressive and !truth(get(message, "bodyCached")) and text(get(message, "bodyCacheError")).len == 0) return error.ReaderMessageChanging;
        const from = get(message, "from");
        const to = try displayMailboxes(self.frame.allocator(), get(message, "to"), displayIncomingMailbox);
        const cc = try displayMailboxes(self.frame.allocator(), get(message, "cc"), displayIncomingMailbox);
        const stamp = try timestamp(self.frame.allocator(), &self.zone, get(message, "receivedAt"));
        const body = text(get(message, "bodyText"));
        if (body.len > types.Limits.body_bytes) return error.BodyTooLarge;
        const raw = try std.fmt.allocPrint(self.frame.allocator(), "From: {s} <{s}>\nTo: {s}\n{s}{s}Subject: {s}\nDate: {s}\n\n{s}", .{ text(get(from, "name")), text(get(from, "address")), to, if (cc.len > 0) @as([]const u8, "Cc: ") else "", if (cc.len > 0) try std.fmt.allocPrint(self.frame.allocator(), "{s}\n", .{cc}) else "", text(get(message, "subject")), stamp, body });
        if (raw.len > types.Limits.request_bytes) return error.MessageTooLarge;
        return safe(self.frame.allocator(), raw, true);
    }
    fn copyReaderMessage(self: *App) !void {
        const snapshot = try self.readerSnapshot();
        self.clearReaderCopy();
        try self.emitReaderCopy(snapshot);
    }
    fn viewReaderEditor(self: *App) anyerror!void {
        if (browser_target) return error.EditorUnavailable;
        if (!self.capabilities.editor) return error.EditorUnavailable;
        if (@import("builtin").is_test) return error.EditorUnavailableInScreenTest;
        const snapshot = try self.readerSnapshot();
        self.clearReaderCopy();
        self.preemptReadOnly();
        if (self.job.future != null) return error.OperationPending;
        self.loop.stop();
        const writer = self.tty.writer();
        try self.vx.resetState(writer);
        try writer.flush();
        try std.posix.tcsetattr(self.tty.fd.handle, .FLUSH, self.tty.termios);
        const result = editor.view(self.io, self.allocator, self.environ, snapshot, self.tty.fd.handle, &self.cancellation);
        _ = try vaxis.Tty.makeRaw(self.tty.fd.handle);
        try self.vx.enterAltScreen(writer);
        try self.vx.enableDetectedFeatures(writer);
        try setMouseReporting(self.vx, writer, !self.options.no_mouse);
        if (self.tty.getWinsize()) |size| try self.resize(size) else |_| {}
        self.vx.queueRefresh();
        try self.loop.start();
        _ = self.meetingTick();
        const exit_code = result catch |err| {
            self.sayFailure("Editor view closed · received mail unchanged", @errorName(err));
            return;
        };
        if (exit_code == 0) self.sayAction(false, "Editor view closed · received mail unchanged", .{}) else self.sayAction(true, "Editor exited with {d} · received mail unchanged", .{exit_code});
    }
    fn onReaderCopyKey(self: *App, key: Key) !bool {
        if (self.mode != .browse or self.ux_overlay != .none or self.reader_overlay != .none or self.label_picker or self.compose_choice or self.update_open or self.grace_active) return false;
        self.reconcileReaderCopy();
        if (self.readerCopyVisible()) {
            if (key.matches(Key.escape, .{}) or key.matches('q', .{}) or key.matches('c', .{ .ctrl = true })) {
                self.clearReaderCopy();
                return true;
            }
            if (key.matches('l', .{ .ctrl = true })) return false; // Theme-only redraw retains source pins.
            if (key.matches('v', .{})) {
                self.clearReaderCopy();
                return false; // Normal v remains the layout shortcut.
            }
            if (self.reader_copy_request) |*request| {
                if (key.matches('V', .{}) or key.matches('v', .{ .shift = true })) {
                    request.mode = switch (request.mode) {
                        .off, .cursor => .character,
                        .character => .line,
                        .line => .character,
                    };
                } else if (key.matches(' ', .{})) request.mode = if (request.mode == .cursor) .character else .cursor;
                return true;
            }
            if (!self.reader_copy.active()) return true;
            if (tabDirection(key)) |backwards| {
                self.reader_copy_focus = @intCast((@as(usize, self.reader_copy_focus) + if (backwards) @as(usize, 2) else 1) % 3);
                return true;
            }
            if (key.matches(Key.enter, .{})) {
                if (self.reader_copy_focus == 1) try self.activateReaderCopyPrimary() else if (self.reader_copy_focus == 2) self.clearReaderCopy();
                return true;
            }
            if (key.matches('y', .{})) {
                try self.copyReaderSelection();
                return true;
            }
            if (key.matches('V', .{}) or key.matches('v', .{ .shift = true })) {
                if (!self.reader_copy.selecting()) self.reader_copy.startSelection() else self.reader_copy.mode = if (self.reader_copy.mode == .character) .line else .character;
                self.reader_copy_focus = 0;
                return true;
            }
            if (key.matches(' ', .{})) {
                if (self.reader_copy.selecting()) self.reader_copy.positionCursor() else self.reader_copy.startSelection();
                self.reader_copy_focus = 0;
                return true;
            }
            if (key.matches('v', .{ .ctrl = true })) {
                self.say(false, "Block selection is not supported · V toggles character/line", .{});
                return true;
            }
            if (key.matches('o', .{})) {
                self.reader_copy.swapEnds();
                self.reader_copy_focus = 0;
                self.revealReaderCopyCursor();
                return true;
            }
            if (key.matches('d', .{ .ctrl = true }) or key.matches('u', .{ .ctrl = true }) or key.matches(Key.page_down, .{}) or key.matches(Key.page_up, .{})) {
                const down = key.matches('d', .{ .ctrl = true }) or key.matches(Key.page_down, .{});
                const amount = @max(self.reader_height / @as(usize, if (key.mods.ctrl) 2 else 1), 1);
                for (0..amount) |_| _ = self.reader_copy.move(if (down) .down else .up);
                self.reader_copy_focus = 0;
                self.revealReaderCopyCursor();
                return true;
            }
            if (key.matches('g', .{})) {
                if (self.reader_copy_g_pending) {
                    _ = self.reader_copy.move(.first);
                    self.reader_copy_g_pending = false;
                    self.revealReaderCopyCursor();
                } else self.reader_copy_g_pending = true;
                return true;
            }
            self.reader_copy_g_pending = false;
            const motion: ?reader_selection.Motion = if (key.matches('h', .{}) or key.matches(Key.left, .{})) .left else if (key.matches('l', .{}) or key.matches(Key.right, .{})) .right else if (key.matches('j', .{}) or key.matches(Key.down, .{})) .down else if (key.matches('k', .{}) or key.matches(Key.up, .{})) .up else if (key.matches('w', .{})) .word_forward else if (key.matches('b', .{})) .word_backward else if (key.matches('e', .{})) .word_end else if (key.matches('0', .{}) or key.matches(Key.home, .{})) .line_start else if (key.matches('$', .{})) .line_end else if (key.matches('G', .{}) or key.matches('g', .{ .shift = true }) or key.matches(Key.end, .{})) .last else null;
            if (motion) |motion_value| {
                _ = self.reader_copy.move(motion_value);
                self.reader_copy_focus = 0;
                self.revealReaderCopyCursor();
                return true;
            }
            // Vim operator letters must never become mail mutations or open
            // a composer/browser. Explicit view/navigation actions can leave.
            if (key.matches('J', .{}) or key.matches('K', .{}) or key.matches('{', .{}) or key.matches('}', .{}) or key.matches('Q', .{}) or key.matches('S', .{}) or key.matches('t', .{}) or key.matches('L', .{}) or key.matches('B', .{}) or key.matches(':', .{}) or key.matches('?', .{}) or key.matches('z', .{}) or key.matches('f', .{ .ctrl = true }) or key.matches('r', .{ .ctrl = true }) or key.matches('1', .{}) or key.matches('2', .{}) or key.matches('3', .{})) {
                self.clearReaderCopy();
                return false;
            }
            self.say(false, "Text cursor/selection · V or Space marks · y Copy · Esc Cancel · mail actions are paused", .{});
            return true;
        }
        if (self.focus != .reader and !self.expanded) return false;
        if (key.matches('V', .{}) or key.matches('v', .{ .shift = true })) {
            self.requestReaderCopy(.cursor, self.reader_scroll, 0) catch |err| switch (err) {
                error.MessageRequired, error.ReaderMessageChanging => self.say(false, "Current message is still loading · wait for this preview", .{}),
                else => return err,
            };
            return true;
        }
        if (key.matches('e', .{})) {
            self.viewReaderEditor() catch |err| switch (err) {
                error.MessageRequired, error.ReaderMessageChanging => self.say(false, "Current message is still loading · wait for this preview", .{}),
                else => return err,
            };
            return true;
        }
        if (key.matches('y', .{})) {
            self.say(false, "V selects text · move to your start, then V/Space marks · :copy-message copies the current mail", .{});
            return true;
        }
        return false;
    }
    fn readerCopyStyle(self: *const App, original: vaxis.Style, row: usize, byte_start: usize, byte_end: usize) vaxis.Style {
        if (!self.reader_copy_paint or !self.reader_copy_scope) return original;
        var style_in = original;
        const cursor_row = self.reader_copy.cursorRow();
        const cursor_line = if (self.reader_copy.active()) self.reader_copy.lines.items[self.reader_copy.cursor.line] else return original;
        const cursor = cursor_row != null and cursor_row.? == row and byte_start <= cursor_line.byte_base + self.reader_copy.cursor.byte and byte_end > cursor_line.byte_base + self.reader_copy.cursor.byte;
        const selected = if (self.reader_copy.range(row)) |range| byte_start < range.end and byte_end > range.start else false;
        if (!selected and !cursor) return original;
        if (self.mono) {
            style_in.reverse = true;
            if (cursor) {
                style_in.bold = true;
                style_in.ul_style = .single;
            }
        } else {
            style_in.bg = .{ .rgb = if (cursor) self.palette.accent else self.palette.selection };
            style_in.fg = .{ .rgb = if (cursor) self.palette.background else self.palette.foreground };
        }
        return style_in;
    }
    fn readerCopyBar(self: *App, outer: vaxis.Window) !void {
        if (!self.readerCopyVisible() or outer.height == 0) return;
        const bar = outer.child(.{ .y_off = outer.height - 1, .height = 1 });
        bar.fill(.{ .style = self.style(.text) });
        const title = switch (self.reader_copy.mode) {
            .off, .cursor => "MOVE",
            .character => "CHAR",
            .line => "LINE",
        };
        const controls: u16 = if (bar.width >= 28) 25 else 18;
        const title_width = bar.width -| controls;
        if (title_width > 0) try self.line(bar.child(.{ .width = title_width }), 0, title, .accent);
        const primary = if (self.reader_copy.selecting()) (if (bar.width >= 28) "[Copy y]" else "[y Copy]") else "[Select V]";
        const x = try self.actionButton(bar, 0, title_width, primary, self.reader_copy_focus == 1, self.reader_copy.active(), .dialog_action, 601);
        _ = try self.actionButton(bar, 0, x, if (bar.width >= 28) "[Cancel Esc]" else "[Esc]", self.reader_copy_focus == 2, true, .dialog_action, 602);
    }
    fn onReaderCopyMouse(self: *App, mouse: vaxis.Mouse) !bool {
        if (self.options.no_mouse or mouse.mods.shift or mouse.mods.alt or mouse.mods.ctrl or self.mode != .browse or self.ux_overlay != .none or self.reader_overlay != .none or self.label_picker or self.compose_choice or self.update_open or self.grace_active) return false;
        self.reconcileReaderCopy();
        if (mouse.type == .press and mouse.button == .left) {
            if (self.reader_copy.active()) if (self.mouse_hits.at(mouse.col, mouse.row)) |hit| if (hit.kind == .dialog_action and (hit.index == 601 or hit.index == 602)) {
                self.reader_copy_focus = if (hit.index == 601) 1 else 2;
                if (hit.index == 601) try self.activateReaderCopyPrimary() else self.clearReaderCopy();
                return true;
            };
            if (self.reader_copy.active()) {
                const hit = self.mouse_hits.at(mouse.col, mouse.row);
                const body_click = if (hit) |value| value.kind == .reader else false;
                self.clearReaderCopy();
                return body_click;
            }
            if (self.mouse_hits.at(mouse.col, mouse.row)) |hit| if (hit.kind != .reader) return false;
            const rect = self.reader_copy_rect orelse return false;
            if (mouse.col < rect.x or mouse.col >= rect.x + rect.width or mouse.row < rect.y or mouse.row >= rect.y + rect.height) return false;
            const logical_row = self.reader_scroll + @as(usize, @intCast(mouse.row - @as(i16, @intCast(rect.y))));
            for (self.reader_body_bounds[0..self.thread.len], 0..) |bounds, card| if (bounds) |body| if (logical_row >= body.start and logical_row < body.end) {
                self.reader_drag_anchor = .{ .card = card, .row = logical_row, .column = @intCast(mouse.col - @as(i16, @intCast(rect.x))) };
                return false; // A plain click keeps its existing reader focus action.
            };
            return false;
        }
        if ((mouse.type == .drag or mouse.type == .motion) and mouse.button == .left) {
            const anchor = self.reader_drag_anchor orelse return false;
            const rect = self.reader_copy_rect orelse return false;
            const col: usize = @intCast(std.math.clamp(mouse.col - @as(i16, @intCast(rect.x)), 0, @as(i16, @intCast(rect.width -| 1))));
            const y = std.math.clamp(mouse.row - @as(i16, @intCast(rect.y)), 0, @as(i16, @intCast(rect.height -| 1)));
            if (!self.reader_dragging and anchor.row == self.reader_scroll + @as(usize, @intCast(y)) and anchor.column == col) return true;
            if (!self.reader_dragging) {
                self.reader_card = anchor.card;
                try self.requestReaderCopy(.character, anchor.row, anchor.column);
                self.reader_drag_anchor = anchor;
                self.reader_dragging = true;
            }
            const row = self.reader_scroll + @as(usize, @intCast(y));
            if (self.reader_copy_request) |*request| {
                request.end_row = row;
                request.end_column = col;
            } else if (self.reader_copy.active()) {
                self.reader_copy.extend(row, col);
                self.revealReaderCopyCursor();
            }
            return true;
        }
        if (mouse.type == .release and mouse.button == .left) {
            const dragging = self.reader_dragging;
            self.reader_drag_anchor = null;
            self.reader_dragging = false;
            return dragging; // Clipboard changes only on y or the Copy control.
        }
        return false;
    }
    fn clearReaderFind(self: *App) void {
        self.reader_find_active = false;
        self.reader_finder = .{};
        self.reader_find_query.wipe();
        self.reader_find_account.wipe();
        self.reader_find_message.wipe();
        self.reader_find_anchor_message.wipe();
        self.reader_find_refresh = false;
        self.reader_find_reveal = false;
        self.reader_find_layout_key = null;
    }
    fn reconcileReaderFind(self: *App) void {
        if (!self.reader_find_active) return;
        if (!same(self.reader_find_account.slice(), self.account())) {
            self.clearReaderFind();
            return;
        }
        if (self.reader_find_refresh) {
            const anchor = self.messageId();
            if (!same(anchor, self.reader_find_anchor_message.slice()) and !same(anchor, self.reader_find_message.slice())) {
                self.clearReaderFind();
                return;
            }
            // A cache update can briefly remove the body while preserving the
            // selected mailbox row. Keep query/ordinal until its replacement.
            if (self.thread.len == 0 or self.reader_account.value().len == 0) return;
            if (same(self.reader_find_account.slice(), self.reader_account.value())) for (self.thread, 0..) |message, index| {
                if (!same(self.reader_find_message.slice(), text(get(message, "id")))) continue;
                self.reader_card = index;
                self.reader_cards[index] = true;
                self.reader_find_refresh = false;
                self.reader_find_reveal = true;
                return;
            };
            self.clearReaderFind();
            return;
        }
        // Keyboard focus may move to the list while the same thread card is
        // displayed. Its stable message ID, not focus-dependent reply routing,
        // defines the find target.
        if (self.reader_card >= self.thread.len or !same(self.reader_find_account.slice(), self.reader_account.value()) or !same(self.reader_find_message.slice(), text(get(self.thread[self.reader_card], "id")))) self.clearReaderFind();
    }
    fn readerFindBar(self: *App, outer: vaxis.Window) !void {
        if (!self.reader_find_active or outer.height == 0) return;
        const bar = outer.child(.{ .y_off = outer.height - 1, .height = 1 });
        const ordinal = if (self.reader_finder.count == 0) 0 else self.reader_finder.selected + 1;
        const count = try std.fmt.allocPrint(self.frame.allocator(), "{s}{d}/{d}{s}", .{ if (bar.width >= 12) @as([]const u8, "Find ") else "", ordinal, self.reader_finder.count, if (self.reader_finder.truncated) "+" else "" });
        const hints = if (self.thread.len == 0) @as([]const u8, " · waiting for message") else if (bar.width >= 56) " · n/N Match · Esc Done" else if (bar.width >= 30) " · n/N · Esc Done" else "";
        const hint_columns = positionAfter(bar, hints).column;
        const query_columns = bar.width -| @as(u16, @intCast(@min(count.len + 3, std.math.maxInt(u16)))) -| hint_columns;
        const query = if (query_columns > 0) try self.fitLine(bar, self.reader_find_query.slice(), query_columns) else "";
        const value = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}{s}{s}", .{ count, if (query.len > 0) @as([]const u8, " · ") else "", query, hints });
        var appearance = self.style(.accent);
        if (!self.mono) appearance.bg = .{ .rgb = self.palette.selection };
        bar.fill(.{ .style = appearance });
        _ = bar.printSegment(.{ .text = try self.fitLine(bar, value, bar.width), .style = appearance }, .{ .wrap = .none });
    }
    fn readerFindStyle(self: *const App, original: vaxis.Style, row: usize, byte_start: usize, byte_end: usize) vaxis.Style {
        if (!self.reader_find_active) return original;
        for (self.reader_finder.values[0..self.reader_finder.count], 0..) |match, index| {
            if (match.row > row) break;
            if (!reader_find.Model.overlaps(match, row, byte_start, byte_end)) continue;
            var result = original;
            const current = index == self.reader_finder.selected;
            result.bold = current;
            if (self.mono) {
                result.reverse = current;
                result.ul_style = .single;
            } else {
                result.bg = .{ .rgb = if (current) self.palette.accent else self.palette.selection };
                result.fg = .{ .rgb = if (current) self.palette.background else self.palette.foreground };
            }
            return result;
        }
        return original;
    }
    fn addReaderCopyLine(self: *App, row: usize, text_line: []const u8, options: reader_selection.LineOptions) void {
        if (self.reader_copy_error != null) return;
        const trimmed = std.mem.trim(u8, text_line, " ");
        if (same(trimmed, "[Signature folded · S shows it]") or same(trimmed, "[Quoted history folded · Q shows it]")) return;
        self.reader_copy.addLine(self.allocator, row, text_line, options) catch |err| {
            self.reader_copy_error = err;
        };
    }
    fn scanReaderFlow(self: *App, clean: []const u8, win: vaxis.Window, options: text_layout.Options) void {
        var iterator = text_layout.Iterator.init(clean, win.width, win.screen.width_method, options);
        var buffer: [32 * 1024]u8 = undefined;
        var length: usize = 0;
        var row = options.base_row;
        var join: reader_find.Join = .separate;
        var source_end: usize = 0;
        const copy_here = self.reader_copy_collect and self.reader_copy_scope and self.reader_find_text;
        var hidden_line = false;
        var hard_start: usize = 0;
        var hard_end = std.mem.indexOfScalar(u8, clean, '\n') orelse clean.len;
        var hard_hidden = same(std.mem.trim(u8, clean[0..hard_end], " "), "[Signature folded · S shows it]") or same(std.mem.trim(u8, clean[0..hard_end], " "), "[Quoted history folded · Q shows it]");
        while (iterator.next()) |glyph| {
            if (glyph.position.row != row) {
                if (self.reader_find_collect) self.reader_finder.addWrappedLine(buffer[0..length], row, join);
                if (copy_here) {
                    if (!hidden_line) self.addReaderCopyLine(row, buffer[0..length], .{ .join = @fromBackingInt(@intCast(@backingInt(join))) });
                    for (row + 1..glyph.position.row) |blank| self.addReaderCopyLine(blank, "", .{});
                }
                const gap = clean[@min(source_end, glyph.byte_offset)..glyph.byte_offset];
                join = if (glyph.position.row > row + 1 or std.mem.indexOfScalar(u8, gap, '\n') != null) .separate else if (gap.len > 0) .space else .none;
                row = glyph.position.row;
                length = 0;
                hidden_line = false;
            }
            if (copy_here) {
                while (glyph.byte_offset > hard_end and hard_end < clean.len) {
                    hard_start = hard_end + 1;
                    hard_end = std.mem.indexOfScalarPos(u8, clean, hard_start, '\n') orelse clean.len;
                    const source_line = std.mem.trim(u8, clean[hard_start..hard_end], " ");
                    hard_hidden = same(source_line, "[Signature folded · S shows it]") or same(source_line, "[Quoted history folded · Q shows it]");
                }
                hidden_line = hidden_line or hard_hidden;
            }
            if (glyph.text.len > buffer.len - length) {
                self.reader_finder.truncated = true;
                if (copy_here) self.reader_copy_error = error.ReaderSelectionTooLarge;
                return;
            }
            @memcpy(buffer[length..][0..glyph.text.len], glyph.text);
            length += glyph.text.len;
            source_end = iterator.offset;
        }
        if (self.reader_find_collect) self.reader_finder.addWrappedLine(buffer[0..length], row, join);
        if (copy_here) {
            if (!hidden_line) self.addReaderCopyLine(row, buffer[0..length], .{ .join = @fromBackingInt(@intCast(@backingInt(join))) });
            for (row + 1..iterator.position.row + 1) |blank| self.addReaderCopyLine(blank, "", .{});
        }
    }
    fn readerRichDraw(self: *App, prepared: *const html_view.Prepared, win: vaxis.Window, base_row: usize) usize {
        if (!self.reader_find_collect and !self.reader_copy_collect and !(self.reader_find_paint and self.reader_find_scope) and !(self.reader_copy_paint and self.reader_copy_scope)) return prepared.drawHighlightedFolded(win, self.reader_scroll, base_row, self.palette, self.mono, self.fold_quotes, self.fold_signatures, if (self.calendar.open) "" else self.search_highlight.value());
        var row = base_row;
        var in_quote = false;
        var in_signature = false;
        var after_hidden = true;
        var buffer: [32 * 1024]u8 = undefined;
        const highlight = self.search_highlight.value();
        for (prepared.cached.lines) |rendered_line| {
            const runs = prepared.cached.runs[rendered_line.first..][0..rendered_line.count];
            var quoted = false;
            var signature = false;
            for (runs) |segment| {
                quoted = quoted or segment.role == .quote;
                const marker = std.mem.trim(u8, segment.text, "\r\n");
                signature = signature or same(marker, "-- ") or (runs.len == 1 and segment.role == .text and same(marker, "--"));
            }
            if ((self.fold_quotes and quoted) or (self.fold_signatures and (signature or in_signature))) {
                const is_signature = self.fold_signatures and (signature or in_signature);
                if (if (is_signature) !in_signature else !in_quote) {
                    if (!self.reader_find_collect and !self.reader_copy_collect and row >= self.reader_scroll and row - self.reader_scroll < win.height) _ = win.printSegment(.{ .text = if (is_signature) "[Signature folded · S shows it]" else "[Quoted history folded · Q shows it]", .style = html_view.style(self.palette, self.mono, .{}, .quote) }, .{ .row_offset = @intCast(row - self.reader_scroll), .wrap = .none });
                    row += 1;
                }
                if (is_signature) in_signature = true else in_quote = true;
                after_hidden = true;
                continue;
            }
            in_quote = false;
            const absolute = row;
            row += 1;
            if (!self.reader_find_collect and !self.reader_copy_collect and (absolute < self.reader_scroll or absolute - self.reader_scroll >= win.height)) continue;
            var length: usize = 0;
            var source_bytes: usize = 0;
            var prefix: usize = 0;
            for (runs) |segment| {
                var glyphs = vaxis.unicode.graphemeIterator(segment.text);
                while (glyphs.next()) |gr| {
                    const glyph = text_layout.cellGrapheme(gr.bytes(segment.text), prepared.method);
                    if (glyph.len > buffer.len - length) break;
                    @memcpy(buffer[length..][0..glyph.len], glyph);
                    length += glyph.len;
                    source_bytes += gr.len;
                    if (source_bytes <= rendered_line.prefix_bytes) prefix = length;
                }
            }
            if (self.reader_find_collect or self.reader_copy_collect) {
                const join: reader_find.Join = if (after_hidden) .separate else @fromBackingInt(@intCast(@backingInt(rendered_line.join)));
                const skip = if (join == .separate) 0 else prefix;
                if (self.reader_copy_collect and self.reader_copy_scope) {
                    const columns = positionAfter(win, buffer[0..skip]).column;
                    self.addReaderCopyLine(absolute, buffer[skip..length], .{ .join = @fromBackingInt(@intCast(@backingInt(join))), .byte_base = skip, .column = columns });
                }
                if (self.reader_find_collect and self.reader_find_scope) {
                    self.reader_finder.addWrappedLineAt(buffer[skip..length], absolute, join, skip);
                }
                after_hidden = false;
                continue;
            }
            var column: u16 = 0;
            var byte_offset: usize = 0;
            var match = cache_query.findRange(buffer[0..length], highlight);
            for (runs) |segment| {
                var glyphs = vaxis.unicode.graphemeIterator(segment.text);
                while (glyphs.next()) |gr| {
                    const glyph = text_layout.cellGrapheme(gr.bytes(segment.text), prepared.method);
                    const columns = @max(vaxis.gwidth.gwidth(glyph, prepared.method), 1);
                    while (match) |match_at| {
                        if (byte_offset < match_at.end) break;
                        match = cache_query.findRangeAt(buffer[0..length], highlight, match_at.end);
                    }
                    var appearance = html_view.style(self.palette, self.mono, segment.flags, segment.role);
                    if (match) |match_at| if (byte_offset >= match_at.start and byte_offset < match_at.end) {
                        appearance.bold = true;
                        if (self.mono) appearance.reverse = true else {
                            appearance.fg = .{ .rgb = self.palette.background };
                            appearance.bg = .{ .rgb = self.palette.yellow };
                        }
                    };
                    if (rendered_line.join == .separate or byte_offset >= prefix) appearance = self.readerFindStyle(appearance, absolute, byte_offset, byte_offset + glyph.len);
                    appearance = self.readerCopyStyle(appearance, absolute, byte_offset, byte_offset + glyph.len);
                    if (column +| columns <= win.width) win.writeCell(column, @intCast(absolute - self.reader_scroll), .{ .char = .{ .grapheme = glyph, .width = @intCast(@min(columns, 255)) }, .style = appearance });
                    column +|= columns;
                    byte_offset += glyph.len;
                }
            }
        }
        return row;
    }
    fn readerDraw(self: *App, outer: vaxis.Window) !void {
        self.reconcileReaderFind();
        self.reconcileReaderCopy();
        self.mouseArea(outer, .reader, 0);
        const browsing = self.mode == .browse or (self.mode == .help and self.previous_mode == .browse) or (self.mode == .command and self.previous_mode == .browse);
        const copy_rows: u16 = if (browsing and self.readerCopyVisible() and outer.height > 0) 1 else 0;
        const find_rows: u16 = if (copy_rows == 0 and browsing and self.reader_find_active and outer.height > 0) 1 else 0;
        const toolbar_rows: u16 = if (browsing and self.focus != .reader and !self.expanded and outer.height >= 18 and outer.width >= 60) 1 else 0;
        const summary_rows: u16 = if (browsing and self.thread.len > 1 and outer.height >= 6) 1 else 0;
        if (toolbar_rows > 0) try self.line(outer, 0, try self.fitLine(outer, if (!self.capabilities.open_urls) "l Focus reader · r Reply · f Forward" else "l Focus reader · o Gmail · L Links · B Files", outer.width), .accent);
        const partial_rows: u16 = if (self.reader_partial and outer.height >= 14) 1 else 0;
        if (partial_rows > 0) {
            const notice = if (self.reader_progressive) try std.fmt.allocPrint(self.frame.allocator(), "{s}{d} bodies on demand · [ {d} older · ] {d} newer", .{ if (self.reader_cached_view) @as([]const u8, "Cached subset · ") else "", self.reader_deferred_messages, self.reader_older_messages, self.reader_newer_messages }) else if (self.reader_omitted_messages > 0) try std.fmt.allocPrint(self.frame.allocator(), "Thread · partial · {d} earlier messages omitted", .{self.reader_omitted_messages}) else if (self.reader_cached_view) "Cached thread · partial" else "Thread · partial";
            try self.line(outer, toolbar_rows + summary_rows, notice, .warning);
        }
        const invitation_index = self.readerInvitationIndex();
        const follow_up_entry = if (!browser_target and browsing) self.followUpEntry(self.readerReplyId()) else null;
        const follow_up_rows: u16 = if (follow_up_entry != null and outer.height >= 7) 1 else 0;
        if (follow_up_rows > 0) {
            const due = text(get(follow_up_entry.?, "dueDate"));
            const today = self.followUpToday() catch "";
            const caption = try std.fmt.allocPrint(self.frame.allocator(), "Follow up {s}{s} · b Change", .{ due, if (std.mem.lessThan(u8, due, today)) @as([]const u8, " · overdue") else if (same(due, today)) " · today" else "" });
            try self.line(outer, toolbar_rows + summary_rows + partial_rows, try self.fitLine(outer, caption, outer.width), .accent);
        }
        const header_rows = toolbar_rows + summary_rows + partial_rows + follow_up_rows;
        const win = outer.child(.{ .y_off = header_rows, .height = outer.height -| header_rows -| find_rows -| copy_rows });
        self.reader_height = win.height;
        self.reader_copy_rect = .{ .x = @intCast(win.x_off), .y = @intCast(win.y_off), .width = win.width, .height = win.height };
        // Measure the new body before clamping a restored scroll position.
        // clearReader resets the old line count, not the persisted position.
        if (self.thread.len == 0) {
            if (self.reader_cache_busy) {
                try self.line(win, 1, "Cache busy · local read queued", .muted);
                try self.line(win, 3, "Input or refresh completion retries locally", .muted);
            } else if (self.body_cache_miss) {
                const fetching = self.job.future != null and (self.job.kind == .read or self.job.kind == .thread);
                const refused = if (self.selectedMessage()) |message| bodyRefusal(message) else null;
                const notice_end = try self.flowTone(win, if (refused) |reason| try std.fmt.allocPrint(self.frame.allocator(), "Body unavailable · {s}", .{reason}) else if (fetching or self.pending_read) try std.fmt.allocPrint(self.frame.allocator(), "{s} {s}", .{ loading.frame(self.loading_frame), if (fetching) "Fetching mail body…" else "Mail body queued…" }) else if (self.follow_ups_list) "Message not available offline\nReminder kept · Enter Fetch" else "Body not cached · Enter fetches full mail", 0, 1, if (refused != null) .warning else if (fetching or self.pending_read) .fetching else .muted);
                if (self.selectedMessage()) |message| {
                    try self.line(win, notice_end + 1, text(get(message, "subject")), .text);
                    if (refused != null) try self.line(win, notice_end + 2, if (!self.capabilities.open_urls) "Snippet only · full body unavailable" else "Snippet only · o Open in Gmail", .muted);
                    _ = try self.flow(win, text(get(message, "snippet")), 0, notice_end + 3);
                }
            } else try self.line(win, 1, if (self.sync[self.account_index].state == .fetching) "Fetching mail · cached bodies appear here" else "Select mail · Enter opens the thread", .muted);
            if (find_rows > 0) try self.readerFindBar(outer);
            return;
        }
        const body_hit_start = self.mouse_hits.count;
        if (self.reader_find_active) {
            const previous = self.reader_finder.current();
            const key = self.readerFindLayoutKey(win);
            if (self.reader_find_layout_key == null or self.reader_find_layout_key.? != key) {
                self.reader_finder.clearMatches();
                self.reader_find_collect = true;
                self.reader_lines = self.readerBodyDraw(win) catch |err| {
                    self.reader_find_collect = false;
                    return err;
                };
                self.reader_find_collect = false;
                self.mouse_hits.count = body_hit_start;
                self.reader_finder.finish();
                self.reader_find_layout_key = key;
            }
            if (self.reader_finder.current()) |match| {
                const moved = if (previous) |old| old.row != match.row or old.end_row != match.end_row else true;
                if (self.reader_find_reveal or moved or self.reader_find_width != win.width or self.reader_find_height != win.height) {
                    self.reader_scroll = @min(match.row -| @as(usize, win.height / 3), readerEnd(self.reader_lines, win.height));
                    self.reader_anchor_card = false;
                    self.reader_card_pinned = false;
                }
            }
            self.reader_find_reveal = false;
            self.reader_find_width = win.width;
            self.reader_find_height = win.height;
        }
        if (self.readerCopyVisible()) {
            if (self.reader_copy.ready and (self.reader_copy.width != win.width or self.reader_copy.method != win.screen.width_method or self.reader_copy_height != win.height)) {
                self.reader_copy_mark = self.reader_copy.mark();
                self.reader_copy.ready = false;
            }
            if (!self.reader_copy.ready) {
                self.reader_copy.reset(self.allocator, self.reader_copy_generation, win.width, win.screen.width_method);
                self.reader_copy_error = null;
                self.reader_copy_collect = true;
                _ = self.readerBodyDraw(win) catch |err| {
                    self.reader_copy_collect = false;
                    return err;
                };
                self.reader_copy_collect = false;
                self.mouse_hits.count = body_hit_start;
                self.reader_copy.finish();
                self.reader_copy_height = win.height;
                if (self.reader_copy_error) |err| {
                    self.clearReaderCopy();
                    self.sayFailure("Selection unavailable · e opens an editor snapshot", @errorName(err));
                } else if (self.reader_copy_mark) |mark| {
                    self.reader_copy_mark = null;
                    if (!self.reader_copy.restore(mark)) self.readerCopyChanged() else self.revealReaderCopyCursor();
                } else if (self.reader_copy_request) |request| {
                    self.reader_copy_request = null;
                    if (request.end_row != null and !self.reader_copy.containsRow(request.row)) self.readerCopyChanged() else if (self.reader_copy.begin(request.mode, request.row, request.column)) {
                        if (request.end_row) |end| self.reader_copy.extend(end, request.end_column);
                        self.revealReaderCopyCursor();
                    } else {
                        self.clearReaderCopy();
                        self.say(false, "No selectable body text · e opens the message snapshot", .{});
                    }
                }
            }
        }
        const painted_scroll = self.reader_scroll;
        self.reader_copy_paint = self.reader_copy.active();
        self.reader_find_paint = self.reader_find_active;
        defer {
            self.reader_find_paint = false;
            self.reader_find_scope = false;
            self.reader_copy_paint = false;
            self.reader_copy_scope = false;
        }
        self.reader_lines = try self.readerBodyDraw(win);
        if (self.reader_anchor_card) {
            self.reader_scroll = self.reader_card_rows[self.reader_card];
            self.reader_anchor_card = false;
        }
        const clamped = @min(self.reader_scroll, self.readerScrollEnd());
        self.reader_scroll = clamped;
        if (clamped != painted_scroll) {
            // A wider layout can reduce wrapping below the old scroll
            // position. Repaint the corrected viewport once in this frame;
            // never wait for another key or schedule a redraw loop.
            win.fill(.{ .style = self.style(.text) });
            self.mouse_hits.count = body_hit_start;
            self.reader_lines = try self.readerBodyDraw(win);
        }
        // Blank paragraphs still need a visible caret while positioning. They
        // remain empty in the copied model; this is only a painted cursor cell.
        if (self.reader_copy.active() and self.reader_copy.lineText(self.reader_copy.cursor.line).len == 0) {
            const cursor_row = self.reader_copy.cursorRow().?;
            const cursor_column = self.reader_copy.cursorColumn().?;
            if (cursor_row >= self.reader_scroll and cursor_row - self.reader_scroll < win.height and cursor_column < win.width) {
                var appearance = self.style(.text);
                if (self.mono) {
                    appearance.reverse = true;
                    appearance.bold = true;
                    appearance.ul_style = .single;
                } else {
                    appearance.bg = .{ .rgb = self.palette.accent };
                    appearance.fg = .{ .rgb = self.palette.background };
                }
                win.writeCell(@intCast(cursor_column), @intCast(cursor_row - self.reader_scroll), .{ .char = .{ .grapheme = " ", .width = 1 }, .style = appearance });
            }
        }
        if (!self.readerCopyVisible()) if (invitation_index) |index| if (self.reader_invitation_row) |logical_row| {
            // Follow the message's labels while its header is visible, then
            // pin the same distinct action at the viewport edge while scrolling.
            const rows = readerInvitationRows(win);
            if (rows > 0) {
                const position = @min(logical_row -| self.reader_scroll, win.height - rows);
                try self.readerInvitationDraw(win.child(.{ .y_off = @intCast(position), .height = rows }), index);
            }
        };
        if (summary_rows > 0) {
            var unread: usize = 0;
            for (self.thread) |message| unread += @intFromBool(truth(get(message, "unread")));
            const earlier = if (self.reader_card > 0 and self.reader_scroll >= self.reader_card_rows[self.reader_card]) try std.fmt.allocPrint(self.frame.allocator(), " · ↑{d} earlier", .{self.reader_card}) else "";
            const summary = if (self.reader_progressive) try std.fmt.allocPrint(self.frame.allocator(), "{d}/{d} mails · window {d}–{d}{s} · {s}", .{ self.reader_older_messages + self.reader_card + 1, self.reader_total_messages, self.reader_older_messages + 1, self.reader_older_messages + self.thread.len, if (self.reader_cached_view) @as([]const u8, " cached") else "", try self.readerProgressText() }) else try std.fmt.allocPrint(self.frame.allocator(), "{d}/{d} mails · {d} unread{s} · {s}", .{ self.reader_card + 1, self.thread.len, unread, earlier, try self.readerProgressText() });
            try self.line(outer, toolbar_rows, try self.fitLine(outer, summary, outer.width), .muted);
        }
        if (find_rows > 0) try self.readerFindBar(outer);
        if (self.readerCopyVisible()) try self.readerCopyBar(outer);
    }
    fn readerFindLayoutKey(self: *App, win: vaxis.Window) u64 {
        var hash = std.hash.Wyhash.init(self.reader_copy_generation);
        hash.update(std.mem.asBytes(&win.width));
        hash.update(std.mem.asBytes(&win.height));
        hash.update(&.{ @intCast(@backingInt(win.screen.width_method)), @intFromBool(self.fold_quotes), @intFromBool(self.fold_signatures), @intFromBool(self.readerCopyVisible()), @intCast(@backingInt(self.ui_preferences.density)) });
        hash.update(self.reader_find_query.slice());
        const invitation_index = self.readerInvitationIndex() orelse std.math.maxInt(usize);
        hash.update(std.mem.asBytes(&invitation_index));
        for (self.reader_cards[0..self.thread.len]) |open| hash.update(&.{@intFromBool(open)});
        for (self.markup) |view| hash.update(&.{ @intCast(@backingInt(view.mode)), @intFromBool(view.details) });
        // Resolved label names can wrap and move the body without replacing
        // its bytes. Include them in the same layout generation.
        for (self.labels) |label| {
            hash.update(text(get(label, "id")));
            hash.update("\x00");
            hash.update(text(get(label, "name")));
            hash.update("\x00");
        }
        return hash.final();
    }
    fn readerScrollEnd(self: *const App) usize {
        const end = readerEnd(self.reader_lines, self.reader_height);
        return if (self.reader_card_pinned and self.reader_card < self.thread.len) @max(end, self.reader_card_rows[self.reader_card]) else end;
    }
    fn scrollReader(self: *App, down: bool, amount: usize) void {
        if (self.mode == .compose and (self.compose_view != .original or self.compose.original != null)) {
            const scroll = if (self.compose_view == .plain) &self.compose_plain_scroll else if (self.compose_view == .original) &self.compose_snapshot_scroll else &self.compose_preview_scroll;
            scroll.* = if (down) @min(scroll.* +| amount, readerEnd(self.compose_preview_lines, self.compose_preview_height)) else scroll.* -| amount;
            return;
        }
        self.reader_anchor_card = false;
        self.reader_card_pinned = false;
        self.reader_scroll = if (down) @min(self.reader_scroll +| amount, readerEnd(self.reader_lines, self.reader_height)) else self.reader_scroll -| amount;
    }
    fn readerProgressText(self: *App) ![]const u8 {
        const visible_end = @min(self.reader_scroll +| self.reader_height, self.reader_lines);
        const percent: usize = if (self.reader_lines == 0) 0 else @intCast(@min(@as(u128, 100), @divTrunc(@as(u128, visible_end) * 100, self.reader_lines)));
        return std.fmt.allocPrint(self.frame.allocator(), "{d}% · {d}–{d}/{d}", .{ percent, if (self.reader_lines == 0) @as(usize, 0) else self.reader_scroll + 1, visible_end, self.reader_lines });
    }
    fn readerMouseRows(self: *App, win: vaxis.Window, row: usize, height: usize, kind: layout.HitKind, index: usize) void {
        const first = @max(row, self.reader_scroll);
        const end = @min(row +| height, self.reader_scroll +| win.height);
        if (end <= first) return;
        self.mouseRows(win, first - self.reader_scroll, @intCast(end - first), kind, index);
    }
    fn readerLabelName(self: *const App, identifier: []const u8) ?[]const u8 {
        if (same(self.labels_account.value(), self.account())) for (self.labels) |label| {
            if (same(text(get(label, "id")), identifier) and text(get(label, "name")).len > 0) return text(get(label, "name"));
        };
        for ([_][]const u8{ "INBOX", "SENT", "DRAFT", "TRASH", "SPAM", "IMPORTANT", "CATEGORY_PERSONAL", "CATEGORY_SOCIAL", "CATEGORY_PROMOTIONS", "CATEGORY_UPDATES", "CATEGORY_FORUMS" }, [_][]const u8{ "Inbox", "Sent", "Drafts", "Trash", "Spam", "Important", "Personal", "Social", "Promotions", "Updates", "Forums" }) |id, name| if (same(id, identifier)) return name;
        return null;
    }
    fn readerLabels(self: *App, message: Value) ![]const u8 {
        var result: std.ArrayList(u8) = .empty;
        const a = self.frame.allocator();
        var unresolved: usize = 0;
        for (items(get(message, "labels"))) |label| {
            const id = text(label);
            if (same(id, "UNREAD") or same(id, "STARRED") or id.len == 0) continue;
            const name = self.readerLabelName(id) orelse {
                unresolved += 1;
                continue;
            };
            if (result.items.len == 0) try result.appendSlice(a, "Labels: ") else try result.appendSlice(a, " · ");
            const clean = try safe(a, name, false);
            var end = @min(clean.len, 256);
            while (end > 0 and !std.unicode.utf8ValidateSlice(clean[0..end])) end -= 1;
            try result.appendSlice(a, clean[0..end]);
            if (result.items.len >= 1024) {
                try result.appendSlice(a, " · …");
                break;
            }
        }
        if (unresolved > 0) {
            if (result.items.len == 0) try result.appendSlice(a, "Labels: ") else try result.appendSlice(a, " · ");
            try result.appendSlice(a, try std.fmt.allocPrint(a, "{d} awaiting names", .{unresolved}));
        }
        return result.items;
    }
    fn readerBodyDraw(self: *App, win: vaxis.Window) !usize {
        var row: usize = 0;
        const natural_height = win.height +| @as(u16, if (self.readerCopyVisible() and !self.reader_find_active) 1 else 0);
        var layout_win = win;
        layout_win.height = natural_height;
        self.reader_body_bounds = @splat(null);
        self.reader_invitation_row = null;
        const invitation_index = self.readerInvitationIndex();
        var attachment_number: usize = 0;
        for (self.thread, 0..) |message, message_index| {
            self.reader_copy_scope = false;
            self.reader_find_scope = self.reader_find_active and same(self.reader_find_message.slice(), text(get(message, "id")));
            self.reader_card_rows[message_index] = row;
            const from = get(message, "from");
            if (self.thread.len > 1) {
                const stamp = try timestamp(self.frame.allocator(), &self.zone, get(message, "receivedAt"));
                const partial = metadataWarning(message) != null or bodyRefusal(message) != null;
                const heading = try std.fmt.allocPrint(self.frame.allocator(), "{s} {d}/{d} {s}{s}{s} · {s}", .{ if (self.reader_cards[message_index]) "▾" else "▸", message_index + 1, self.thread.len, if (partial) @as([]const u8, "Warning · ") else "", if (truth(get(message, "unread"))) "● " else "", if (text(get(from, "name")).len > 0) text(get(from, "name")) else text(get(from, "address")), if (stamp.len >= 16) stamp[5..16] else stamp });
                const block_start = row;
                row = try self.flowTone(win, try self.fitLine(win, heading, win.width), self.reader_scroll, row, if (partial) .warning else if (message_index == self.reader_card) .accent else .sender);
                self.readerMouseRows(win, block_start, row - block_start, .reader_thread, message_index);
                if (!self.reader_cards[message_index]) {
                    if (invitation_index == message_index) {
                        const rows = readerInvitationRows(layout_win);
                        if (rows > 0) {
                            self.reader_invitation_row = row;
                            row += rows;
                        }
                    }
                    attachment_number += items(get(message, "attachments")).len;
                    continue;
                }
            }
            const show_details = message_index < self.markup.len and self.markup[message_index].details;
            const compact = !show_details and (natural_height <= 12 or win.width < 60 or self.ui_preferences.density == .compact);
            const single_header = compact and self.ui_preferences.density == .compact and win.width < 100;
            const to = try displayMailboxes(self.frame.allocator(), get(message, "to"), displayIncomingMailbox);
            const cc = try displayMailboxes(self.frame.allocator(), get(message, "cc"), displayIncomingMailbox);
            const subject = text(get(message, "subject"));
            const shown_subject = if (subject.len == 0) "(no subject)" else subject;
            const stamp = try timestamp(self.frame.allocator(), &self.zone, get(message, "receivedAt"));
            if (single_header) {
                const who = if (text(get(from, "name")).len > 0) text(get(from, "name")) else text(get(from, "address"));
                const header = try std.fmt.allocPrint(self.frame.allocator(), "{s} · {s} · {s} · H Details", .{ who, if (stamp.len >= 16) stamp[5..16] else stamp, shown_subject });
                row = try self.flowTone(win, try self.fitLine(win, header, win.width), self.reader_scroll, row, .subject);
            } else row = try self.flowTone(win, if (compact) try self.fitLine(win, shown_subject, win.width) else shown_subject, self.reader_scroll, row, .subject);
            if (!single_header and (!compact or self.thread.len == 1)) {
                const sender_line = try std.fmt.allocPrint(self.frame.allocator(), "From: {s} <{s}>{s}{s}", .{ text(get(from, "name")), text(get(from, "address")), if (compact and stamp.len > 0) " · " else "", if (compact) (if (stamp.len >= 16) stamp[5..16] else stamp) else "" });
                row = try self.flowTone(win, if (compact) try self.fitLine(win, sender_line, win.width) else sender_line, self.reader_scroll, row, .sender);
            }
            if (single_header) {
                // Full recipients and status remain available through H.
            } else if (compact) {
                if (to.len > 0 or cc.len > 0) {
                    const envelope = try std.fmt.allocPrint(self.frame.allocator(), "To: {s}{s}{s}", .{ to, if (cc.len > 0) " · Cc: " else "", cc });
                    row = try self.flowTone(win, try self.fitLine(win, envelope, win.width), self.reader_scroll, row, .muted);
                }
            } else {
                const envelope = if (self.thread.len > 1) (if (cc.len > 0) try std.fmt.allocPrint(self.frame.allocator(), "To: {s}\nCc: {s}", .{ to, cc }) else try std.fmt.allocPrint(self.frame.allocator(), "To: {s}", .{to})) else try readerEnvelope(self.frame.allocator(), to, cc, stamp);
                row = try self.flowTone(win, envelope, self.reader_scroll, row, .muted);
            }
            if (!single_header) {
                const status = try std.fmt.allocPrint(self.frame.allocator(), "{s}{s}", .{ if (messageUnread(message)) @as([]const u8, "● Unread") else "Read", if (messageHasLabel(message, "STARRED") or truth(get(message, "starred"))) @as([]const u8, " · ⭐ Starred") else "" });
                row = try self.flowTone(win, status, self.reader_scroll, row, .muted);
                const labels = try self.readerLabels(message);
                if (labels.len > 0) row = try self.flowTone(win, labels, self.reader_scroll, row, .accent);
            }
            if (bodyRefusal(message)) |code| {
                const notice = try std.fmt.allocPrint(self.frame.allocator(), "Body unavailable · {s} ({s})", .{ decodeWarningLabel(code), code });
                row = try self.flowTone(win, notice, self.reader_scroll, row, .warning);
                // A refused DTO is metadata only, even if a malformed legacy
                // record still carries text or HTML beside its diagnostic.
                self.reader_body_bounds[message_index] = .{ .start = row, .end = row };
                attachment_number += items(get(message, "attachments")).len;
                row = try self.flow(win, "\n────────────────────\n", self.reader_scroll, row);
                continue;
            }
            if (self.reader_progressive and !truth(get(message, "bodyCached"))) {
                const waiting = self.job.future != null and self.job.kind == .thread;
                row = try self.flowTone(win, if (waiting) "Loading selected body…" else "Body on demand · t closes/opens and fetches · { / } selects", self.reader_scroll, row, if (waiting) .fetching else .muted);
                row = try self.flowTone(win, text(get(message, "snippet")), self.reader_scroll, row, .muted);
                self.reader_body_bounds[message_index] = .{ .start = row, .end = row };
                attachment_number += items(get(message, "attachments")).len;
                continue;
            }
            if (metadataWarning(message)) |code| {
                const notice = try std.fmt.allocPrint(self.frame.allocator(), "Warning · {s} ({s})", .{ decodeWarningLabel(code), code });
                row = try self.flowTone(win, notice, self.reader_scroll, row, .warning);
            }
            if (invitation_index == message_index) {
                const rows = readerInvitationRows(layout_win);
                if (rows > 0) {
                    if (natural_height >= 12) row += 1;
                    self.reader_invitation_row = row;
                    row += rows;
                }
            }
            if (self.ui_preferences.density != .compact) row += 1;
            if (message_index < self.markup.len and text(get(message, "bodyHtml")).len > 0) {
                const view_label = if (self.readerFormatted(self.markup[message_index], message)) @as([]const u8, "Formatted · p Plain · H Details") else "Plain · p Formatted · H Details";
                row = try self.flowTone(win, view_label, self.reader_scroll, row, .muted);
            }
            const body_start = row;
            self.reader_copy_scope = same(self.reader_copy_message.slice(), text(get(message, "id"))) and same(self.reader_copy_account.slice(), self.account());
            var rich_drawn = false;
            if (message_index < self.markup.len) {
                const view = &self.markup[message_index];
                if (self.readerFormatted(view.*, message)) self.prepareVisibleMarkup(view, message);
                if (self.readerFormatted(view.*, message)) if (view.prepared) |*prepared| {
                    const builds = prepared.layout_builds;
                    const ready = blk: {
                        prepared.ensure(win.width, win.screen.width_method) catch {
                            if (prepared.layout_builds != builds) self.html_stats.htmlFallbacks += 1;
                            view.fallback = true;
                            break :blk false;
                        };
                        break :blk true;
                    };
                    self.html_stats.htmlLayoutBuilds += prepared.layout_builds - builds;
                    if (ready) {
                        view.fallback = false;
                        row = self.readerRichDraw(prepared, win, row);
                        rich_drawn = true;
                    }
                };
                if (view.fallback and self.readerFormatted(view.*, message)) row = try self.flowTone(win, "Plain text · HTML layout unavailable", self.reader_scroll, row, .muted);
            }
            if (!rich_drawn) {
                const body = if (message_index < self.markup.len) self.markup[message_index].display_text orelse text(get(message, "bodyText")) else text(get(message, "bodyText"));
                if (message_index < self.markup.len) {
                    row = try self.preparedPlainDraw(&self.markup[message_index], win, body, row);
                } else {
                    const folded = try reader_tools.fold(self.frame.allocator(), body, self.fold_quotes, self.fold_signatures);
                    row = try self.flowReaderText(win, folded.text, self.reader_scroll, row);
                }
            }
            self.reader_body_bounds[message_index] = .{ .start = body_start, .end = row };
            self.reader_copy_scope = false;
            var links_in_text: reader_tools.Links = .{};
            reader_tools.findLinks(text(get(message, "bodyText")), &links_in_text);
            if (links_in_text.count > 0 or std.mem.indexOf(u8, text(get(message, "bodyHtml")), "href=") != null) {
                const block_start = row;
                row = try self.flowTone(win, if (!self.capabilities.open_urls) "Links shown literally · opening is unavailable on this platform" else "Links · L chooses a literal URL to open", self.reader_scroll, row, .sender);
                if (self.capabilities.open_urls) self.readerMouseRows(win, block_start, row - block_start, .reader_link, 0);
            }
            for (items(get(message, "attachments")), 0..) |attachment, attachment_index| {
                attachment_number += 1;
                const size_value = get(attachment, "size");
                const size: u64 = if (size_value == .integer and size_value.integer >= 0) @intCast(size_value.integer) else 0;
                const title = try std.fmt.allocPrint(self.frame.allocator(), "Attachment {d}: {s} · {s}", .{ attachment_index + 1, text(get(attachment, "filename")), try attachmentSizeLabel(self.frame.allocator(), size) });
                const action: []const u8 = if (self.capabilities.files) (if (win.width >= 13) "[B Save/open]" else "[B]") else "file access unavailable";
                const together = try std.fmt.allocPrint(self.frame.allocator(), "{s} · {s}", .{ title, action });
                const block_start = row;
                if (positionAfter(win, together).row == 0) {
                    row = try self.flowTone(win, together, self.reader_scroll, row, .sender);
                } else {
                    row = try self.flowTone(win, title, self.reader_scroll, row, .sender);
                    row = try self.flowTone(win, action, self.reader_scroll, row, .sender);
                }
                if (self.capabilities.files) self.readerMouseRows(win, block_start, row - block_start, .reader_attachment, attachment_number - 1);
            }
            if (self.ui_preferences.density != .compact) row = try self.flow(win, "\n────────────────────\n", self.reader_scroll, row);
        }
        return row;
    }
    fn composeAttachmentsDraw(self: *App, win: vaxis.Window, row: usize, visible: usize) !void {
        if (!self.capabilities.attachments) {
            try self.line(win, row, "Attachments unavailable · Ctrl+S Review · a Contacts", .muted);
            return;
        }
        self.compose.attachment_height = visible;
        if (self.compose.attachment_focus and self.compose.attachment_cursor > 0 and self.compose.attachment_cursor <= self.compose.attachments.len and visible > 0) {
            const chosen = self.compose.attachment_cursor - 1;
            if (chosen < self.compose.attachment_scroll) self.compose.attachment_scroll = chosen;
            if (chosen >= self.compose.attachment_scroll + visible) self.compose.attachment_scroll = chosen + 1 - visible;
        }
        self.compose.attachment_scroll = @min(self.compose.attachment_scroll, self.compose.attachments.len -| visible);
        if (row >= win.height or win.width == 0) return;
        const viewport = win.child(.{ .y_off = @intCast(row), .height = @intCast(visible + 1) });
        self.mouseArea(viewport, .compose_attachment_scroll, 0);
        const can_edit = self.canEditAttachments();
        const add = if (self.capabilities.files) "[Add A]" else "";
        const add_width: u16 = @intCast(@min(add.len, win.width));
        const add_x = win.width - add_width;
        var attachment_bytes: usize = 0;
        for (self.compose.attachments) |attachment| attachment_bytes +|= attachment.size;
        const title = if (self.capabilities.files) try std.fmt.allocPrint(self.frame.allocator(), "Attachments {d} · {s} / {s}", .{ self.compose.attachments.len, try attachmentSizeLabel(self.frame.allocator(), attachment_bytes), try attachmentSizeLabel(self.frame.allocator(), types.Limits.attachment_bytes) }) else try std.fmt.allocPrint(self.frame.allocator(), "Attachments {d} · {s}", .{ self.compose.attachments.len, try attachmentSizeLabel(self.frame.allocator(), attachment_bytes) });
        try self.line(viewport.child(.{ .width = add_x -| 1 }), 0, title, .muted);
        const add_button = viewport.child(.{ .x_off = add_x, .width = add_width, .height = 1 });
        try self.line(add_button, 0, add, if (!can_edit or !self.capabilities.files) .muted else if (self.compose.attachment_focus and self.compose.attachment_cursor == 0) .selected else .accent);
        if (can_edit and self.capabilities.files) self.mouseArea(add_button, .compose_attachment_add, 0);
        const end = @min(self.compose.attachment_scroll + visible, self.compose.attachments.len);
        for (self.compose.attachments[self.compose.attachment_scroll..end], self.compose.attachment_scroll..) |attachment, index| {
            const file_row = viewport.child(.{ .y_off = @intCast(index - self.compose.attachment_scroll + 1), .height = 1 });
            const focused = self.compose.attachment_focus and self.compose.attachment_cursor == index + 1;
            file_row.fill(.{ .style = self.style(if (focused) .selected else .text) });
            self.mouseArea(file_row, .compose_attachment_select, index);
            const remove_width: u16 = @min(3, file_row.width);
            const remove_x = file_row.width - remove_width;
            const size = try attachmentSizeLabel(self.frame.allocator(), attachment.size);
            const size_right = remove_x -| 1;
            const size_width: u16 = @intCast(@min(size.len, size_right));
            const size_x = size_right - size_width;
            try self.line(file_row.child(.{ .width = size_x -| 1 }), 0, try std.fmt.allocPrint(self.frame.allocator(), "{d}. {s}", .{ index + 1, attachment.filename }), .text);
            try self.line(file_row.child(.{ .x_off = size_x, .width = size_width }), 0, size, .muted);
            const remove_button = file_row.child(.{ .x_off = remove_x, .width = remove_width });
            try self.line(remove_button, 0, "[x]", if (!can_edit) .muted else if (focused) .selected else .accent);
            if (can_edit) self.mouseArea(remove_button, .compose_attachment_remove, index);
        }
    }
    fn composeCompletionDraw(self: *App, win: vaxis.Window) !void {
        if (self.compose.attachment_focus) return;
        const matches = self.composeCompletions();
        if (win.width < 20) return;
        const header_row: usize = if (self.compose.unknown_outcome or self.compose.original != null or self.compose_source_mode == .attached or self.compose.omitted_attachments > 0) 2 else 1;
        const row = self.compose.selected + header_row + 1;
        if (matches.len == 0) {
            if (!self.compose.insert_mode or self.compose.selected >= 3 or matches.range.query.len == 0) return;
            recipients.validateAddress(matches.range.query) catch {
                if (row < win.height) try self.line(win, row, self.recipientHint(), .muted);
            };
            return;
        }
        const visible: usize = @min(4, @min(matches.len, win.height -| (row + 2)));
        if (visible == 0) return;
        self.compose.completion_selected = @min(self.compose.completion_selected, matches.len - 1);
        const top = self.compose.completion_selected -| (visible - 1);
        const popup = win.child(.{ .y_off = @intCast(row), .height = @intCast(visible + 1) });
        popup.fill(.{ .style = self.style(.text) });
        try self.line(popup, 0, "Recipients · Ctrl+N/P · Enter accepts", .muted);
        for (matches.values[top .. top + visible], top..) |candidate, index| {
            const label = if (candidate.name.len > 0) try std.fmt.allocPrint(self.frame.allocator(), "{s} <{s}>", .{ candidate.name, candidate.address }) else candidate.address;
            try self.line(popup, index - top + 1, label, if (index == self.compose.completion_selected) .selected else .text);
            self.mouseRows(popup, index - top + 1, 1, .compose_completion, index);
        }
    }
    /// Native actions own their rows below the complete composer, including
    /// the narrow full-preview page. They never compete with body controls.
    fn composeActionsDraw(self: *App, win: vaxis.Window) !u16 {
        self.compose_action_mask = 0;
        self.compose_action_drawn = 0;
        if (browser_target or !self.compose_active or self.compose.id.value().len == 0 or win.height < 2) return 0;
        const show_browser = self.capabilities.open_urls;
        const show_gmail = !self.compose.unknown_outcome;
        if (!show_browser and !show_gmail) return 0;
        const normal_browser = "[P Preview in browser]";
        const normal_gmail = if (self.compose.gmailPaused()) "[g Gmail status]" else "[g Continue in Gmail]";
        const width_needed = (if (show_browser) normal_browser.len else @as(usize, 0)) + (if (show_gmail) normal_gmail.len else @as(usize, 0)) + (if (show_browser and show_gmail) @as(usize, 2) else 0);
        // The usual 38-column terminal keeps two complete labels and five
        // body rows. A short terminal uses compact labels on one row instead.
        const two_rows = width_needed > win.width and show_browser and show_gmail and win.height >= 18;
        const compact = width_needed > win.width and !two_rows;
        const rows: u16 = if (two_rows) 2 else 1;
        const browser_label: []const u8 = if (compact) (if (self.compose.insert_mode) "[  Browser]" else "[P Browser]") else if (self.compose.insert_mode) "[  Preview in browser]" else normal_browser;
        const gmail_label: []const u8 = if (compact) (if (self.compose.insert_mode) "[  Gmail]" else "[g Gmail]") else if (self.compose.insert_mode) (if (self.compose.gmailPaused()) "[  Gmail status]" else "[  Continue in Gmail]") else normal_gmail;
        const enabled = self.job.future == null or readOnlyJob(self.job.kind);
        const narrow_preview = self.compose_preview_full and win.width < 90 and !self.compose.unknown_outcome;
        var x: u16 = 0;
        const row = win.height - rows;
        if (show_browser and browser_label.len <= win.width) {
            const focused = if (narrow_preview) self.dialog_focus.context == .preview and self.dialog_focus.index == 3 else self.compose.attachment_focus and self.compose.attachment_cursor == self.compose.attachments.len + 4;
            x = try self.actionButton(win, row, 0, browser_label, focused, enabled, .compose_browser_preview, 0);
            self.compose_action_drawn |= 1;
            if (enabled) self.compose_action_mask |= 1;
        }
        const gmail_row = row + @as(u16, if (two_rows) 1 else 0);
        if (two_rows) x = 0;
        if (show_gmail and x + gmail_label.len <= win.width) {
            const focused = if (narrow_preview) self.dialog_focus.context == .preview and self.dialog_focus.index == 4 else self.compose.attachment_focus and self.compose.attachment_cursor == self.compose.attachments.len + 5;
            _ = try self.actionButton(win, gmail_row, x, gmail_label, focused, enabled, .compose_gmail, 0);
            self.compose_action_drawn |= 2;
            if (enabled) self.compose_action_mask |= 2;
        }
        return rows;
    }
    fn composeDraw(self: *App, full: vaxis.Window) !void {
        self.compose_layout_width = full.width;
        self.compose_original_drawn = false;
        self.compose_fold_drawn = false;
        defer {
            if (self.compose.attachment_focus and self.compose.attachment_cursor >= self.compose.attachments.len + 6 and !self.composeControlFocusable(self.compose.attachment_cursor)) self.leaveComposeAttachments(4, false);
            if (self.dialog_focus.context == .preview and ((self.dialog_focus.index == 5 and !(self.compose_original_drawn and self.originalPolicyUnlocked())) or (self.dialog_focus.index == 6 and !self.compose_fold_drawn))) self.dialog_focus.index = 2;
        }
        self.compose_action_mask = 0;
        self.compose_action_drawn = 0;
        const action_rows = if (self.mode == .review) 0 else try self.composeActionsDraw(full);
        const meter_rows: u16 = if (!browser_target and self.mode != .review and self.compose_active and self.compose.id.value().len > 0 and full.height >= 18) 1 else 0;
        if (meter_rows != 0) try self.line(full, full.height -| action_rows -| 1, try self.composeSizeLabel(false), if (self.composeMeasureCurrent() and (self.compose_measure.over_limit or self.compose_measure.bytes.? >= self.compose_measure.max_bytes - self.compose_measure.max_bytes / 5)) .warning else .muted);
