            } else {
                try self.calendarComposeError(code);
                if (self.job.kind == .calendar_event_edit) {
                    self.calendar_form_edit_after_read = false;
                    try self.calendar.notice.set(self.calendar_form_error.slice());
                }
            }
            return;
        }
