        app.reader_scroll = 9;
        app.reader_card = 1;
        try std.testing.expect(try app.loadCachedList("a"));
        try std.testing.expectEqual(@as(usize, 2), app.thread.len);
        try std.testing.expectEqualStrings("Retained provider body", text(get(app.thread[0], "bodyText")));
