test "local UI: help aligns colored bindings and keeps the last instructions reachable when narrow" {
    const allocator = std.testing.allocator;
    var client: CacheTestClient = .{};
    var app = client.app(allocator);
    defer app.deinit();
    var screen = try vaxis.Screen.init(allocator, .{ .cols = 90, .rows = 60, .x_pixel = 0, .y_pixel = 0 });
    defer screen.deinit(allocator);
    var win: vaxis.Window = .{ .x_off = 0, .y_off = 0, .parent_x_off = 0, .parent_y_off = 0, .width = 84, .height = 60, .screen = &screen };
    const wide_lines = try app.helpContent(win, 0, true);
    const navigation_row: u16 = found: {
        for (0..screen.height) |row| {
            var row_text: std.ArrayList(u8) = .empty;
            defer row_text.deinit(allocator);
            for (0..win.width) |column| try row_text.appendSlice(allocator, screen.readCell(@intCast(column), @intCast(row)).?.char.grapheme);
            if (std.mem.startsWith(u8, row_text.items, "j / k · arrows") and std.mem.indexOf(u8, row_text.items, "Move through the focused pane") != null) break :found @intCast(row);
        }
        return error.NavigationBindingNotVisible;
    };
    try std.testing.expectEqualStrings("j", screen.readCell(0, navigation_row).?.char.grapheme);
    try std.testing.expectEqualStrings("M", screen.readCell(28, navigation_row).?.char.grapheme);
    try std.testing.expect(vaxis.Color.eql(.{ .rgb = app.palette.cyan }, screen.readCell(0, navigation_row).?.style.fg));
    try std.testing.expect(vaxis.Color.eql(.{ .rgb = app.palette.foreground }, screen.readCell(28, navigation_row).?.style.fg));
    win.width = 28;
    win.height = 8;
    screen.clear();
    const narrow_lines = try app.helpContent(win, 0, false);
    try std.testing.expect(narrow_lines > wide_lines);
    app.help_lines = narrow_lines;
    app.help_height = win.height;
    try app.onHelpKey(.{ .codepoint = 'G' });
    try std.testing.expectEqual(narrow_lines - win.height, app.help_scroll);
    _ = try app.helpContent(win, app.help_scroll, true);
    var rendered: std.ArrayList(u8) = .empty;
    defer rendered.deinit(allocator);
    for (0..win.height) |row| {
        var row_text: std.ArrayList(u8) = .empty;
        defer row_text.deinit(allocator);
        for (0..win.width) |column| try row_text.appendSlice(allocator, screen.readCell(@intCast(column), @intCast(row)).?.char.grapheme);
        try rendered.appendSlice(allocator, std.mem.trim(u8, row_text.items, " "));
        try rendered.append(allocator, ' ');
    }
    // Meeting reminders follow the former PERSONALIZE tail. The actual final
    // binding and its complete wrapped instruction must be reachable with G.
    try std.testing.expect(std.mem.indexOf(u8, rendered.items, "Esc / M in a meeting card") != null);
    try std.testing.expect(std.mem.endsWith(u8, std.mem.trim(u8, rendered.items, " "), "Return to your view without dismissing; reminders stay hidden while composing"));
    try std.testing.expectEqual(@as(usize, 0), client.provider_calls);
}

fn helpTestScreenText(a: Allocator, screen: *vaxis.Screen) ![]u8 {
    var rendered: std.ArrayList(u8) = .empty;
    errdefer rendered.deinit(a);
    for (0..screen.height) |row| {
        for (0..screen.width) |column| try rendered.appendSlice(a, screen.readCell(@intCast(column), @intCast(row)).?.char.grapheme);
        try rendered.append(a, '\n');
    }
    return rendered.toOwnedSlice(a);
}

