    try app.apply(.labels_list, "{\"ok\":true,\"data\":{\"labels\":[]}}");
    try std.testing.expectEqualStrings(expected, app.status[0..app.status_len]);
    try app.apply(.identities, "{\"ok\":true,\"data\":{\"identities\":[]}}");
    try std.testing.expectEqualStrings(expected, app.status[0..app.status_len]);
    try app.onKey(.{ .codepoint = Key.escape });
