        .{ .codepoint = 0x1b, .columns = 0 },
        .{ .codepoint = 0x7f, .columns = 0 },
        .{ .codepoint = ' ', .columns = 1 },
        .{ .codepoint = 'A', .columns = 1 },
        .{ .codepoint = 0xe9, .columns = 1 },
        .{ .codepoint = 0x301, .columns = 0 },
        .{ .codepoint = 0xad, .columns = 0 },
        .{ .codepoint = 0x200d, .columns = 0 },
        .{ .codepoint = 0xfe0f, .columns = 0 },
        .{ .codepoint = 0x2b50, .columns = 2 },
        .{ .codepoint = 0x754c, .columns = 2 },
        .{ .codepoint = 0x1f3fb, .columns = 2 },
        .{ .codepoint = 0x1f9d9, .columns = 2 },
        .{ .codepoint = 0x1fa84, .columns = 2 },
        .{ .codepoint = 0x1fae0, .columns = 2 },
        .{ .codepoint = 0x600, .columns = 1 },
        .{ .codepoint = 0x1160, .columns = 1 },
        .{ .codepoint = 0x180e, .columns = 1 },
        .{ .codepoint = 0x2063, .columns = 1 },
        .{ .codepoint = 0xe0067, .columns = 1 },
        .{ .codepoint = 0xd800, .columns = 1 },
        .{ .codepoint = 0xdfff, .columns = 1 },
        .{ .codepoint = 0x110000, .columns = 1 },
        .{ .codepoint = 0xffffffff, .columns = 1 },
    };
    for (cases) |case| try std.testing.expectEqual(case.columns, browserCodepointWidth(case.codepoint));
}

/// Browser runtime adapter for the same App controller used by run().
/// Provider owns sessions, bounded persistence and command execution; this
/// shell only owns the terminal surface and serial completion pump.
pub const BrowserSession = struct {
    app: App = undefined,
    provider: browser_provider.Provider = undefined,
    vx: vaxis.Vaxis = undefined,
    tty: Tty = undefined,
    loop: Loop = .{},
    environ: std.process.Environ.Map = undefined,
    pending_cache: []const u8 = "",
    pending_drafts: []const u8 = "",
    draft_restore_blocked: [3]bool = @splat(false),

    pub fn init(self: *BrowserSession, allocator: Allocator, output: *Io.Writer, cols: u16, rows: u16) !void {
        if (!browser_target) @compileError("BrowserSession requires wasm32-freestanding");
        self.provider = browser_provider.Provider.init(allocator);
        errdefer self.provider.deinit();
        self.environ = std.process.Environ.Map.init(allocator);
        errdefer self.environ.deinit();
        self.pending_cache = "";
        self.pending_drafts = "";
        self.draft_restore_blocked = @splat(false);
        self.tty = .{ .output = output };
        self.vx = try vaxis.init(browser_live.io, allocator, &self.environ, .{});
        errdefer self.vx.deinit(allocator, output);
        self.vx.caps.rgb = true;
        self.vx.caps.unicode = browser_width_method;
        self.vx.sgr = .legacy;
        self.vx.state.alt_screen = true;
        self.app = .{
            .io = browser_live.io,
            .allocator = allocator,
            .client = self.provider.client(),
            .capabilities = platform.browser_capabilities,
            .options = .{ .fixtures = true },
            .environ = &self.environ,
            .vx = &self.vx,
            .tty = &self.tty,
            .loop = &self.loop,
            .account_arena = .init(allocator),
            .list_arena = .init(allocator),
            .read_arena = .init(allocator),
            .contact_arena = .init(allocator),
            .job_arena = .init(allocator),
            .frame = .init(allocator),
            .ui_preferences = .{ .theme = .omagma, .sendGraceSeconds = 0 },
            .theme_choice = .omagma,
            .update_loaded = true,
        };
        errdefer self.app.deinit();
        try self.app.boot();
        self.updateIdentity();
        try self.resize(cols, rows);
        try self.app.reload();
        try self.drain();
        self.app.say(false, "Fictional sample mail · connect an account for Gmail · ? Help", .{});
    }
    fn updateIdentity(self: *BrowserSession) void {
        self.app.operation_nonce = self.provider.sessionNonce(self.app.account_index);
    }
    fn drain(self: *BrowserSession) !void {
        // Native wakes its loop on completion. JSPI suspends the sole owned
        // call, so complete the same jobs before admitting the next host call.
        for (0..64) |_| {
            if (self.app.job.future != null) {
                if (!self.app.job.done.load(.acquire)) return error.OperationPending;
                try self.app.finish();
            } else {
                try self.app.dispatchPending();
                if (self.app.job.future == null) return;
            }
        }
        return error.OperationLimitExceeded;
    }
    pub fn failure(self: *BrowserSession, err: anyerror) void {
        self.app.sayFailure("Operation failed", @errorName(err));
    }
    pub fn accountCount(self: *const BrowserSession) usize {
        return self.provider.accountCount();
    }
    pub fn draftCount(self: *const BrowserSession) usize {
        return self.provider.draftCount();
    }
    pub fn draftDirty(self: *const BrowserSession) bool {
        return self.app.browserDraftDirty();
    }
    pub fn autosavePending(self: *const BrowserSession) bool {
        return self.app.autosave_due and self.app.browserDraftDirty();
    }
    pub fn autosaveAcceptsInput(self: *const BrowserSession) bool {
        return self.app.job.kind == .autosave and self.app.compose_active;
    }
    pub fn autosaveDelay(self: *const BrowserSession) u32 {
        return self.app.browserAutosaveDelay();
    }
    pub fn idle(self: *BrowserSession) !void {
        try self.app.onComposeIdle();
        try self.drain();
    }
    pub fn canSend(self: *const BrowserSession) bool {
        return self.provider.canSend(self.app.account_index);
    }
    pub fn canContacts(self: *const BrowserSession, index: usize) bool {
        return self.provider.canContacts(index);
    }
    pub fn sendStatus(self: *const BrowserSession) u32 {
        return self.provider.sendStatus();
    }
    pub fn draftsRestored(self: *const BrowserSession, index: usize) bool {
        return index < self.provider.accountCount() and !self.draft_restore_blocked[index];
    }
    pub fn stageDrafts(self: *BrowserSession, bytes: []const u8) void {
        self.pending_drafts = bytes;
    }
    pub fn stageCache(self: *BrowserSession, bytes: []const u8) void {
        self.pending_cache = bytes;
    }
    pub fn cacheSnapshot(self: *BrowserSession, index: usize, out: []u8) ![]u8 {
        return self.provider.cacheSnapshot(index, out);
    }
    pub fn cacheRevision(self: *const BrowserSession, index: usize) u32 {
        return self.provider.cacheRevision(index);
    }
    pub fn cacheClear(self: *BrowserSession, index: usize) !void {
        try self.provider.cacheClear(index);
        if (index != self.app.account_index) return;
        self.app.clearReader();
        self.app.messages = &.{};
        self.app.contacts = &.{};
        self.app.contacts_warnings = .{};
        self.app.recipient_values = &.{};
        self.app.recipient_ready = false;
        self.app.contacts_cache_ready = false;
        self.app.sync[index] = .{ .state = .cached };
        self.app.say(false, "Local cache cleared · Ctrl+R refreshes Gmail", .{});
    }
    pub fn restrictContacts(self: *BrowserSession, index: usize, allowed: bool) !void {
        try self.provider.restrictContacts(index, allowed);
        if (allowed) return;
        self.app.restrictContactViews(index, self.provider.accountAddress(index));
        if (index != self.app.account_index) return;
        try self.drain();
        self.app.say(true, "Contacts permission narrowed · saved contacts removed", .{});
    }
    pub fn connect(self: *BrowserSession, bytes: []const u8) !void {
        defer {
            self.pending_cache = "";
            self.pending_drafts = "";
        }
        if (self.app.compose_active) return error.DraftAccountMismatch;
        const index = try self.provider.connect(bytes, self.pending_cache);
        self.provider.restoreDrafts(index, self.pending_drafts) catch {
            self.draft_restore_blocked[index] = true;
        };
        self.app.cancelJob();
        self.app.clearReader();
        self.app.messages = &.{};
        self.app.accounts = &.{};
        _ = self.app.account_arena.reset(.free_all);
        self.app.options.fixtures = false;
        self.app.mode = .browse;
        self.app.compose_choice = false;
        self.app.closeUx();
        try self.app.boot();
        self.app.account_index = index;
        self.app.sync[index] = .{ .state = .cached };
        self.updateIdentity();
        try self.app.chooseAccount(index);
        // An explicit connection initializes an uncached actor once. Later
        // account navigation uses that snapshot until the user refreshes it.
        if (!self.app.sync[index].cache_ready) try self.app.refreshMailbox();
        self.app.navigation = index;
        self.app.focus = .list;
        try self.drain();
    }
    pub fn unknownTarget(self: *const BrowserSession) ?struct { account_index: usize, draft_id: []const u8, operation_id: []const u8, account: []const u8 } {
        const target = self.provider.pendingUnknown() orelse return null;
        return .{ .account_index = target.account_index, .draft_id = target.draft_id, .operation_id = target.operation_id, .account = self.provider.accountAddress(target.account_index) };
    }
    pub fn acknowledgeUnknown(self: *BrowserSession, expected_index: u32, expected_draft: []const u8) !void {
        const target = self.provider.pendingUnknown() orelse {
            if (expected_index != 0xffffffff or expected_draft.len != 0) return error.OperationConflict;
            return;
        };
        if (expected_index != target.account_index or !same(expected_draft, target.draft_id)) return error.OperationConflict;
        const current_draft = self.app.account_index == target.account_index and same(self.app.compose.id.value(), target.draft_id);
        try self.provider.acknowledgeUnknown(target.account_index, target.draft_id);
        if (current_draft) {
            self.app.compose.unknown_outcome = false;
            self.app.receipt_unknown = false;
            self.app.review_ready = false;
            if (self.app.compose_active) {
                self.app.mode = .compose;
                self.app.compose.insert_mode = false;
            }
        }
        self.app.say(false, "Checked Sent acknowledged · draft retained · fresh review required", .{});
    }
    pub fn resize(self: *BrowserSession, cols: u16, rows: u16) !void {
        try self.app.resize(.{ .cols = cols, .rows = rows, .x_pixel = 0, .y_pixel = 0 });
    }
    pub fn draw(self: *BrowserSession) !void {
        try self.app.draw();
        try self.tty.writer().writeAll("\x1b[?1000h\x1b[?1006h\x1b[?2004h\x1b[H");
        self.vx.queueRefresh();
        self.vx.render(self.tty.writer()) catch |err| {
            self.app.review_ready = false;
            return err;
        };
    }
    pub fn key(self: *BrowserSession, key_value: Key) !void {
        self.updateIdentity();
        try self.app.onKey(key_value);
        self.updateIdentity();
        if (!self.app.paste) try self.drain();
    }
    pub fn mouse(self: *BrowserSession, event: vaxis.Mouse) !void {
        self.updateIdentity();
        try self.app.onMouse(event);
        self.updateIdentity();
        try self.drain();
    }
    pub fn pasteStart(self: *BrowserSession) void {
        self.app.pasteStart();
    }
    pub fn pasteEnd(self: *BrowserSession) void {
        self.app.pasteEnd();
        self.drain() catch |err| self.failure(err);
    }
};

const RemotePreferencesTestClient = struct {
    bytes: [256 * 1024]u8 = undefined,
    len: usize = 0,
    reads: usize = 0,
    writes: usize = 0,
    locked: bool = false,

    fn call(ctx: *anyopaque, a: Allocator, raw: []const u8) ![]const u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        if (self.locked) return a.dupe(u8, "{\"ok\":false,\"error\":{\"code\":\"VaultLocked\"}}");
        const request = try std.json.parseFromSliceLeaky(Value, a, raw, .{});
        if (same(text(get(request, "cmd")), "preferences.get")) {
            self.reads += 1;
            const value: Value = if (self.len == 0) .null else try std.json.parseFromSliceLeaky(Value, a, self.bytes[0..self.len], .{});
            return @import("json.zig").encodeAlloc(a, .{ .ok = true, .data = .{ .preferences = value } }, .{});
        }
        if (same(text(get(request, "cmd")), "preferences.set")) {
            const bytes = try @import("json.zig").encodeAlloc(a, get(request, "preferences"), .{});
            if (bytes.len > self.bytes.len) return error.UiPreferencesTooLarge;
            @memcpy(self.bytes[0..bytes.len], bytes);
            self.len = bytes.len;
            self.writes += 1;
            return a.dupe(u8, "{\"ok\":true,\"data\":{\"saved\":true}}");
        }
        return error.UnexpectedCommand;
    }
};

test "local UI: daemon preferences preserve saved searches and never resolve a plaintext path" {
    const a = std.testing.allocator;
    var baseline: CacheTestClient = .{};
    var client: RemotePreferencesTestClient = .{};
    var app = baseline.app(a);
    defer app.deinit();
    app.client = .{ .ctx = &client, .callFn = RemotePreferencesTestClient.call };
    app.options.remote_preferences = true;
    // environ is deliberately absent: the daemon route must never consult HOME.
    app.options.ui_file = "/not-a-real-preferences-destination/ui.json";
    app.loadPreferences();
    try std.testing.expect(app.remote_preferences_loaded);
    try std.testing.expectEqual(@as(usize, 0), app.preferences_file.value().len);
    try preferences.rememberSearch(&app.ui_preferences, "personal@example.test", "subject:private-vault-marker", .cache, "Work");
    app.ui_preferences.density = .compact;
    app.reader_layout = .below;
    app.saveUiPreferences();
    try std.testing.expect(app.remote_preferences_pending);
    try std.testing.expectEqual(@as(usize, 0), client.writes); // No blocking I/O in a key event.
    try app.flushRemotePreferences();
    try std.testing.expectEqual(@as(usize, 1), client.writes);
    app.ui_preferences = .{};
    app.reader_layout = .right;
    app.loadPreferences();
    try std.testing.expectEqual(layout.ReaderLayout.below, app.reader_layout);
    try std.testing.expectEqual(preferences.Density.compact, app.ui_preferences.density);
    try std.testing.expectEqualStrings("subject:private-vault-marker", app.ui_preferences.savedSearches[0].?.query.slice());
    try std.testing.expectEqual(@as(usize, 0), baseline.local_calls + baseline.provider_calls);
}

