        try app.finishCalendarCompose();
        try std.testing.expect(!app.calendar_form_unknown);
        try std.testing.expect(app.calendar_form_error.len > 0);
    }
    app.job.response = "{\"ok\":false,\"error\":{\"code\":\"UnknownOutcome\"}}";
