        defer a.destroy(loop);
        loop.init(std.testing.io, a, &tty, &vx);
        defer loop.deinit();
        var factory: CacheTestClient = .{};
        var app = factory.app(a);
        defer app.deinit();
        defer app.cancelJob();
        try meetingFlowReady(&app, &client, loop);
